 function cultivationFacts(saved,incoming){const out=schemaGoods(saved);if(!incoming?.培育材料)return out;try{const next=cp(incoming.培育材料),old=out.培育材料;if(old){for(const k of ['单位','每件量','容器']){if(own(old,k))next[k]=cp(old[k]);else delete next[k];}if(own(old,'余量'))next.余量=old.余量;else delete next.余量;}else delete next.余量;const candidate={...out,培育材料:next};if(typeof DLH_LINGMU!=='undefined')for(const k of ['评级','品级'])if(own(incoming,k)&&own(DLH_LINGMU.gradePoints,incoming[k]))candidate[k]=incoming[k];if(typeof DLH_LINGMU!=='undefined')DLH_LINGMU.material(candidate);return candidate;}catch(_){return out;}}
