if(typeof module==='object'&&module.exports)module.exports=DLH_LINGMU;

/* Estate popup is driven by committed RT updates; selections are transient UI only. */
var LINGMU_VIEW={open:false,site:'',plan:'',materials:{},action:'温养',busy:false,serial:0};
function openLingmu(){if(COURTYARD_UI){COURTYARD_UI.open();return;}LINGMU_VIEW.open=true;renderLingmu();}
function lingmuClose(){LINGMU_VIEW.open=false;}
function lingmuDirectionLabel(info){return !info?.registered?'倾向待补':info.routes.length?info.routes.map((k,i)=>k+(info.routes.length===2?(i?'25%':'75%'):'')).join(' / '):'无倾向';}
function lingmuDevelopmentHtml(tree){
 const d=DLH_LINGMU.development(tree),fx=DLH_LINGMU.effects(tree),highest=Math.max(1,...Object.values(d.分值));
 return '<section class="lm-development" aria-label="灵木培养方向"><h4>培养方向</h4><p class="lm-direction-lead">'+(d.主倾向?'主倾向 <b>'+esc(d.主倾向)+'</b>'+(d.副倾向?'　副倾向 <b>'+esc(d.副倾向)+'</b>':'')+(d.并列?'（当前并列）':''):'尚未定向，温养时由实际投料累计')+'</p>'+DLH_LINGMU.directions.map(k=>'<div class="lm-direction-row"><span>'+esc(k)+'</span><meter min="0" max="'+highest+'" value="'+d.分值[k]+'" aria-label="'+esc(k)+' '+d.分值[k]+'分"></meter><strong>'+DLH_DISPLAY.number(d.分值[k])+'</strong><small>'+esc(DLH_LINGMU.directionGoals[k])+' · 当前有效 '+fx.档位[k]+' 档'+'</small></div>').join('')+'<div class="lm-panel-effects"><b>倾向属性</b><p>'+esc(DLH_CURIOS.text({面板加成:DLH_LINGMU.panelBonus(tree)})||'成长后激活，当前无额外属性')+'</p></div><p class="lm-direction-note">产业：恢复灵果 +'+Math.round(fx.恢复增幅*100)+'%；采露消耗生机 '+(Math.round(20*(1-fx.采露减耗)*100)/100)+'、树势 '+(Math.round(8*(1-fx.树势减耗)*100)/100)+'；同场药圃成熟缩短 '+Math.round(fx.成熟缩短*10000)/100+'%；留种 +'+Math.round(fx.留种增产*10000)/100+'%；毒材 +'+Math.round(fx.毒材增产*100)+'%。灵果基础效用按品阶核定，培养增幅单独结算。</p><details><summary>投料、档位与实际效果</summary><p>32／128／512／2048分升档，主倾向全额、副倾向半额。初植未激活，扎根／成荫／开华／结实分别最多一／二／三／四档。药圃加成在播种时固定，仅作用于本命树同场地新批次；毒材不足一件的增产会累计。留种按繁育倾向增产，不享受蚀毒加成。</p><p>每标准份：'+Object.entries(DLH_LINGMU.gradePoints).map(([g,n])=>g+' '+n+'分').join('；')+'。</p><p>标准份为100毫升、100克或1粒／株／份。双倾向按主75%、副25%分配总分；无倾向材料只用于日常养护。分装不会增加总分。</p></details></section>';
}
function lingmuPreviewHtml(){
 const v=LINGMU_VIEW;if(v.action!=='温养')return '';
 try{const p=DLH_LINGMU.preview(V,{action:'温养',site:v.site,materials:v.materials});return '<div class="lm-feed-preview" role="status"><b>本次培养贡献 '+DLH_DISPLAY.number(p.总分)+' 分</b><p>'+Object.entries(p.分值).filter(([k,n])=>n>0).map(([k,n])=>esc(k)+' +'+DLH_DISPLAY.number(n)).join('，')+'</p>'+(p.投料后?'<p>投料后：'+esc(p.投料后.方向.主倾向||'尚未定向')+(p.投料后.方向.副倾向?' / '+esc(p.投料后.方向.副倾向):'')+'</p><p>届时生效：'+esc(DLH_CURIOS.text({面板加成:p.投料后.面板})||'尚未达到激活条件')+'</p>':'')+'<small>以实际消耗计分，确认温养后入账。</small></div>';}catch(e){return '<p class="lm-reason">'+esc(e.message)+'</p>';}
}
function lingmuHeader(){const ok=DLH_LINGMU.learned(V);return '<button type="button" id="industry-lingmu"><b>本命灵树</b><span>'+(ok?'温养灵根 · 药圃栽培 · 奇物反哺':'修习《灵木妙植》后开放')+'</span></button>';}
function lingmuRun(action,extra){const view=LINGMU_VIEW;if(view.busy)return;view.busy=true;const sel={action,site:view.site,plan:view.plan,materials:{...view.materials},expected:WORLD.游戏累计时辰||0,revision:DLH_LINGMU.read(V)?.序号||0,...extra},request='lm-ui-'+Date.now()+'-'+(++view.serial);renderLingmu();RT.mutate(all=>{const sd=all.stat_data;DLH_CALENDAR.process(sd);DLH_LINGMU.act(sd,sel,request);CHARACTER.recompute(sd.主角);}).then(()=>{snap();toast('已完成'+action+'，结果已加入统一承接');},e=>toast(e.message)).finally(()=>{view.busy=false;if(view.open&&$('#poplay').classList.contains('open'))renderLingmu();});}
