function proof(ctx){const map=new Map();if(!ctx?.trusted||!ctx.chatId||!Array.isArray(ctx.activeSources))return {ok:false,map};let chain=hash(ctx.chatId);for(const s of ctx.activeSources){if(!s||typeof s.body!=='string'||!s.key||!s.generationId)return {ok:false,map:new Map()};const p={chatId:ctx.chatId,key:s.key,messageId:String(s.messageId),swipeId:String(s.swipeId),generationId:s.generationId,bodyFingerprint:hash(s.body),parent:chain};chain=hash(chain+'\n'+JSON.stringify(p));map.set(s.key,{...p,chain,body:s.body});}return {ok:true,map};}
