function month(sd){const current=sd.世界?.日历?.今日?.月;if(Number.isInteger(current)&&current>=1&&current<=12)return current;const raw=sd.世界?.当前时间??'';const m=String(raw).match(/([一二三四五六七八九十正冬腊\d]{1,3})月/);if(!m)return null;const v=m[1],special={正:1,冬:11,腊:12,十:10,十一:11,十二:12};return (special[v]??(/^\d+$/.test(v)?Number(v):'一二三四五六七八九'.indexOf(v)+1))||null;}
