  if(e.动作==='接入'&&p.暂停自动接入===true&&!(String(ctx.userText||'').includes(e.剧情)&&/继续|追查|参加|赴|恢复/.test(ctx.userText)))throw Error('自动接入已暂停，须玩家明确主动要求');
