function plan(sd,ctx,catalog){const state=derive(sd.剧情线||{},ctx,catalog),p=sd.剧情线||{},explicit=String(ctx?.userText||''),evaluation=catalog.plots.map(plot=>({plot,condition:condition(plot.condition,{...sd,剧情线:{...p,已完成:state.done}},ctx,state.records)}));let selected=state.current&&evaluation.find(x=>x.plot.name===state.current);function route(c){if(!c.ok)return 0;if(c.children)return c.label==='任选一路'?Math.max(...c.children.map(route)):c.children.reduce((n,x)=>n+route(x),0);return c.label.startsWith('地点')?30:c.label.startsWith('势力')?20:c.label.startsWith('前置')?10:0;}if(!selected){const paused=p.暂停自动接入===true;selected=evaluation.filter(x=>x.plot.ready&&x.condition.ok&&!state.done.includes(x.plot.name)&&(!['暂缓','拒绝'].includes(state.records[x.plot.name]?.状态)||explicit.includes(x.plot.name))&&(!paused||explicit.includes(x.plot.name)&&/继续|追查|参加|赴|恢复/.test(explicit))).sort((a,b)=>{const score=x=>(explicit.includes(x.plot.name)?1000:0)+(x.plot.name==='除恶务尽'?500:0)+route(x.condition);return score(b)-score(a);})[0];}return {state,selected,evaluation,diagnostics:state.diagnostics};}
