/* No independent generation, timers or prompt injection. Reuse the memory source frame. */
function dlhPlotContext(frame,host){const ctx={...frame};const chat=host?.chat;if(Array.isArray(chat)){const row=chat.slice().reverse().find(m=>m?.is_user&&!m.is_system);ctx.userText=DLH_PLOT_DISPATCH.visible(row?.mes??row?.message??'');const source=frame.activeSources?.find(x=>x.key===frame.sourceKey),id=Number(source?.messageId);if(Number.isInteger(id))for(let i=id-1;i>=0;i--){const m=chat[i],vars=Array.isArray(m?.variables)?m.variables[m.swipe_id||0]:m?.variables,p=vars?.stat_data?.剧情线,previous=frame.activeSources?.find(x=>x.messageId===String(i));if(p&&previous){ctx.previousPlot=JSON.parse(JSON.stringify(p));ctx.previousPlotSourceKey=previous.key;break;}}}return ctx;}
function dlhCombinedNarrativeView(sd,host,bridge,catalog){const session=bridge.projection(sd,host),ctx=dlhPlotContext(session.context,host);return DLH_PLOT_DISPATCH.combined(sd,ctx,catalog,session.project);}
/* Keep dispatch receipts and diagnostic buckets in the save, outside model input. */
function dlhPlotReadView(view,brief){if(view?.剧情线){view.剧情线={当前:brief?.plot?.current||'',已完成:Array.isArray(view.剧情线.已完成)?view.剧情线.已完成:[],暂停自动接入:view.剧情线.暂停自动接入===true};}return view;}
if(typeof module==='object'&&module.exports)module.exports={dlhPlotContext,dlhCombinedNarrativeView,dlhPlotReadView};
