    if(s.seen[key])return {duplicate:true,gain:0,diverted:0,counter:0};s.seen[key]=true;
    const pressure=finite(e.pressure),prevented=Math.min(pressure,finite(e.blocked));
    if(!s.grounded||!this.eligible(e))return {gain:0,diverted:0,counter:0,afterBlock:pressure-prevented};
    const root=String(e.root||e.id),rootUsed=s.roots[root]||0;
    let budget=Math.max(0,Math.min(this.room(),.75*s.J-rootUsed,1.5*s.J-s.incomingGain));
    const diverted=Math.min(s.opportunity<s.braceUntil?(pressure-prevented)*.2:0,budget);budget-=diverted;
