    if(!valid||!s.grounded||!Number.isInteger(targets)||targets<1||!Number.isInteger(segments)||segments<1)return {committed:false};
    if(s.casts[id])return {...clone(s.casts[id]),duplicate:true};
    if(reserve&&s.pending)return {committed:false};
