  function take(token,strength=1,round=1,action='manual'){
   const key='take/'+action+'/'+token;if(state.processed[key]===round)return {strength:0};state.processed[key]=round;
   const entry=[state.weather,...state.terrain].find(s=>s?.token===token);if(!entry)return {strength:0};
   const used=Math.min(entry.strength,Math.max(0,Math.min(3,Math.floor(Number(strength)||0))));entry.strength-=used;
   if(entry.strength<=0){if(state.weather===entry)state.weather=null;else state.terrain=state.terrain.filter(s=>s!==entry);}
   if(used)emit(round,'灾势消减'+entry.kind,{strength:used,source:entry.sourceName});validate();return {strength:used,token,kind:entry.kind};
  }
  function spread(token,area='全场',round=1,action='manual'){
   if(!areas.includes(area))throw Error('unknown terrain area');const key='spread/'+action+'/'+token;if(state.processed[key]===round)return {changed:false};state.processed[key]=round;
   const entry=state.terrain.find(s=>s.token===token);if(!entry||entry.area===area)return {changed:false};
   const conflict=state.terrain.find(s=>s!==entry&&s.kind===entry.kind&&s.area===area);if(conflict&&conflict.strength>=entry.strength)return {changed:false};
   if(conflict)state.terrain=state.terrain.filter(s=>s!==conflict);entry.area=area;emit(round,'灾势扩及'+area,{kind:entry.kind});validate();return {changed:true};
  }

  function presence(kind,area='全场'){return state.terrain.some(s=>s.kind===kind&&matches(s,area));}
  function weatherFactor(element,protect=false,area='全场'){const ts=tags(),level=state.weather?.strength||state.base.strength||1;let value=1;if(element==='火'){if(ts.includes('雨'))value*=[1,.94,.88,.82][level];if(ts.includes('热'))value*=1+[0,.08,.12,.16][level];if(ts.includes('风')&&presence('燃烧',area))value*=1+[0,.10,.15,.20][level];}if(['寒','冰','水'].includes(element)){if(ts.includes('寒'))value*=1+[0,.08,.12,.16][level];if(ts.includes('热'))value*=[1,.94,.91,.88][level];}if(element==='雷'&&ts.includes('雷'))value*=1+[0,.10,.15,.20][level];return protect?Math.max(1,Math.min(1.05,value)):value;}
  function terrainFactor(element,area='全场',ranged=false){let value=1;if(element==='火'&&presence('燃烧',area))value*=1.04;if(['寒','冰','水'].includes(element)&&(presence('结霜',area)||presence('冰面',area)))value*=1.04;if(element==='雷'&&!tags().includes('雷')&&(presence('积水',area)||state.base.ground==='水域'))value*=1.10;if(ranged&&presence('蒸汽',area))value*=.96;return value;}
  function factor(element,area='全场',ranged=false,options={}){return Math.max(.80,Math.min(1.25,weatherFactor(element,options.selfSeasons===true,area)*terrainFactor(element,area,ranged)));}

