 function virtual(h,r){if(h.生死==='已死'||h.基础信息?.生死==='已死'||h.境界修行?.已死亡)throw Error('已身死，无法使用物品');const i=r.item;if(!i||i.状态==='已服用'||Number(i.数量??1)<1)throw Error(i?.状态==='已服用'?'此物已服用，无剩余库存':'物品已用尽');return {...h,物品栏:{...h.物品栏,[r.key]:{...i,数量:i.数量??1}}};}
 function canUse(h,id,context,replace,target){const r=locate(h,id),v=virtual(h,r),i=v.物品栏[r.key];if(DLH_ITEMS.restriction(i))throw Error('使用条件尚需确认：'+DLH_ITEMS.restriction(i));if(context==='battle'&&i.类型==='食物')throw Error('食物仅战前可用');if(context==='battle'&&i.使用限制==='仅日常'||context==='daily'&&i.使用限制==='仅战斗')throw Error('此物使用场景受限');if(wisdomIntent(i,r.key)&&i.效用&&!own(i.效用,'悟性加成'))throw Error('原文明确永久提升悟性，当前定义与用途不符，请重新补全，不能改为体属性');if(i.效用?.装备折算||i.效用&&own(i.效用,'悟性加成')){const e=validate(i);if(context==='battle'&&e.类别==='永久类')throw Error('永久药力须在场外炼化');if(e.装备折算)scaled(h,i);return {item:i,effect:e};}if(i.效用?.类别==='成长类'){const e=validate(i);if(context==='battle')throw Error('修行与感悟物品须在场外使用');if((h.战斗面板?.消耗品?.服用计数?.[DLH_ITEMS.identity(i,r.key)]||0)>=e.限服)throw Error('药力已至尽头');return {item:i,effect:e};}if(i.效用?.类别==='持续类'){v.战斗面板={...v.战斗面板,消耗品:{...cp(v.战斗面板?.消耗品||{服用计数:{}}),食物:[],丹药:[]}};}return native.canUse(v,r.key,context,replace,target);}
