  if(r.kind==='mark'&&(!d.moves.some(m=>m.effects.some(fx=>fx.kind==='status'&&fx.target==='enemy'&&fx.status===r.status))||r.mode==='absent'&&moves.some(m=>!m.effects.some(fx=>fx.kind==='status'&&fx.target==='enemy'&&fx.status===r.status))))fail('机制【'+(t.name||t.id)+'】('+t.id+')：标记【'+r.status+'】须由本门moves[].effects中的{kind:status,target:enemy,status:'+r.status+'}实际施加；mode=absent时每个绑定招式须自行施加，缺少施加的绑定id：'+moves.filter(m=>!m.effects.some(fx=>fx.kind==="status"&&fx.target==="enemy"&&fx.status===r.status)).map(m=>m.id).join('、')+'；不以描述或statuses定义代替真实施加');
  if(r.kind==='sequence'&&(r.sequence.length<2||r.sequence.length>3||r.sequence.some(id=>!d.moves.some(m=>m.id===id&&!m.charge&&!m.reaction&&!m.followUp?.free&&m.cost+m.stamina>=10))||new Set(r.sequence).size<2||r.ratio>.25||moves.some(m=>m.kind!=='attack')||t.moves.some(id=>r.sequence.includes(id))))fail('施术次序须2~3个稳定id、至少两种正常付费招式，独立消费招式增幅≤25%');
