 function bounds(key,ref){const max=ref?.[key];if(!DLH_EQUIPMENT.keys.includes(key)||!Number.isFinite(max)||max<=0)throw Error('装备词条缺少满值参考：'+key);return {min:Math.ceil((max*config.ordinaryRollRange[0]-1e-10)*1e8)/1e8,max};}
