   const e=v.效用;if(e?.类别!=='即时类'||!e.恢复?.气血)throw Error('恢复灵果须先登记可执行的即时气血恢复效用');
   v.类型=v.类型||'食物';if(typeof DLH_ITEMS==='undefined')throw Error('消耗品结算接口未就绪');
