  let after=null;if(tree){after=cp(tree);after.培养分值=after.培养分值||emptyScores();for(const k of directions)after.培养分值[k]=round(after.培养分值[k]+contribution.分值[k]);after.根基=round((after.根基||0)+1);grow(sd,after);}
