  // These two duration names already mean elapsed game hours in the two local
  // journals. Only move the value; never coerce, infer or resolve conflicts.
  const e={...raw};
  for(const k of Object.keys(e).filter(k=>!allowed.includes(k)&&k!==alias).slice(0,6))add(k,'不支持字段；仅登记事实，不填写奖励或派生结果');
  if(own(e,alias)){
   if(own(e,canonical)&&e[canonical]!==e[alias])add(alias,'与'+canonical+'冲突（'+summary(e[alias])+'／'+summary(e[canonical])+'）；须核对实际时长');
   else if(!own(e,canonical))e[canonical]=e[alias];
   delete e[alias];
  }
