  function legacyShell(f){return f&&f.字段版本==null&&NUMERIC_FIELDS.every(k=>Object.hasOwn(f,k))&&NUMERIC_FIELDS.every(k=>num(f[k])===0||k==='会心伤害'&&num(f[k])===50||k==='会意伤害'&&num(f[k])===35);}
