    for(const e of rows){const a=Math.max(cursor,e.开始时辰),b=Math.min(end,e.开始时辰+e.经过时辰);if(a>cursor)out.push({start:cursor,end:a,type:'自然'});if(b>a){out.push({start:a,end:b,type:mode(e.类型)});cursor=b;}}
