  function eligibleArt(h,name){if(!name)return DLH_MASTERY.level(h.基础信息?.武道境界)<=2||h.基础信息?.武道境界==='无修为';const a=h.武学与意境面板?.掌握武学?.[name];return !!a&&/内功|横练|锻体|硬功/.test(a.类型||'');}
