  function choose(sd,t){t=DLH_FIVE.canonicalRealm(t);process(sd);const b=sd.主角.境界修行;if(!choices(b.当前境界,seaRoot(b)).includes(t))throw Error('不能跳境、跳关或选择不符根基的入海路线');b.目标=t;b.积累=Math.min(b.积累,required(b));}
