 function costume(g){return g?.开局衣装==='星海溯古/时空防护服'&&g.名称==='破损的时空防护服'&&g.评级==='后天'&&g.部位==='胸甲'&&!g.通用加成&&!g.定音&&(!g.面板加成||Object.values(g.面板加成).every(v=>typeof v==='object'?!Object.values(v).some(Boolean):!v));}
