/* Generated by extract_mechanics.py from the preserved battle demo.
 * Numerical kernel runs inside createDlhBattleEngine; no DOM/timers/network. */
/* Pure, bounded action scoring. No combat mutation, random draws or engine calls. */
var DLH_UTILITY_AI = (function () {
  const profiles = {
    fish: { attack: 1.12, defend: .75, heal: .85, setup: .8, adapt: .35 },
    adept: { attack: 1, defend: 1, heal: 1, setup: 1, adapt: .75 },
    boss: { attack: 1, defend: 1.1, heal: 1.1, setup: 1.15, adapt: 1 },
    boss2: { attack: 1.06, defend: 1, heal: 1, setup: 1.15, adapt: 1 }
  };
  const finite = x => Number.isFinite(x) ? x : 0;
  const clamp = (x, lo = 0, hi = 1) => Math.min(hi, Math.max(lo, finite(x)));
  function score(view, action) {
    const p = profiles[view.style] || profiles.adept;
    const scale = Math.max(1, view.power), danger = clamp(view.danger);
    const factors = {
      damage: Math.max(0, finite(action.damage)) / scale * 35 * p.attack,
      finish: Math.max(0, finite(action.kills)) * 85 * p.attack,
      healing: Math.max(0, finite(action.healing)) / scale * 38 * p.heal,
      rescue: Math.max(0, finite(action.rescue)) * 85 * p.heal,
      setup: Math.max(0, finite(action.setup)) * p.setup,
      control: Math.max(0, finite(action.control)) * (20 + danger * 20),
      defense: 0,
      resources: Math.max(0, finite(action.resource)) * 40,
      cost: -Math.max(0, finite(action.cost)) / Math.max(25, view.mana) * 26,
      stamina: -Math.max(0, finite(action.stamina)) / Math.max(15, view.stamina) * 8,
      chargeRisk: -Math.max(0, finite(action.charge)) * danger * 30
    };
    if (action.defense) {
      const learnedRisk = clamp(view.fooled * p.adapt * .38, 0, .8);
      factors.defense = (4 + 100 * danger + (view.incomingCharge ? 28 : 0)) * p.defend * (1 - learnedRisk);
      if (action.defense === 'dodge' && view.incomingCharge) factors.defense *= 1.12;
    }
    if (action.escape) factors.defense = clamp((.2 - view.hpFraction) / .2) * 160;
    if (action.observe) factors.setup = .01;
    // Value measures progress per occupied opportunity, not just the release burst.
    factors.damage /= 1 + Math.max(0, finite(action.charge));
    factors.finish /= 1 + Math.max(0, finite(action.charge));
    return { ...action, factors, score: Object.values(factors).reduce((a, b) => a + b, 0) };
  }
  function rank(view, actions) {
    return actions.map(a => score(view, a)).filter(a => Number.isFinite(a.score))
      .sort((a, b) => b.score - a.score || String(a.key).localeCompare(String(b.key)));
  }
  function choose(rows, draw) {
    if (!rows.length) return null;
    const best = rows[0].score;
    const shortlist = rows.filter(a => a.score >= best - Math.max(3, Math.abs(best) * .15)).slice(0, 3);
    const weights = shortlist.map(a => Math.exp((a.score - best) / Math.max(1, Math.abs(best) * .1)));
    let cursor = clamp(draw, 0, .999999999999) * weights.reduce((a, b) => a + b, 0);
    for (let i = 0; i < shortlist.length; i++) { cursor -= weights[i]; if (cursor < 0) return shortlist[i]; }
    return shortlist[shortlist.length - 1];
  }
  return { rank, choose, profiles };
})();

