const INNATE_CONFIG={"revision":5,"arts":{"jiuxiao":{"name":"九霄雷诀","lv":"先天","type":"外功","适器":[],"yuan":"纯阳宗创派祖师于雷暴之夜观天象所创，纯阳宗镇宗不传之秘。","requirement":"纯阳体质；以引雷淬体修习。","pos":"雷法开道，天人感应：以己雷引天雷，以人身御天象。雷劫连接人身与雷域，可留劫感应、主动渡劫，亦可回雷护体。","bonuses":[{"slot":1,"name":"辨雷","key":"精准率","mode":"flat","value":10},{"slot":2,"name":"伏魔","key":"会心率","mode":"flat","value":5}],"sigs":[["神雷伏魔","本门雷伤粗通+30%、圆满+36%；有效主攻击整招积1荡魔，上限3；追雷花1、聚雷域花3，不再加攻击面板。 对当前身份明确为魔门者，本门直接雷伤、天雷及同源雷劫持续伤害另增25%；不提高面板，不由名称、恶行或所学武功推断身份。 借天行雷：处于真实公共雷雨时，每回合首次有效本门主攻击额外积1荡魔，仍上限3；不因段数、目标数、追雷、持续伤害或刷新重复触发。",1],["渡世雷劫","同源雷劫5层、4回合；每层双防−2%，真气快照10%持续伤害；同源同目标每回合最多2层，满层不自动爆破。渡劫消耗旧层追加天雷0.9/层，然后挂本招新层。",1],["电闪雷鸣","雷光或雷蛇有效命中后，同一目标雷劫≥3，可花1荡魔及8内力追雷一次；免主动作、不递归。",1],["以身引天","雷域释放后布下3回合雷天，每回合末对每名身负自身雷劫的存活敌人各引一道真气倍率1.5的天雷。天雷独立于本体行动，即使本体被控仍落雷；无同源雷劫则空落。常式蓄势2；聚雷起蓄耗荡魔3改蓄势1且强韧，雷域期间后续主招额外挂1雷劫，仍限每目标每回合2层。 雷域释放、首个目标伤害前尝试引来全场雷雨3回合，入室强度1、圆满强度2；遵守公共天气强度覆盖及遮蔽规则。顺势聚雷：真实公共雷雨强度2以上，聚雷耗荡魔由3降至2，仍蓄势1；费用在起蓄时锁定并只扣一次。",3],["回雷抱元","登堂后可花10内力，回收目标2同源雷劫，回复自身护体真气上限10%；占主动作，调息3。气竭、无护体上限或护体已满时不可使用，不返还内力。",2]],"moves":[{"id":"dh","name":"电弧掌","tier":0,"type":"hybrid","hpR":0.35,"qqR":0.175,"cost":5,"cd":0,"desc":"挂麻痹1回合；低成本起手。","innateNative":true,"fx":[["麻痹",1,1]],"playerDesc":"掌中电弧迅疾击向敌人，造成少量伤害，并使敌人短暂麻痹。"},{"id":"lg","name":"雷光灼刃","tier":1,"type":"pure","hpR":0,"qqR":1.8,"cost":18,"cd":2,"desc":"挂灼伤1层3回合；可开启追雷。","innateNative":true,"fx":[["灼伤",1,3]],"playerDesc":"以雷光刺穿敌势，造成中等伤害，并留下灼伤，持续伤害敌人。命中后可顺势追雷。"},{"id":"chase","name":"雷光灼刃·追雷","tier":1,"type":"pure","hpR":0,"qqR":2.2,"cost":8,"cd":0,"desc":"花1荡魔；雷光或雷蛇有效命中的同一目标须有3雷劫；免主动作，每主动作一次，不挂雷劫、不积荡魔。","innateNative":true,"free":"combo","playerDesc":"循着刚才命中的雷意再追一击，造成中等伤害。"},{"id":"ls","name":"雷蛇传导","tier":2,"type":"pure","hpR":0,"qqR":2.1,"cost":25,"cd":2,"desc":"三段0.6/0.7/0.8；整招挂2雷劫，麻痹1回合。 群战向其他敌人传导，每目标结算完整三段；每目标独立挂劫，追雷仅接首目标。","innateNative":true,"segs":[{"hpR":0,"qqR":0.6},{"hpR":0,"qqR":0.7},{"hpR":0,"qqR":0.8}],"fx":[["麻痹",1,1]],"playerDesc":"雷蛇贯穿敌阵，对首敌造成中等伤害，并向其余敌人传导。命中首敌后可顺势追雷。","range":true},{"id":"ll","name":"九霄落雷","tier":3,"type":"pure","hpR":0,"qqR":3,"cost":38,"cd":3,"desc":"两段1.2/1.8；保留旧雷劫，挂本招1层。","innateNative":true,"segs":[{"hpR":0,"qqR":1.2},{"hpR":0,"qqR":1.8}],"playerDesc":"掌中雷霆连落数次，以连续攻势造成较高伤害。"},{"id":"judgement","name":"九霄落雷·渡劫","tier":3,"type":"pure","hpR":0,"qqR":3,"cost":38,"cd":3,"desc":"目标须有3同源雷劫；有效命中后消耗释放前全部旧层，追加真气倍率0.9/层天雷，再挂本招新层；与落雷共调息。","innateNative":true,"segs":[{"hpR":0,"qqR":1.2},{"hpR":0,"qqR":1.8}],"sharedCooldown":"ll","playerDesc":"引爆自己留在敌人体内的雷劫，落下一道重雷，造成高额伤害。雷劫越深，渡劫越重。"},{"id":"ly","name":"雷域·九天殛顶","tier":3,"type":"pure","hpR":0,"qqR":3.8,"cost":65,"cd":6,"desc":"圆满真气倍率4.5；范围。常式蓄势2；聚雷耗荡魔3、蓄势1且强韧。两式释放均布雷域3回合，回合末对每名身负同源雷劫的存活敌人各落一道天雷（真气倍率1.5）；聚雷域另强化后续挂劫。 真实雷雨强度2以上聚雷只耗2荡魔。释放时尝试引来3回合公共雷雨：入室强度1、圆满强度2；非起蓄时引天。","innateNative":true,"charge":2,"range":true,"playerDesc":"蓄势后召来压顶雷云，造成高额伤害，并在随后数回合引来天雷，追击身负你雷劫的敌人。聚雷可更快成阵。 放雷时也会尝试引来雷雨；已有盛势雷雨时，聚雷更省荡魔之力。"},{"id":"reclaim","name":"回雷抱元","tier":2,"type":"pure","hpR":0,"qqR":0,"cost":10,"cd":3,"desc":"回收所选目标2同源雷劫，回复自身最大护体真气10%；占主动作、无伤害，不挂雷劫、不积荡魔。气竭或护体已满时不可空耗。","innateNative":true,"playerDesc":"收回敌人体内的一部分雷意，补充自己的护体真气。"}],"breakthrough":"雷域脱离本体行动独立运转，循同源雷劫引天雷。","boundaries":"雷劫按施加者分别保存，双防削减取最高单来源层数，不多人相加；持续伤害各按自己来源结算。雷域持续含释放当回合及后两回合，持续伤害结算后感应；按同源雷劫层数与参战标识稳定排序，每个有同源雷劫的敌人各结算一次，不攻击无同源雷劫目标。每人同时一个域，重布覆盖不叠加。天雷按布域时攻击面板快照、本门增伤与当前目标防御/抗性/闪避/格挡/护体结算；范围攻击，先付65内力，后续无额外主动作或重复扣费，不生成资源/雷劫、不触发攻击侧其他武学连锁。本体死亡或退场即停止，战斗结束清除。 魔门判定取当前结构化身份标签中的魔门，或所属势力末段确为天魔阁/血神宫；不以招式名、习得魔功、疑似或旧身份代替。其他魔门须有正文确认的魔门标签。 天气为双方共享：雷伤沿用公共雷雨强度1/2/3的10%/15%/20%增益，不另叠一套；本门同源雷劫持续伤害同样读取当前公共环境一次。雷雨可由自然场景、本门或其他真实来源提供，梦境景象不提供借天荡魔和聚雷优惠。室内/洞穴及明确遮蔽可阻止公共引天；不取消原有本门雷域。公共天气按自身期限、来源存活和覆盖规则变化，与施法者私有雷域分别保存、各自到期；引天失败不重复付款。战后只回传真实环境结算，不将临时天气永久写入世界。","playerPos":"以己身之雷引动九天雷霆。雷意留在敌人体内，既能追击渡劫，也能唤来天雷相助。","playerSigs":{"神雷伏魔":"本门雷招威力更强。命中后积蓄荡魔之力，可用于追雷与聚雷。 对魔门中人更具威力。 真实雷雨中，首次有效出招还能借天势积蓄荡魔。","回雷抱元":"敌身雷意也可收回己用，补足护体真气。","渡世雷劫":"雷招命中会留下雷劫，持续伤害敌人，并削弱其防御。","电闪雷鸣":"雷光、雷蛇命中后，可以循雷追击。","以身引天":"雷域能感应你留下的雷劫，自行引天雷追敌。 释放时尝试引来公共雷雨，盛势雷雨可助你更快聚雷。"}},"yunlong":{"name":"云龙九现","lv":"先天","type":"轻功","适器":[],"yuan":"前朝行走十三州的说书人武人所创，一生见龙三回揉进腿法，刻于琼州云海崖壁；后世无人修全。","requirement":"五境八关以上；已有一门轻功圆满。","pos":"身法极致，虚实相参：九处现形，一身为真。攻势留在影中，本体可另行攻守；虚影用于借形或龙隐，照现用于实击与九现归一。","passive":"速度+30、先天轻功闪避加成20%、闪避等级+2，沿用原有一次装配口径；速度不直接加闪避概率。","sigs":[["虚影","虚影上限6；云龙主攻击有效命中整招+1，龙行三叠按有效段最多+3；其他外功主攻击整招+1；成功闪避每回合+1；不再自动换闪。",0],["龙隐云现","本门踏雪或龙隐实际新增闪避层时照现+1；成功闪避每回合+1，上限9。龙隐另留一具虚身，承接下次非范围、非必中、非追踪攻势的一半伤害；虚身至本体下次行动前消散。仅回风／踏虚／九现消费照现，普通攻击保留。",1],["回风照影","本轮或上轮真实成功闪避后，下次有效云龙主攻击可消费1照现和10内力接回风；与龙隐／借形三选一，资格一次、收尾结束即失效。",2],["九虚一实","九现归一至少6照现，花当前全部；6至8蓄势1，9即发，独立增伤10%/层，圆满12%/层；释放后不开放龙隐或回风。",3],["照影成真","有效云龙主招后，借形耗虚影3及内力15留下原招35%倍率、同段数的影招，在本体下次行动前先行出手，即使本体被控也照常结算。只保留伤害倍率，不复制效果、穿透、九现或其他武学连锁；与龙隐／回风三选一。",2]],"moves":[{"id":"xh","name":"虚晃一现","tier":0,"type":"hybrid","hpR":0.3,"qqR":0.15,"cost":5,"cd":0,"desc":"挂破绽1回合；获得1虚影。","innateNative":true,"fx":[["破绽",1,1]],"playerDesc":"身形乍现，突袭敌人的空隙，造成少量伤害。"},{"id":"tx","name":"踏雪无痕","tier":1,"type":"self","hpR":0,"qqR":0,"cost":5,"cd":2,"desc":"耗耐力15；占主动作，新增1闪避判定和1虚影，实际加层时照现+1；共用龙隐调息，层满或法相中不可施展。","innateNative":true,"nai":15,"playerDesc":"踏雪无痕，增添闪避机会，并积蓄虚影与照现。"},{"id":"hide","name":"踏雪无痕·龙隐","tier":1,"type":"self","hpR":0,"qqR":0,"cost":5,"cd":2,"desc":"有效主攻击后，耗内力5、虚影3及耐力10，新增1闪避判定和1照现，留下虚身承接下次普通单体攻势50%伤害；虚身在本体下次行动前消散。免主动作；与回风／借形三选一；共用踏雪调息。","innateNative":true,"nai":10,"free":"combo","sharedCooldown":"tx","playerDesc":"云龙攻势命中后隐去真身，让虚身承受下一次寻常单体攻势的一半伤害。"},{"id":"lx","name":"龙行三叠","tier":2,"type":"hybrid","hpR":1.8,"qqR":0.9,"cost":20,"cd":2,"desc":"三段有效命中各+1虚影，整招最多3。","innateNative":true,"segs":[{"hpR":0.5,"qqR":0.25},{"hpR":0.6,"qqR":0.3},{"hpR":0.7,"qqR":0.35}],"playerDesc":"如龙行云，连续出手，造成中等伤害。"},{"id":"return","name":"龙行三叠·回风","tier":2,"type":"hybrid","hpR":0.8,"qqR":0.4,"cost":10,"cd":2,"desc":"有效云龙主攻击后，消耗1照现；本轮或上轮须成功闪避，免主动作，不再积影；与龙隐／借形三选一。","innateNative":true,"free":"combo","playerDesc":"闪过敌袭后顺势回身，借刚才的云龙攻势追击，造成少量伤害。"},{"id":"tt","name":"踏虚一腿","tier":3,"type":"hybrid","hpR":1.4,"qqR":1.4,"cost":30,"cd":2,"desc":"消耗3照现；本次真气穿透+10点。","innateNative":true,"playerDesc":"踏虚越隙，一击直入，造成较高伤害，且更易穿透真气防御。"},{"id":"jx","name":"九现归一","tier":3,"type":"hybrid","hpR":3.6,"qqR":1.4,"cost":50,"cd":6,"desc":"耗耐力30及当前全部6至9照现；6至8蓄势1，9即发；每层独立增伤10%，圆满12%；本招不接龙隐或回风。","innateNative":true,"nai":30,"charge":1,"playerDesc":"将多处照现归于真身，发出高额一击。照现越充足，威力越强；积至九现即可直接出手。"},{"id":"echo","name":"游龙借形","tier":2,"type":"hybrid","hpR":0,"qqR":0,"cost":15,"cd":2,"desc":"有效云龙主招后，耗虚影3及内力15留下原招35%倍率、同段数的影招；本体下次行动前先行出手，可在本体被控时结算。绑定原目标，原目标退场则影散；不复制效果、穿透或九现。免主动作，与龙隐／回风三选一。","free":"combo","innateNative":true,"playerDesc":"借刚才的云龙主招留下影形。影招在你下次行动前先行出手，以较弱威力再袭原来的敌人。"}],"breakthrough":"身与影分担攻守：影招下次本体行动前独立出手，虚身承接一次单体普通攻势。","boundaries":"每人最多一记待发影招。影招攻击面板在借形时快照，命中/会心/会意照常判定，防御/抗性/闪避/格挡/护体按目标当时状态；只伤原目标，原目标或本体退场则消散。借形预付内力，触发时不重复扣费；原招或借形内力不足而退化时，影招不恢复真气段。影招不生成资源、不触发攻击侧其他武学连锁，闪避反击无实体可击。虚身不是额外参战单位、不增加行动；只承接一次普通单体物理/真气攻势的一半伤害，多段只挡一段，不挡神魂、持续伤害、范围、必中、追踪、法相攻势，法相中也不生效；完全闪避不消耗虚身，承接本身不视为成功闪避。资源、影招与虚身战斗结束清除，圆满只提高九现归一每层增伤至12%，入室即可成完整体系。","playerPos":"身法臻至虚实相生，九处现形，一身为真。闪转间积蓄照现之机，以虚身承敌、以影招先行。","playerSigs":{"虚影":"云龙攻势与成功闪避能积蓄虚影，可用来隐身或留下影招。","九虚一实":"照现汇聚，能化为更强、更快的归一之击。","龙隐云现":"添上闪避机会或成功闪避，都会积蓄照现，为重招寻找时机。","回风照影":"成功闪避后，可借下一次云龙攻势回身追击。","照影成真":"虚影可以承接敌招，也能留下独立出手的影招。"},"bonuses":[{"slot":1,"name":"游龙养息","key":"最大耐力","mode":"ratio","value":0.1},{"slot":2,"name":"照影辨形","key":"精准率","mode":"flat","value":6}]}}};
function innateState(f){return f.innate||(f.innate={version:2,serial:0,storm:{dm:0,domainUntil:0,domainSerial:0,field:null},cloud:{xy:0,zx:0,dodgeRound:-99,lastDodge:-99,shadow:null,body:null},window:null});}
function innateOwns(f){return !!(f?.arts?.jiuxiao||f?.arts?.yunlong);}
// Only current structured affiliation/tags authorize the conditional bonus; names and learned arts do not.
function innateIdentity(facts){const faction=String(facts?.所属势力||'').trim(),tags=Array.isArray(facts?.身份标签)?facts.身份标签.filter(t=>typeof t==='string'):[];return {faction,tags:copy(tags),demon:tags.includes('魔门')||['天魔阁','血神宫'].includes(faction.split(/\s*[-—·/]\s*/).pop())};}
function innateDemonMultiplier(f,def){return hasSig(f,'jiuxiao','神雷伏魔')&&def?.identity?.demon===true?1.25:1;}
function innateMirror(f){if(!f.innate)return;f.as.dm=f.innate.storm.dm;f.as.xy=f.innate.cloud.xy;f.as.zx=f.innate.cloud.zx;}
function innateInit(f){if(innateOwns(f)){innateState(f);innateMirror(f);}}
function innateLei(def,atk){return def?.statuses.find(s=>s.innateLei&&s.ownerKey===(atk.groupId||atk.side));}
function innateLeiDef(f){return Math.max(0,...f.statuses.filter(s=>s.name==='雷劫').map(s=>Math.min(5,s.stacks||0)));}
// Borrow only real public thunderstorm weather. Dream scenery cannot supply physical lightning.
function innateThunderWeather(){const env=dreamEnv(),view=env.physicalView();return env.physicalTags().includes('雷')?view.天气强度:0;}
function innateGatherCost(f){return innateThunderWeather()>=2?2:3;}
function innateWindow(f,m){const s=innateState(f);if(!s.window||s.window.serial!==m.innateSerial||s.window.round!==round)s.window={serial:m.innateSerial,round,gainedVirtual:0,dmGiven:false,cloudEligible:false,cloudSpent:false,returnEligible:false,chased:false};return s.window;}
function innateOpenDomain(f,m){
 if(m.innateLegacy||m.innateSerial===undefined)return;const s=innateState(f),w=innateWindow(f,m);if(w.fieldOpened)return;w.fieldOpened=true;
 const env=dreamEnv(),id=protoKey(f)+'/jiuxiao/'+m.innateSerial,options={sourceId:protoKey(f),sourceName:f.name+'·以身引天',turns:3,strength:profTier(f,'jiuxiao')>=4?2:1,area:'全场',keepAfterDeath:false};
 const change=env.add('雷雨',options,round,id);
 log(f.name+(change.changed?'以身引天：引来'+options.strength+'级雷雨3回合':'以身引天：'+(change.reason==='sheltered'?'遮蔽阻隔，未改变公共天气':change.reason==='weaker weather'?'未盖过更强天气，借用现有天势':'公共天气未重复改变')),'sig');
 s.storm.domainUntil=round+2;s.storm.domainSerial=m.innateSerial;s.storm.field={until:round+2,lastRound:round-1,gathered:!!m.innateFastDomain,source:innatePower(f,'jiuxiao')};log(f.name+'布下雷域3回合，回合末循同源雷劫引天雷','sig');
}
function innateActionTarget(f,a){return GROUP_ENABLED&&a.targetIds?.length===1?groupFind(a.targetIds[0])||groupOpponent(f):groupOpponent(f);}
function innatePrepare(f,m){
 if(!m||m.innateLegacy)return m;let out={...m};
 if(out.art==='jiuxiao'&&out.id==='ly'){out.qqR=profTier(f,'jiuxiao')>=4?7.6:6.4;out.charge=out.innateMode==='聚雷'?1:2;if(out.innateMode==='聚雷')out.chargeProtection='强韧';}
 if(out.art==='yunlong'&&out.id==='jx'){const n=out.innateZxPaid??innateState(f).cloud.zx;out.charge=n>=9?0:1;out.innateCloudMultiplier=1+n*(profTier(f,'yunlong')>=4?.12:.10);}
 if(out.sharedCooldown)out.key=out.art+'/'+out.sharedCooldown;
 return out;
}
function innatePool(f,all){
 if(!innateOwns(f))return all;const state=innateState(f),out=[];
 for(const original of all){let m={...original,desc:original.playerDesc||original.desc};
  if(m.art==='jiuxiao'&&m.id==='ly'){m.innateMode='常式';m.displayName=m.name+' · 常式';out.push(innatePrepare(f,m));if(state.storm.dm>=innateGatherCost(f))out.push(innatePrepare(f,{...original,id:'ly',key:'jiuxiao/ly-fast',innateMode:'聚雷',displayName:original.name+' · 聚雷'}));continue;}
  if(m.innateNative&&m.free&&!state.window)continue;
  out.push(m.art==='yunlong'&&m.id==='jx'?innatePrepare(f,m):m);
 }
 return out;
}
function dariBaseInnateReason(f,m,def){
 if(!m?.innateNative)return '';const s=innateState(f),w=s.window,cs=f.combo||{freeRound:-1,freeCount:0};
 if(m.sharedCooldown&&f.cds[m.art+'/'+m.sharedCooldown]>0||m.art==='jiuxiao'&&m.id==='ly'&&f.cds['jiuxiao/ly']>0)return '共用调息中';
 if(m.free){if(!w||w.round!==round||w.serial!==s.serial)return '本次有效主攻击后的派生窗口未开启';if(cs.freeRound===round&&cs.freeCount>=COMBO_FREE_LIMIT)return '本轮免主动作派生次数已用尽';}
 if(m.art==='jiuxiao'){
  if(m.id==='chase'){if(!w.thunderTarget||w.thunderTarget!==(def?.groupId||def?.side)||w.chased)return '追雷仅限雷光／雷蛇命中的同一目标一次';if(s.storm.dm<1)return '需荡魔1层';if((innateLei(def,f)?.stacks||0)<3)return '需同源雷劫3层';}
  if(m.id==='judgement'&&(innateLei(def,f)?.stacks||0)<3)return '需目标同源雷劫3层';
  if(m.id==='reclaim'){if((innateLei(def,f)?.stacks||0)<2)return '回雷需目标同源雷劫2层';if(f.exhaust>0)return '气竭期间无法回雷护体';if(!(f.qiMax>0)||f.qi>=f.qiMax)return '护体真气已满或没有护体上限';}
  if(m.id==='ly'&&m.innateMode==='聚雷'&&s.storm.dm<innateGatherCost(f))return '聚雷需荡魔'+innateGatherCost(f)+'层';
 }
 if(m.art==='yunlong'){
  if(['tx','hide'].includes(m.id)){if(f.fxOn)return '法相存在期间无法闪避';if(f.dodgeL.length>=3)return '闪避判定层已满';}
  if(m.id==='hide'){if(!w.cloudEligible||w.cloudSpent)return '龙隐／回风／借形限本次主攻击后三选一';if(s.cloud.xy<3)return '需虚影3层';}
  if(m.id==='return'){if(!w.returnEligible||w.cloudSpent)return '需成功闪避后的有效云龙主攻击，且未选择龙隐';if(s.cloud.zx<1)return '需照现1层';}
  if(m.id==='echo'){if(s.cloud.shadow)return '已有待发影招';if(!w.cloudMove||w.cloudSpent||w.cloudTarget!==(def?.groupId||def?.side))return '借形须同一云龙主招命中的目标，收尾三选一';if(s.cloud.xy<3)return '借形需虚影3层';}
  if(m.id==='tt'&&s.cloud.zx<3)return '踏虚需照现3层';
  if(m.id==='jx'&&s.cloud.zx<6)return '九现需照现6层；9层即发';
 }
 return '';
}
function innateBegin(f,m,full){
 m=innatePrepare(f,m);if(!innateOwns(f)||m.innateLegacy||m.cycleInstant)return m;
 const s=innateState(f);if(!m.free){s.serial++;s.window={serial:s.serial,round,gainedVirtual:0,dmGiven:false,cloudEligible:false,cloudSpent:false,returnEligible:false,chased:false};}
 const out={...m,innateSerial:s.serial,innatePaidFull:full!==false};
 if(m.art==='jiuxiao'&&m.id==='ly')out.key='jiuxiao/ly';
 if(m.innateNative&&m.free&&!m.dariPair){const cs=comboState(f);if(cs.freeRound!==round){cs.freeRound=round;cs.freeCount=0;}cs.freeCount++;}
 if(m.art==='jiuxiao'&&m.id==='chase'){s.storm.dm--;s.window.chased=true;}
 if(m.art==='jiuxiao'&&m.id==='ly'&&m.innateMode==='聚雷'){out.innateDmPaid=innateGatherCost(f);s.storm.dm-=out.innateDmPaid;out.innateFastDomain=true;}
 if(m.art==='yunlong'){
  if(m.id==='hide'){s.cloud.xy-=3;s.window.cloudSpent=true;}
  if(m.id==='return'){s.cloud.zx--;s.window.cloudSpent=true;}
  if(m.id==='echo'){s.cloud.xy-=3;s.window.cloudSpent=true;out.innateEcho=copy(s.window.cloudMove);out.innateEchoTarget=s.window.cloudTarget;out.innateEchoFull=s.window.cloudFull!==false;}
  if(m.id==='tt')s.cloud.zx-=3;
  if(m.id==='jx'){out.innateZxPaid=s.cloud.zx;s.cloud.zx=0;}
 }
 innateMirror(f);return innatePrepare(f,out);
}
function innateAddDodge(f){if(f.fxOn||f.dodgeL.length>=3)return false;f.dodgeL.push({src:'云龙九现'});const s=innateState(f);if(profTier(f,'yunlong')>=1)s.cloud.zx=Math.min(9,s.cloud.zx+1);innateMirror(f);log(f.name+'云龙新增闪避判定 · 照现 '+s.cloud.zx+'/9','sig');qiushaCheck(f);return true;}
function innateDodge(f){if(!hasArt(f,'yunlong'))return;const s=innateState(f);if(s.cloud.dodgeRound===round)return;s.cloud.dodgeRound=round;s.cloud.lastDodge=round;s.cloud.xy=Math.min(6,s.cloud.xy+1);if(profTier(f,'yunlong')>=1)s.cloud.zx=Math.min(9,s.cloud.zx+1);innateMirror(f);log(f.name+'成功闪避 · 虚影 '+s.cloud.xy+'/6 · 照现 '+s.cloud.zx+'/9','sig');}
function innateSegment(f,def,m,out){if(m.innateSerial!==undefined&&!m.secondaryDirect&&!m.nineBurst&&out.effectHit&&out.dealt>0)m.innateHits=(m.innateHits||0)+1;}
function innateApplyLei(f,def,m){
 if(!hasSig(f,'jiuxiao','渡世雷劫')||def.hp<=0)return;
 let status=innateLei(def,f);if(!status){status={name:'雷劫',innateLei:true,ownerKey:f.groupId||f.side,owner:f.side,...(GROUP_ENABLED?{ownerId:f.groupId}:{}),src:'九霄雷诀',stacks:0,turns:4,elem:'雷',damage:true,appliedRound:-99,appliedCount:0};def.statuses.push(status);}
 if(status.appliedRound!==round){status.appliedRound=round;status.appliedCount=0;}
 const s=innateState(f),boost=s.storm.field?.gathered&&s.storm.domainUntil>=round&&s.storm.domainSerial!==m.innateSerial?1:0,n=Math.min(2-status.appliedCount,(m.id==='ls'?2:1)+boost);
 if(n<=0)return;status.stacks=Math.min(5,status.stacks+n);status.appliedCount+=n;status.turns=4;status.fresh=true;status.qSnap=effQiAtk(f);status.snp=mkSnp(f);log(def.name+'同源雷劫 '+status.stacks+'/5（本轮施加 '+status.appliedCount+'/2）','sig');
}
function innateRecord(f,def,m,out){
 if(!innateOwns(f)||m.innateSerial===undefined||m.innateLegacy)return;const s=innateState(f);
 const w=innateWindow(f,m);
 if(m.art==='yunlong'&&['tx','hide'].includes(m.id)){if(innateAddDodge(f)){if(m.id==='tx')s.cloud.xy=Math.min(6,s.cloud.xy+1);else{s.cloud.body={untilActor:true};log(f.name+'龙隐：虚身承接下次单体普通攻势的一半伤害，至下次自身行动','sig');}innateMirror(f);}return;}
 if(!out?.effectHit||!(m.innateHits>0)||m.free||m.reaction||m.secondaryDirect||m.nineBurst)return;
 if(hasArt(f,'yunlong')&&!(m.art==='yunlong'&&m.id==='jx')){
  const ceiling=m.art==='yunlong'&&m.id==='lx'?3:1,gain=Math.max(0,Math.min(ceiling-w.gainedVirtual,m.innateHits));s.cloud.xy=Math.min(6,s.cloud.xy+gain);w.gainedVirtual+=gain;w.cloudEligible=true;
  if(m.art==='yunlong'&&profTier(f,'yunlong')>=2&&!w.returnEligible&&s.cloud.lastDodge>=round-1){w.returnEligible=true;s.cloud.lastDodge=-99;}
  if(m.art==='yunlong'){w.cloudMove={name:m.name,segs:copy(m.segs||[{hpR:m.hpR,qqR:m.qqR}])};w.cloudTarget=def.groupId||def.side;w.cloudFull=m.innatePaidFull!==false;}
  innateMirror(f);
 }
 if(m.art==='jiuxiao'){
  if(hasSig(f,'jiuxiao','神雷伏魔')&&!w.dmGiven){s.storm.dm=Math.min(3,s.storm.dm+1);w.dmGiven=true;if(innateThunderWeather()>0&&s.storm.borrowRound!==round){s.storm.borrowRound=round;const gained=Math.min(1,3-s.storm.dm);s.storm.dm+=gained;log(f.name+'借天行雷：本回合首次有效主攻击，荡魔+'+gained,'sig');}innateMirror(f);log(f.name+'荡魔 '+s.storm.dm+'/3','sig');}
  if(m.id==='judgement'&&def.hp>0){const old=innateLei(def,f),n=old?.stacks||0;if(n>=3){strike(f,def,{...m,name:'九霄落雷·天雷',innateHits:0,secondaryDirect:true,fx:[]},0,1.05*n,'九霄落雷·天雷',true);def.statuses=def.statuses.filter(x=>x!==old);log(f.name+'主动渡劫 · 消耗 '+n+'同源雷劫','sig');}}
  innateApplyLei(f,def,m);
  if(['lg','ls'].includes(m.id)&&def.hp>0&&(!GROUP_ENABLED||GROUP_CAST_INDEX===0))w.thunderTarget=def.groupId||def.side;
 }
}
function innateCast(f,def,m,full){if(!m.innateNative)return null;
 if(m.art==='jiuxiao'&&m.id==='ly')innateOpenDomain(f,m);
 if(m.art==='jiuxiao'&&m.id==='reclaim'){const mark=innateLei(def,f);mark.stacks-=2;if(mark.stacks<=0)def.statuses=def.statuses.filter(x=>x!==mark);const gained=Math.min(f.qiMax-f.qi,Math.round(f.qiMax*.1));f.qi+=gained;log(f.name+'回雷抱元：回收2雷劫，护体真气+'+gained,'sig');return {outcome:{effectHit:false,dealt:0}};}
 if(m.art==='yunlong'&&m.id==='echo'){innateState(f).cloud.shadow={target:m.innateEchoTarget,source:innatePower(f,'yunlong'),move:{name:'游龙借形·'+m.innateEcho.name,art:'yunlong',type:'hybrid',segs:m.innateEcho.segs.map(s=>({hpR:s.hpR*.35,qqR:s.qqR*.35})),fx:[],secondaryDirect:true,innateIndependent:true},full:full!==false&&m.innateEchoFull!==false};log(f.name+'游龙借形：留下【'+m.innateEcho.name+'】35%影招，于本体下次行动前独立出手','sig');return {outcome:{effectHit:false,dealt:0}};}
 if(['tx','hide'].includes(m.id)&&m.art==='yunlong'){log(f.name+'施展【'+m.name+'】','rnd');return {outcome:{effectHit:false,dealt:0}};}return null;}
function innateThunderMultiplier(f,m,def){return (m.innateLegacy?1.3:profTier(f,'jiuxiao')>=4?1.36:1.3)*(m.innateLegacy?1:innateDemonMultiplier(f,def));}
function innatePreview(f,m){if(!m.innateNative)return {};const p=innatePrepare(f,m);let resourceText='';if(m.art==='jiuxiao'){if(m.id==='chase')resourceText='耗荡魔1';if(m.id==='judgement')resourceText='耗目标旧雷劫全部（至少3层）';if(m.id==='reclaim')resourceText='回收同源雷劫2 · 护体真气+10%';if(m.id==='ly')resourceText=(m.innateMode==='聚雷'?(m.innateDmPaid===undefined?'耗荡魔'+innateGatherCost(f):'已付荡魔'+m.innateDmPaid)+' · 强韧 · 强化挂劫':'保留荡魔 · 常式')+' · 雷域3回合 · 尝试引来'+(profTier(f,'jiuxiao')>=4?2:1)+'级雷雨3回合';}if(m.art==='yunlong'){if(m.id==='hide')resourceText='耗虚影3 · 留虚身 · 三选一';if(m.id==='return')resourceText='耗照现1 · 闪后回风 · 三选一';if(m.id==='echo')resourceText='耗虚影3 · 下次自身行动前影招35% · 三选一';if(m.id==='tt')resourceText='耗照现3 · 当次真气穿透+10';if(m.id==='jx')resourceText='耗照现全部 '+innateState(f).cloud.zx+'层 · '+(p.charge?'蓄势后释放':'九现即发');}return {charge:p.charge||0,resourceText};}
// Store power without nesting a fighter's existing weather/shadow or inheriting other arts' proc state.
function innatePower(f,art){const p=copy({...f,innate:null,cycle:null});p.base.wMin=effWMin(f)*zyWmin(f);p.base.wMax=effWMax(f);p.base.qiMin=effQiMin(f);p.base.qiAtk=effQiAtk(f);p.hhCasterId=hhKey(f);p.arts={[art]:copy(f.arts[art])};p.statuses=[];p.as={};p.zyEff=p.zyEff.filter(x=>x.k!=='wminMul');p.cj=null;p.xl=null;p.nili=null;p.jian=null;p.nine=null;p.drunk=null;p.fxOn=p.fxDebuff=false;p.critTmp=0;p.swordBonus=0;return p;}
function innateIndependent(source,def,m,full){let dealt=0;const segs=m.segs||[{hpR:m.hpR||0,qqR:m.qqR||0}];for(let i=0;i<segs.length&&!over&&groupActive(def);i++){const part=segs[i];dealt+=strike(source,def,m,part.hpR,part.qqR,m.name+(segs.length>1?'·段'+(i+1):''),full).dealt||0;checkEnd(def);}return dealt;}
function innateEndRound(){for(const f of groupActors()){const s=f.innate,field=s?.storm.field;if(!field)continue;if(!groupActive(f)||round>field.until){s.storm.field=null;s.storm.domainUntil=0;continue;}if(field.lastRound===round)continue;field.lastRound=round;
 const targets=groupActors().filter(t=>groupActive(t)&&t.side!==f.side&&(innateLei(t,f)?.stacks||0)>0).sort((a,b)=>(innateLei(b,f)?.stacks||0)-(innateLei(a,f)?.stacks||0)||String(a.groupId||a.side).localeCompare(String(b.groupId||b.side)));
 if(targets.length){for(const target of targets){if(over||!groupActive(f))break;log(f.name+'雷域感应 → '+target.name,'sig');innateIndependent(field.source,target,{name:'雷域·感应天雷',art:'jiuxiao',type:'pure',hpR:0,qqR:1.65,range:true,secondaryDirect:true,innateIndependent:true},true);}}else log(f.name+'雷域：同源雷劫已断，天雷无从感应','sig');
 if(round===field.until){s.storm.field=null;s.storm.domainUntil=0;}if(over)break;
}}
function dreamBaseInnateBeforeActor(f){if(!f.innate)return;const c=f.innate.cloud;c.body=null;const shadow=c.shadow;if(!shadow)return;c.shadow=null;const target=groupActors().find(t=>(t.groupId||t.side)===shadow.target);if(groupActive(f)&&groupActive(target)&&target.side!==f.side){log(f.name+'影招先行，本体另待行动','sig');innateIndependent(shadow.source,target,shadow.move,shadow.full);}else log(f.name+'影招：原目标或本体已退场，影散','sig');}
function innateBody(def,atk,m,raw,L){if(!(raw>0)||!def.innate?.cloud.body||def.fxOn||atk.fxOn||m.range||m.mustHit||hasSig(atk,'jian','我见真我，我剑非剑'))return raw;def.innate.cloud.body=null;L.push('龙隐虚身承接一半攻势');return raw*.5;}
function dariBaseInnateTick(def,status){
 if(!status.innateLei)return false;const atk=GROUP_ENABLED?groupFind(status.ownerId):status.owner===P.side?P:E;if(!atk){status.fresh=false;status.turns--;return true;}
 let raw=(status.qSnap||0)*.10*status.stacks,quality='';if(status.snp){if(rnd()<wumingDotInsight(atk,def,status.snp.ins)){raw*=1.35+wumingJadeBonus(atk);quality=' · 会意';}else if(rnd()<status.snp.prec){if(rnd()<status.snp.crit){raw*=1.5;quality=' · 会心';}}else{raw*=.7;quality=' · 擦伤';}}
 raw*=dreamEnv().factor('雷',protoArea(def))*innateDemonMultiplier(atk,def)*nineDot(atk,def,status)*realmFactor(atk,def)*(1+zySum(atk,'dotAmp'))*penZone(penV(atk,'q',def,null),resV(def,'q',atk))*effDR(def)*hhTiger(atk,def);if(def.dotImmunities?.includes('雷劫'))raw=0;
 const shield=jianShield(atk,def,raw);def.qi-=shield.spent;qiBurn(def,shield.spent);const before=def.hp;dealHp(def,Math.round(Math.max(0,raw-shield.absorb)));const lost=hpLost(def,before);curioPeriodicAfter(atk,def,lost);nineLifesteal(atk,{}, {hpLost:lost});log(def.name+'受同源雷劫 '+status.stacks+'层 · 实扣 '+lost+quality,'dmg');
 status.fresh=false;status.turns--;if(def.qi<=0&&def.exhaust<=0){def.qi=0;def.exhaust=3;}checkEnd(def);return true;
}
function innateCloseWindow(f){if(f.innate)f.innate.window=null;}
function innateClear(f){if(f.innate){const s=f.innate;s.storm.dm=0;s.storm.borrowRound=-99;s.storm.domainUntil=0;s.storm.field=null;s.cloud.xy=s.cloud.zx=0;s.cloud.lastDodge=-99;s.cloud.shadow=s.cloud.body=null;s.window=null;innateMirror(f);}f.statuses=f.statuses.filter(x=>!x.innateLei);}
function innateRestore(){if(!saved.innateRevision)for(const f of groupActors())f.statuses=f.statuses.filter(x=>!(x.name==='雷劫'&&x.src==='九霄雷诀'&&!x.innateLei));for(const f of groupActors()){
 if(!innateOwns(f))continue;if(f.innate?.version===1){f.innate.version=2;f.innate.storm.field=null;f.innate.storm.domainUntil=0;f.innate.cloud.shadow=f.innate.cloud.body=null;}const old=!f.innate||f.innate.version!==2;
 if(old){if(f.charging&&['jiuxiao','yunlong'].includes(f.charging.mv.art)){f.charging.mv.innateLegacy=true;if(f.charging.mv.art==='yunlong')f.charging.mv.innateCloudMultiplier=1+.15*(f.as.zx||0);}delete f.innate;innateInit(f);f.statuses=f.statuses.filter(x=>!(x.name==='雷劫'&&x.src==='九霄雷诀'));for(const id of ['jiuxiao','yunlong']){const art=f.arts[id],a=INNATE_CONFIG.arts[id];if(!art)continue;art.moves=a.moves.filter(m=>m.tier<=art.tier).map(m=>m.name);art.sigs=a.sigs.filter(x=>x[2]<=art.tier).map(x=>x[0]);}}
 innateMirror(f);
 }}

/* Private native rules for seasonal transformation and caster-owned dreams. */
const CYCLE_CONFIG={"revision":2,"arts":{"sixiang":{"name":"四象归元","lv":"先天","type":"内功","适器":[],"pos":"四时生化：以春生、夏长、秋收、冬藏改变余息用途，能独立主攻，也能回护队友与接引属性攻势。","yuan":"上古先天武学；春秋残篇归春秋禅公孙茗，夏冬残篇归天人宫；集齐四篇融会贯通。","requirement":"悟性契合自然生化；缺篇不能施展该季法，四篇齐备方能归一。","bonuses":[{"slot":1,"name":"元息","key":"真气防御","mode":"flat","value":8},{"slot":2,"name":"知时","key":"会意率","mode":"flat","value":1}],"sigs":[["四时无常","随机天时每4回合改变；对应门施展效力增强5%，不封锁其他已掌握法门，不需要额外轮转动作。",0],["四时生化","夏秋收尽剩余炎息、夏冬消费一跳相激；春冬将剩余持续治疗转屏障，冬春把剩余屏障转实际治疗。消费部分不再后续结算，每主施展最多计一次有效生化。",1],["四季归元","四篇齐备，完成一次有效本门生化，下一次主招效力增强25%；同次正常扣费和占主动作，不额外加行动。",1],["春冬加护","春法治疗、冬法屏障对队友附加2回合加护，下次正常纯真气或混元攻击各段增强10%；同源刷新不叠，自己不获得自己的攻击增益，免费派生／应变不消费。",1],["四象相引","其他火雷功法有效命中消耗一份同阵营炎息；寒冰水消耗一份寒息，按该份未来伤害1.10倍立即兑现；每来源／目标／回合一次，不加归元进度，不递归或由免费派生触发。",1]],"moves":[{"id":"springSingle","name":"春息回护","book":"春","tier":1,"type":"self","qqR":0,"cost":25,"friendly":true,"healRatio":1,"hotRatio":0.32,"hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"春门共用调息，施展后下一回合不可再施同门。回护按本门生化规则结算。","playerDesc":"以春息滋养自己或队友，立即回护，并在随后数回合继续恢复气血。","effect":"healRunwu","targetPolicy":{"team":"ally","scope":"single","includeSelf":true,"allowDefeated":false}},{"id":"springGroup","name":"春雨解厄","book":"春","tier":2,"type":"self","qqR":0,"cost":35,"friendly":true,"range":true,"healRatio":0.7,"hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"春门共用调息，施展后下一回合不可再施同门。回护按本门生化规则结算。","playerDesc":"春雨遍及同伴，回复气血，并为每人化去一种可清理的战斗负面状态。","effect":"healRunwu","targetPolicy":{"team":"ally","scope":"all","includeSelf":true,"allowDefeated":false}},{"id":"springMana","name":"运息归元","book":"春","tier":2,"type":"self","qqR":0,"cost":10,"friendly":true,"nai":15,"hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"春门共用调息，施展后下一回合不可再施同门。回护按本门生化规则结算。","playerDesc":"运转元息恢复内力与护体真气，需花费一次行动和少量耐力。","effect":"healRunwu","targetPolicy":{"team":"ally","scope":"single","includeSelf":true,"allowDefeated":false}},{"id":"summerSingle","name":"烈日熔金","book":"夏","tier":1,"type":"pure","qqR":3.4,"cost":40,"elem":"火","hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"夏门共用调息，施展后下一回合不可再施同门。攻击按本门生化规则结算。","playerDesc":"烈阳凝作一击，造成高额伤害，留下一缕炎息。"},{"id":"summerFire","name":"火云满山","book":"夏","tier":2,"type":"pure","qqR":2.5,"cost":35,"range":true,"elem":"火","hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"夏门共用调息，施展后下一回合不可再施同门。攻击按本门生化规则结算。","playerDesc":"夏火漫过群敌，造成较高伤害，留下较持久的炎息。"},{"id":"summerCharge","name":"炎天破阵","book":"夏","tier":3,"type":"pure","qqR":5.8,"cost":60,"range":true,"charge":1,"elem":"火","hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"夏门共用调息，施展后下一回合不可再施同门。攻击按本门生化规则结算。","playerDesc":"短暂蓄势后倾泻炎天之势，对群敌造成极高伤害，并留下较强炎息。"},{"id":"autumnHarvest","name":"秋意收尽","book":"秋","tier":2,"type":"pure","qqR":2.2,"cost":30,"hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"秋门共用调息，施展后下一回合不可再施同门。攻击按本门生化规则结算。","playerDesc":"秋意一收，造成较高伤害；若敌人仍有你的炎息，将剩余火势一并收尽。"},{"id":"autumnDispel","name":"落木萧萧","book":"秋","tier":3,"type":"pure","qqR":2.6,"cost":35,"hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"秋门共用调息，施展后下一回合不可再施同门。攻击按本门生化规则结算。","playerDesc":"以秋风破势，造成高额伤害，并散去敌人一种可驱散的临时强化。"},{"id":"autumnWither","name":"金风凋露","book":"秋","tier":2,"type":"pure","qqR":2.4,"cost":30,"hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"秋门共用调息，施展后下一回合不可再施同门。攻击按本门生化规则结算。","playerDesc":"金风凋露，造成较高伤害，并短暂压低敌人获得的治疗。"},{"id":"winterControl","name":"万里凝","book":"冬","tier":2,"type":"pure","qqR":2.1,"cost":30,"elem":"寒","hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"冬门共用调息，施展后下一回合不可再施同门。攻击按本门生化规则结算。","playerDesc":"寒息凝入敌身，造成较高伤害并牵制行动；与自己的炎息相接时，可进一步令其失去行动。"},{"id":"winterSingle","name":"千山暮雪","book":"冬","tier":1,"type":"self","qqR":0,"cost":25,"friendly":true,"wardRatio":1.6,"hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"冬门共用调息，施展后下一回合不可再施同门。回护按本门生化规则结算。","playerDesc":"为自己或队友凝成较厚屏障；若尚有你的春息滋养，可将余力一并收为防护。","effect":"healRunwu","targetPolicy":{"team":"ally","scope":"single","includeSelf":true,"allowDefeated":false}},{"id":"winterGroup","name":"霜天护野","book":"冬","tier":3,"type":"self","qqR":0,"cost":35,"friendly":true,"range":true,"wardRatio":1,"hpR":0,"cd":0,"cycleNative":true,"four2":true,"desc":"冬门共用调息，施展后下一回合不可再施同门。回护按本门生化规则结算。","playerDesc":"冬藏之息护住同伴，每人获得较薄屏障，可接续各人身上的春息。","effect":"healRunwu","targetPolicy":{"team":"ally","scope":"all","includeSelf":true,"allowDefeated":false}}],"boundaries":"新四象使用私有炎息、寒息、生息、藏息、秋凋和春冬加护，不改变公共灼伤与冻伤定义。旧本门词条只作历史兼容；旧已付费蓄势按捕获招式结算、不重扣费。余息绑定来源与目标，不回滚已结算收益。选择季法只展开菜单，确认出招一次本地结算，不调用生成API。","playerPos":"通晓真气的生、长、收、藏。春息能转成屏障，炎息能提前收尽，冬藏余力又能化作回护；四门各有用途，可随战况选择。","playerSigs":{"四时无常":"顺时施展稍有助益，仍可自由选择需要的季法。","四时生化":"让尚未散尽的力量改变用途：火势可提前收尽，滋养可化屏障，屏障可化回护。","四季归元":"四篇齐备，生化有成后，下一招会更强。","春冬加护":"回护队友时一并为其加护，使他下一次正常攻势更强。","四象相引":"炎息可接引火雷攻势，寒息可接引寒水攻势，提前兑现一部分持续伤害。"},"revision":2,"values":{"enabled":true,"bookCd":2,"guiNeed":1,"guiAmp":1.25,"gui":true,"convert":true,"convertAmp":1.2,"coldRatio":0.2,"allyAmp":0.1,"link":true,"linkAmp":1.1,"manaReturn":90,"attackScale":1.75,"fireRatio":0.5}},"dameng":{"name":"大梦神功","lv":"先天","type":"奇门","适器":[],"pos":"以梦探心，以幻诱守。梦意由各人分别施下，己方梦境助势；真实骗守即刻梦醒，深梦可汇成一式千秋。","yuan":"大梦教前帮主梦无双所创，圆满仅梦无双达到；现世残卷，赫连博山强修半部心境大损。","requirement":"由五感深入潜意识，再以幻象影响实物；明确仅修半部／残卷最高登堂，全卷或另悟可继续。","bonuses":[{"slot":1,"name":"明镜","key":"精准率","mode":"flat","value":3},{"slot":2,"name":"心渊","key":"神魂穿透","mode":"flat","value":4}],"sigs":[["引梦","本门主动有效命中引梦，迷魂引整招两层；其他敌人各独立50%概率同源一层，整招一次不连锁。",0],["虚实相生","实击照常结算；虚招须有可诱导的普通守势，真实移除一份，立即兑现梦醒并引梦；未移除则不触发。",1],["梦中留身","沿用已登记的梦中身：单体普通主攻可能落在梦身，至自身下次行动前散去。",2],["梦为天地","场景由场主控制，神魂助势仅给同阵营；入梦仍按来源分别保存，梦境不改写现实天气。",3],["幻实归一","幻刃按目标同源梦深增强，千秋汇总在场敌人的同源梦意并按梦深分伤，均不消耗梦层。",4]],"moves":[{"id":"guide","name":"迷魂引","tier":0,"type":"pure","qqR":3,"cost":15,"cd":0,"kind":"attack","playerDesc":"幻音扰心，随己方梦境逐渐增强；镜庭连响，梦天地时直侵神魂，命中加深此人入梦。此人的同源入梦达到十层后，命中可随机附加一种负面状态，持续一回合，每六回合仅一次。","hpR":0,"fx":[],"cycleNative":true,"dreamNative":true,"desc":"无己方场／梦雾／镜庭／梦天地总真气倍率分别3.0／3.3／3.6／3.9；镜庭两段合计，梦天地为神魂；有效命中整招积同源入梦2层。本招有效命中并加深入梦后，目标同源入梦达到10层时，随机附加1种公共负面状态，1层、持续1回合；施术者共用6回合间隔（第R回合触发后，第R+6回合可再次触发），换目标或多段不能绕过。只从可施加的公共负面中等概率抽取，不选增益、专属代价或免疫状态；不消耗入梦，不增加费用。"},{"id":"veil","name":"镜花水月","tier":1,"type":"pure","qqR":8,"cost":25,"cd":1,"kind":"illusion","playerDesc":"可虚可实。实击伤敌；虚招引走一份真实守势后即刻梦醒，并将梦意传向其他敌人。","hpR":0,"fx":[],"cycleNative":true,"dreamNative":true,"desc":"实击8.0普通真气倍率；虚招须移除目标一份普通闪避或格挡，立刻兑现5.7倍率神魂梦醒，积同源入梦2层、己方镜庭及以上3层；剩余守势仍接替。真实骗守时其他存活敌人必得同源1梦，无追加付款。"},{"id":"body","name":"梦中身","tier":2,"type":"pure","qqR":0.0,"cost":20,"cd":2,"kind":"body","playerDesc":"梦中留身，或守住真身。敌人若未看破，下一次单体攻势可能落在幻影之上。","hpR":0,"fx":[],"cycleNative":true,"dreamNative":true,"desc":"梦中留身，或守住真身。敌人若未看破，下一次单体攻势可能落在幻影之上。","targetPolicy":{"team":"enemy","scope":"single","includeSelf":false,"allowDefeated":false}},{"id":"field","name":"黄粱一梦","tier":2,"type":"pure","qqR":4.2,"cost":30,"cd":2,"kind":"field","playerDesc":"借目标梦深铺开己方梦境，梦越深，场景与己方神魂助势越强。","hpR":0,"fx":[],"cycleNative":true,"dreamNative":true,"desc":"须目标有自己所留入梦；按1／4／7层形成梦雾／镜庭／梦天地，神魂助势为场主同阵营4%／8%／12%，场景持续至本回合后两回合；不覆盖现实天气。"},{"id":"blade","name":"幻刃成真","tier":3,"type":"pure","qqR":3.6,"cost":40,"cd":2,"kind":"conversion","playerDesc":"凝梦成刃，梦越深，神魂伤害越高；施展后保留入梦。","hpR":0,"fx":[],"cycleNative":true,"dreamNative":true,"desc":"须目标至少同源入梦1层；神魂倍率3.6＋0.36×目标同源梦层，不消耗入梦，不额外引梦。"},{"id":"millennia","name":"大梦千秋","tier":4,"type":"pure","qqR":0,"cost":90,"cd":8,"charge":1,"range":true,"kind":"finish","playerDesc":"须己方梦天地，汇聚全场同源梦意；按梦深分向每名在场敌人，浅梦亦分得少量。蓄势后释放，不消耗梦层，失去己方梦天地则收招。","hpR":0,"fx":[],"cycleNative":true,"dreamNative":true,"desc":"起蓄与释放均须己方梦天地、全场同源总梦S至少1。释放时总基础威力为真气攻击×1.6×S，再按各目标(1＋同源梦层)/(S＋存活敌人数)分配；零层也分得少量。快照真气攻击、助势与各份额，随后分别走神魂防御；全招一次付款90、蓄势1、调息8，不耗梦、不引梦、不溅射、不重分被挡或过量份额。"}],"boundaries":"入梦按施术者与目标独立保存，每源最多十层；幻刃与千秋不消耗入梦。己方场景助势仅给场主同阵营，仍可由另一位大梦修炼者争夺。主动成功引梦时，其他在场敌人各有一半机会获同源一层；真实骗守必定外溢，整招一次、不连锁。神魂不扣外功／真气防御数值，仍过穿透、境界、通用减伤、格挡／闪避及护体真气条。梦中身沿用既有功能，未引入讨论中的改版；旧已付费蓄势与待揭晓梦招保留所捕获规则。","playerPos":"以梦探心，以幻诱守。梦意由各人分别施下，己方梦境助势；真实骗守即刻梦醒，深梦可汇成一式千秋。","playerSigs":{"引梦":"本门主动命中能加深此人的入梦，梦意也有机会传向其他敌人；真实骗守时必定外溢。","虚实相生":"实击伤敌；虚招引走一份真实守势后即刻梦醒，并加深此人入梦。","梦中留身":"布置梦身诱敌，或守住本体；一次普通单体主攻可能落在梦身，至自身下次行动前散去。","梦为天地":"梦境随深浅变化，为场主同阵营提供神魂助势；现实天气仍然存在。","幻实归一":"幻刃随此人的梦深增强；千秋汇聚全场同源梦意后分伤，两式均保留梦层。"},"values":{"enabled":true,"scale":1,"mode":"independent","revision":2,"guideDebuff":{"depth":10,"turns":1,"cooldown":6}}}}};
const CYCLE_SEASONS=['春','夏','秋','冬'];
function cycleKey(f){return f.groupId||f.side;}
function cycleOwns(f){return !!(f?.arts?.sixiang||f?.arts?.dameng);}
function cycleArtTier(id,tier,info){return id==='dameng'&&/残卷|仅[^。]*半部|上半部/.test(info?.特殊效果||'')&&!/补全|悟出下半|已得全卷/.test(info?.特殊效果||'')?Math.min(2,tier):tier;}
function cycleState(f){return f.cycle||(f.cycle={version:1,serial:0,window:null,four:{season:null,until:0,rolled:[],used:[],ready:false,wheelRound:-99,tySerial:-1,markSerial:-1,dual:null,seed:null},dream:{dodgeRound:-99}});}
function cycleChapters(info){const explicit=info?.篇章;if(Array.isArray(explicit)&&explicit.length)return CYCLE_SEASONS.filter(s=>explicit.includes(s)||explicit.includes(s+'篇'));const text=String(info?.特殊效果||''),hits=[...text.matchAll(/([春夏秋冬](?:[、/·与和及\s]*[春夏秋冬]){0,3})(?:两篇|二篇|残篇|残卷)/g)];return hits.length?CYCLE_SEASONS.filter(s=>hits.some(m=>m[1].includes(s))):CYCLE_SEASONS.slice();}
function baseCycleInit(f){f.cycleScoped=true;f.cycleMirror=f.rm||0;if(cycleOwns(f))cycleState(f);}
function baseCycleHasSeason(f,s){const c=f.cycle?.four;return !!c&&(c.season===s&&c.until>=round||c.dual?.until>=round&&c.dual.seasons.includes(s));}
function cycleDream(target,source){const mark=target?.statuses.find(s=>s.cycleKind==='dream'&&s.ownerKey===cycleKey(source));return mark?.stacks||(!target?.cycleScoped?target?.rm||0:0);}
function cycleMirrorDream(f){f.rm=Math.max(0,...f.statuses.filter(s=>s.cycleKind==='dream').map(s=>s.stacks));f.cycleMirror=f.rm;}
function cycleSetDream(target,source,n){let s=target.statuses.find(s=>s.cycleKind==='dream'&&s.ownerKey===cycleKey(source));n=Math.max(0,Math.min(10,n));if(!n){if(s)target.statuses=target.statuses.filter(x=>x!==s);}else if(s)s.stacks=n;else target.statuses.push({name:'入梦',label:'入梦·'+source.name,cycleKind:'dream',ownerKey:cycleKey(source),ownerId:source.groupId,owner:source.side,src:'大梦神功',stacks:n,turns:999});cycleMirrorDream(target);}
function cycleSource(s){return groupActors().find(f=>cycleKey(f)===s.ownerKey);}
function cyclePower(f,art){const p=innatePower({...f,cycle:null},art);p.cycle=null;return p;}
function cycleStatus(f,target,name,kind,turns,extra={}){let s=target.statuses.find(x=>x.name===name&&x.cycleKind===kind&&x.ownerKey===cycleKey(f));const value={name,cycleKind:kind,ownerKey:cycleKey(f),ownerId:f.groupId,owner:f.side,src:['dream','contract','seedDream','dreamDot'].includes(kind)?'大梦神功':'四象归元',stacks:1,turns,...extra};if(s)Object.assign(s,value);else{ s=value;target.statuses.push(s);}return s;}
function cycleOwnedStatus(target,f,kind,name){return target?.statuses.find(s=>s.cycleKind===kind&&s.ownerKey===cycleKey(f)&&(!name||s.name===name));}
function cycleStatusKey(s){return s.name+(s.src?'·'+s.src:'')+(s.cycleKind?'·'+s.ownerKey:'');}
function cycleTarget(f,a){return innateActionTarget(f,a);}
function baseCyclePool(f,list){if(!cycleOwns(f))return list;const out=[];for(const raw of list){const m={...raw,desc:raw.playerDesc||raw.desc};if(m.cycleNative&&m.id==='contract'){for(const mode of ['攻','守'])out.push({...m,key:'dameng/contract-'+mode,cycleMode:mode,displayName:m.name+' · '+mode+'约'});continue;}if(m.cycleNative&&m.id==='dual'){for(const mode of ['春夏','秋冬'])out.push({...m,key:'sixiang/dual-'+mode,cycleMode:mode,displayName:m.name+' · '+mode});continue;}if(m.cycleNative&&m.id==='seal'){for(const mode of ['灼伤','裂伤','冻伤'])out.push({...m,key:'sixiang/seal-'+mode,cycleMode:mode,displayName:m.name+' · '+mode});continue;}out.push(m);}return out;}
