function f4Enabled(f){return !!F4_CONFIG.enabled&&!!f?.arts?.sixiang;}
function f4State(f){if(!f.four2){f.four2={version:2,serial:0,cds:{},conversions:0,ready:false,lastConversion:-1,firstConversion:null,firstReady:null,guiUses:0,guiTurns:[],conversionEvents:[],fireCreated:0,fireTicked:0,fireConverted:0,fireReplaced:0,firePurged:0,coldCreated:0,coldTicked:0,coldConverted:0,coldReplaced:0,coldPurged:0,linkByTarget:{},linkEvents:[],season:'春'};f.arts.sixiang.sigs=F4_CONFIG.sigs.filter(s=>s[2]<=f.arts.sixiang.tier).map(s=>s[0]);f.as.ty=0;f.as.season=null;const seasons=f.arts.sixiang.chapters||CYCLE_SEASONS;f.four2.season=seasons[(rnd()*seasons.length)|0];}return f.four2;}
function f4Key(f){return f.groupId||f.side;}
function f4Own(target,source,kind){return target.statuses.find(s=>s.cycleKind==='four2'&&s.ownerKey===f4Key(source)&&s.subtype===kind&&s.turns>0);}
function f4Source(s){return groupActors().find(f=>f4Key(f)===s.ownerKey);}
function f4Status(f,t,kind,extra,turns){let s=f4Own(t,f,kind);if(s){if(['fire','cold'].includes(kind))f4State(f)[kind+'Replaced']+=s.turns;Object.assign(s,extra,{turns});}else{ s={name:{fire:'炎息',cold:'寒息',hot:'生息',ward:'藏息',wither:'秋凋',blessing:'春冬加护'}[kind],cycleKind:'four2',subtype:kind,ownerKey:f4Key(f),ownerId:f.groupId,src:'四象归元',stacks:1,turns,buff:['hot','ward','blessing'].includes(kind),damage:['fire','cold'].includes(kind),...extra};t.statuses.push(s);}return s;}
function f4Remove(t,s){t.statuses=t.statuses.filter(x=>x!==s);}
function f4Conversion(f,kind,amount,m){if(!(amount>0)||!F4_CONFIG.convert)return;const s=f4State(f);if(s.lastConversion===m.f4Serial)return;s.lastConversion=m.f4Serial;s.conversions++;s.firstConversion??=round;s.conversionEvents.push({round,kind,amount});if(s.conversions>=F4_CONFIG.guiNeed&&F4_CONFIG.gui&&(f.arts.sixiang.chapters||CYCLE_SEASONS).length===4){s.ready=true;s.firstReady??=round;s.conversions=0;}log(f.name+'四时生化：'+kind,'sig');}
function cycleInit(f){baseCycleInit(f);if(f4Enabled(f))f4State(f);}
function cycleHasSeason(f,s){return f4Enabled(f)?false:baseCycleHasSeason(f,s);}
function dreamBaseCyclePool(f,list){if(!f4Enabled(f))return baseCyclePool(f,list);const chapters=f.arts.sixiang.chapters||CYCLE_SEASONS;return [...baseCyclePool(f,list.filter(m=>m.art!=='sixiang')),...F4_CONFIG.moves.filter(m=>m.tier<=f.arts.sixiang.tier&&chapters.includes(m.book)).map(m=>({...m,desc:m.playerDesc||m.desc,art:'sixiang',key:'sixiang/'+m.id,cycleNative:true,four2:true,cd:0,hpR:0,fx:[],targetPolicy:{team:m.friendly?(GROUP_ENABLED?'ally':'self'):'enemy',scope:GROUP_ENABLED&&m.range?'all':'single',includeSelf:!!m.friendly,allowDefeated:false},...(m.friendly?{effect:'healRunwu'}:{})}))];}
function dreamBaseCyclePrepare(f,m){return m?.four2?m:baseCyclePrepare(f,m);}
function dreamBaseCycleReason(f,m,def){if(!m?.four2)return baseCycleReason(f,m,def);const c=f4State(f);if((c.cds[m.book]||0)>round)return '同门调息';if(m.id==='springMana'&&f.neili>=f.neiliMax-20)return '无需回气';return '';}
function dreamBaseCycleBegin(f,m,full){let out;if(m?.four2){const s=f4State(f);s.serial++;let amp=1;if(s.season===m.book)amp*=1.05;if(s.ready){s.ready=false;amp*=F4_CONFIG.guiAmp;s.guiUses++;s.guiTurns.push(round);}out={...m,f4Serial:s.serial,f4Amp:amp,qqR:(m.qqR||0)*F4_CONFIG.attackScale*amp};}else out=baseCycleBegin(f,m,full);
 if(!out.f4BlessingPaid&&!out.free&&!out.reaction&&!out.cycleInstant&&['pure','hybrid'].includes(out.type)){const choices=f.statuses.filter(s=>s.cycleKind==='four2'&&s.subtype==='blessing'&&s.turns>0&&groupActive(f4Source(s))).sort((a,b)=>b.amp-a.amp);if(choices.length){out={...out,f4BlessingPaid:1+choices[0].amp};f4Remove(f,choices[0]);log(f.name+'承春冬加护，下一招攻势增强','sig');}}return out;}
function dreamBaseStrike(atk,def,m,hpR,qqR,tag,full){const amp=m.f4BlessingPaid||1;return baseStrike(atk,def,m,hpR*amp,qqR*amp,tag,full);}
function f4FireDamage(f,t,s,mult=1){const shadow={...s,name:s.subtype==='cold'?'冻伤':'灼伤'},ratio=s.ratio??(s.subtype==='cold'?F4_CONFIG.coldRatio:F4_CONFIG.fireRatio);const n=cycleDamage(f,t,shadow,mult*ratio/.1);checkEnd(t);return n;}
function f4ConsumeFire(f,t,m,all){const s=f4Own(t,f,'fire');if(!s||!F4_CONFIG.convert)return 0;const ticks=all?s.turns:Math.min(1,s.turns),amount=s.qSnap*(s.ratio??F4_CONFIG.fireRatio)*ticks;let lost=0;for(let i=0;i<ticks&&!over&&groupActive(t);i++)lost+=f4FireDamage(f,t,s,F4_CONFIG.convertAmp);s.turns-=ticks;f4State(f).fireConverted+=ticks;if(s.turns<=0)f4Remove(t,s);f4Conversion(f,all?'夏秋收尽':'夏冬相激',amount,m);return lost;}
function f4MakeWard(f,t,m){let extra=0;const hot=f4Own(t,f,'hot');if(hot&&F4_CONFIG.convert){extra=hot.amount*hot.turns*F4_CONFIG.convertAmp;f4Remove(t,hot);f4Conversion(f,'春冬回护',extra,m);}const amount=Math.round(Math.min(t.hpMax*.25,effQiAtk(f)*m.wardRatio*m.f4Amp+extra));f4Status(f,t,'ward',{amount},2);log(t.name+'获得藏息屏障 '+amount,'sig');}
function f4Bless(f,t){if(t!==f&&t.side===f.side&&F4_CONFIG.allyAmp>0)f4Status(f,t,'blessing',{amp:F4_CONFIG.allyAmp},2);}
function dreamBaseCycleCast(f,def,m,full){if(!m?.four2)return baseCycleCast(f,def,m,full);if(m.friendly&&!GROUP_ENABLED)def=f;const empty={outcome:{effectHit:false,dealt:0,hpLost:0}};
 if(m.friendly){
  if(m.id==='springMana'){const mana=Math.max(0,Math.min(def.neiliMax-def.neili,F4_CONFIG.manaReturn));dariWrite(def,"neili",def.neili+(mana));fwGain(def,mana);const qi=Math.max(0,Math.min(def.qiMax-def.qi,effQiAtk(f)*.3));def.qi+=qi;log(def.name+'归元回气 '+Math.round(mana),'sig');return empty;}
  if(m.book==='冬'){f4MakeWard(f,def,m);f4Bless(f,def);return empty;}
  if(m.id==='springGroup'){const removable=def.statuses.find(s=>!s.buff&&!s.damage&&['内伤','麻痹','封穴','缠绕','梦魇','冬寂'].includes(s.name));if(removable){f4Remove(def,removable);log(def.name+'化去【'+removable.name+'】','sig');}}
  const ward=f4Own(def,f,'ward');const h=healingGain(f,def,(def.hpMax*(m.id==='springSingle'?.06:.03)+effQiAtk(f)*m.healRatio)*m.f4Amp,m.name,m).gained;
  if(ward&&F4_CONFIG.convert&&def.hp<def.hpMax){const stored=ward.amount;f4Remove(def,ward);const gain=healingGain(f,def,stored*F4_CONFIG.convertAmp,m.name+'·冬春回护',{}, {name:f.name,crit:0,ins:0,critMultiplier:1,insMultiplier:1}).gained;f4Conversion(f,'冬春回护',gain,m);}
  if(h>0&&m.hotRatio)f4Status(f,def,'hot',{amount:(def.hpMax*.01+effQiAtk(f)*m.hotRatio)*m.f4Amp,healing:healingProfile(f,m)},3);
  f4Bless(f,def);
  return empty;
 }
 const out=execMove(f,def,m,full)||{};if(out.effectHit&&full!==false){
  if(m.book==='夏'){const turns=m.id==='summerFire'?3:2,ratio=F4_CONFIG.fireRatio*(m.id==='summerSingle'?.45:m.id==='summerCharge'?.8:1);f4Status(f,def,'fire',{qSnap:effQiAtk(f)*m.f4Amp,snp:mkSnp(f),elem:'火',ratio},turns);f4State(f).fireCreated+=turns;}
  if(m.id==='autumnHarvest')out.hpLost=(out.hpLost||0)+f4ConsumeFire(f,def,m,true);
  if(m.id==='winterControl'){applyFx(f,def,{art:'sixiang',fx:[['缠绕',1,2]]});if(f4Own(def,f,'fire')&&F4_CONFIG.convert){out.hpLost=(out.hpLost||0)+f4ConsumeFire(f,def,m,false);applyFx(f,def,{art:'sixiang',fx:[['眩晕',1,1]]});}f4Status(f,def,'cold',{qSnap:effQiAtk(f)*m.f4Amp,snp:mkSnp(f),elem:'寒',ratio:F4_CONFIG.coldRatio},2);f4State(f).coldCreated+=2;}
  if(m.id==='autumnWither')f4Status(f,def,'wither',{},2);
  if(m.id==='autumnDispel'){const buff=def.statuses.find(s=>f4Dispellable(s));if(buff){f4Remove(def,buff);log(def.name+'的【'+buff.name+'】被秋风散去','sig');}}
 }
 return {outcome:out};
}
function f4Link(f,t,m,out){if(!F4_CONFIG.link||m.art==='sixiang'||m.free||m.reaction||m.cycleInstant||!out?.effectHit||!['pure','hybrid'].includes(m.type))return;const elem=m.elemName||m.elem||ART_ELEM[m.art],kind=['火','雷'].includes(elem)?'fire':['寒','冰','水'].includes(elem)?'cold':null;if(!kind)return;const candidates=t.statuses.filter(s=>s.cycleKind==='four2'&&s.subtype===kind&&s.turns>0).sort((a,b)=>a.ownerKey.localeCompare(b.ownerKey));for(const s of candidates){const source=f4Source(s);if(!groupActive(source)||source.side!==f.side)continue;const state=f4State(source),key=f4Key(t);if(state.linkByTarget[key]===round)continue;state.linkByTarget[key]=round;const lost=f4FireDamage(source,t,s,F4_CONFIG.linkAmp);s.turns--;state[kind+'Converted']++;if(s.turns<=0)f4Remove(t,s);state.linkEvents.push({round,actor:f4Key(f),target:key,element:elem,kind,lost});log(source.name+'余息接引'+elem+'势 · 实扣 '+lost,'sig');break;}}
function dreamBaseCycleRecord(f,def,m,out){if(!m.four2)baseCycleRecord(f,def,m,out);f4Link(f,def,m,out);for(const t of groupActors())if(t.cycleScoped)cycleMirrorDream(t);}
function wumingBaseCycleTick(t,s){if(s.cycleKind!=='four2')return baseCycleTick(t,s);const f=f4Source(s);if(!groupActive(f)){if(['fire','cold'].includes(s.subtype)&&f)f4State(f)[s.subtype+'Purged']+=s.turns;s.turns=0;return true;}
 if(['fire','cold'].includes(s.subtype)){f4FireDamage(f,t,s);f4State(f)[s.subtype+'Ticked']++;}
 if(s.subtype==='hot')healingGain(f,t,s.amount,'春息回护',{},s.healing);s.turns--;return true;
}
function cycleEndUnit(f){if(!f4Enabled(f))return baseCycleEndUnit(f);const c=f4State(f);if(round%4===0){const seasons=f.arts.sixiang.chapters||CYCLE_SEASONS;c.season=seasons[(rnd()*seasons.length)|0];}f.cycle.window=null;}
function dreamBaseCyclePreview(f,m){return m?.four2?{resourceText:m.book+'门共用调息',charge:m.charge||0}:baseCyclePreview(f,m);}

function f4Dispellable(s){return !!s.buff&&s.turns>0&&!s.permanent&&(s.dispellable===true||s.removable===true||s.labDispellable||['金刚怒目','大日如来','火云','冬凝','木灵显圣','白云无尽时','今朝是何夕'].includes(s.name));}
function fourBodyDamage(f,damage){let left=damage;if(left>0)for(const s of f.statuses.filter(s=>s.cycleKind==='four2'&&s.subtype==='ward'&&s.turns>0)){if(!groupActive(f4Source(s)))continue;const blocked=Math.min(left,s.amount);s.amount-=blocked;left-=blocked;if(blocked>0)log(f.name+'藏息屏障抵挡 '+blocked,'sig');if(s.amount<=0)f4Remove(f,s);if(left<=0)break;}return left;}
function disasterBaseHealingGain(source,target,amount,label,move={},snapshot){const wither=target?.statuses.some(s=>s.cycleKind==='four2'&&s.subtype==='wither'&&s.turns>0);return baseHealingGain(source,target,amount*(wither?.5:1),label,move,snapshot);}
function wumingBaseCycleClear(f){baseCycleClear(f);delete f.four2;}
