 if(m.kind==='field'&&n<1)return '须先引梦';
 if(m.kind==='conversion'&&n<DREAM_RULES.bladeMinimumDepth)return '入梦不足';
 if(m.kind==='finish'&&dreamOwnedStage(f)!==3)return '须己方梦天地';if(m.kind==='finish'&&dreamPoolTotal(f)<DREAM_POOL_RULES.minimumTotalDream)return '全场同源入梦不足';
