function disasterBaseCyclePool(f,list){
 if(!DREAM_CONFIG.enabled||!hasArt(f,'dameng'))return dreamBaseCyclePool(f,list);
 const base=dreamBaseCyclePool(f,list.filter(m=>m.art!=='dameng'));
 for(const raw of DREAM_CONFIG.moves.filter(m=>m.tier<=profTier(f,'dameng')&&m.kind!=='follow')){
  const m={...raw};
  if(m.id==='guide'){m.dreamStageAtCast=dreamOwnedStage(f);m.qqR=DREAM_RULES.guideRatios[m.dreamStageAtCast];if(m.dreamStageAtCast===2){m.count=2;m.segs=[{hpR:0,qqR:m.qqR/2},{hpR:0,qqR:m.qqR/2}];}base.push(m);}
  else if(m.kind==='body'){for(const mode of ['真','虚'])base.push({...m,key:m.key+'/'+mode,dreamMode:mode,displayName:m.name+' · '+(mode==='虚'?'留影':'守真')});}
  else if(m.kind==='field')base.push({...m,key:m.key+'/静夜',dreamScene:'静夜'});
  else if(m.kind==='illusion'){for(const mode of ['真','虚'])base.push({...m,key:m.key+'/'+mode,dreamMode:mode,displayName:m.name+' · '+(mode==='虚'?'虚招':'实击')});}
  else base.push(m);
 }if(f.dreamV1?.follow?.legacy&&profTier(f,'dameng')>=3)base.push({...DREAM_LEGACY_WAKE});return base;
}
