function disasterBaseCyclePreview(f,m){if(!m.dreamNative)return dreamBaseCyclePreview(f,m);return {charge:m.charge||0,freeAction:!!m.free,resourceText:({attack:m.id==='guide'?'命中引梦 · 十层随机附加负面1回合 · 每6回合一次'+(f.dreamV1?.guideDebuff?.readyRound>round?'（尚余'+(f.dreamV1.guideDebuff.readyRound-round)+'回合）':''):'命中引梦',illusion:m.dreamMode==='虚'?'引走一份真实守势 · 即刻梦醒':'普通真气实击',conversion:'同源入梦至少1层 · 梦深增威 · 不耗梦',body:'耗1层入梦 · 至下次自身行动',field:'按目标梦深推进梦境',finish:'己方梦天地 · 全场同源总梦至少1层 · 汇梦分伤 · 不耗梦',follow:'骗守后的追击'})[m.kind]||''};}
function lightBaseDodgeChance(def,atk,o){if(!DREAM_CONFIG.enabled)return dreamBaseDodgeChance(def,atk,o);const d={...def,arts:{...def.arts}};delete d.arts.dameng;return dreamBaseDodgeChance(d,atk,o);}
function disasterBaseStrike(f,t,m,h,q,tag,full){let scale=DREAM_CONFIG.enabled&&!m.dreamNative?DREAM_SCALE:1;scale*=dreamEnv().factor(m.elemName||m.elem||ART_ELEM[m.art],protoArea(t),m.range,{selfSeasons:m.art==='sixiang'});if(m.range&&dreamEnv().stage()>0)scale*=.97;return dreamBaseStrike(f,t,m,h*scale,q*scale,tag,full);}
