function dreamCleanup(){if(!BATTLE_ENV)return;dreamEnv().sweep(round,id=>groupActive(dreamFind(id)));dreamSyncField();for(const f of groupActors())if(f.dreamV1&&(over||!groupActive(f))){f.dreamV1.body=null;f.dreamV1.follow=null;}if(over)dreamEnv().demote(0,round);}
function dariBaseCheckEnd(f){const out=dreamBaseCheckEnd(f);dreamCleanup();return out;}
function wyBaseDreamRoundEnd(){dreamEnv().advance(round,id=>groupActive(dreamFind(id)));for(const f of groupActors())if(f.dreamV1)f.dreamV1.gains={};}
function dreamInstall(api){
 dreamMigrate();dreamInit();const advanceNative=api.advance,reasonNative=api.reason;
 api.dreamView=()=>copy(dreamView());api.environmentView=()=>dreamEnv().view();api.phase=()=>DREAM_PENDING?'dreamReaction':phase;
 api.reason=a=>DREAM_PENDING?dreamResponseReason(a.name):reasonNative(a);
 api.advance=a=>{if(!DREAM_PENDING)return advanceNative(a);const resume=dreamResolve(a.name);if(over){phase='running';settleUntilInput();}else if(resume==='finish')phase='finish';else {phase='running';settleUntilInput();}return snapshot();};
 const syncNative=api.sync;api.sync=sd=>{syncNative(sd);const bs=sd.战斗状态||sd.主角?.战斗状态;if(bs){bs.环境状态=dreamEnv().view();bs.环境基底||=DLH_ENVIRONMENT_INPUT(dreamEnv().snapshot().physical.base);bs.输入阶段=DREAM_PENDING?'梦中应对':bs.输入阶段;bs.待应变=DREAM_PENDING?dreamView().text:bs.待应变;}};
 api.needsAutoResume=()=>!DREAM_PENDING&&needsAutoResume();api.resumeIfNoReaction=()=>!DREAM_PENDING&&resumeIfNoReaction();

 return api;
}

/* Candidate source module. No DOM, external randomness, recursive gain or damage. */
function dreamSplashGain(f,t,n,serial,guaranteed=false){
 if(!DREAM_SPLASH.enabled)return dreamGain(f,t,n,serial);
 if(!groupActive(f)||!groupActive(t)||f.side===t.side||!hasArt(f,'dameng')||!(n>0))return;
 const st=dreamState(f),key=dreamKey(t);
 if(st.splash?.processed[serial]?.targets.includes(key))return;
 if(serial!==undefined&&st.gains[key]===serial)return;
 const others=groupActors().filter(x=>x!==t&&x.side!==f.side&&groupActive(x));
 // Single-target battles do not create state or draw any additional RNG.
 if(!others.length)return dreamGain(f,t,n,serial);
 if(!Number.isSafeInteger(serial)||serial<1)throw Error('Dream splash requires a committed move serial');
 dreamGain(f,t,n,serial);
 const splash=st.splash||(st.splash={version:1,processed:{},events:[]});
 const processed=splash.processed[serial]||(splash.processed[serial]={targets:[],rolled:false});
 processed.targets.push(key);
 if(processed.rolled)return;
 processed.rolled=true;
 const event={round,serial,source:dreamKey(f),primary:key,guaranteed,targets:[]};
 for(const other of others){
  const before=cycleDream(other,f),roll=guaranteed?null:rnd(),success=guaranteed||roll<DREAM_SPLASH.chance;
  if(success)cycleSetDream(other,f,Math.min(10,before+DREAM_SPLASH.layers));
  const after=cycleDream(other,f),applied=after-before;
  event.targets.push({id:dreamKey(other),roll,success,before,after,applied});
  if(after>=7&&st.stats.firstDeep===null)st.stats.firstDeep=round;
  if(applied>0)log('梦意外溢：'+other.name+'入梦+'+applied+'（'+after+'/10）','sig');
 }
 splash.events.push(event);
 dreamSyncField();
}

/* One committed pre-defense power pool, allocated before any target is hit. */
function dreamPoolTargets(f){return groupActors().filter(t=>t.side!==f.side&&groupActive(t));}
function dreamPoolTotal(f){return dreamPoolTargets(f).reduce((n,t)=>n+cycleDream(t,f),0);}
function dreamPoolBuild(f,targets,rules=DREAM_POOL_RULES){
 const rows=targets.filter(t=>groupActive(t)&&t.side!==f.side).map(t=>({id:dreamKey(t),layers:cycleDream(t,f)}));
 const totalDream=rows.reduce((s,t)=>s+t.layers,0),weightTotal=rows.reduce((s,t)=>s+rules.weightBase+t.layers,0);
 const totalRatio=rules.coefficientPerDream*totalDream,power=effQiAtk(f)*totalRatio;
 const shares={};for(const row of rows){const weight=rules.weightBase+row.layers,fraction=weightTotal>0?weight/weightTotal:0;shares[row.id]={...row,weight,fraction,ratio:totalRatio*fraction,raw:power*fraction};}
 return {rules:copy(rules),totalDream,totalRatio,power,weightTotal,fieldFactor:dreamFieldFactor(f),shares};
}
function dreamPooledExecute(f,t,m,full,provided){
 if(m?.dreamNative&&m.kind==='finish'&&!m.dreamLegacyV1){
  if(dreamOwnedStage(f)!==3){log('释放时己方梦天地已失效，千秋未能成形','sys');return {dealt:0,hpLost:0,effectHit:false};}
  const rules=m.dreamPoolRules||DREAM_POOL_RULES,targets=provided||groupTargets(f,m,undefined,false),packet=dreamPoolBuild(f,targets,rules);
  if(packet.totalDream<rules.minimumTotalDream){log('全场同源梦意不足，千秋未能成形','sys');return {dealt:0,hpLost:0,effectHit:false};}
  const state=f.pooledFinishV1||(f.pooledFinishV1={version:1,processed:{},events:[]});
  if(state.processed[m.cycleSerial])return {dealt:0,hpLost:0,effectHit:false};
  state.processed[m.cycleSerial]=true;state.events.push({round,serial:m.cycleSerial,...copy(packet)});
  log(f.name+'收束全场梦意（'+packet.totalDream+'层），按梦深分配千秋攻势','sig');
  m={...m,dreamPool:packet};
 }
 return dreamBaseGroupExecute(f,t,m,full,provided);
}

/* Captured, paid old moves finish under their old art contract; new moves use v2. */
function dreamMigrate(){
 if(saved?.version!==1||saved.dreamRulesRevision>=2)return;
 const retain=m=>{if(m?.dreamNative)m.dreamLegacyV1=true;};
 for(const f of groupActors()){if(f.charging)retain(f.charging.mv);if(f.dreamV1?.follow)f.dreamV1.follow.legacy=true;}
 if(pending?.charged)retain(pending);
 if(DREAM_PENDING)retain(DREAM_PENDING.move);
}

/* Guide-only native proc. Forecasts inspect eligibility without state or RNG writes. */
const DREAM_GUIDE_DEBUFF=DREAM_CONFIG.guideDebuff||{depth:10,turns:1,cooldown:6};
function dreamGuideStatusPool(t){
 return Object.entries(DLH_STATUS_LIBRARY.rows).filter(([name,row])=>!row.buff&&!protectedControl(t,name)&&!(t.fxOn&&['封穴','流血'].includes(name))&&!(DOT_ELEM[name]&&t.dotImmunities?.includes(name))).map(([name])=>name);
}
function dreamGuideEligible(f,t,m,afterHit=false){
 if(!DREAM_CONFIG.enabled||!m?.dreamNative||m.dreamLegacyV1||m.cycleLegacy||m.art!=='dameng'||m.id!=='guide'||m.free||m.reaction||m.secondaryDirect||!hasArt(f,'dameng')||!groupActive(f)||!groupActive(t)||f.side===t.side)return false;
 const last=f.dreamV1?.guideDebuff;
 if(last&&round<last.readyRound)return false;
 if(afterHit&&last&&m.cycleSerial<=last.serial)return false;
 return cycleDream(t,f)+(afterHit?0:DREAM_RULES.guideDreamGain)>=DREAM_GUIDE_DEBUFF.depth&&dreamGuideStatusPool(t).length>0;
}
function dreamGuidePotential(f,t,m){return dreamGuideEligible(f,t,m)?6:0;}
function dreamGuideProc(f,t,m,out){
 if(!out?.effectHit||!Number.isSafeInteger(m.cycleSerial)||!dreamGuideEligible(f,t,m,true))return;
 const pool=dreamGuideStatusPool(t),name=pool[Math.floor(rnd()*pool.length)],turns=DREAM_GUIDE_DEBUFF.turns,owner=dreamKey(f),src='大梦神功·迷魂引';
 // An independent ordinary pool must not overwrite another art, owner or native cost.
 t.statuses=t.statuses.filter(s=>!(s.dreamGuideStatus&&s.name===name&&s.dreamGuideOwner===owner));
 let status;
 if(name==='流血'){
  genericBleedApply(f,t,{...m,source:src},{stacks:1,turns,ratio:.1,stacking:'refresh'});
  status=t.statuses.find(s=>s.name===name&&s.src===src&&genericBleedSource(t,s)===f);
 }else{
  status={name,stacks:1,turns,expires:round+turns-1,fresh:false,buff:false,src,owner:f.side,ownerId:f.groupId||undefined,qSnap:effQiAtk(f),snp:judgedRates(f,t),elem:DOT_ELEM[name]||null,damage:!!DOT_ELEM[name],ratio:DOT_ELEM[name]?.1:0};
  t.statuses.push(status);
 }
 if(!status)return;
 Object.assign(status,{dreamGuideStatus:true,dreamGuideOwner:owner,description:'迷魂引在本施术者所留入梦达到十层后随机附加。本次仅持续'+turns+'回合，不沿用通用生成的固定长回合数；可以按普通负面状态净化。'});
 const state=dreamState(f),previous=state.guideDebuff;
 state.guideDebuff={serial:m.cycleSerial,lastRound:round,readyRound:round+DREAM_GUIDE_DEBUFF.cooldown,target:dreamKey(t),status:name,count:(previous?.count||0)+1};
 log(f.name+'迷魂引 · 十层深梦附加【'+name+'】'+turns+'回合；'+DREAM_GUIDE_DEBUFF.cooldown+'回合内仅一次','sig');
}

