/* Nameless Sword: finite action windows, source-owned marks and one payment per cast. */
const WUMING_CONFIG={"name":"无名剑法","lv":"后天","type":"外功","适器":["剑"],"yuan":"作者原案：飞剑进身、退剑蓄势、三道剑气；本轮补入收剑重击与气竭追放。","requirement":"持剑施展，按自身熟练度解锁。","pos":"进剑护身，退剑蓄势；三叠剑气乘气竭追斩，亦须留力接续。","bonuses":[{"slot":1,"name":"砺锋","key":"外功攻击","mode":"flat","minValue":40,"value":56},{"slot":2,"name":"留力","key":"最大耐力","mode":"ratio","value":0.08}],"sigs":[["进退有据","出畏之后可在本次行动接执讯连连，免主动作但仍耗内力；执讯护持三回合使真气条损耗减少20%。退亦有方留一层闪避并使命中者减速15%三回合；薄言还归有效命中且执讯护持尚在时，每回合回复耐力8。",0],["执剑无双","仅退亦有方与无以为家系列属于本门剑气；逐目标、逐施放者留剑气蚀痕，命中后加一层，五回合、最多三层，每层使自己的后续剑气伤害增强5%。三道按1、0.8、0.64衰减。",3],["无名心法","起蓄时有执讯护持、退剑后的五回合窗口或三道释放后的五回合窗口之一，即锁定三道。三道出剑时整招额外燃烧至多耐力20，每点增伤1.5%、上限30%；气竭目标不擦伤，第三道必会意，仍可闪避。三道有效命中已经气竭的目标，下次自身行动可付同样费用免蓄力追放，可继续接续，每次只留一份机会。圆满蓄势强韧。",3],["玉斗","释放出畏之并结算完毕后，十回合内会意伤害加成增加10个百分点；每段伤害结算时，目标当前护体真气比例低于自身，或低于40%，直接会意率增加7.5个百分点，两条件同时满足不重复增加。每十二回合最多获得一次，期间重放出畏之不刷新持续时间或冷却。",1]],"playerSigs":{"进退有据":"进身连剑后可护住真气；退剑留出回避余地，护持尚在时，收剑重击可回复少量耐力。","执剑无双":"剑气接连命中同一敌人，后续剑气会逐渐增强。飞剑与贴身剑击另循自身剑路。","无名心法":"循进退留下的余势，可蓄成三叠剑气。三剑耗耐更重，第三剑藏有决胜锋芒；命中气竭之敌，下次可乘势直接再放三剑。圆满后蓄势不易被打断。","玉斗":"出畏之后，玉斗生辉，十回合内会意伤害提高；敌人真气成数低于自己，或已不足四成时，更易会意。每十二回合只得一次。"},"moves":[{"id":"enter","name":"出畏之","tier":0,"type":"hybrid","hpR":1.8,"qqR":0.7,"cost":20,"cd":1,"count":2,"wumingNative":true,"playerDesc":"掷剑伤敌，随剑进身，连续造成中等伤害；随后可接执讯连连。粗通后，收势可引玉斗生辉。","desc":"两段，各外功0.9、真气0.35；释放即可开本次行动派生，不要求命中。"},{"id":"follow","name":"执讯连连","tier":0,"type":"hybrid","hpR":1.8,"qqR":0.7,"cost":15,"cd":0,"count":2,"free":"combo","nativeCombo":true,"followUp":{"from":[{"art":"","move":"出畏之"}],"free":true,"windowRounds":0,"requireHit":false},"wumingNative":true,"playerDesc":"循着进剑之势再接两剑，造成中等伤害，并护住真气；本次行动可接，仍消耗内力。","desc":"两段；释放后执讯护持三回合，减少真气条损耗20%，不回复或新建护盾。"},{"id":"retreat","name":"退亦有方","tier":1,"type":"hybrid","hpR":1,"qqR":0.4,"cost":0,"nai":30,"cd":2,"ranged":true,"wumingNative":true,"swordWave":true,"zeroCostReason":"作者原文明示退亦有方无耗气，消耗耐力30。","playerDesc":"退身斩出剑气，造成中等伤害；命中使敌人减速，并为自己留下一次闪避机会。此招只耗耐力。","desc":"单体远袭；释放获得一层闪避，命中减速15%三回合。无耗气为原文明示例外。"},{"id":"return","name":"薄言还归","tier":1,"type":"hybrid","hpR":2.8,"qqR":1.1,"cost":25,"cd":1,"wumingNative":true,"playerDesc":"贴身收剑重击，造成较高伤害；自己的执讯护持仍在时，命中可回复少量耐力。","desc":"每回合有效命中且自身执讯护持尚在，回复耐力8一次；不属于剑气。"},{"id":"home","name":"无以为家","tier":2,"type":"hybrid","hpR":2.6,"qqR":1,"cost":45,"nai":30,"cd":3,"charge":1,"range":true,"wumingNative":true,"swordWave":true,"playerDesc":"蓄势后向敌阵斩出高额剑气；循护持或退剑余势，可化作三道，出剑时会额外燃烧耐力。","desc":"起蓄支付内力45、耐力30，释放不重复支付；入室符合窗口锁定三道，圆满起蓄获强韧。"},{"id":"drive","name":"无以为家·长驱","tier":3,"type":"hybrid","hpR":2.6,"qqR":1,"cost":45,"nai":30,"cd":0,"range":true,"wumingNative":true,"swordWave":true,"playerDesc":"乘气竭之隙，直接再斩三道高额剑气；占本次主动作，仍须支付内力与耐力。","desc":"仅三道有效命中气竭目标后的下次自身行动可用；不受母招调息限制、不重置母招调息；再次命中可续下一次。"}],"boundaries":"长驱不是免主动作。蓄势期间锁定三道；出剑额外耐力按释放时实耗整招一次、群体不重复扣。机会按回合只留一份、不叠段数或人数；战终清空。"};
function wumingKey(f){return f.groupId||String(runId)+':'+f.side;}
function wumingState(f,write=false){if(!f.wuming&&write)f.wuming={retreatUntil:-1,tripleUntil:-1,followAt:-1,lastReturn:-1,serial:0,jadeReadyAt:-1};return f.wuming||{retreatUntil:-1,tripleUntil:-1,followAt:-1,lastReturn:-1,serial:0,jadeReadyAt:-1};}
function wumingStatus(f,kind,source=f){return f.statuses.find(s=>s.wumingKind===kind&&s.ownerKey===wumingKey(source)&&s.until>=round);}
function wumingPut(f,kind,name,source,turns,stacks=1){let s=wumingStatus(f,kind,source);if(!s){s={name,wumingKind:kind,src:'无名剑法',ownerKey:wumingKey(source),ownerId:source.groupId,owner:source.side,buff:kind==='guard'||kind==='jade',stacks:0,turns};f.statuses.push(s);}s.stacks=kind==='mark'?Math.min(3,s.stacks+stacks):stacks;s.until=round+turns-1;s.turns=turns;return s;}
function wumingJadeGain(f){if(!hasSig(f,'wuming','玉斗')||round<(wumingState(f).jadeReadyAt??-1))return;wumingPut(f,'jade','玉斗',f,10);wumingState(f,true).jadeReadyAt=round+12;log(f.name+'玉斗生辉 · 会意锋芒十回合','sig');}
function wumingJadeBonus(f){return f&&wumingStatus(f,'jade') ? .10 : 0;}
function wumingQiRatio(f){return f&&Number.isFinite(f.qiMax)&&f.qiMax>0?Math.max(0,Math.min(1,(Number.isFinite(f.qi)?f.qi:0)/f.qiMax)):0;}
function wumingDirectIns(f,t){if(!wumingJadeBonus(f)||!t)return 0;const r=wumingQiRatio(t);return r<wumingQiRatio(f)||r<.4 ? .075 : 0;}
function wumingDotInsight(f,t,rate){return Math.min(1,Math.max(0,rate||0)+wumingDirectIns(f,t));}
function jxBaseJianInsDamage(f,m){return wumingBaseJianInsDamage(f,m)+wumingJadeBonus(f);}
function wumingTriple(f){const s=wumingState(f);return hasSig(f,'wuming','无名心法')&&!!(wumingStatus(f,'guard')||s.retreatUntil>=round||s.tripleUntil>=round);}
function wyBaseCyclePool(f,list){let out=wumingBaseCyclePool(f,list);if(!hasArt(f,'wuming'))return out;const ready=wumingState(f).followAt===round;return out.filter(m=>m.art!=='wuming'||(m.id==='drive'?ready:m.id!=='home'||!ready));}
function wyBaseCyclePrepare(f,m){const out=wumingBaseCyclePrepare(f,m);if(!out?.wumingNative)return out;return {...out,...(out.id==='home'&&profTier(f,'wuming')>=4?{chargeProtection:'强韧'}:{})};}
function wyBaseCycleReason(f,m,t){const prior=wumingBaseCycleReason(f,m,t);if(prior||!m?.wumingNative)return prior;if(m.cost>0&&f.neili<costOf(f,m))return '内力不足：需要 '+costOf(f,m);if(m.id==='drive'&&wumingState(f).followAt!==round)return '须在三道命中气竭目标后的下次行动追剑';return '';}
function wyBaseCycleBegin(f,m,full){const out=wumingBaseCycleBegin(f,m,full);if(!out?.wumingNative)return out;const s=wumingState(f,true),ready={...out,wumingSerial:++s.serial};if(out.id==='home'||out.id==='drive'){ready.wumingTriple=out.id==='drive'||wumingTriple(f);ready.segs=(ready.wumingTriple?[1,.8,.64]:[1]).map(x=>({hpR:out.hpR*x,qqR:out.qqR*x}));if(out.id==='drive')s.followAt=-1;}else if(out.count)ready.segs=Array.from({length:out.count},()=>({hpR:out.hpR/out.count,qqR:out.qqR/out.count}));return ready;}
function dariBaseGroupExecute(f,t,m,full,provided){if(m?.wumingNative&&m.wumingTriple&&!m.wumingBurned){const spent=Math.min(20,Math.max(0,f.nai));f.nai-=spent;if(spent)f.usedNai=true;m={...m,wumingBurned:true,wumingBurn:spent,wumingAmp:spent*.015};wumingState(f,true).tripleUntil=round+4;log(f.name+'三叠剑气出锋'+(spent?' · 燃耐'+spent:''),'sig');}return wumingBaseGroupExecute(f,t,m,full,provided);}
function wyBaseCycleCast(f,t,m,full){if(!m?.wumingNative)return wumingBaseCycleCast(f,t,m,full);const out=execMove(f,t,m,full)||{};if(m.id==='enter')wumingJadeGain(f);if(m.id==='follow'){wumingPut(f,'guard','执讯护持',f,3);log(f.name+'执讯护持 · 三回合','sig');}if(m.id==='retreat'){const s=wumingState(f,true);s.retreatUntil=round+4;if(f.dodgeL.length<3)f.dodgeL.push({src:'无名剑法'});}if(m.id==='return'&&out.effectHit&&wumingStatus(f,'guard')){const s=wumingState(f,true);if(s.lastReturn!==round){s.lastReturn=round;const gain=Math.min(8,Math.max(0,f.naiMax-f.nai));f.nai+=gain;if(gain)log(f.name+'收剑留力 · 回复耐力'+gain,'sig');}}return {outcome:out};}
function wumingCommon(f,t,m){return m?.wumingNative?(m.wumingDamageBonus||0):0;}
function dariBaseStrike(f,t,m,h,q,tag,full){if(!m?.wumingNative)return wumingBaseStrike(f,t,m,h,q,tag,full);if(t.hp<=0)return {dealt:0,effectHit:false};const exhausted=t.exhaust>0,mark=m.swordWave&&hasSig(f,'wuming','执剑无双')?wumingStatus(t,'mark',f):null,mv={...m,wumingDamageBonus:(m.wumingAmp||0)+(mark?.stacks||0)*.05,ranged:m.id==='enter'?tag.endsWith('·段1'):!!m.ranged,forceInsight:!!(m.wumingTriple&&tag.endsWith('·段3'))};const out=wumingBaseStrike(f,t,mv,h,q,tag,full);if(t.qi<=0&&t.exhaust<=0){t.qi=0;t.exhaust=3;log(t.name+'真气枯竭 · 气竭三回合','dmg');}if(out?.effectHit){if(m.swordWave&&hasSig(f,'wuming','执剑无双'))wumingPut(t,'mark','剑气蚀痕',f,5);if(m.id==='retreat')wumingPut(t,'slow','退剑缓势',f,3);if(m.wumingTriple&&exhausted){const s=wumingState(f,true);if(s.followAt!==round+1)log(f.name+'剑势未歇 · 下次行动可直接追放三道剑气','sig');s.followAt=round+1;}}return out;}
function jianNoGraze(f,t,m){return !!(m?.wumingTriple&&t.exhaust>0)||wumingBaseJianNoGraze(f,t,m);}
function jxBaseJianShield(f,t,raw){if(!wumingStatus(t,'guard'))return wumingBaseJianShield(f,t,raw);const factor=(1+jianFlowers(f)*JV.flowerShield)*.8,absorb=t.exhaust<=0&&t.qi>0?Math.min(t.qi/factor,raw*t.qiCut):0;return {absorb,spent:absorb*factor};}
function bwBaseEffSpd(f){return wumingBaseEffSpd(f)*(f.statuses.some(s=>s.wumingKind==='slow'&&s.until>=round)?.85:1);}
function bleedBaseCycleTick(f,s){if(!s.wumingKind)return wumingBaseCycleTick(f,s);s.turns=Math.max(0,s.until-round);return true;}
function wyBaseCycleClear(f){wumingBaseCycleClear(f);delete f.wuming;f.statuses=f.statuses.filter(s=>!s.wumingKind);}
function wumingInstall(api){for(const f of groupActors()){const old=Object.entries(f.arts).find(([id,a])=>id!=='wuming'&&a.name==='无名剑法');if(old){delete f.arts[old[0]];f.arts.wuming=artConfig('无名剑法',old[1].tier);}}
 const previous=api.preview;api.preview=a=>{let out=previous(a);const m=findMove(P,a);if(!out||!m)return out;if(out.rates&&wumingJadeBonus(P)){try{const targets=GROUP_ENABLED?groupTargets(P,m,a.targetIds,false):[E];if(targets[0])out={...out,rates:moveRates(P,targets[0],m)};}catch(_){}}if(!m.wumingNative)return out;let hint='';if(m.id==='enter')hint='出剑后可在本次行动接执讯连连，护持能为三叠剑气铺路。'+(hasSig(P,'wuming','玉斗')?(round>=(wumingState(P).jadeReadyAt??-1)?'此剑收势后，玉斗生辉十回合。':'玉斗尚待'+((wumingState(P).jadeReadyAt??round)-round)+'回合方可再得。'):'');if(m.id==='follow')hint='连剑后真气损耗减轻，护持尚在时可蓄三叠剑气。';if(m.id==='retreat')hint='退剑后留五回合余势，入室后可借此蓄三叠剑气。';if(m.id==='return')hint=wumingStatus(P,'guard')?'护持未散，命中可收剑留力。':'先接执讯护持，再以此剑回耐。';if(m.id==='home')hint=wumingTriple(P)?'余势已备，可蓄三叠剑气；出剑时至多再耗耐力20。命中气竭之敌，下次可直接追放。':'眼下将斩出一道剑气；入室后，可循护持或退剑余势蓄成三叠。';if(m.id==='drive')hint='乘隙直接再放三道，占主动作；出剑时至多再耗耐力20，命中气竭之敌可继续追剑。';return {...out,charge:m.charge||0,freeAction:!!m.free,contextHint:hint,resourceText:(m.wumingTriple||m.id==='drive'||m.id==='home'&&wumingTriple(P))?'三叠待发 · 出剑至多再耗耐力20':''};};return api;}

/* Generic bleeding: owner-specific external-attack snapshot and finite layer clocks. */
function genericBleedKey(f){return f.groupId||String(runId)+':'+f.side;}
function jxBaseGenericBleedSource(t,s){if(s.ownerId)return groupActors().find(f=>f.groupId===s.ownerId)||null;if(s.bleedOwner)return groupActors().find(f=>genericBleedKey(f)===s.bleedOwner)||null;if(!GROUP_ENABLED)return s.owner===P.side?P:s.owner===E.side?E:groupOpponent(t);const side=s.owner||(t.side==='L'?'R':'L'),candidates=groupActors().filter(f=>f.side===side&&(!s.src||Object.values(f.arts||{}).some(a=>a.name===s.src)));return candidates.length===1?candidates[0]:null;}
function genericBleedClocks(s){if(!s.bleedLayers)s.bleedLayers=Array.from({length:Math.min(5,Math.max(0,s.stacks||1))},()=>({turns:Math.max(0,s.turns||0)}));if(s.stacks<s.bleedLayers.length)s.bleedLayers.sort((a,b)=>b.turns-a.turns).splice(Math.max(0,s.stacks));const longest=Math.max(0,...s.bleedLayers.map(x=>x.turns));if(s.turns>longest)for(const x of s.bleedLayers)x.turns+=s.turns-longest;return s.bleedLayers;}
function bodyBaseGenericBleedApply(f,t,m,fx){if(t.fxOn)return;const key=genericBleedKey(f),old=t.statuses.find(s=>s.name==='流血'&&!s.qyDot&&!s.nineBleed&&!s.nilBlood&&s.src===m.source&&genericBleedSource(t,s)===f),turns=Math.max(1,fx.turns||4),count=Math.min(5,Math.max(1,fx.stacks||1));let s=old;if(!s){s={name:'流血',src:m.source,owner:f.side,ownerId:f.groupId,bleedOwner:key,bleedGeneric:true,bleedLayers:[],stacks:0,turns:0,elem:'外伤',damage:true};t.statuses.push(s);}else genericBleedClocks(s);
 if(fx.stacking==='add'){for(let i=0;i<count;i++){if(s.bleedLayers.length<5)s.bleedLayers.push({turns});else{s.bleedLayers.sort((a,b)=>a.turns-b.turns);s.bleedLayers[0].turns=Math.max(s.bleedLayers[0].turns,turns);}}}else{while(s.bleedLayers.length<count)s.bleedLayers.push({turns});for(const x of s.bleedLayers)x.turns=Math.max(x.turns,turns);}
 Object.assign(s,{label:fx.label||'',bleedOwner:key,bleedGeneric:true,wSnap:effWMax(f),snp:judgedRates(f,t),ratio:Math.max(s.ratio||0,fx.ratio||.1),fresh:false,stacks:s.bleedLayers.length,turns:Math.max(...s.bleedLayers.map(x=>x.turns))});log(t.name+'流血 '+s.stacks+'/5 · '+turns+'回合〈'+m.source+'〉','sig');}
function genericBleedTick(t,s){const layers=genericBleedClocks(s),f=genericBleedSource(t,s);s.bleedGeneric=true;if(f&&s.wSnap==null){s.wSnap=effWMax(f);s.snp=s.snp||judgedRates(f,t);s.bleedOwner=genericBleedKey(f);}let raw=f&&layers.length>0&&!t.fxOn&&!t.dotImmunities?.includes('流血')?s.wSnap*(s.ratio>0?s.ratio:.1)*layers.length:0,quality='';
 if(raw>0&&s.snp){if(rnd()<wumingDotInsight(f,t,s.snp.ins)){raw*=1.35+wumingJadeBonus(f);quality=' · 会意';}else if(rnd()<s.snp.prec){if(rnd()<s.snp.crit){raw*=1.5;quality=' · 会心';}}else{raw*=.7;quality=' · 擦伤';}}
 if(raw>0){raw*=nineDot(f,t,s)*realmFactor(f,t)*hhTiger(f,t)*(1+zySum(f,'dotAmp'))*penZone(penV(f,'w',t,null),resV(t,'w',f))*effDR(t)*dreamEnv().factor('外伤',protoArea(t));if(hasSig(t,'tianjiao','金身不漏'))raw=Math.max(0,raw-30);raw=bodyDotAmount(t,s,raw);const shield=jianShield(f,t,raw);t.qi=Math.max(0,t.qi-shield.spent);qiBurn(t,shield.spent);const before=t.hp;dealHp(t,Math.max(0,Math.round(raw-shield.absorb)));const lost=hpLost(t,before);if(hasArt(t,'tianjiao'))protoTian(t).dotPressure+=lost;nineLifesteal(f,{}, {hpLost:lost});bwBleedGain(f,t,s,lost);curioPeriodicAfter(f,t,lost);log(t.name+'受【流血·外伤】持续伤害 · 实扣 '+lost+quality+'〈'+s.src+'〉','dmg');if(t.qi<=0&&t.exhaust<=0){t.qi=0;t.exhaust=3;}checkEnd(t);}
 for(const x of layers)x.turns--;s.bleedLayers=layers.filter(x=>x.turns>0);s.stacks=s.bleedLayers.length;s.turns=Math.max(0,...s.bleedLayers.map(x=>x.turns));s.fresh=false;return true;
}
function dariBaseCycleTick(f,s){return s.name==='流血'&&!s.nineBleed&&!s.nilBlood&&!s.cycleKind?genericBleedTick(f,s):bleedBaseCycleTick(f,s);}

/* Native Five Peaks: one finite ledger, real physical terrain and one payment per cast. */
const WUYUE_CONFIG={"revision":3,"arts":{"wuyue":{"name":"五岳山主","lv":"先天","type":"外功","适器":[],"yuan":"五岳五脉剑法同出一源，五剑归一，借地脉承来力、转山势为剑。","requirement":"五脉剑法传承齐备，或拥有天齐、朱陵、太华、镇朔、中天五柄传承剑，即可获得本门；不要求五门先练至圆满。御剑仅显剑意，不叠加五件武器面板。","pos":"一人御五剑，以地承力，借山还剑；不需多人结阵。","bonuses":[{"slot":1,"name":"岳骨","key":"外功防御","mode":"flat","value":40},{"slot":2,"name":"地藏","key":"最大内力值","mode":"ratio","value":0.12}],"sigs":[["五脉归一","五剑仅为表现，不占装备槽。天齐付费正常出剑可注入2倍当前最大外功的山重，按绝对数值存储。",0],["接劲入地","接地时可收格挡实际挡掉劲力的一半；承山期间可将格挡后余力的20%实际导入地面。每根来袭上限0.75倍、每自身正常行动窗口上限1.5倍最大外功。",1],["移山转岳","太华至多分送1.5倍最大外功的山重；镇朔预埋至多1倍，单段来袭达到0.8倍时，返力至多为该段八成且不超过预埋量。",2],["山河在握","隆起每级增加0.5倍最大外功承载，上限4.5倍；中天倾岳消耗真实隆起并形成崩裂，每级仅得0.15倍有限地势收益。",3],["不拔之根","圆满且接地，每次正常行动窗口回复最大内力的1%；免费行动、预览与刷新不触发。",4],["山川应势","须装配本门且接地，读取本人所在前／后排及全场的现存动态地形；不同种类同时适用，同种只取最高有效等级，最多三级。每级：隆起外功防御+6%；崩裂本门普通招式外功穿透+3点；积水本门招式内力消耗降低5%；冰面本门招式耐力消耗降低5%；燃烧本门普通直接攻击增伤3%；结霜在承山期间额外减伤3%；蒸汽本门普通招式精准率+3个百分点。费用在原有费用修正后、内伤／气绝加费前取整；耐力在原有修正后取整，零消耗不凭空增加费用。燃烧不重复放大山重、返力、持续或独立追加。地形不提供新属性伤害、免费行动或额外格挡；未承山的霜地不减伤。地形消失、移出范围或离地即时失效，不在永久面板叠加。不以无等级的基础山地／水域或天气冒充动态地形。",0]],"playerSigs":{"五脉归一":"五剑环身，各循本脉剑意。天齐可主动蓄起山重，未必等敌人先出手。","接劲入地":"挡住来力，可将余劲沉入地下；承山时还能接引部分来袭，山重满载便须另寻出路。","移山转岳":"既可分力连剑，也可藏力于地，等重击引动返势。","山河在握":"隆起可承更多劲力，也能主动倾覆伤敌；崩裂处则难以久蓄山重。","不拔之根":"立足接地，真气运转绵长，每次正常行动可回复少量内力。","山川应势":"接地御剑，随所在之地转势：隆起护体，裂地破防，水冰省力，余火助剑，霜地稳守，蒸汽凝神。多种地势可共同助益；霜地护持须先承山。"},"moves":[{"id":"press","name":"连峰去天","aliases":["一剑开山"],"tier":0,"type":"hybrid","hpR":6,"qqR":1.6,"cost":24,"cd":1,"wuyueNative":true,"sword":"天齐","playerDesc":"完成后向地下注入2J，并使平整地面隆起一级；已有隆起提高一级，最多三级。崩裂时先消减一级崩裂，本次不同时生出隆起。地形改变在整招结算后提交。","desc":"完成后向地下注入2J，并使平整地面隆起一级；已有隆起提高一级，最多三级。崩裂时先消减一级崩裂，本次不同时生出隆起。地形改变在整招结算后提交。"},{"id":"pierce","name":"泉声咽危石","aliases":["石罅穿泉"],"tier":0,"type":"hybrid","hpR":5.8,"qqR":1.6,"cost":26,"cd":1,"wuyueNative":true,"sword":"朱陵","playerDesc":"专攻防护的基础剑招；被敌方格挡挡掉的劲力可回收全部，每招最多2J，受自身窗口自注入总限约束。已入山重的部分不能在本招立刻释放。","desc":"专攻防护的基础剑招；被敌方格挡挡掉的劲力可回收全部，每招最多2J，受自身窗口自注入总限约束。已入山重的部分不能在本招立刻释放。"},{"id":"fast","name":"飞流直下","aliases":["飞梁渡壑"],"tier":0,"type":"hybrid","hpR":6.4,"qqR":1.6,"cost":28,"cd":0,"wuyueNative":true,"sword":"太华","playerDesc":"三段共用所列总倍率和山重总量；每段各占三分之一。前段正常消耗防护后，后段可乘隙命中。没有额外位移、换位或免费追击。 释放已有山重本金的伤害乘1.3，本金只扣一次。","desc":"三段共用所列总倍率和山重总量；每段各占三分之一。前段正常消耗防护后，后段可乘隙命中。没有额外位移、换位或免费追击。 释放已有山重本金的伤害乘1.3，本金只扣一次。","count":3},{"id":"turn","name":"山回路转","aliases":["峰回路转"],"tier":0,"type":"hybrid","hpR":5.6,"qqR":1.6,"cost":28,"cd":2,"wuyueNative":true,"sword":"镇朔","playerDesc":"先出剑，再将最多1J已有山重预埋。下两段行动间隙内，敌方主动直接攻击的单段有效劲力达到0.8J时触发；返力为该段有效劲力的八成，且不超过预埋余量。至多触发一次，剩余散失，未触发也按原寿命失效。多段轻击不累加凑阈值，预埋不额外抵消来袭伤害。","desc":"先出剑，再将最多1J已有山重预埋。下两段行动间隙内，敌方主动直接攻击的单段有效劲力达到0.8J时触发；返力为该段有效劲力的八成，且不超过预埋余量。至多触发一次，剩余散失，未触发也按原寿命失效。多段轻击不累加凑阈值，预埋不额外抵消来袭伤害。"},{"id":"fall","name":"五岳倒为轻","aliases":["孤峰绝顶"],"tier":0,"type":"hybrid","hpR":8.4,"qqR":2.3,"cost":36,"cd":2,"wuyueNative":true,"sword":"中天","playerDesc":"镇岳：单体，释放山重并保留地面。倾岳：确有隆起时可选，消耗其全部强度，加入有限地势收益并分配为范围伤害，原地留下同强度崩裂。先预留山重，再改变承载，不能塌地后把同一笔山重再收一次。 释放已有山重本金的伤害乘1.8。倾岳每个目标完整承受基础剑伤，仅山重与地势追加总额平分。","desc":"镇岳：单体，释放山重并保留地面。倾岳：确有隆起时可选，消耗其全部强度，加入有限地势收益并分配为范围伤害，原地留下同强度崩裂。先预留山重，再改变承载，不能塌地后把同一笔山重再收一次。 释放已有山重本金的伤害乘1.8。倾岳每个目标完整承受基础剑伤，仅山重与地势追加总额平分。"},{"id":"brace","name":"江流石不转","aliases":["列嶂如屏"],"tier":1,"type":"self","hpR":0,"qqR":0,"cost":18,"cd":2,"wuyueNative":true,"sword":"五剑","playerDesc":"消耗正常行动，按现有上限获得一层格挡，并进入承山，持续至下下次正常行动窗口开始。只护自己，不新设队伍屏障或队友分摊。","desc":"消耗正常行动，按现有上限获得一层格挡，并进入承山，持续至下下次正常行动窗口开始。只护自己，不新设队伍屏障或队友分摊。"},{"id":"mend","name":"地维赖以立","aliases":["地维相接"],"tier":0,"type":"hybrid","hpR":3.6,"qqR":1.1,"cost":18,"cd":1,"wuyueNative":true,"sword":"朱陵","playerDesc":"出剑并消减一级真实崩裂。没有崩裂时仍能出基础剑招，但不凭空生成山重、隆起或队伍连接。","desc":"出剑并消减一级真实崩裂。没有崩裂时仍能出基础剑招，但不凭空生成山重、隆起或队伍连接。"}],"boundaries":"山重份额不重复会心会意或兵器增伤，释放仍受目标防护；多段、多目标共分一份。释放包、反击与持续伤害不能再次收取山重。每份山重独立失效，新战斗清空。 山重保留后续四次自身正常行动机会；天齐连峰自注入最多2倍有效最大外功攻击，敌方借力限额不变。飞流直下释放本金伤害乘1.3，五岳倒为轻乘1.8；本金只扣一次，地脉返力不享受。倾岳每目标完整基础剑伤，仅山重与崩山追加总额平分。"}}};
let WUYUE_SERIAL=number(saved?.wuyueSerial),WUYUE_CONTEXT=null;
const wyKey=f=>f.groupId||runId+':'+f.side;
function wyLedger(f){if(!hasArt(f,'wuyue'))return null;const l=new DLH_WUYUE_FORCE({runId:runId+'/'+wyKey(f),J:Math.max(1,effWMax(f)),saved:f.wuyue});f.wuyue=l.s;return l;}
function wyStats(f){const s=wyLedger(f).s;return s.stats||(s.stats={borrowed:0,injected:0,diverted:0,forceDamage:0,counterDamage:0,casts:{}});}
function wyGrounded(f){return f.grounded!==false&&!f.statuses.some(s=>['离地','失足'].includes(s.name)&&s.turns>0);}
function wyStructure(){return dreamEnv().entries(['隆起','崩裂'],'全场').filter(s=>s.area==='全场').sort((a,b)=>b.strength-a.strength)[0]||null;}
function wySync(f){const l=wyLedger(f);if(!l)return null;const t=wyStructure(),kind=t?.kind==='隆起'&&profTier(f,'wuyue')<3?'平整':t?.kind||'平整',strength=kind==='平整'?0:t?.strength||0;
 if(l.s.terrain.kind!==kind||l.s.terrain.strength!==strength)l.terrain(kind,strength);
 if(l.s.grounded!==wyGrounded(f))l.ground(wyGrounded(f));return l;
}
function wySyncAll(){for(const f of groupActors())if(hasArt(f,'wuyue'))wySync(f);}
function dariBaseInnateBeforeActor(f){if(hasArt(f,'wuyue')){const l=wySync(f),stamp=round+'/'+cursor+'/'+wyKey(f);if(l.s.actorStamp!==stamp){l.beginOpportunity(Math.max(1,effWMax(f)));l.s.actorStamp=stamp;if(profTier(f,'wuyue')>=4&&l.s.grounded){const gain=Math.min(f.neiliMax-f.neili,Math.max(0,f.neiliMax*.01));dariWrite(f,"neili",f.neili+(gain));}}}return wyBaseInnateBeforeActor(f);}
function yxBaseCyclePool(f,list){const out=wyBaseCyclePool(f,list);if(!hasArt(f,'wuyue'))return out;return out.flatMap(m=>m.wuyueNative&&m.id==='fall'&&profTier(f,'wuyue')>=3?[{...m,wyMode:'镇岳',key:'wuyue/fall/镇岳',displayName:m.name+' · 镇岳'},{...m,wyMode:'倾岳',key:'wuyue/fall/倾岳',range:true,targetPolicy:{team:'enemy',scope:GROUP_ENABLED?'all':'single',includeSelf:false,allowDefeated:false},displayName:m.name+' · 倾岳'}]:[m]);}
function cyclePrepare(f,m){const out=wyBaseCyclePrepare(f,m);return out?.wuyueNative&&out.id==='fall'?{...out,key:'wuyue/fall'}:out;}
function yxBaseCycleReason(f,m,t){const reason=wyBaseCycleReason(f,m,t);if(reason||!m?.wuyueNative)return reason;if(f.neili<costOf(f,m))return '内力不足：需要 '+costOf(f,m);if(f.cds['wuyue/'+m.id]>0)return '调息尚未结束';
 const ground=wyGrounded(f);if(m.type==='self'&&!ground)return '脚下尚未立稳，无法承山';if(m.wyMode==='倾岳'&&(!ground||wyStructure()?.kind!=='隆起'))return '须脚踏实地，且场上确有隆起';return '';
}
function tmBaseCycleBegin(f,m,full){const out=wyBaseCycleBegin(f,m,full);if(!out?.wuyueNative)return out;return {...out,wyCastId:wyKey(f)+'/cast/'+ ++WUYUE_SERIAL,key:'wuyue/'+out.id};}
function dreamBaseGroupExecute(f,t,m,full,provided){
 const old=WUYUE_CONTEXT,targets=GROUP_ENABLED?(provided||groupTargets(f,m,undefined,false)):[t];
 WUYUE_CONTEXT={root:m.wyCastId||wyKey(f)+'/root/'+ ++WUYUE_SERIAL,name:m.name,art:m.art,source:wyKey(f),segment:0};
 const ready=m.wuyueNative?{...m,wyTargets:Math.max(1,targets.length)}:m;
 try{return wyBaseResolvedGroupExecute(f,t,ready,full,provided);}finally{if(ready.wuyueNative){const c=wyLedger(f)?.s.commits?.[ready.wyCastId];if(c)wyFinish(f,ready,c);}WUYUE_CONTEXT=old;}
}
function wyCommit(f,m){const l=wySync(f),s=l.s;s.commits||={};if(s.commits[m.wyCastId])return s.commits[m.wyCastId];const tier=profTier(f,'wuyue'),amount=(m.id==='fast'&&tier>=2?1.5:m.id==='fall'?3:0)*s.J;
 let r={principal:0,bonus:0,packets:[]};if(s.grounded&&amount)r=l.cast({id:m.wyCastId,amount,targets:m.wyTargets||1,segments:m.count||1,collapse:false});
 const c={principal:r.principal||0,bonus:0,targets:m.wyTargets||1,segments:m.count||1,finished:false,blocked:0};
 if(m.wyMode==='倾岳'&&s.grounded){const terrain=wyStructure();if(terrain?.kind==='隆起'){const consumed=dreamEnv().take(terrain.token,terrain.strength,round,m.wyCastId);c.collapse=consumed.strength;c.bonus=consumed.strength*.15*s.J;l.s.audit.terrainYield+=c.bonus;}}
 s.commits[m.wyCastId]=c;s.lastSword=m.sword||'';s.lastCast=m.wyCastId;const stats=wyStats(f);stats.casts[m.name]=(stats.casts[m.name]||0)+1;return c;
}
function wyFinish(f,m,c){if(c.finished)return;c.finished=true;const env=dreamEnv(),options={sourceId:wyKey(f),sourceName:f.name,area:'全场',strength:1,turns:3,keepAfterDeath:true};
 if(m.id==='press'){const t=wyStructure();if(t?.kind==='崩裂')env.take(t.token,1,round,m.wyCastId);else env.add('隆起',{...options,strength:Math.min(3,(t?.strength||0)+1)},round,m.wyCastId);}
 if(m.id==='mend'){const t=wyStructure();if(t?.kind==='崩裂')env.take(t.token,1,round,m.wyCastId);}
 if(c.collapse)env.add('崩裂',{...options,strength:c.collapse},round,m.wyCastId);
 wySyncAll();const l=wyLedger(f);if(!groupActive(f)){l.clear();return;}
 const tier=profTier(f,'wuyue');let amount=m.id==='press'?2*l.s.J:m.id==='pierce'?Math.min(2*l.s.J,c.blocked):0;
 if(amount){const n=l.seed({id:m.wyCastId,root:m.wyCastId,completed:true,paid:m.cost>0,free:!!m.free,amount});wyStats(f).injected+=n;if(n)log(f.name+'引剑力入地 · 山重渐蓄','sig');}
 if(m.id==='turn'&&tier>=2&&l.s.grounded&&!l.s.pending&&l.bank){l.cast({id:m.wyCastId+'/trap',amount:Math.min(l.s.J,l.bank),reserve:true});log(f.name+'剑势潜入地脉，待重劲折回','sig');}
}
function tmBaseCycleCast(f,t,m,full){if(!m?.wuyueNative)return wyBaseCycleCast(f,t,m,full);const c=wyCommit(f,m);
 if(m.id==='brace'){const l=wyLedger(f);if(f.blockL.length<3)f.blockL.push({src:'五岳山主'});l.brace();log(f.name+'五剑列嶂，立足承山','sig');return {outcome:{dealt:0,hpLost:0,effectHit:false}};}
 const divisor=m.wyTargets||1,move={...m,hpR:m.hpR,qqR:m.qqR,wyForcePacket:(c.principal+c.bonus)>0,wyForceBudget:(c.principal*(m.id==='fast'?1.3:m.id==='fall'?1.8:1)+c.bonus)/divisor,wySegmentCount:c.segments,segs:Array.from({length:c.segments},()=>({hpR:m.hpR/c.segments,qqR:m.qqR/c.segments}))};
 return {outcome:execMove(f,t,move,full)};
}
function wyForceRaw(f,t,m,qual){if(!(m.wyForceBudget>0))return 0;const flat=effDefs(t,0,0)[0],raw=Math.max(0,m.wyForceBudget-flat)/(m.wySegmentCount||1)*penZone(penV(f,'w',t,m),resV(t,'w',f))*Math.max(0,1-(t.base.wCut||0))*effDR(t)*(qual.includes('擦伤')?.7:1);
 const injury=getSt(t,'伤势加重');return raw*(1+(injury?.stacks||0)*.06)*(getSt(t,'绝念')?1.04:1)*(getSt(t,'离猎')?1.02:1)*(1+.01*(t.qsi||0))*(DREAM_CONFIG.enabled&&!m.dreamNative?DREAM_SCALE:1)*dreamEnv().factor('外伤',protoArea(t),!!m.range);
}
function wyIncoming(f,t,m,pressure,afterBlock,tag){if(!WUYUE_CONTEXT)return null;const ctx=WUYUE_CONTEXT,primary=ctx.source===wyKey(f)&&ctx.name===m.name&&ctx.art===m.art&&!m.free&&!m.reaction&&!m.secondaryDirect&&!m.innateIndependent&&!m.nineBurst&&!m.wyNoBorrow;
 if(m.wuyueNative&&m.id==='pierce'&&primary){const c=wyLedger(f)?.s.commits?.[m.wyCastId];if(c)c.blocked+=Math.max(0,pressure-afterBlock);}
 if(!hasArt(t,'wuyue')||profTier(t,'wuyue')<1)return null;const l=wySync(t),o=l.incoming({id:ctx.root+'/'+wyKey(t)+'/'+ ++ctx.segment,root:ctx.root,hostile:f.side!==t.side,direct:true,primary,landed:true,pressure,blocked:Math.max(0,pressure-afterBlock),forceRelease:!!m.wyForcePacket});
 const stats=wyStats(t);stats.borrowed+=o.gain||0;stats.diverted+=o.diverted||0;if(o.gain)log(t.name+'接劲入地 · 山重渐蓄','sig');return o;
}
function wyAfterHit(f,t,m,o){if(!(o?.counter>0)||!groupActive(t)||!groupActive(f))return;
 const out=strike(t,f,{name:'山回路转·地脉返力',id:'wy-counter',art:'wuyue',type:'hybrid',wyOnlyForce:true,wyForceBudget:o.counter,wySegmentCount:1,wyForcePacket:true,wyNoBorrow:true,secondaryDirect:true,range:true,fx:[]},0,0,'山回路转·地脉返力',true);wyStats(t).counterDamage+=out.hpLost||0;checkEnd(f);
}
function yxBaseCycleClear(f){wyBaseCycleClear(f);if(f.wuyue){new DLH_WUYUE_FORCE({runId:f.wuyue.runId,saved:f.wuyue}).clear();delete f.wuyue;}}
function dreamRoundEnd(){wyBaseDreamRoundEnd();wySyncAll();}
function zwBaseEquipmentWeaponDamage(f,m){return m?.wuyueNative?(f.weaponKind==='剑'?number(DLH_WEAPONS.damageMap(f.weaponDamage).剑):0):wyBaseEquipmentWeaponDamage(f,m);}
function wyView(f){if(!hasArt(f,'wuyue'))return null;const l=new DLH_WUYUE_FORCE({runId:runId+'/'+wyKey(f),J:Math.max(1,effWMax(f)),saved:f.wuyue});return {value:Math.round(l.bank+l.reserved),capacity:Math.round(l.capacity()),reserved:Math.round(l.reserved),brace:l.s.opportunity<l.s.braceUntil,sword:l.s.lastSword||'',cast:l.s.lastCast||'',grounded:wyGrounded(f),terrain:wyTerrainView(f)};}
function wuyueInstall(api){for(const f of groupActors()){if(hasArt(f,'wuyue')){f.arts.wuyue.suitable=null;f.arts.wuyue.sword=true;wySync(f);}}
 const old=api.preview;api.preview=a=>{const out=old(a),m=findMove(P,a);if(!out||!m?.wuyueNative)return out;const state=P.wuyue,view=state?{bank:state.lots.reduce((n,x)=>n+x.amount,0),pending:!!state.pending}:null;let hint=m.playerDesc;
 if(m.id==='fast')hint=view?.bank?'可将已有山重分送三剑；落空的剑势随之散去。':'尚无山重，仍可凭自身剑力连斩。';if(m.id==='fall')hint=m.wyMode==='倾岳'?'此剑将倾覆隆起，波及敌众；脚下也将留下裂地。':'此剑可尽卸山重，保留脚下山势。';if(m.id==='turn')hint=view?.pending?'先前潜伏的剑势尚在；此剑不重复预埋。':view?.bank?'埋下已有山重，等待重劲折回；轻招不会引动。':'尚无山重可埋，仍可施展奇剑伤敌。';const terrain=wyTerrainView(P);return {...out,contextHint:hint+(terrain.length?' 地势：'+terrain.map(x=>x.text).join('；')+'。':''),resourceText:'五剑御山 · '+(view?.bank?'山重已蓄':'地脉初静')};};
 api.wuyueView=id=>{const f=id?groupActors().find(f=>(f.groupId||f.side)===id):P;return f?wyView(f):null;};
}

/* Native Dharma refinement. Persistent state is plain fighter data. */
const DARI_CONFIG={"revision":1,"soloEnabled":true,"counterPerLayer":0.1,"counterCap":3,"healPerLayer":0.1,"healCap":3,"masterDamageReduction":0.1,"masterManaRatio":4,"eightDamageReduction":0.1,"eightManaRatio":5,"eightMinimumTurns":4,"eightDamageFraction":0.25,"eightDistinctMoves":3,"eightLowMana":0.1,"eightStableTurns":4,"eightBaseUpkeep":0.04,"eightUpkeepStep":0.02,"eightPairScale":0.6,"wardRemainingFraction":0.2,"wardBaseQiCap":0.25,"wardOwnTurns":2,"fistHpRatio":1.5,"fistQiRatio":0.75,"fistCost":10,"sunQiRatio":2};
if(DARI_CONFIG.soloEnabled!==false)for(const m of ARTS.dari.moves){
 if(m.id==='jg'){m.hpR=DARI_CONFIG.fistHpRatio;m.qqR=DARI_CONFIG.fistQiRatio;m.cost=DARI_CONFIG.fistCost;}
 if(m.effect==='numuBuff'){m.free='combo';m.dariAnger=true;}
 if(m.effect==='dariFahui'){m.type='pure';m.hpR=0;m.qqR=DARI_CONFIG.sunQiRatio;m.range=true;m.dariSun=true;}
}
let DARI_CAST=null,DARI_PERIODIC=false,DARI_HEAL_BYPASS=0;
function dariState(f){return f.dariV1||(f.dariV1={revision:1,turns:0,received:0,moves:[],used:false,active:false,eightTurns:0,pairRound:-1,window:null,lastEnd:-1,lastDot:-1,ward:0,wardTurns:0});}
function dariOwner(f){return !!f?.arts?.dari;}
function dariMaster(f){return dariOwner(f)&&profTier(f,'dari')>=4;}
function dariLabel(f){return f.groupId||f.side;}
function dariDrop(f,reason){const s=f.dariV1;if(!s?.active)return;s.active=false;s.window=null;log(f.name+'八臂收归法相 · '+reason,'sig');}
function dariLow(f){if(f?.dariV1?.active&&(!f.fxOn||f.neili<=f.neiliMax*DARI_CONFIG.eightLowMana))dariDrop(f,!f.fxOn?'法相已解除':'内力已至一成');}
function dariManaRatio(f){return dariMaster(f)?(f.dariV1?.active?DARI_CONFIG.eightManaRatio:DARI_CONFIG.masterManaRatio):3;}
function dariNewAvatar(f){const old=dariState(f),used=old.used;f.dariV1={...old,turns:0,received:0,moves:[],initialHp:f.fxHp,used,active:false,eightTurns:0,window:null,pairRound:-1,lastEnd:-1,lastDot:-1,ward:0,wardTurns:0};f.as.bhDmg=0;f.as.bhHeal=0;}
function dariClearProgress(f){const s=f.dariV1;if(!s)return;dariDrop(f,'法相已解除');s.turns=0;s.received=0;s.moves=[];s.window=null;f.as.bhDmg=0;f.as.bhHeal=0;}
function dariReadyReason(f){const s=f.dariV1;if(!dariMaster(f))return '八臂天王需大日如来圆满';if(!f.fxOn)return '需三界法相存续';if(s?.used)return '本场已升华过八臂天王';if(f.neili<=f.neiliMax*DARI_CONFIG.eightLowMana)return '内力须高于一成';if((s?.turns||0)<DARI_CONFIG.eightMinimumTurns)return '法相圆成 '+(s?.turns||0)+'/'+DARI_CONFIG.eightMinimumTurns+' 回合';if((s?.received||0)<(s?.initialHp||f.fxHpMax)*DARI_CONFIG.eightDamageFraction)return '金身历劫尚不足初始法相气血的四分之一';if((s?.moves?.length||0)<DARI_CONFIG.eightDistinctMoves)return '诸法归身 '+(s?.moves?.length||0)+'/'+DARI_CONFIG.eightDistinctMoves+' 种有效招式';return '';}
function dariAttackFactor(f,m){if(!f.fxOn||!hasSig(f,'dari','宝华殊严')||m?.secondaryDirect||m?.nineBurst)return 1;const c=DARI_CAST;if(!c||c.source!==f)return 1;if(c.counter===null){c.counter=Math.min(DARI_CONFIG.counterCap,Math.max(0,f.as.bhDmg||0));f.as.bhDmg=0;if(c.counter)log('宝华殊严：'+c.counter+'层反攻强化整招','sig');}return 1+c.counter*DARI_CONFIG.counterPerLayer;}
function dariHealFactor(f){if(!f?.fxOn||!hasSig(f,'dari','宝华殊严'))return 1;const c=DARI_CAST;if(c?.heals.has(f))return c.heals.get(f);const n=Math.min(DARI_CONFIG.healCap,Math.max(0,f.as.bhHeal||0)),factor=1+n*DARI_CONFIG.healPerLayer;if(n){f.as.bhHeal=0;log('宝华殊严：'+n+'层强化本次回复','sig');}if(c)c.heals.set(f,factor);return factor;}
function dariWrite(f,key,next){
 const old=f[key];let value=next;
 if((key==='hp'||key==='neili')&&Number.isFinite(old)&&Number.isFinite(next)){
  if(next>old&&!DARI_HEAL_BYPASS){const source=DARI_CAST?.source&&DARI_CAST.source.side===f.side?DARI_CAST.source:f;const factor=dariHealFactor(source);value=Math.min(f[key==='hp'?'hpMax':'neiliMax'],old+(next-old)*factor);}
  if(key==='hp'&&value<old&&!f.fxOn&&f.dariV1?.ward>0){const s=f.dariV1,blocked=Math.min(s.ward,old-value);s.ward-=blocked;value+=blocked;if(blocked)log(f.name+'散相余辉抵挡 '+Math.round(blocked),'sig');}
 }
 if(key==='hp')value=xmShareHp(f,value);
 f[key]=value;if(key==='neili')dariLow(f);return value;
}
function dariWithCast(f,m,fn){
 dariLow(f);
 if(DARI_CAST?.source===f&&DARI_CAST.move?.art===m?.art&&DARI_CAST.move?.id===m?.id)return fn();
 const previous=DARI_CAST,c={source:f,move:m,counter:null,heals:new Map(),received:new Set(),hit:false,made:false};DARI_CAST=c;
 let completed=false;try{const out=fn();completed=true;return out;}finally{
  DARI_CAST=previous;
  if(f.fxOn&&hasSig(f,'dari','宝华殊严')&&c.made)f.as.bhHeal=Math.min(DARI_CONFIG.healCap,(f.as.bhHeal||0)+1);
  if(f.fxOn&&dariOwner(f)&&c.hit&&!m?.free&&!m?.reaction&&!m?.dariPair&&!m?.secondaryDirect&&!m?.innateIndependent&&!m?.nineBurst&&!m?.wyOnlyForce&&m?.art&&m.art!=='dari'&&m.art!=='none'){
   const s=dariState(f),key=m.art+'/'+(m.id||m.name);if(!s.moves.includes(key))s.moves.push(key);s.lastMain={round,art:m.art,key};if(s.active)s.window=s.lastMain;
  }
  if(completed&&(m?.dariPair||m?.dariEight||m?.dariAnger)){const cs=comboState(f);if(cs.freeRound!==round){cs.freeRound=round;cs.freeCount=0;}cs.freeCount++;}
  if(completed&&m?.dariPair){const s=dariState(f);s.pairRound=round;s.window=null;const key=m.dariOriginalKey;f.cds[key]=Math.max(f.cds[key]||0,(m.cd||0)>0?m.cd+1:0);}
  dariLow(f);dariPublish(f);
 }
}
function tmBaseGroupExecute(f,t,m,full,provided){return dariWithCast(f,m,()=>dariBaseGroupExecute(f,t,m,full,provided));}
function tmBaseExecuteMove(f,t,m,full){return dariWithCast(f,m,()=>{if(m.dariSun&&!DARI_CAST.sunApplied){DARI_CAST.sunApplied=true;castSelf(f,{...m,type:'self'});}return dariBaseExecuteMove(f,t,m,full);});}
function tmBaseStrike(f,t,m,h,q,tag,full){const scale=m.dariPair?DARI_CONFIG.eightPairScale:1;const out=dariBaseStrike(f,t,m,h*scale,q*scale,tag,full);if(DARI_CAST?.source===f){DARI_CAST.hit||=!!out?.effectHit;DARI_CAST.made||=out?.dealt>0;}return out;}
function bwBaseSoulHit(f,t,raw,tag,o){const out=dariBaseSoulHit(f,t,raw,tag,o);if(DARI_CAST?.source===f&&!o?.secondary&&!o?.jianFinalDamage){DARI_CAST.hit||=!!out?.effectHit;DARI_CAST.made||=out?.dealt>0;}return out;}
function jmBaseFinishMove(f,t,m,total,full){if(DARI_CAST?.source===f)DARI_CAST.made||=total>0;return dariBaseFinishMove(f,t,m,total,full);}
function xmBaseDealHp(f,d){
 if(!f.fxOn||!dariOwner(f))return dariBaseDealHp(f,d);
 const s=dariState(f),before=f.fxHp,hostile=DARI_CAST?.source?DARI_CAST.source.side!==f.side:true;
 const reduction=dariMaster(f)?(1-DARI_CONFIG.masterDamageReduction)*(s.active?1-DARI_CONFIG.eightDamageReduction:1):1;
 const result=dariBaseDealHp(f,Math.max(0,d*reduction)),lost=Math.max(0,before-f.fxHp);
 if(lost>0&&hostile){s.received+=lost;let gain=false;
  if(DARI_PERIODIC){gain=s.lastDot!==round;s.lastDot=round;}
  else if(DARI_CAST){gain=!DARI_CAST.received.has(f);DARI_CAST.received.add(f);}
  else gain=true;
  if(gain&&f.fxOn&&hasSig(f,'dari','宝华殊严'))f.as.bhDmg=Math.min(DARI_CONFIG.counterCap,(f.as.bhDmg||0)+1);
 }
 if(!f.fxOn)dariClearProgress(f);dariLow(f);dariPublish(f);return result;
}
function tmBaseHealingGain(f,t,amount,label,m={},snap){
 if(!t||t.hp<=0||t.hp>=t.hpMax||!(amount>0))return dariBaseHealingGain(f,t,amount,label,m,snap);
 const run=()=>{const factor=dariHealFactor(f);DARI_HEAL_BYPASS++;try{return dariBaseHealingGain(f,t,amount*factor,label,m,snap);}finally{DARI_HEAL_BYPASS--;}};
 return DARI_CAST?run():dariWithCast(f,{id:'heal/'+label,art:m.art,type:'self'},run);
}
function jmBaseCastSelf(f,m,healer=f){return dariWithCast(healer,m,()=>{
 if(m.dariEight){const why=dariReadyReason(f);if(why)throw Error(why);const s=dariState(f);s.used=s.active=true;s.eightTurns=0;s.window=s.lastMain?.round===round?s.lastMain:null;log(f.name+'升华八臂天王！四臂镇身，四臂演武','sig');dariPublish(f);return;}
 const was=f.fxOn,left=f.fxHp||0,baseQi=f.qiMax/(was&&hasSig(f,'dari','宝华殊严')?2:1),out=dariBaseCastSelf(f,m,healer);
 if(m.effect==='avatar'){
  if(!was&&f.fxOn)dariNewAvatar(f);
  else if(was&&!f.fxOn){dariClearProgress(f);const s=dariState(f);s.ward=Math.max(0,Math.round(Math.min(left*DARI_CONFIG.wardRemainingFraction,baseQi*DARI_CONFIG.wardBaseQiCap)));s.wardTurns=DARI_CONFIG.wardOwnTurns;log(f.name+'收相留辉 · 临时护体 '+s.ward,'sig');}
 }
 dariPublish(f);return out;
});}
function dariUpkeep(f){const s=dariState(f);if(!s.active)return Math.round(f.neiliMax*(dariMaster(f)?.03:.05));return Math.round(f.neiliMax*(DARI_CONFIG.eightBaseUpkeep+Math.max(0,s.eightTurns-DARI_CONFIG.eightStableTurns+1)*DARI_CONFIG.eightUpkeepStep));}
function tmBaseInnateBeforeActor(f){const s=f.dariV1;if(s){s.window=null;if(s.ward>0&&--s.wardTurns<=0)s.ward=0;}dariLow(f);return dariBaseInnateBeforeActor(f);}
function growthBaseEndRound(){const old=DARI_PERIODIC,previous=DARI_CAST;DARI_PERIODIC=true;DARI_CAST={source:null,move:{},counter:null,heals:new Map(),received:new Set()};try{dariBaseEndRound();}finally{DARI_PERIODIC=old;DARI_CAST=previous;for(const f of groupActors()){const s=f.dariV1;if(!s)continue;if(f.fxOn&&s.lastEnd!==round){s.lastEnd=round;s.turns++;if(s.active)s.eightTurns++;s.window=null;}dariLow(f);dariPublish(f);}}}
function dariPeriodicDamage(f,d,source){const previous=DARI_CAST;DARI_CAST={source,move:{},counter:null,heals:new Map(),received:new Set()};try{return dealHp(f,d);}finally{DARI_CAST=previous;}}
function dariTick(f,s,fn){const source=groupDotSource(f,s),old=DARI_PERIODIC;DARI_PERIODIC=true;try{return dariWithCast(source||f,{id:'tick/'+s.name,art:'none',type:'self'},fn);}finally{DARI_PERIODIC=old;}}
function cycleTick(f,s){return dariTick(f,s,()=>dariBaseCycleTick(f,s));}
function innateTick(f,s){return dariTick(f,s,()=>dariBaseInnateTick(f,s));}
function nineTick(f,s){return dariTick(f,s,()=>dariBaseNineTick(f,s));}
function dariEligiblePair(m){return m.art&&m.art!=='none'&&m.art!=='dari'&&!m.free&&!m.reaction&&!m.charge&&!m.chargeDyn&&!m.cycleInstant&&!m.dreamNative&&!m.soul&&!m.soulDot&&!m.delay&&m.customChannel!=='soul'&&['pure','hybrid'].includes(m.type)&&(m.hpR>0||m.qqR>0||m.segs?.length);}
function tmBasePool(f){const all=dariBasePool(f);if(!dariOwner(f))return all;const s=f.dariV1;
 if(dariMaster(f))all.push({id:'eight',key:'dari/eight',art:'dari',name:'八臂天王',type:'self',effect:'dariEight',dariEight:true,hpR:0,qqR:0,cost:0,cd:0,free:'combo',desc:'法相历劫、诸法归身、四回合圆成后升华；每场一次。内力降至一成自动收归普通法相。',resourceText:s?.active?'八臂存续 · 下次维持 '+dariUpkeep(f):dariReadyReason(f)||'法相圆成 · 可升华'});
 if(s?.active&&s.window?.round===round&&s.pairRound!==round)for(const m of all.slice())if(dariEligiblePair(m)&&m.art!==s.window.art)all.push({...m,key:m.key+'~eight',dariOriginalKey:m.key,dariPair:true,free:'combo',displayName:m.name+' · 八臂合演',resourceText:'接另一门武学 · 攻击倍率60% · 正常费用与调息'});
 return all;
}
function tmBaseUnavailable(f,m,t){if(m?.dariEight||m?.dariPair||m?.dariAnger){const cs=f.combo;if(cs?.freeRound===round&&cs.freeCount>=COMBO_FREE_LIMIT)return '本轮免主动作次数已用尽';}if(m?.dariAnger&&!f.fxOn)return '金刚怒目需法相存在';if(m?.dariEight){const why=dariReadyReason(f);if(why)return why;}if(m?.dariPair){const s=f.dariV1;if(!s?.active||s.window?.round!==round||s.pairRound===round||s.window.art===m.art)return '本回合没有可用的八臂合演';if(f.cds[m.dariOriginalKey]>0)return '原招尚在调息';}return dariBaseUnavailable(f,m,t);}
function innateReason(f,m,t){return dariBaseInnateReason(f,m?.dariPair?{...m,free:false}:m,t);}
function tmBasePreview(a){const p=dariBasePreview(a),m=findMove(P,a);return p&&m?.dariEight?{...p,freeAction:true,resourceText:dariReadyReason(P)||'本场一次 · 升华八臂天王'}:p&&m?.dariPair?{...p,freeAction:true,resourceText:'接另一门武学 · 攻击倍率60% · 正常费用与调息'}:p;}
function tmBaseGenAction(f,kind){const out=dariBaseGenAction(f,kind);return out;}
function tmBaseCheckEnd(f){const out=dariBaseCheckEnd(f);if(over||f.hp<=0||f.retired)for(const unit of groupActors())if(unit.dariV1&&(over||unit.hp<=0||unit.retired)){dariClearProgress(unit);unit.dariV1.ward=0;dariPublish(unit);}return out;}
function dariPublish(f){/* UI derives state from the checkpoint; no synthetic timed buffs. */}
function dariView(f){const s=f.dariV1;return {active:!!s?.active,used:!!s?.used,turns:s?.turns||0,received:s?.received||0,requiredDamage:(s?.initialHp||0)*DARI_CONFIG.eightDamageFraction,moves:(s?.moves||[]).slice(),requiredMoves:DARI_CONFIG.eightDistinctMoves,requiredTurns:DARI_CONFIG.eightMinimumTurns,upkeep:s?.active?dariUpkeep(f):0,ward:s?.ward||0,readyReason:dariReadyReason(f)};}
function dariInstall(api){for(const f of groupActors()){if(f.dariV1){f.as.bhDmg=Math.min(DARI_CONFIG.counterCap,f.as.bhDmg||0);f.as.bhHeal=Math.min(DARI_CONFIG.healCap,f.as.bhHeal||0);dariLow(f);}else if(dariOwner(f)&&f.fxOn)dariNewAvatar(f);}api.dariView=()=>copy(dariView(P));}

/* Native Tianmo. Plain checkpoints; every foreign move has a unique paid source event. */
