function tmCanExtract(m){return !!m&&!m.generic&&m.art&&m.art!=='none'&&m.art!=='tianmo'&&!m.tianmoBorrowed&&!m.free&&!m.reaction&&!m.cycleInstant&&!m.secondaryDirect&&!m.dariPair&&['hybrid','pure'].includes(m.type)&&(m.hpR>0||m.qqR>0);}
