   if(profTier(f,'tianmo')>=2)for(const shape of s.stolen.recipes)base.push({id:'shape-now',key:'tianmo/shape-now/'+shape,name:'笼天地于形内',displayName:'笼天地于形内',variantText:'当轮化相 · '+shape,art:'tianmo',type:'self',hpR:0,qqR:0,cost:TM_RULES.instantShapeMana,cd:0,tianmoNative:true,tmKind:'shape',tmShape:shape,tmSource:s.stolen.event,tmInstant:true,free:'combo',desc:'噬经成功后的当次收尾，消耗夺式化相；不另攻击，后续两次正常行动生效，共用免主动作次数。'});
