function tmEndOverload(f,wound=true){const s=f.tmV1,o=s?.overload;if(!o)return;f.hpMax=Math.max(1,f.hpMax-o.hp);f.neiliMax=Math.max(0,f.neiliMax-o.mana);f.hp=Math.min(f.hp,f.hpMax);f.neili=Math.min(f.neili,f.neiliMax);s.overload=null;if(wound)s.backlashUntil=Math.max(s.backlashUntil||0,s.opportunity+TM_RULES.overloadWoundOpportunities);log(f.name+'极盛魔躯退去，超额上限回落'+(wound?'，三次行动内治疗减半':''),'sig');}
