function tmExternal(f,ext){const s=f.tmV1;if(!s?.scatter||!groupActive(f))return ext;const cut=Math.max(0,Math.min(s.scatter.budget,ext*(s.scatter.fraction??.5)));s.scatter.budget-=cut;s.stats.unloaded+=cut;if(cut)log(f.name+'散魔卸去外功压力 '+Math.round(cut),'sig');return ext-cut;}
function bwBaseCycleCast(f,t,m,full){if(m.tmInstant&&m.type==='self'&&!m.tianmoBorrowed)return {outcome:{effectHit:false,dealt:0,hpLost:0}};if(m.tmKind==='purge'){for(const x of groupActors())if(x.side!==f.side&&x.tmV1?.seed?.target===tmKey(f))x.tmV1.seed=null;log(f.name+'行气驱魔，魔念散尽','sig');return {outcome:{effectHit:false,dealt:0,hpLost:0}};}return tmBaseCycleCast(f,t,m,full);}
function innerBaseExecuteMove(f,t,m,full){if(m.tmWideSplit){const fraction=tmKey(t)===m.tmWidePrimary?TM_RULES.widePrimary:1-TM_RULES.widePrimary;m={...m,tmWideSplit:false,hpR:m.hpR*fraction,qqR:m.qqR*fraction,segs:m.segs?.map(x=>({...x,hpR:x.hpR*fraction,qqR:x.qqR*fraction}))};}const out=tmBaseExecuteMove(f,t,m,full);if(['cleanse','healCleanse'].includes(m.effect)||(m.effects||[]).some(x=>x.kind==='cleanse')){const target=m.targetPolicy?.team==='ally'?t:f;for(const owner of groupActors())if(owner.side!==target.side&&owner.tmV1?.seed?.target===tmKey(target))owner.tmV1.seed=null;}return out;}
