function bwBaseCheckEnd(f){const result=tmBaseCheckEnd(f);if(f.hp<=0&&mode!=='qiecuo')for(const owner of groupActors()){if(!tmOwner(owner)||!groupActive(owner)||owner.side===f.side)continue;const s=tmState(owner),key=tmKey(f);if(s.souls[key]||s.seed?.target!==key)continue;
  const contact=s.contributions[key]||TM_FRAME?.source===owner&&TM_FRAME.before.has(key)&&TM_FRAME.before.get(key).hp>f.hp;s.souls[key]=true;if(!contact||profTier(owner,'tianmo')<1)continue;
  const known=owner===P?(currentData||saved)?.主角?.武学与意境面板?.掌握武学||{}:{};
  const candidates=Object.values(f.arts||{}).filter(a=>!Object.hasOwn(known,a.name)).map(a=>({name:a.name,info:tmSoulInfo(f,a)})).filter(a=>a.info);
  if(candidates.length&&rnd()<TM_RULES.soulChance[profTier(owner,'tianmo')]){const art=candidates[Math.floor(rnd()*candidates.length)];s.awards.push({event:runId+'/soul/'+key,name:art.name,info:art.info});recordBattleConsequence(owner,'tianmo/soul/'+key,{招式:'噬魂夺魄',来源人物:f.name,永久获得武学:art.name,起始熟练度:'皮毛',写入:'战斗结束后本地发放，正文不得重复奖励'});log(owner.name+'噬魂夺魄 · 摄得'+art.name+'，由皮毛起修','sig');}
 }if(!groupActive(f)){if(f.tmV1)f.tmV1.seed=null;for(const owner of groupActors())if(owner.tmV1?.seed?.target===tmKey(f))owner.tmV1.seed=null;}return result;}
function tmCleanup(){for(const f of groupActors())if(f.tmV1){tmEndOverload(f,false);f.tmV1.seed=f.tmV1.stolen=f.tmV1.shape=f.tmV1.scatter=null;}}
function tmView(f){const s=f?.tmV1;if(!s||!tmOwner(f))return null;const host=tmHost(f);return {stock:Math.floor(s.stock),spent:Math.round(s.spent),capacity:s.capacity,body:s.overload?'极盛魔躯':s.scatter?'散魔':'凝身',overload:s.overload?{remaining:Math.max(0,s.overload.until-s.opportunity-(f===P&&mainActionUsed?1:0)),min:TM_RULES.overloadMinAttack,max:TM_RULES.overloadMaxAttack,hp:s.overload.hp,mana:s.overload.mana,wMin:effWMin(f),wMax:effWMax(f),qMin:effQiMin(f),qMax:effQiAtk(f)}:null,overloadUsed:!!s.overloadUsed,scatter:s.scatter?Math.round(s.scatter.budget):0,host:host?.name||'',seedRemaining:s.seed?Math.max(0,s.seed.until-s.opportunity):0,observed:s.seed?.observed?{name:s.seed.observed.name,reason:s.seed.observed.reason,structure:!!s.seed.observed.structure,recipes:s.seed.observed.recipes}:null,stolen:s.stolen?{name:s.stolen.name,source:s.stolen.sourceArt,recipes:s.stolen.recipes,canReplay:!!s.stolen.move,reason:s.stolen.reason,instant:tmInstantOpen(f,s),cost:s.stolen.move?.cost??s.stolen.cost??0,charge:s.stolen.move?.charge??s.stolen.charge??0}:null,shape:s.shape?.kind||'',extremeUsed:s.extremeUsed,backlash:s.opportunity<(s.backlashUntil||0),woundRemaining:Math.max(0,Math.max(s.woundUntil,s.backlashUntil||0)-s.opportunity),wounded:s.opportunity<Math.max(s.woundUntil,s.backlashUntil||0)};}
