/* One stored attack and caster-owned blood accounting. Views never settle turns. */
const BW_RULES={"conversionCaps":[0.1,0.25,0.5,1,1],"bloodToMana":0.8,"drinkRatios":[0.15,0.3,0.3,0.3,0.3],"drinkCap":0.12,"drawRatio":0.8,"drawCap":0.18,"reapRatio":1,"reapCap":0.18,"totalHealCap":0.2,"seaBleedRatio":0.4,"seaHealCap":0.04,"seaUpkeep":12,"seaDamageReduction":0.08,"bleedDamageReductionPerLayer":0.02,"bleedSpeedReductionPerLayer":0.03,"essenceHpCost":0.1,"essenceManaCost":0.3,"essenceHours":6,"essenceRevive":0.25,"whaleUnlockTier":2,"whaleUpkeep":0.1,"auditedChargeKeys":["huhuang/hsbf","lingmu/wk","jian/thousands","jiju/heavy"]};
let BW_CAST=null;
function bwKey(f){return f.groupId||f.side;}
function bwBlood(f){return !!f?.arts?.xueshen;}
function bwWhale(f){return !!f?.arts?.changjing&&profTier(f,'changjing')>=BW_RULES.whaleUnlockTier;}
function bwOwner(f){return bwBlood(f)||bwWhale(f);}
function bwData(){return currentData||(saved?.主角?saved:null);}
function bwAsset(f){const sd=bwData();return f===P?sd?.主角?.血神记录:GROUP_ENABLED?GROUP_PROFILES[f.groupId]?.profile?.血神记录:(sd?.战斗状态||sd?.主角?.战斗状态)?.敌方?.血神记录;}
function bwState(f){return f.bloodWhale||(f.bloodWhale={version:1,stamp:'',opportunity:0,pending:false,baseHp:f.hpMaxBase||f.hpMax,healed:0,seaHealed:0,convertedRound:-1,sea:false,seaDue:0,stored:null,essence:Math.min(1,Math.max(0,bwAsset(f)?.本源精血||0)),essenceSpent:0});}
function bwResources(f){return {气血:f.hp,最大气血:f.hpMax,内力值:f.neili,最大内力值:f.neiliMax};}
function bwOwnWindow(){return !DREAM_PENDING&&!over&&['player','finish'].includes(phase);}
function bwStoredValid(f,ch){if(!ch||!bwWhale(f))return '内海传承失效';const a=f.arts[ch.mv.art];if(!a||a.tier<(ch.mv.tier||0)||!a.moves?.includes(ch.mv.name))return '原招武学来源或熟练度失效';return jianWeaponReason(f,ch.mv)||'';}
function bwDrop(f,why){const s=f.bloodWhale;if(!s?.stored)return;s.stored=null;log(f.name+'所藏攻势散去 · '+why+'（已付费用不返还）','sig');}
function bwUpkeep(ch){return Math.max(1,Math.ceil(ch.paidMana*BW_RULES.whaleUpkeep));}
function bwBudget(f){const s=f.bloodWhale;let available=f.neili,whale=0,sea=0;if(!s?.pending)return {available,whale,sea};if(s.stored&&!bwStoredValid(f,s.stored)){const fee=bwUpkeep(s.stored);if(available>=fee){whale=fee;available-=fee;}}if(s.sea&&s.seaDue&&available>=s.seaDue){sea=s.seaDue;available-=sea;}return {available,whale,sea};}
function bwSpend(f,n,label){if(!n)return;dariWrite(f,'neili',f.neili-n);xlSpend(f,n);log(f.name+label+' · 内力-'+n,'sig');}
function bwCommit(f,advance=true){const s=f.bloodWhale;if(!s?.pending)return;s.pending=false;
 if(s.stored){const why=bwStoredValid(f,s.stored);if(why)bwDrop(f,why);else{const fee=bwUpkeep(s.stored);if(f.neili<fee)bwDrop(f,'内力不足以续养');else{bwSpend(f,fee,'续养藏招');if(advance&&s.stored.left>0){s.stored.left--;log(f.name+(s.stored.left?'藏招仍需 '+s.stored.left+' 次正常机会':'所藏【'+s.stored.mv.name+'】已成招待发'),'sig');}}}}
 if(s.sea&&s.seaDue){if(!bwBlood(f)||f.neili<s.seaDue){s.sea=false;log(f.name+'血海消散 · 无法继续行气或内力不足','sig');}else bwSpend(f,s.seaDue,'维持血海');}s.seaDue=0;
}
function yxBaseInnateBeforeActor(f){const out=bwBaseInnateBeforeActor(f);if(!bwOwner(f))return out;const s=bwState(f),stamp=round+'/'+cursor+'/'+bwKey(f);if(s.normalRound!==round){s.normalRound=round;s.stamp=stamp;s.opportunity++;s.healed=s.seaHealed=0;s.pending=true;s.seaDue=s.sea?BW_RULES.seaUpkeep:0;}return out;}
function prevented(f){const stun=!!getSt(f,'眩晕')&&!getSt(f,'霸体'),retains=!!getSt(f,'强韧');const yes=bwBasePrevented(f);if(yes&&f.bloodWhale){if(stun&&!retains)bwDrop(f,'眩晕打断');bwCommit(f,false);}return yes;}
function bwWeak(f){return Math.max(0,...f.statuses.filter(s=>s.name==='流血'&&s.src==='血神子'&&s.bloodOwned&&s.turns>0).map(s=>Math.min(5,s.bleedLayers?.length??s.stacks??0)));}
function bwDirectFactor(f){const sea=groupActors().some(x=>x.side!==f.side&&groupActive(x)&&x.bloodWhale?.sea);return (1-bwWeak(f)*BW_RULES.bleedDamageReductionPerLayer)*(sea?1-BW_RULES.seaDamageReduction:1);}
function curioBaseEffSpd(f){return bwBaseEffSpd(f)*(1-bwWeak(f)*BW_RULES.bleedSpeedReductionPerLayer);}
function bwHeal(f,amount,castCap,label,sea=false){if(!bwBlood(f)||!groupActive(f)||amount<=0)return 0;const s=bwState(f);let budget=Math.max(0,s.baseHp*BW_RULES.totalHealCap-s.healed);if(sea)budget=Math.min(budget,Math.max(0,s.baseHp*BW_RULES.seaHealCap-s.seaHealed));const raw=Math.min(amount,castCap,budget);if(raw<=0)return 0;const before=f.hp;healingGain(f,f,raw,label,{}, {name:f.name,crit:0,ins:0,critMultiplier:1,insMultiplier:1});const gained=Math.max(0,f.hp-before);s.healed+=gained;if(sea)s.seaHealed+=gained;return gained;}
function bwBleedGain(f,t,s,lost){if(f&&f.side!==t.side&&s.src==='血神子'&&s.bloodOwned&&f.bloodWhale?.sea)bwHeal(f,lost*BW_RULES.seaBleedRatio,Infinity,'血海收摄',true);}
function bwHeavy(f,t,lost){if(f.side!==t.side&&t.bloodWhale?.stored&&lost>=t.bloodWhale.baseHp*.25&&!getSt(t,'强韧')&&!getSt(t,'霸体'))bwDrop(t,'单次命中损失基准气血25%，重创打断');}
function iwBaseStrike(f,t,m,h,q,tag,full){const k=bwDirectFactor(f),out=bwBaseStrike(f,t,m,h*k,q*k,tag,full);bwHeavy(f,t,out?.hpLost||0);if(BW_CAST?.source===f&&m.bloodNative&&t.side!==f.side){BW_CAST.lost+=Math.max(0,out?.hpLost||0);if(m.id==='bleed'&&full!==false&&out?.effectHit&&out.hpLost>0&&!t.fxOn&&!BW_CAST.bled.has(bwKey(t))){BW_CAST.bled.add(bwKey(t));genericBleedApply(f,t,{...m,source:'血神子'},{stacks:2,turns:4,stacking:'add',ratio:.1});const s=t.statuses.find(s=>s.src==='血神子'&&genericBleedSource(t,s)===f);if(s)s.bloodOwned=true;}}return out;}
function iwBaseSoulHit(f,t,raw,label,options={}){const before=t.hp,out=bwBaseSoulHit(f,t,raw*(options.secondary?1:bwDirectFactor(f)),label,options);bwHeavy(f,t,hpLost(t,before));return out;}
function xlBaseGroupExecute(f,t,m,full,provided){if(!m?.bloodNative)return bwBaseGroupExecute(f,t,m,full,provided);const old=BW_CAST,frame={source:f,lost:0,bled:new Set()};BW_CAST=frame;try{return bwBaseGroupExecute(f,t,m,full,provided);}finally{BW_CAST=old;if(full!==false&&['drink','draw','reap'].includes(m.id)){const s=bwState(f),ratio=m.id==='drink'?BW_RULES.drinkRatios[profTier(f,'xueshen')]:m.id==='draw'?BW_RULES.drawRatio:BW_RULES.reapRatio,cap=m.id==='drink'?BW_RULES.drinkCap:m.id==='draw'?BW_RULES.drawCap:BW_RULES.reapCap;bwHeal(f,frame.lost*ratio,s.baseHp*cap,m.name+'·饮血');}}}
function yxBaseCycleCast(f,t,m,full){if(!m?.bloodNative)return bwBaseCycleCast(f,t,m,full);if(m.id==='sea'){if(full===false)return {outcome:{effectHit:false,hpLost:0,dealt:0}};const s=bwState(f);s.sea=true;s.seaDue=0;log(f.name+'展开血海 · 后续每正常机会耗内力'+BW_RULES.seaUpkeep,'sig');return {outcome:{effectHit:false,hpLost:0,dealt:0}};}return {outcome:execMove(f,t,m,full)};}
function bwAudited(f,m){if(!m||m.type==='self'||m.free||m.reaction||m.tianmoNative||m.tianmoBorrowed||m.bwRelease||!(m.charge||m.chargeDyn)||!(m.cost>0))return false;return BW_RULES.auditedChargeKeys.includes(m.art+'/'+m.id)||m.custom&&!m.packageMove&&!m.resourceCosts?.length&&!m.requirements?.resources?.length&&!f.arts[m.art]?.packageResourceDefs?.length&&!m.resourceConditions?.length&&!m.effects?.some(x=>x.kind==='resource');}
function reactionMoves(){if(pending?.bloodNative&&pending.ranged)return [];return bwBaseReactionMoves();}
function pool(f){const list=bwBasePool(f);if(!bwOwner(f))return list;const s=bwState(f),out=[];for(const raw of list){let m=raw;if(m.bloodNative&&['drink','draw'].includes(m.id)&&s.sea&&profTier(f,'xueshen')>=4)m={...m,ranged:true,variantText:'身化血海 · 远袭单体，费用与吸血额度照常'};out.push(m);if(bwWhale(f)&&bwAudited(f,m))out.push({...m,key:m.key+'/whale',bwStore:true,bwOriginalKey:m.key,variantText:'藏招于海 · 起手占主动作；后续每次正常机会续耗起手实付内力10%'});}
 if(s.stored)out.push({...copy(s.stored.mv),key:'changjing/release',bwRelease:true,bwOriginalKey:s.stored.mv.key,cost:0,nai:0,charge:0,chargeDyn:false,variantText:'释放藏招 · 占主动作，不重付原费；'+(s.stored.left>0?'尚需 '+Math.max(0,s.stored.left-(s.pending?1:0))+' 次正常机会':'已成招待发')});return out;}
function bwWithBudget(f,fn){const before=f.neili;try{f.neili=bwBudget(f).available;return fn();}finally{f.neili=before;}}
function qimenBaseUnavailable(f,m,t){if(!m)return bwBaseUnavailable(f,m,t);const s=f.bloodWhale;
 if(m.bwRelease){if(!s?.stored)return '没有所藏攻势';const why=bwStoredValid(f,s.stored);if(why)return why;if(s.stored.left-(s.pending?1:0)>0)return '藏招尚未成形';if(s.pending&&!bwBudget(f).whale)return '内力不足以续养并释放';return bwWithBudget(f,()=>bwBaseUnavailable(f,{...s.stored.mv,cost:0,nai:0,charge:0,chargeDyn:false},t));}
 if(s?.stored&&(m.charge||m.chargeDyn))return '已有一记藏招，不能同时再起蓄势';
 if(m.bwStore&&(!bwWhale(f)||!bwAudited(f,m)))return '此招尚未开放藏招';
 if(m.bloodNative){if(m.id==='sea'&&s?.sea)return '血海已经展开';if(m.id==='reap'&&(!s?.sea||!groupActors().some(x=>x.side!==f.side&&groupActive(x)&&x.hp/x.hpMax<=.35)))return '须在血海中选择气血不高于35%的敌人';}
 return bwWithBudget(f,()=>{if(m.bwStore&&f.neili<costOf(f,m))return '藏招须足额支付原招内力';return bwBaseUnavailable(f,m,t);});
}
function intentBasePerform(f,t,m){if(!m)return;bwCommit(f,true);if(m.bloodNative&&m.id==='reap'&&!groupActors().some(x=>x.side!==f.side&&groupActive(x)&&x.hp/x.hpMax<=.35)){log(f.name+'收招 · 已无符合血海抽血条件的目标，未扣招式费','sys');return;}if(m.bwRelease){const s=bwState(f),ch=s.stored;if(!ch)return;const why=bwStoredValid(f,ch)||getSt(f,'眩晕')&&!getSt(f,'强韧')&&!getSt(f,'霸体')&&'眩晕打断';if(why){bwDrop(f,why);return;}s.stored=null;const original=copy(ch.mv);f.art=original.art;cycleAction(f,original);log(f.name+'蓄势完成【'+original.name+'】 · 自内海释放','sig');groupExecute(f,t,original,ch.full,f===P?GROUP_ACTION_TARGETS:undefined);if(original.cd)f.cds[original.key]=original.cd+1;if(f!==P&&!over)enemyFollowups(f,t);checkEnd(f);checkEnd(t);return;}
 if(m.bwStore){const original={...m,key:m.bwOriginalKey};delete original.bwStore;delete original.bwOriginalKey;delete original.variantText;const cost=costOf(f,original);bwBasePerform(f,t,original);if(f.charging){bwState(f).stored={...f.charging,paidMana:cost};f.charging=null;log(f.name+'将【'+original.name+'】沉入气海 · 身体可继续攻守','sig');}return;}return bwBasePerform(f,t,m);
}
function enemyChoice(f=E,def=P){if(bwBlood(f)&&bwState(f).convertedRound!==round){if(f.hp<f.hpMax*.35&&f.neili>0)bwConvert(f,'manaToHp',Math.min(f.neili,f.hpMax*.2));else if(f.neili<f.neiliMax*.15&&f.hp>f.hpMax*.65)bwConvert(f,'hpToMana',f.hpMax*.1);}bwCommit(f,true);const s=f.bloodWhale;if(s?.stored&&s.stored.left<=0){const release=pool(f).find(x=>x.bwRelease);if(release&&!unavailable(f,release,def))return release;}return bwBaseEnemyChoice(f,def);}
function bwRevive(f){const s=f.bloodWhale;if(!bwBlood(f)||profTier(f,'xueshen')<4||!s?.essence||mode==='qiecuo')return false;s.essence=0;s.essenceSpent++;f.hp=Math.max(1,Math.min(f.hpMax,Math.round(s.baseHp*BW_RULES.essenceRevive)));f.retired=false;log(f.name+'借血重生 · 消耗一滴本源精血，气血复至'+Math.round(f.hp)+'；内力与其他资源照旧','sig');recordBattleConsequence(f,'xueshen/essence/'+s.essenceSpent,{招式:'借血重生',消耗本源精血:1,剩余本源精血:0,恢复气血:Math.round(f.hp),后续影响:'一滴精血已实际耗尽，需场外付血与内力并温养六时辰重新凝炼；伤病与其他消耗不撤销。'});return true;}
function curioBaseCheckEnd(f){const out=bwBaseCheckEnd(f);if(over){for(const unit of groupActors())if(unit.bloodWhale){unit.bloodWhale.stored=null;unit.bloodWhale.sea=false;}}else if(!groupActive(f)&&f.bloodWhale){f.bloodWhale.stored=null;f.bloodWhale.sea=false;}return out;}
function bwConvertQuote(f,direction,amount){return DLH_BLOOD.quote(bwResources(f),profTier(f,'xueshen'),direction,amount);}
function bwConvert(f,direction,amount){const q=bwConvertQuote(f,direction,amount);if(q.reason)return q;const s=bwState(f);f.hp=q.after.气血;f.neili=q.after.内力值;s.convertedRound=round;log(f.name+'血气互转 · '+(direction==='manaToHp'?'内力-'+q.spent+'，气血+'+q.gain:'气血-'+q.spent+'，内力+'+q.gain)+'（转化，不触发回复、支出或获取）','sig');return q;}
function bwControl(a){return ['血气互转','散去藏招','收起血海'].includes(a.name);}
function xlBaseReason(a){if(bwControl(a)){if(!bwOwnWindow())return '只能在自己本人的行动回合操作';if(a.name==='散去藏招')return P.bloodWhale?.stored?'':'没有所藏攻势';if(a.name==='收起血海')return P.bloodWhale?.sea?'':'没有展开血海';if(!bwBlood(P))return '未装配血神子';if(bwState(P).convertedRound===round)return '本公共回合已转换';try{return bwConvertQuote(P,a.direction,a.amount).reason;}catch(e){return e.message;}}if(a.name==='切换武器'&&P.bloodWhale?.stored)return '藏招期间不可切换兵器，可先散招';return bwBaseReason(a);}
/* One event per committed whole cast; all state lives in the battle checkpoint. */
let INTENT_CAST=null;
function intentId(f){return f.groupId||f.side;}
function intentState(f){return f.intentV1||null;}
function intentOwnTurn(f){return GROUP_ENABLED?order[cursor]===f.groupId:order[cursor]===f.side;}
function intentExpiry(f){const s=intentState(f);if(!s)return;for(const [id,x]of Object.entries(s.tracks))if(x.until<round)delete s.tracks[id];}
function intentModifiers(f,k){return (f?.statuses||[]).filter(s=>s.intentBuff&&s.turns>0).flatMap(s=>(s.intentModifiers||[]).filter(m=>m.key===k).map(m=>({k,v:m.value*(s.stacks||1),equipment:true})));}
function intentCondition(f,e,c){const s=f.intentV1,t=s.tracks[c.ref]?.value||0,buff=()=>f.statuses.some(x=>x.intentBuff===s.owner+'/'+c.ref&&x.turns>0);switch(c.kind){case'trackAtLeast':return t>=c.amount;case'trackBelow':return t<c.amount;case'buff':return buff();case'notBuff':return !buff();case'sameTarget':return !!e.target&&s.lastTarget===intentId(e.target);case'singleTarget':return e.single===true;case'hit':return e.hit===true;case'blocked':return e.blocked===true;case'dodged':return e.dodged===true;case'chargeHit':return !!s.chargeHit;case'hpBelow':return f.hp/f.hpMax<c.amount;case'neiliBelow':return f.neili/f.neiliMax<c.amount;case'defenseKind':return e.defenseKind===c.value;default:return false;}}
function intentEmit(f,on,e={}){
 const s=intentState(f);if(!s||f.hp<=0)return;intentExpiry(f);
 for(const term of s.definition.terms){if(term.tier>s.tier)continue;
  for(let i=0;i<term.rules.length;i++){
   const r=term.rules[i],key=term.id+'/'+i;if(r.on!==on||round-(s.fired[key]??-999)<r.cooldown||!r.conditions.every(c=>intentCondition(f,e,c)))continue;
   // Check all costs before any effect: a refused operation never half-spends.
   if(r.effects.some(x=>x.kind==='spend'&&(s.tracks[x.ref]?.value||0)<x.amount))continue;
   const before=copy(s.tracks);s.fired[key]=round;
   for(const fx of r.effects){const t=fx.target==='enemy'?e.target:f;if(!t||t.hp<=0)continue;
    if(fx.kind==='gain'){const d=s.definition.tracks.find(x=>x.id===fx.ref),old=s.tracks[fx.ref]?.value||0;s.tracks[fx.ref]={value:Math.min(d.maximum,old+fx.amount),until:round+d.turns-1};log(f.name+'【'+term.name+'】'+d.name+' '+s.tracks[fx.ref].value+'/'+d.maximum,'sig');}
    else if(fx.kind==='spend'){s.tracks[fx.ref].value-=fx.amount;log(f.name+'【'+term.name+'】消费'+fx.amount+'层'+s.definition.tracks.find(x=>x.id===fx.ref).name,'sig');}
    else if(fx.kind==='removeBuff'){f.statuses=f.statuses.filter(x=>x.intentBuff!==s.owner+'/'+fx.ref);log(f.name+'【'+term.name+'】消费'+s.definition.buffs.find(x=>x.id===fx.ref).name,'sig');}
    else if(fx.kind==='buff'){
     const b=s.definition.buffs.find(x=>x.id===fx.ref),key=s.owner+'/'+b.id,old=t.statuses.find(x=>x.intentBuff===key),mods=b.modifiers.map(m=>({key:m.key,value:m.value*(fx.scale?(before[fx.scale]?.value||0):1)}));
     const value={name:s.name+'·'+b.name,label:b.name,description:mods.map(m=>DLH_INTENT.valueText(m.key,m.value)+'／层').join('；')+(b.consume==='none'?'':b.consume==='attack'?'；下一次攻击整招后消费':'；下一次承伤攻击整招后消费'),intentBuff:key,intentModifiers:mods,intentConsume:b.consume,stacks:1,turns:b.turns,expires:round+b.turns,buff:mods.every(m=>m.value>0),src:s.name,owner:f.side,ownerId:intentId(f)};
     if(old){old.stacks=b.stacking==='add'?Math.min(b.maxStacks,old.stacks+1):Math.max(1,old.stacks);old.expires=Math.max(old.expires,value.expires);old.turns=Math.max(old.turns,b.turns);old.intentModifiers=mods;}else t.statuses.push(value);
     log(t.name+'获得【'+b.name+'】 '+b.turns+'回合（'+term.name+'）','sig');
    }else if(fx.kind==='status'){
     if(fx.target==='enemy'&&protectedControl(t,fx.status)){log(t.name+'霸体抵御【'+fx.status+'】','sig');continue;}
     if(['霸体','强韧'].includes(fx.status)){if(getSt(t,'霸体')||getSt(t,fx.status))continue;drunkStatus(t,fx.status,fx.turns);}
     else {addSt(t,fx.status,1,fx.turns);const x=getSt(t,fx.status);if(x){x.src=s.name;x.owner=f.side;x.ownerId=intentId(f);}}
     log(t.name+'获得【'+fx.status+'】 '+fx.turns+'回合（'+term.name+'）','sig');
    }else if(fx.kind==='restore'){
     if(fx.resource==='hp'){healingGain(f,t,t.hpMax*fx.ratio,term.name);continue;}
     const max={qi:'qiMax',neili:'neiliMax',nai:'naiMax'}[fx.resource],delta=Math.max(0,Math.min(t[max]-t[fx.resource],t[max]*fx.ratio));t[fx.resource]+=delta;if(fx.resource==='neili')fwGain(t,delta);log(t.name+'【'+term.name+'】回复'+({qi:'真气',neili:'内力',nai:'耐力'})[fx.resource]+' '+Math.round(delta),'sig');
    }else if(fx.kind==='cleanse'){const index=t.statuses.findIndex(x=>!x.buff&&!x.intentPersistent);if(index>=0){const removed=t.statuses.splice(index,1)[0];log(t.name+'【'+term.name+'】解除'+(removed.label||removed.name),'sig');}}
   }
  }
 }
}
function intentInstallFighter(f,name,y){const d=DLH_INTENT.resolve(name,y);if(!d)return;f.intentV1={version:1,name,owner:intentId(f)+'/'+name,tier:DLH_INTENT.tier(y),definition:copy(d),tracks:{},fired:{},serial:0,lastTarget:'',chargeHit:false,chargeKey:''};}
function intentRoundEnd(){for(const f of groupActors()){intentExpiry(f);intentEmit(f,'roundEnd',{target:groupOpponent(f),single:!GROUP_ENABLED});}}
function intentBeforeStrike(atk,def,mv){if(!INTENT_CAST||INTENT_CAST.f!==atk||mv?.secondaryDirect||mv?.nineBurst||mv?.innateIndependent||mv?.wyOnlyForce)return null;return {hp:def.hp,qi:def.qi,fx:def.fxHp||0,mul:def.mulHp||0,block:def.blockL.length,dodge:def.dodgeL.length,dodgeRound:def.dodgedRound};}
function intentAfterStrike(atk,def,mv,before,result){
 if(!before||!INTENT_CAST||INTENT_CAST.f!==atk)return;
 const c=INTENT_CAST,id=intentId(def),x=c.results[id]||(c.results[id]={target:def,count:0,dodges:0,blocked:false,hit:false,taken:false,buffs:new Set(def.statuses.filter(x=>x.intentConsume==='hit').map(x=>x.intentBuff))});x.count++;
 x.dodges+=!!(before.dodge>def.dodgeL.length&&def.dodgedRound===round&&def.hp===before.hp&&def.qi===before.qi&&result?.dealt===0);
 x.blocked=x.blocked||(result?.blocked===undefined?before.block>def.blockL.length:result.blocked===true);
 x.hit=x.hit||def.hp<before.hp||def.qi<before.qi;
 x.taken=x.taken||x.hit||(def.fxHp||0)<before.fx||(def.mulHp||0)<before.mul;
}
function intentCast(f,t,m,full,provided){
 if(!groupActors().some(x=>x.intentV1||x.statuses.some(s=>s.intentBuff))||!intentOwnTurn(f)||INTENT_CAST||m.reaction||m.free==='combo'||m.secondaryDirect||m.innateIndependent||m.nineBurst||m.wyOnlyForce)return intentBaseGroupExecute(f,t,m,full,provided);
 const policy=groupPolicy(f,m),targets=GROUP_ENABLED?(provided||groupTargets(f,m,undefined,false)):[t],isAttack=policy?.team==='enemy'&&m.type!=='self';
 if(!isAttack)return intentBaseGroupExecute(f,t,m,full,provided);
 const s=intentState(f),e={target:t,single:targets.length===1&&!m.range},c={f,results:{},buffs:new Set(f.statuses.filter(x=>x.intentConsume==='attack').map(x=>x.intentBuff))};
 INTENT_CAST=c;
 try{
  if(s?.chargeKey&&s.chargeKey===(m.key||m.name)){intentEmit(f,'chargeRelease',e);s.chargeKey='';}
  intentEmit(f,'attackStart',e);
  // attackStart may grant a bonus explicitly intended for this very cast.
  for(const x of f.statuses)if(x.intentConsume==='attack')c.buffs.add(x.intentBuff);
  intentBaseGroupExecute(f,t,m,full,provided);
  const rows=Object.values(c.results),primary=rows.find(x=>x.target===t);e.hit=!!primary?.hit;e.blocked=!!primary?.blocked;e.dodged=!!primary&&primary.count===primary.dodges;
  f.statuses=f.statuses.filter(x=>!c.buffs.has(x.intentBuff));
  for(const x of rows){const d=x.target,ev={target:f,single:targets.length===1,hit:x.hit,blocked:x.blocked,dodged:x.count===x.dodges};
   if(x.taken){d.statuses=d.statuses.filter(b=>!x.buffs.has(b.intentBuff));if(d.intentV1&&d.charging)d.intentV1.chargeHit=true;intentEmit(d,'hitTaken',ev);}
   if(x.blocked)intentEmit(d,'block',ev);if(x.count===x.dodges)intentEmit(d,'dodge',ev);
  }
  intentEmit(f,'attackEnd',e);if(s)s.lastTarget=e.single&&t.hp>0?intentId(t):'';
 }finally{INTENT_CAST=null;}
}
function curioBaseGroupExecute(f,t,m,full,provided){return intentCast(f,t,m,full,provided);}
function curioBaseStrike(atk,def,mv,hpR,qqR,tag,full){const b=intentBeforeStrike(atk,def,mv),result=intentBaseStrike(atk,def,mv,hpR,qqR,tag,full);intentAfterStrike(atk,def,mv,b,result);return result;}
function curioBaseSoulHit(atk,def,raw,tag,opts){const b=opts?.secondary?null:intentBeforeStrike(atk,def,opts?.sourceMove),r=intentBaseSoulHit(atk,def,raw,tag,opts);intentAfterStrike(atk,def,opts?.sourceMove,b,r);return r;}
function curioBaseGenAction(f,kind){const before=f.nai;intentBaseGenAction(f,kind);if(f.nai<before&&intentOwnTurn(f))intentEmit(f,'defend',{target:groupOpponent(f),single:!GROUP_ENABLED,defenseKind:kind});}
function qimenBasePerform(f,def,m){const before=f.charging;intentBasePerform(f,def,m);if(f.intentV1&&f.charging&&f.charging!==before&&intentOwnTurn(f)){f.intentV1.chargeKey=m.key||m.name;f.intentV1.chargeHit=false;intentEmit(f,'chargeStart',{target:def,single:!m.range});}}

/* Authored curio events. Only checkpoint fields persist; derived effects never recurse. */
let CURIO_CAST=null,CURIO_DEPTH=0;
const curioId=f=>f.groupId||f.side;
const curioOwned=(f,id)=>!!f?.curioV1?.owned?.includes(id);
function curioSyncStatus(f){const c=f?.curioV1;if(!c)return;for(const kind of ['tracks','poisons','questions','marks'])for(const[id,s]of Object.entries(c[kind]||{}))if(s.shown&&!f.statuses.some(x=>x.curioRef===kind+'/'+id))delete c[kind][id];if(c.candle?.shown&&!f.statuses.some(x=>x.curioRef==='candle'))delete c.candle;}
function curioState(f){return f.curioV1||(f.curioV1={version:1,owned:[],tracks:{},fired:{},poisons:{},questions:{},marks:{},acc:0});}
function curioTrack(f,id){curioSyncStatus(f);const s=f?.curioV1?.tracks?.[id];return s&&s.until>=round?s.stacks:0;}
function curioReady(f,id,interval){return round-(f.curioV1?.fired?.[id]??-999)>=interval;}
function curioGain(f,id,label,amount,max,turns){const c=curioState(f),old=curioTrack(f,id);c.tracks[id]={stacks:Math.min(max,old+amount),until:round+turns-1};log(f.name+'【'+label+'】'+c.tracks[id].stacks+'/'+max+'层 · '+turns+'回合','sig');curioPublish(f);}
function curioControlled(f){return [...CONTROL_STATUS].some(n=>!!getSt(f,n));}
function curioOutgoing(f,t,m={},periodic=false){let gain=0;if(curioOwned(f,'yishui'))gain+=curioTrack(f,'yishui')*.01*(curioControlled(t)?2:1);if(curioOwned(f,'return')&&(f.curioV1.returnUntil??-1)<round)gain+=.08;if(!periodic&&curioOwned(f,'mighty')&&(m.charge>0||m.curioCharged)){gain+=.15+Math.min(.10,Math.floor((Math.max(0,f.naiMax-f.nai)/Math.max(1,f.naiMax))*10+1e-9)*.02);}return 1+gain;}
function curioIncoming(f,source){curioSyncStatus(f);if(source)curioSyncStatus(source);const c=f?.curioV1;let factor=1;if(!c)return factor;let extra=(c.candle?.until>=round?c.candle.stacks*.03:0);if(curioOwned(f,'return')&&c.cage&&(c.cageUntil??-1)<round)extra+=.03;factor*=1+extra;if(curioTrack(f,'heart'))factor*=.8;if(curioOwned(f,'shadow')&&(f.dodgeL.length||c.dodgeRound===round))factor*=.8;if(source){const q=source.curioV1?.questions?.[curioId(f)];if(q?.until>=round)factor*=1-.03*q.stacks;}return factor;}
function curioRestoreHp(f,amount,label){if(f.hp<=0)return 0;const gained=Math.max(0,Math.min(f.hpMax-f.hp,Math.round(amount)));if(gained){f.hp+=gained;log(f.name+'【'+label+'】气血+'+gained,'sig');}return gained;}
function curioNaiChanged(f,delta){if(!curioOwned(f,'spark')||!delta)return;const c=f.curioV1;if(Math.abs(delta)>=10-1e-8)curioGain(f,'spark','星火',1,10,10);if(delta>=0)return;c.acc+=-delta;f.nai=Math.min(f.naiMax,f.nai-delta*.07);log(f.name+'【燎原星火】返还耐力 '+R1(-delta*.07),'sig');if(c.acc>=50&&curioReady(f,'sparkRefund',20)){c.acc-=50;c.fired.sparkRefund=round;f.nai=Math.min(f.naiMax,f.nai+10);log(f.name+'【燎原星火】累计消耗达标，耐力+10','sig');}}
