 const m=context.move,scope=context.scope||'move',cast=context.cast||INNER_CAST;
 let bonus=0;
 for(const x of rows){const r=x.r;
  if(r.kind==='recoveryMode'&&['move','passive','natural'].includes(scope)){
   const maximum=r.resource==='qi'?f.qiMax:f.neiliMax,low=maximum>0&&f[r.resource]/maximum<r.threshold;
   if(key===(low?r.lowResource:r.highResource))bonus+=low?r.lowRatio:r.highRatio;
  }
  if(r.kind==='actionRhythm'&&key==='qi'&&scope==='move'&&cast?.f===f&&cast.eligible&&m?.type==='self'&&!m.charge&&!m.reaction&&cast.previous===r.previous)bonus+=r.ratio;
  if(r.kind==='adversity'&&['move','passive','natural'].includes(scope)&&key===(r.benefit==='restoreQi'?'qi':r.benefit==='restoreNeili'?'neili':'')&&f.innerV1?.adversity?.[x.key]?.active&&f.innerV1.adversity[x.key].round===(context.at??round))bonus+=r.ratio;
 }
