function lightPayment(f,m,paid){if(!lightEntries(f).length||!lightEligible(m))return;const s=lightState(f);s.payment={id:++s.serial,key:m.key||m.art+'/'+m.id,nai:paid.nai,neili:paid.neili,used:false};if(paid.nai+paid.neili>0&&lightDodgeMove(m)&&s.coupon){const x=lightEntries(f).find(x=>x.key===s.coupon.key);if(x&&lightApplies(x,m)&&s.coupon.until>=round){log(f.name+'【'+x.term.name+'】消费一次身法优惠','sig');s.coupon=null;}}}
