/* Whole-cast windows keep adaptation local; committed protections and quotas are checkpointed. */
let BODY_CAST=null,BODY_PACKET=null;
const BODY_INDEX=new WeakMap();
function bodyEntries(f){if(!f)return [];let list=BODY_INDEX.get(f);if(!list){list=[];for(const[art,a]of Object.entries(f.arts||{}))for(const term of a.packageTerms||[])if(term.trigger==='body')list.push({art,a,term,r:term.body,key:art+'::'+term.id});BODY_INDEX.set(f,list);}return list.filter(x=>x.a.name===f.bodyEquipped&&x.a.tier>=TIERS.indexOf(x.term.tier));}
