function bodyAdaptMain(f,t,m){return bodyDirect(f,t,m)&&!m.free&&!m.reaction&&!m.cycleInstant&&!m.bodyResponse&&!m.proxyDamage&&!m.proxy;}
function bodyAdaptChannels(f,m){return [...o2Channels(f,m,{conversion:m.o2Conversion?{r:m.o2Conversion}:null})].filter(k=>k==='external'||k==='qi').sort().join('+');}
function bodyReceipt(t,m=BODY_CAST.m,at=round){let r=BODY_CAST.targets.get(t);if(!r){const f=BODY_CAST.f,mask=bodyAdaptChannels(f,m),old=t.bodyV1?.adaptation,eligible=bodyAdaptMain(f,t,m),same=eligible&&old&&old.source===bodyAdaptId(f)&&old.mask===mask&&at-old.at<=2&&at>=old.at&&(f.bodyAdaptTargets||[]).includes(bodyAdaptId(t));r={loss:0,channels:{external:0,qi:0},saved:{},protections:{},adaptation:{eligible,source:bodyAdaptId(f),mask,counts:same?{...old.counts}:{external:0,qi:0}}};BODY_CAST.targets.set(t,r);}return r;}
function bodyAdaptCommit(t,receipt,at=round){const a=receipt.adaptation;if(!a?.eligible||!bodyEntries(t).some(x=>x.r.kind==='comboAdapt'))return;const s=bodyState(t);if(!receipt.channels.external&&!receipt.channels.qi){s.adaptation=null;return;}const counts={...a.counts};for(const k of ['external','qi'])if(receipt.channels[k]>0)counts[k]=Math.min(1000000,(counts[k]||0)+1);s.adaptation={source:a.source,mask:a.mask,at,counts};}
function growthBaseBodyModify(f,t,m,ext,qi,quiet=false,at=round){
 if(!bodyDirect(f,t,m))return {ext,qi};const rows=bodyEntries(t);if(!rows.length)return {ext,qi};const receipt=bodyReceipt(t,m,at),original={external:f.fxOn&&!m.o2Mapped?0:ext,qi:qi+(f.fxOn&&!m.o2Mapped?ext:0)},result={...original};
 for(const field of ['protection','windowGuard'])if(!receipt.protections[field]){const p=t.bodyV1?.[field];if(p&&p.until>=at&&original[p.channel]>0&&rows.some(x=>x.key===p.key)){receipt.protections[field]={...p};t.bodyV1[field]=null;}}
 for(const channel of ['external','qi']){const raw=original[channel];if(!(raw>0))continue;const amounts=[];
  for(const x of rows){const r=x.r;if(r.channel!==channel)continue;let wanted=0;
   if(r.kind==='conditionalGuard'){const max={hp:'hpMax',qi:'qiMax',nai:'naiMax'}[r.resource],v=t[r.resource]/Math.max(1,t[max]);if(v>=r.minRatio&&v<=r.maxRatio)wanted=raw*r.ratio;}
   if(r.kind==='comboAdapt'&&receipt.adaptation.eligible&&receipt.adaptation.counts[channel]>0)wanted=Math.min(raw*Math.min(r.capRatio,r.stepRatio*receipt.adaptation.counts[channel]),Math.max(0,t.hpMax*r.budgetRatio-(receipt.saved[x.key]||0)));
   if(r.kind==='aftershockGuard'&&receipt.protections.protection?.key===x.key)wanted=raw*r.ratio;
   if(r.kind==='pressureWindow'&&receipt.protections.windowGuard?.key===x.key)wanted=raw*receipt.protections.windowGuard.ratio;
   if(wanted>0)amounts.push({x,wanted});
  }
  const asked=amounts.reduce((n,x)=>n+x.wanted,0),saved=raw*(1-amounts.reduce((remaining,x)=>remaining*(1-Math.min(1,x.wanted/raw)),1));result[channel]=Math.max(0,raw-saved);
  if(saved>0){for(const a of amounts)if(a.x.r.kind==='comboAdapt')receipt.saved[a.x.key]=(receipt.saved[a.x.key]||0)+saved*a.wanted/asked;if(!quiet)log(t.name+'横练护身：'+(channel==='external'?'外功':'真气')+'本段减轻'+R1(saved),'sig');}
 }
 if(BODY_PACKET?.f===f&&BODY_PACKET.t===t)BODY_PACKET.channels=Object.keys(result).filter(k=>result[k]>0);
 if(f.fxOn&&!m.o2Mapped){const factor=original.qi>0?result.qi/original.qi:1;return {ext:ext*factor,qi:qi*factor};}return {ext:result.external,qi:result.qi};
}
function bodyCastEnd(t,receipt,at=round,quiet=false){if(over||!groupActive(t))return;bodyAdaptCommit(t,receipt,at);if(!(receipt.loss>0))return;for(const x of bodyEntries(t)){
 const r=x.r;if(r.kind==='aftershockGuard'&&receipt.loss>=t.hpMax*r.minimumLoss){const s=bodyState(t);if(s.fired[x.key]!=null&&at-s.fired[x.key]<x.term.cooldown)continue;s.fired[x.key]=at;s.protection={key:x.key,channel:r.channel,ratio:r.ratio,until:at+1};if(!quiet)log(t.name+'【'+x.term.name+'】受创稳身，护持下一次合格敌招','sig');}
 if(r.kind==='pressureReserve'&&receipt.loss>=t.hpMax*r.minimumLoss){const s=bodyState(t),record=s.reserve[x.key]?.round===at?s.reserve[x.key]:(s.reserve[x.key]={round:at,count:0});if(record.count>=r.perRound)continue;const pool=t.packageResources?.[x.art],def=x.a.packageResourceDefs.find(v=>v.id===x.term.resource);if(!pool||!def)continue;record.count++;const before=pool[def.id]||0;pool[def.id]=Math.min(def.maximum,before+1);if(pool[def.id]>before&&!quiet)log(t.name+'【'+x.term.name+'】承伤蓄劲：'+def.name+' '+pool[def.id]+'/'+def.maximum,'sig');}
 if(r.kind==='paidResilience'&&receipt.loss>=t.hpMax*r.minimumLoss){const s=bodyState(t),pool=t.packageResources?.[x.art],def=x.a.packageResourceDefs.find(v=>v.id===x.term.resource),cost=Math.max(1,Math.ceil(t.qiMax*r.spendRatio));if(!pool||!def||pool[def.id]>=def.maximum||t.qi<cost||s.fired[x.key]!=null&&at-s.fired[x.key]<x.term.cooldown)continue;s.fired[x.key]=at;if(quiet)t.qi-=cost;else{dariWrite(t,'qi',t.qi-cost);qiBurn(t,cost);}if(t.qi<=0&&t.exhaust<=0)t.exhaust=3;pool[def.id]=(pool[def.id]||0)+1;if(!quiet)log(t.name+'【'+x.term.name+'】实付护体'+cost+'，'+def.name+'+1','sig');}
}}
function bodyRunCast(f,m,run){if(!groupActors().some(u=>bodyEntries(u).length))return run();const previous=BODY_CAST;BODY_CAST={f,m,targets:new Map()};const current=BODY_CAST,old=new Set(f.blockL),payment=f.bodyV1?.payment;let complete=false;try{const out=run();complete=true;return out;}finally{BODY_CAST=previous;if(complete&&!over&&groupActive(f)&&payment&&!payment.used&&payment.key===(m.key||m.art+'/'+m.id)){payment.used=true;if(m.type==='self'&&m.effects?.some(fx=>fx.kind==='block'&&fx.target==='self'))bodyOpenGuard(f,old,payment);}if(complete&&!previous&&f.side){for(const[t,r]of current.targets)if(t.side!==f.side)bodyCastEnd(t,r);if(!over&&[...current.targets.values()].some(r=>r.adaptation?.eligible))f.bodyAdaptTargets=[...current.targets].filter(([t,r])=>t.side!==f.side&&r.adaptation?.eligible).map(([t])=>bodyAdaptId(t));}}}
function qimenBaseGroupExecute(f,t,m,full,provided){return bodyRunCast(f,m,()=>bodyBaseGroupExecute(f,t,m,full,provided));}
function qimenBaseExecuteMove(f,t,m,full){if(BODY_CAST?.f===f)return bodyBaseExecuteMove(f,t,m,full);return bodyRunCast(f,m,()=>bodyBaseExecuteMove(f,t,m,full));}
function qimenBaseStrike(f,t,m,h,q,tag,full){if(!bodyDirect(f,t,m))return bodyBaseStrike(f,t,m,h,q,tag,full);const r=bodyReceipt(t,m),previous=BODY_PACKET,packet={f,t,channels:[]};BODY_PACKET=packet;try{const out=bodyBaseStrike(f,t,m,h,q,tag,full);r.loss+=Math.max(0,out?.hpLost||0);if(out?.effectHit&&((out.hpLost||0)>0||(out.qiLost||0)>0||(out.dealt||0)>0))for(const channel of packet.channels)r.channels[channel]=1;return out;}finally{BODY_PACKET=previous;}}
function qimenBaseSoulHit(f,t,n,label,o){const m={...o?.sourceMove,secondaryDirect:o?.secondary||o?.jianFinalDamage};const out=bodyBaseSoulHit(f,t,n,label,o);if(bodySource(f,t,m)&&bodyEntries(t).length&&(out?.hpLost||0)>0)bodyReceipt(t).loss+=out.hpLost;return out;}
function bodyHealingMultiplier(t,m={},at=round){const qualified=!!m.bodyHealingTick||m.effect==='healRunwu'||!!m.bodyArtHealing;if(!qualified||CURIO_DEPTH)return 1;let bonus=0;for(const x of bodyEntries(t))if(x.r.kind==='healingReceived'){const r=x.r,active=r.gate===undefined||r.gate==='medicine'?(r.gate===undefined||(t.bodyMedicine??-1)>=DLH_BODY_RULES.medicineIndex(r.minimumMedicine)):t.statuses.some(s=>s.name==='润物'&&s.turns>0&&!s.cost&&!s.permanent&&!s.curioState&&!s.intentState&&!s.unremovable&&(s.expires==null||s.expires>=at));if(active)bonus+=r.ratio;}return 1+bonus;}
