function bodyForecastDamage(f,t,m,ext,qi,scale=1){if(!bodyEntries(t).length||m.soul||m.customChannel==='soul'||m.secondaryDirect)return {ext,qi};const target={...t,bodyV1:t.bodyV1?JSON.parse(JSON.stringify(t.bodyV1)):null},previous=BODY_CAST;BODY_CAST={f,m,targets:new Map()};try{const parts=m.segs?.length?m.segs:[{hpR:m.hpR||0,qqR:m.qqR||0}],sumH=parts.reduce((n,p)=>n+(p.hpR||0),0),sumQ=parts.reduce((n,p)=>n+(p.qqR||0),0);let totalH=0,totalQ=0;for(const p of parts){const h=sumH?ext*(p.hpR||0)/sumH:0,q=sumQ?qi*(p.qqR||0)/sumQ:0,v=bodyModify(f,target,m,h,q,true,f.lightForecastRound??round);totalH+=v.ext;totalQ+=v.qi;const raw=(v.ext+v.qi)*scale,absorb=target.exhaust<=0?Math.min(target.qi,raw*target.qiCut):0;target.qi-=absorb;const loss=Math.max(0,raw-absorb);target.hp-=loss;/* Forecast reads the same pre-cast adaptation snapshot for every segment; never commits segment counters. */}return {ext:totalH,qi:totalQ};}finally{BODY_CAST=previous;}}
