function bodyPayment(f,m,p){if(!bodyEntries(f).length||m.free||m.reaction||m.innerUpkeep||m.cycleInstant||m.charge||m.charged)return;if(p.nai+p.neili>0){const s=bodyState(f);s.serial=(s.serial||0)+1;s.payment={id:s.serial,key:m.key||m.art+'/'+m.id,used:false,...p};}}
function bodyOpenGuard(f,old,paid){if(over||!groupActive(f)||paid.nai+paid.neili<=0)return;const added=f.blockL.filter(l=>!old.has(l));if(!added.length)return;for(const l of added){l.bodyGuardOwner=f.groupId||f.side;l.bodyGuardRound=round;}const s=bodyState(f);for(const x of bodyEntries(f))if(x.r.kind==='pressureWindow'&&(!s.window||s.window.closed||s.window.round!==round)&&(s.fired[x.key]==null||round-s.fired[x.key]>=x.term.cooldown)){s.fired[x.key]=round;s.serial=(s.serial||0)+1;s.window={id:(f.groupId||f.side)+'::'+s.serial,key:x.key,round,count:0,closed:false};}}
