let QIMEN_CAST=null;
const QIMEN_INDEX=new WeakMap();
function qimenId(f){return f?.groupId||String(runId)+':'+f?.side;}
function qimenKey(m){return m.key||m.art+'/'+m.id;}
function qimenEntries(f){if(!f)return [];let rows=QIMEN_INDEX.get(f);if(!rows){rows=[];for(const[art,a]of Object.entries(f.arts||{}))for(const term of a.packageTerms||[])if(term.trigger==='qimen')rows.push({art,a,term,r:DLH_QIMEN_RULES.execution(term),key:art+'::'+term.id});QIMEN_INDEX.set(f,rows);}return rows.filter(x=>x.a.name===f.qimenEquipped&&x.a.tier>=TIERS.indexOf(x.term.tier));}
function qimenState(f){return f.qimenV1||(f.qimenV1={version:1,serial:0,actionSerial:0,closedSerial:0,fired:{},tokens:{},sequences:{},taxes:[],history:null,payment:null});}
function qimenMain(m){return m&&!m.free&&!m.reaction&&!m.cycleInstant&&!m.secondaryDirect&&!m.nineBurst&&!m.innateIndependent&&!m.innerUpkeep&&!CURIO_DEPTH;}
function qimenMarkOwner(f,m){return m.custom&&qimenEntries(f).some(x=>x.art===m.art)?qimenId(f):'';}
function qimenOwnedStatus(f,t,m,name,at=round){return t?.statuses?.find(s=>s.name===name&&s.src===(f.arts[m.art]?.name||m.source)&&s.qimenArt===m.art&&s.qimenOwner===qimenId(f)&&bodyOrdinary(s)&&s.turns>0&&(s.expires==null||s.expires>=at));}
function qimenRemove(t,s,n){if(!s||n<=0)return 0;const removed=Math.min(n,s.stacks||0);if(s.bleedLayers){s.bleedLayers.splice(0,removed);s.stacks=s.bleedLayers.length;s.turns=Math.max(0,...s.bleedLayers.map(x=>x.turns));}else s.stacks-=removed;if(s.stacks<=0)t.statuses=t.statuses.filter(x=>x!==s);return removed;}
