function offenseBasePayCost(f,m){const before=f.neili+f.nai,out=qimenBasePayCost(f,{...m,cost:qimenTax(f,m,'neili',m.cost||0)});if(out?.ok&&(out.receipt?.paid||before>f.neili+f.nai)&&qimenMain(m)&&groupActors().some(u=>qimenEntries(u).length)){const s=qimenState(f);s.payment={key:qimenKey(m),used:false,id:++s.serial,paid:true,neili:out.receipt?.net.neili??costOf(f,m),nai:out.receipt?.net.nai??moveNai(f,m),currencies:out.receipt?.net};s.taxes=s.taxes.filter(x=>x.until>=round&&x.move!==qimenKey(m));}return out;}
function qimenReason(f,m,t,at=f.lightForecastRound??round){if(!m)return '';if((f.qimenV1?.taxes||[]).some(x=>x.until>=at&&x.move===qimenKey(m)&&x.channel==='neili')&&f.neili<costOf(f,m))return '识破加费后内力不足';for(const x of qimenEntries(f)){const r=x.r;if(x.art!==m.art)continue;if((x.term.moves.includes(m.id)||r.setupMove===m.id||r.sequence?.includes(m.id))&&f.neili<costOf(f,m))return '奇门招式须足额支付内力';if(r.setupMove===m.id&&r.kind!=='windowDamage'){if(!qimenReady(f,x,at))return '奇门准备尚在调息';if(qimenToken(f,x,at))return '上次准备尚未兑现或过期';}if(r.kind==='repeatTax'&&x.term.moves.includes(m.id)){const h=t?.qimenV1?.history;if(!h||h.count<r.repeats||h.until<at)return '须目标公开连续使用同一具体招式'+r.repeats+'次';if(!qimenReady(f,x,at))return '识破尚在调息';}}return '';}
