function qimenRunCast(f,t,m,run,provided){const paid=f.qimenV1?.payment,eligible=qimenMain(m)&&paid&&!paid.used&&paid.key===qimenKey(m);if(!qimenMain(m)||!groupActors().some(u=>qimenEntries(u).length))return run();if(eligible)paid.used=true;const previous=QIMEN_CAST,targets=GROUP_ENABLED?(provided||groupTargets(f,m,undefined,false)):m.type==='self'?[f]:[t],c=eligible?qimenBegin(f,m,targets):{f,m,bonus:{},hits:new Set(),rows:[],at:round,paid:false};QIMEN_CAST=c;let complete=false;try{const out=run();complete=true;return out;}finally{QIMEN_CAST=previous;if(eligible&&complete&&!over&&groupActive(f))qimenFinish(c,targets);}}
