function offenseRouteIncoming(f,t,m,run,provided){const targets=GROUP_ENABLED?(provided||groupTargets(f,m,undefined,false)):[t];if(!targets.some(t=>t&&offenseEntries(t).some(x=>x.r.route))||m.type==='self'||m.reaction)return run();const parent=OFFENSE_CAST,c={f,m,targets:new Map(),routeIncoming:true};OFFENSE_CAST=c;let completed=false;try{const out=run();completed=true;return out;}finally{OFFENSE_CAST=parent;if(completed&&!over)for(const [victim,r]of c.targets)if(victim.side!==f.side&&groupActive(victim))for(const x of offenseEntries(victim))if(x.r.route)offenseRouteTransition(victim,x,[...(r.blocked?['blockSuccess']:[]),...(r.packets>0&&r.dodged===r.packets?['dodgeSuccess']:[])],'',round,false);}}
function offenseRunCast(f,t,m,run,provided){const paid=f.offenseV1?.payment;if(!offenseMain(m,f)||!paid||paid.used||paid.key!==offenseKey(m)||!offenseEntries(f).length)return offenseRouteIncoming(f,t,m,run,provided);paid.used=true;const parent=OFFENSE_CAST,targets=GROUP_ENABLED?(provided||groupTargets(f,m,undefined,false)):[t],c=offenseBegin(f,m,targets,paid);OFFENSE_CAST=c;let completed=false;try{const result=run();completed=true;return result;}finally{OFFENSE_CAST=parent;if(completed&&groupActive(f)){offenseHitRefund(c);if(!over)offenseFinish(c);}}}
