function growthBaseStrike(f,t,m,h,q,tag,full){const c=OFFENSE_CAST,eligible=c?.f===f&&f.side!==t.side&&(c.routeIncoming||offenseMain(m,f))&&offenseKey(c.m)===offenseKey(m);if(!eligible)return offenseBaseStrike(f,t,m,h,q,tag,full);const parent=OFFENSE_PACKET,packet={t,dodged:false};OFFENSE_PACKET=packet;let out;try{out=offenseBaseStrike(f,t,{...m,defPen:c.routeIncoming?m.defPen:offensePen(f,t,m)},h,q,tag,full);return out;}finally{OFFENSE_PACKET=parent;if(out){const r=offenseReceipt(c,t);r.packets++;if(packet.dodged)r.dodged++;r.hit||=!!out.effectHit;r.blocked||=!!out.blocked;r.loss+=Math.max(0,out.hpLost||0);}}}
function growthBaseSoulHit(f,t,n,label,o){return offenseBaseSoulHit(f,t,n,label,o);}
function offenseClearRhythm(f){if(f.offenseV1){f.offenseV1.chains={};const keep=new Set(offenseEntries(f).filter(x=>x.r.route).map(x=>x.key));for(const key of Object.keys(f.offenseV1.stages||{}))if(!keep.has(key))delete f.offenseV1.stages[key];}}
