 const highest=Math.max(...entries.map(a=>a.grade)),pool=entries.filter(a=>a.grade===highest),a=pool.length>1?pool[Math.floor(rnd()*pool.length)]:pool[0],turns=JIEMAI_CONFIG.rules.sealTurns;
 t.qsi=0;t.statuses=t.statuses.filter(s=>!(s.jiemaiSeal&&s.sealedArt===a.id));
 t.statuses.push({name:'封禁·'+a.name,jiemaiSeal:true,sealedArt:a.id,sealedName:a.name,stacks:1,turns,expires:round+turns-1,src:'截脉百式',owner:f.side,ownerId:f.groupId||undefined,buff:false,description:'《'+a.name+'》的招式暂时无法施展，包括应变与派生；常驻加成仍在。持续'+turns+'回合，可按普通负面状态净化。'});
