 const baseFields={外功伤害加成:'wDmg',真气伤害加成:'qDmg',神魂伤害加成:'sDmg',外功伤害减免:'wCut',真气伤害减免:'qCut',神魂伤害减免:'sCut',会心伤害:'critDmg',会意伤害:'insDmg'};
 for(const [k,field]of Object.entries(baseFields))f.base[field]+=(number(next.flat[k])-number(old.flat[k]))/100;
 for(const[k,field]of [['精准率','prec'],['会心率','crit'],['会意率','ins']])f[field]+=(number(next.flat[k])-number(old.flat[k]))/100;
 const ratioDelta=k=>{const total=number(s.totals[k])+number(extra[k]),before=number(s.normalContribution.ratio[k]),a=number(old.ratio[k]),b=number(next.ratio[k]),bare=number(s.baseCaps[k],number(s.baseAttrs[k]));return Math.round(bare*(1+Math.max(-.95,total-before+b)))-Math.round(bare*(1+Math.max(-.95,total-before+a)));};
