 api.advance=a=>{const why=api.reason(a);if(why)throw Error(why);if(a.name==='服药'&&a.item?.injury){iwSet(P,a.item.injury.modifiers);const cured=a.item.injury.method==='治愈';recordBattleConsequence(P,'伤势用药/'+round+'/'+a.item.injury.key,{类型:cured?'特效药治愈':'压伤用药',招式:a.item.name,长期后果:cured?a.item.injury.key+'已被对症特效药治愈，相关伤势限制解除；其他伤病和已支付代价保留':'暂时减轻'+a.item.injury.key+'的部分影响；本场结束药效消失，伤势与禁招条件仍在'});}return advance(a);};
