/* Public, timed mana discount. The same quote is used for payment and forecasts. */
function manaDiscountRate(f,at=f.lightForecastRound??round){
 return Math.min(.3,Math.max(0,...(f.statuses||[]).filter(s=>s.manaDiscount&&s.turns>0&&s.expires>=at).map(s=>number(s.manaDiscount.ratio))));
}
function manaDiscountPrice(f,m,cost){
 if(!(cost>0)||m?.generic||m?.innerUpkeep)return cost;
 return bwuPrice(f,m,Math.max(1,Math.ceil(cost*(1-manaDiscountRate(f))-1e-9)));
}
function manaDiscountApply(f,t,m,fx,at=round,quiet=false){
 const old=t.statuses.find(s=>s.manaDiscount),active=old&&old.turns>0&&old.expires>=at;
 const value={name:'省气',label:'省气',description:'所有招式内力消耗降低；同类取强刷新，正费用最低1点。',src:m.source||f.arts[m.art]?.name||m.name,owner:f.side,ownerId:utilityId(f),buff:true,stacks:1,
  turns:Math.max(active?old.expires-at+1:0,fx.turns),expires:Math.max(active?old.expires:0,at+fx.turns-1),manaDiscount:{ratio:Math.max(active?old.manaDiscount.ratio:0,fx.ratio)}};
 value.description='所有招式内力消耗降低'+Math.round(value.manaDiscount.ratio*100)+'%；同类取强刷新，正费用最低1点；不影响耐力、气血或专属资源。';
 if(old)Object.assign(old,value);else t.statuses.push(value);
 if(!quiet)log(f.name+'【'+m.name+'】→'+t.name+' · 省气 '+Math.round(value.manaDiscount.ratio*100)+'%，'+value.turns+'回合（同类取强、刷新）','sig');
 return value;
}

/* Ordinary dodge and observation are shared by the player, companions and NPCs. */
function perceptionProfile(f){const data=currentData||saved;if(f===P)return data?.主角;return GROUP_ENABLED?GROUP_PROFILES[f.groupId]?.profile:(data?.战斗状态||data?.主角?.战斗状态)?.敌方;}
function zwBasePerceptionInit(f){if(f.perceptionV1)return f.perceptionV1;const h=perceptionProfile(f),time=number((currentData||saved)?.世界?.游戏累计时辰);return f.perceptionV1={version:1,bodyDodge:DLH_TALENTS.dodge(h),rules:DLH_BATTLE_LEARNING.rules(h,registry),growth:copy(DLH_MASTERY.sources(h||{})),time,observed:{},pending:null};}
function perceptionDodge(f){const s=perceptionInit(f),intent=f.intentV1;let bonus=s.bodyDodge||0;if(intent)for(const t of intent.definition.terms)if(t.tier<=intent.tier&&t.passive?.key==='dodge'&&!t.passive.scaling)bonus+=t.passive.values[intent.tier];bonus+=intentModifiers(f,'dodge').reduce((n,x)=>n+x.v,0);return Math.max(-.15,Math.min(.15,bonus));}
function studyKnown(f,name){const h=perceptionProfile(f);return f===P?Object.hasOwn(h?.武学与意境面板?.掌握武学||{},name):(h?.武学表||[]).some(a=>a.名称===name);}
function studyInfo(f,a){if(a.talent||a.name.startsWith('天赋·'))return null;const native=meta.arts[a.name];if(native)return {类型:native.type,评级:native.lv,熟练度:'皮毛'};const h=perceptionProfile(f),raw=f===P?h?.武学与意境面板?.掌握武学?.[a.name]:(h?.武学表||[]).find(x=>x.名称===a.name);if(!raw)return null;const out=copy(raw),shared=DLH_SHARED_ARTS.find(currentData||saved,a.name,out,registry);if(shared)out.战斗定义=shared;try{if(registry.resolve(a.name,out).state!=='已生成')return null;}catch(_){return null;}const info={熟练度:'皮毛'};for(const k of ['类型','评级','特殊效果','面板加成','适器','战斗定义'])if(out[k]!==undefined)info[k]=copy(out[k]);return info;}
function studyWisdom(s,name,a){return s.growth.filter(x=>!x.适用真意&&(!x.适用武学||x.适用武学.includes(name))&&(!x.适用类型||x.适用类型.includes(a.类型))&&(!x.适用品级||x.适用品级.includes(a.评级))&&(x.开始时辰??0)<=s.time&&(x.结束时辰??Infinity)>s.time).reduce((n,x)=>n+Math.max(0,number(x.悟性加成)),0);}
function zwBaseStudyObserve(caster,m){if(!m||m.generic||m.free||m.reaction||m.cycleInstant||m.dariPair||m.innerUpkeep||m.tianmoBorrowed||m.tmExtremeBorrowed||m.innateIndependent||m.secondaryDirect||!m.art)return;const a=caster.arts[m.art];if(!a)return;const info=studyInfo(caster,a);if(!info)return;
 for(const observer of groupActors()){if(observer.side===caster.side||observer.hp<=0||observer.retired||studyKnown(observer,a.name))continue;const s=perceptionInit(observer);if(s.pending||!s.rules.length)continue;const rules=s.rules.filter(x=>DLH_BATTLE_LEARNING.grades.indexOf(info.评级)<=DLH_BATTLE_LEARNING.grades.indexOf(x.rule.最高品级)&&DLH_BATTLE_LEARNING.qualified(x.rule,x.source,studyWisdom(s,a.name,info))).sort((a,b)=>b.rule.概率-a.rule.概率||a.rule.观察次数-b.rule.观察次数||a.id.localeCompare(b.id));if(!rules.length)continue;
  const rule=rules[0],key=JSON.stringify([a.name,registry.source(a.name,info)]);if(!Object.hasOwn(s.observed,key)&&Object.keys(s.observed).length>=64)continue;const row=s.observed[key]||(s.observed[key]={name:a.name,count:0,rolled:false,source:caster.name,sourceId:caster.groupId||caster.side});if(row.rolled)continue;row.count++;if(row.count<rule.rule.观察次数)continue;row.rolled=true;row.rule=rule.id;row.chance=rule.rule.概率;row.success=rnd()<rule.rule.概率;
  if(row.success){s.pending={name:a.name,info:copy(info),source:caster.name,sourceId:row.sourceId,count:row.count,rule:rule.id,chance:row.chance};log(observer.name+'观招悟学 · 捕捉到'+a.name+'的关窍，存活至战后由皮毛起修','sig');}else log(observer.name+'观招悟学 · 观察'+a.name+' '+row.count+'次，本场未能悟得','sys');
 }
}
function studySettle(sd){if(!over)return;for(const f of groupActors()){const award=f.perceptionV1?.pending;if(!award||f.hp<=0)continue;const id=f.groupId||f.side,event=runId+'/study/'+id,archive=f===P?sd.主角:sd.世界?.NPC战斗档案?.[f.npcProfileKey||(GROUP_ENABLED?GROUP_PROFILES[f.groupId]?.id:npcProfileKey)||id]?.配置;if(!archive)continue;const book=archive.悟学记录||(archive.悟学记录={版本:1,已收讫:{},事件:[]});if(book.已收讫[event])continue;let added=false;
  if(f===P){const known=archive.武学与意境面板.掌握武学;if(!Object.hasOwn(known,award.name)){Object.defineProperty(known,award.name,{value:copy(award.info),enumerable:true,writable:true,configurable:true});added=true;}}
  else {archive.武学表||=[];if(!archive.武学表.some(a=>a.名称===award.name)){archive.武学表.push({名称:award.name,...copy(award.info)});added=true;}}
  book.已收讫[event]=true;book.事件.push({标识:event,战斗:runId,武学:award.name,来源:award.source,观察次数:award.count,概率:award.chance,词条:award.rule,结果:added?'已悟得':'已掌握，不重复发放'});if(book.事件.length>128)book.事件.splice(0,book.事件.length-128);
  if(added){recordBattleConsequence(f,'study/'+id,{类型:'战斗悟学',来源人物:award.source,永久获得武学:award.name,起始熟练度:'皮毛',观察次数:award.count,写入:'战后本地已经发放，正文只承接，不重复奖励'});log(f.name+'战斗悟学 · 已学会'+award.name+'（皮毛）','sig');}
 }}
