/* Native Nine Swords weakness. Context-scoped, never a panel/qi-damage nerf. */
const NINE_SHIELD_LABEL='九剑独修',NINE_SHIELD_FACTOR=.8;
let NINE_SHIELD_FRAME=null;
function nineShieldOwner(f){return f?.jxActor?groupActors().find(x=>x&&jxId(x)===f.jxOwner)||f:f;}
function nineShieldWeak(f){const owner=nineShieldOwner(f);return !!f?.arts?.jiju&&!owner?.arts?.jiuqu;}
function nineShieldContext(f,enabled,run){const previous=NINE_SHIELD_FRAME;NINE_SHIELD_FRAME={f,enabled};try{return run();}finally{NINE_SHIELD_FRAME=previous;}}
const nineShieldStrike=strike;
strike=function(f,t,m,...args){return nineShieldContext(f,m?.art==='jiju',()=>nineShieldStrike(f,t,m,...args));};
const nineShieldSoul=soulHit;
soulHit=function(f,t,raw,label,options){return nineShieldContext(f,options?.sourceMove?.art==='jiju'&&!options?.jianFinalDamage,()=>nineShieldSoul(f,t,raw,label,options));};
const nineShieldTick=nineTick;
nineTick=function(t,s){const f=groupDotSource(t,s);return nineShieldContext(f,!!s?.nineBleed,()=>nineShieldTick(t,s));};
const nineShieldBase=jianShield;
jianShield=function(f,t,raw){if(!NINE_SHIELD_FRAME?.enabled||NINE_SHIELD_FRAME.f!==f||!nineShieldWeak(f))return nineShieldBase(f,t,raw);
 // Treat each point of real qi as 1/.8 points for the existing absorption rule.
 // Preserve sword flowers / other shield-spend factors, reach exact zero on
 // exhaustion, and never mutate the live defender during this pure query.
 const out=nineShieldBase(f,{...t,qi:Math.max(0,t.qi)/NINE_SHIELD_FACTOR},raw);
 return {...out,spent:Math.min(Math.max(0,t.qi),Math.max(0,out.spent*NINE_SHIELD_FACTOR))};};
const nineShieldStatuses=statusDict;
statusDict=function(f){const out=nineShieldStatuses(f);delete out[NINE_SHIELD_LABEL];if(!over&&nineShieldWeak(f))out[NINE_SHIELD_LABEL]={层数:1,剩余回合:1,来源:'积矩九剑',显示名称:NINE_SHIELD_LABEL,说明:'本门攻击、派生、血爆及同源流血造成的护体真气条损耗降低20%；实际装配九曲惊神枪时解除。不是降低真气攻击倍率；此为装配条件弱点，普通净化不能解除。'};return out;};
function nineShieldFinalize(){for(const f of groupActors())if(f?.statuses)f.statuses=f.statuses.filter(s=>s.name!==NINE_SHIELD_LABEL);}
/* Installed before battle initialization. All committed counters live in fighter state. */
let SF_CAST=null;
const sfId=f=>f.groupId||f.side;
function sfState(f){return f.lifeArtsV1||(f.lifeArtsV1={version:1,opportunity:0,stamp:'',feedbackRound:-1,feedback:0,woodRound:-1,wood:0,extraRound:-1,stats:{treeHeal:0,feedback:0,poisonDamage:0,diverted:0,furnaceGuard:0}});}
function sfSetup(f){const s=sfState(f),role=iwRole(f);if(s.trait===undefined)s.trait=role?DLH_LIFE_ARTS.trait(role):'';return s;}
function sfTrait(f,k){return hasArt(f,'lingmu')&&profTier(f,'lingmu')>=3&&sfSetup(f).trait===k;}
function sfPoison(f,t){return t.statuses.find(s=>s.name==='草木枯毒'&&(s.sfOwner===sfId(f)||groupDotSource(t,s)===f));}
function sfPoisonRatio(f){return [.08,.08,.1,.1,.12][Math.max(0,profTier(f,'lingmu'))]||.08;}
function sfPoolBase(f,t,s){const owner=groupDotSource(t,s)||f;if(s.name==='草木枯毒')return (s.qSnap||effQiAtk(owner))*sfPoisonRatio(owner)*s.stacks;const ratio=s.ratio>0?s.ratio:.1;return (s.qSnap||effQiAtk(owner))*ratio*s.stacks;}
function sfFeedback(f,amount,label){if(!(amount>0)||!groupActive(f))return 0;const s=sfState(f);if(s.feedbackRound!==round){s.feedbackRound=round;s.feedback=0;}const base=f.hpMaxBase||f.bareHp||f.hpMax,cap=base*(sfTrait(f,'生息')?.05:.04),budget=Math.floor(Math.max(0,cap-s.feedback)),raw=Math.min(amount,budget);if(!(raw>0))return 0;const wound=iwState(f).modifiers.healing??1,withering=f.statuses.some(x=>x.cycleKind==='four2'&&x.subtype==='wither'&&x.turns>0)?.5:1;const tm=f.tmV1,tmFactor=tm?(tm.opportunity<(tm.backlashUntil||0)?TM_RULES.overloadHealingFactor:tm.opportunity<tm.woundUntil?TM_RULES.woundHealingFactor:1):1;const out=baseHealingGain(f,f,raw*Math.min(1,wound)*withering*Math.min(1,tmFactor),label,{scope:'special',special:true,sfFeedback:true,sfHealCap:budget},{name:f.name,crit:0,ins:0,critMultiplier:1,insMultiplier:1});const gained=out?.gained||0;s.feedback+=gained;s.stats.feedback+=gained;return gained;}
function sfHealTree(f,amount,label){if(!f.mulAlive||!(amount>0)||!groupActive(f))return 0;const real=Math.max(0,Math.min(amount,f.mulMax-f.mulHp));f.mulHp+=real;const s=sfState(f);s.stats.treeHeal+=real;const back=sfFeedback(f,real*.8*(sfTrait(f,'生息')?1.3:1),label+'·反哺');if(real||back)log(f.name+label+' · 木灵+'+R1(real)+'，反哺+'+R1(back),'sig');return real;}
function sfTreeTurn(f){if(f.mulAlive){const amount=Math.round(f.mulMax*(getSt(f,'木灵显圣')?.12:.08)),real=sfHealTree(f,amount,'木灵自疗'),unused=Math.max(0,amount-real);if(unused&&f.hp<f.hpMax)sfFeedback(f,Math.min(unused*.8,(f.hpMaxBase||f.hpMax)*.02),'满木滋养');}else if(f.mulTimer>0){f.mulTimer--;if(f.mulTimer<=0&&f.mulDeaths<3){const pct=f.mulDeaths===1?1:.5;f.mulHp=Math.round(f.mulMax*pct);f.mulAlive=true;log(f.name+'木灵重现 · 生机'+f.mulHp+'，重现不触发反哺','sig');}}}
function sfRespawnDelay(f){return sfTrait(f,'繁育')?5:8;}
function sfTreeShare(f,damage){if(!hasSig(f,'lingmu','移花接木')||!f.mulAlive||f.fxOn||!(damage>0)||damage>=f.hp)return damage;const ratio=f.transferAll===1?1:profTier(f,'lingmu')>=4?.3:.2,factor=sfTrait(f,'固本')?.8:1,desired=Math.floor(damage*ratio),share=Math.min(desired,Math.floor(f.mulHp/factor));if(!share)return damage;const cost=Math.min(f.mulHp,Math.ceil(share*factor));f.mulHp-=cost;sfState(f).stats.diverted+=share;log(f.name+'移花接木 · 分摊'+Math.round(ratio*100)+'%，实际代伤'+share+'，木灵消耗'+cost,'sig');if(f.mulHp<=0){f.mulHp=0;f.mulAlive=false;f.mulDeaths++;f.mulTimer=f.mulDeaths<3?sfRespawnDelay(f):0;log(f.name+(f.mulTimer?'木灵遁土 · '+f.mulTimer+'回合后重现':'木灵永枯'),'sig');}return damage-share;}
function sfPoisonWood(f,t,s,lost){if(!f||f.side===t.side||!hasArt(f,'lingmu')||s.name!=='草木枯毒'||groupDotSource(t,s)!==f||!(lost>0))return;const a=sfState(f);a.stats.poisonDamage+=lost;if(profTier(f,'lingmu')<3||!f.mulAlive)return;if(a.woodRound!==round){a.woodRound=round;a.wood=0;}const amount=Math.min(lost*.2,Math.max(0,f.mulMax*.05-a.wood));a.wood+=sfHealTree(f,amount,'毒发养木');}
function sfPoisonReceipt(f,t,s,lost,raw){sfPoisonWood(f,t,s,lost);if(!f||!sfTrait(f,'蚀毒')||!groupActive(t)||!groupActive(f)||s.name!=='草木枯毒'||s.stacks<5||groupDotSource(t,s)!==f||!(lost>0)||sfState(f).extraRound===round)return;sfState(f).extraRound=round;let ab=0;if(t.exhaust<=0&&t.qi>0){ab=Math.min(t.qi,raw*t.qiCut);t.qi-=ab;qiBurn(t,ab);}const before=t.hp;dariPeriodicDamage(t,Math.max(0,Math.round(raw-ab)),f);const actual=hpLost(t,before);curioPeriodicAfter(f,t,actual);sfPoisonWood(f,t,s,actual);log(f.name+'蚀毒树性 · 额外毒跳，实际失血'+actual,'dmg');if(t.qi<=0&&t.exhaust<=0){t.qi=0;t.exhaust=3;}checkEnd(t);}
function sfNaturalMana(f,amount){return amount*(f.mulAlive&&sfTrait(f,'蕴灵')?1.5:1);}
function sfFurnaceGuard(f,attacker,m){if(!attacker||attacker.side===f.side||!xlOwner(f)||m?.secondaryDirect||m?.innateIndependent||m?.nineBurst||m?.wyForcePacket||m?.yxReturn)return 1;const s=xlState(f),state=sfState(f),rate=state.protectionUntil>state.opportunity?.5:!s.炉竭&&s.柴薪>=50?.15:0;return 1-rate;}
function sfWarmPaid(f,w){if(w.fuel&&xlState(f).火候==='武火'){f.xl.lifeHot=true;f.xl.lifeHotUntil=sfState(f).opportunity+1;}}
function sfNormal(m){return !!m&&!m.generic&&m.type!=='self'&&!m.free&&!m.reaction&&!m.secondaryDirect&&!m.innateIndependent&&!m.nineBurst&&!m.jxAuto;}
function sfCastHot(f,m){return !!SF_CAST&&SF_CAST.actor===f&&SF_CAST.hot&&sfNormal(m)&&m.art===SF_CAST.move.art&&m.name===SF_CAST.move.name;}
const sfBeforeActor=innateBeforeActor;
innateBeforeActor=function(f){const s=sfSetup(f),stamp=round+'/'+cursor+'/'+sfId(f);if(s.stamp!==stamp){s.stamp=stamp;s.opportunity++;if(f.xl?.lifeHot&&f.xl.lifeHotUntil<s.opportunity)f.xl.lifeHot=false;}return sfBeforeActor(f);};
const sfGroupExecute=groupExecute;
groupExecute=function(f,t,m,...args){const previous=SF_CAST,hot=sfNormal(m)&&!!f.xl?.lifeHot&&f.xl.lifeHotUntil>=sfState(f).opportunity;SF_CAST={actor:f,move:m,hot,ember:false};if(hot)f.xl.lifeHot=false;try{return sfGroupExecute(f,t,m,...args);}finally{SF_CAST=previous;}};
const sfSoulHit=soulHit;
soulHit=function(f,t,raw,label,opts={}){const direct=!opts.secondary&&!opts.dot;const hot=direct&&opts.sourceMove&&sfCastHot(f,opts.sourceMove);return sfSoulHit(f,t,raw*(hot?1.25:1)*(direct?sfFurnaceGuard(t,f,opts.sourceMove):1),label,opts);};
function sfEmber(f,t){if(!SF_CAST||SF_CAST.actor!==f||SF_CAST.ember||!f.xl||!hasSig(f,'xianlu','烈火真金')||!t||t.side===f.side||!groupActive(t))return;SF_CAST.ember=true;xlEmber(f,4);}
const sfRecordStatus=bodyRecordStatus;
bodyRecordStatus=function(f,t,s,before){const out=sfRecordStatus(f,t,s,before);if(s.name==='灼伤'&&s.turns>0&&s.stacks>0)sfEmber(f,t);return out;};
function sfRevive(f){const s=xlState(f);if(!s||!hasSig(f,'xianlu','涅槃')||f.xl.nieUsed||s.炉竭||s.柴薪<50)return false;const fuel=DLH_XIANLU.drain(s,'涅槃',iwData()?.世界?.游戏累计时辰||0);f.xl.nieUsed=true;f.xl.cx=0;f.xl.temporary=0;f.xl.lifeHot=false;f.qi=f.qiMax;f.exhaust=0;dariWrite(f,'hp',Math.round(f.hpMax*.7));dariWrite(f,'neili',Math.max(f.neili,Math.round(f.neiliMax*.4)));sfState(f).protectionUntil=sfState(f).opportunity+1;recordBattleConsequence(f,'仙炉涅槃',{类型:'涅槃续命',招式:'不死仙炉·涅槃',长期后果:'烧尽实际柴薪'+fuel+'；气血回至70%、护体回满、内力至少40%；至本人下次正常行动前直接减伤50%。炉竭跨战，须重炼50真实柴薪并休息或疗伤温养6时辰。'});log(f.name+'涅槃 · 气血70%、护体回满、内力至少40%，复起护持50%至下次正常行动前','sig');return true;}
/* New-save rule: no old neipan cost status or mana-debt migration. Self-refining debt stays. */
const sfReason=reason;
reason=function(a){if(a.name==='仙炉保留底薪'){if(!xlOwner(P))return '未装配不死仙炉';if(!xlOwn())return '仅可在本人正常行动回合设置';return typeof a.reserve==='boolean'?'':'保留选项须为布尔值';}return sfReason(a);};
