function spRows(f){const out=[];for(const [art,a]of Object.entries(f?.arts||{}))for(const term of a.packageTerms||[])if(term.trigger==='special'&&!(term.special?.kind==='ward'&&/轻功/.test(a.artType||meta.arts[a.name]?.type||''))&&a.tier>=TIERS.indexOf(term.tier)&&!(f.lightSuppressed&&a.name===f.lightEquipped))out.push({art,a,term,r:term.special,key:art+'::'+term.id});const intent=f?.intentV1;if(intent)for(const t of intent.definition.terms)if(t.special&&t.tier<=intent.tier)out.push({art:'intent:'+intent.name,a:{name:intent.name},term:{...t,tier:'皮毛',trigger:'special',cooldown:t.cooldown},r:t.special,key:'intent:'+intent.name+'::'+t.id});return out;}
