const spDodge=drunkDodge;drunkDodge=function(f,t){if(SP_PACKET?.t===f&&SP_PACKET.f===t)SP_PACKET.dodged=true;return spDodge.apply(this,arguments);};
const spInnate=innateDodge;innateDodge=function(f){if(SP_PACKET?.t===f)SP_PACKET.dodged=true;return spInnate.apply(this,arguments);};
const spChance=dodgeChance;dodgeChance=function(f,t,o){const bonus=SP_PACKET?.t===f?spObservation(f,t,SP_PACKET.m,'dodge'):0,old=f.dodgeBonus;try{f.dodgeBonus=(old||0)+bonus;return spChance(f,t,o);}finally{f.dodgeBonus=old;}};
