function spAbsorb(f,n,channel,source){let remaining=n;if(channel&&source&&source.side!==f.side&&n>0){for(const x of spRows(f)){if(x.r.kind!=='ward'||!x.r.channels.includes(channel))continue;const s=f.specialAbilitiesV1?.terms[x.key];if(!s||s.until<round||!(s.pool>0))continue;const absorbed=Math.min(remaining,s.pool);s.pool-=absorbed;remaining-=absorbed;if(absorbed)log(f.name+'【'+x.term.name+'】气血护盾承受 '+R1(absorbed)+' · 余 '+R1(s.pool),'sig');if(remaining<=0)break;}}return n-remaining;}
const spShield=jianShield;jianShield=function(f,t,n){const channel=SP_PACKET?.t===t?SP_PACKET.channel:DARI_PERIODIC?'dot':'direct',absorbed=spAbsorb(t,n,channel,f),out=spShield(f,t,n-absorbed);return {...out,absorb:out.absorb+absorbed,spWardAbsorb:absorbed};};
