const SUK_CFG=DLH_SUKUNA.cfg,SUK_IDS=Object.fromEntries(Object.entries(SUK_CFG.arts).map(([k,a])=>[k,a.id]));
let SUK_CAST=null,SUK_FOLLOW_DEPTH=0;
function sukHas(f,key){return !!f?.arts?.[SUK_IDS[key]]&&!f.jxActor;}
function sukBody(f){return !!f?.arts?.['talent:天赋·两面四臂']&&!f.jxActor;}
function sukActor(f){return !!f&&(sukBody(f)||Object.values(SUK_IDS).some(id=>f.arts?.[id])||f.sukunaV1);}
function sukState(f){return f.sukunaV1||(f.sukunaV1={version:1,lastFollow:'',lastManaRound:0,marks:{},stats:{marks:0,marksSpent:0,manaRecovered:0,follows:0,domains:0,domainCasts:0}});}
function sukMark(f,t){const r=f?.sukunaV1?.marks?.[bwuId(t)];return r&&r.until>=round?r.layers:0;}
function sukGainMark(f,t){const s=sukState(f),key=bwuId(t),layers=Math.min(SUK_CFG.mark.cap,sukMark(f,t)+1);s.marks[key]={layers,until:round+SUK_CFG.mark.turns-1};s.stats.marks++;log(t.name+'获得斩痕 '+layers+'/'+SUK_CFG.mark.cap+'（来源：'+f.name+'）','sig');}
function sukDomain(f){return bwuDomains().find(x=>bwuId(x.f)===bwuId(f)&&x.d.kind==='sukuna'&&x.state==='生效');}
function sukSure(f,m){return !!sukDomain(f)&&['dismantle','cleave','domainSlash'].includes(m?.sukunaKind);}
function sukSolo(f){return !groupActors().some(t=>bwuId(t)!==bwuId(f)&&t.side===f.side&&groupActive(t));}
function sukFurnace(f){const field=sukDomain(f);return field?.d.furnaceUnlocked&&sukSolo(f)?field.d:null;}
function sukMove(f,m){if(!m)return m;if(!GROUP_ENABLED&&m.sukunaKind&&m.targetPolicy?.scope==='all')m={...m,targetPolicy:{...m.targetPolicy,scope:'single'}};const sure=sukSure(f,m);if(m.sukDomainSure&&!sure){m={...m};delete m.mustHit;delete m.sukDomainSure;}if(sure&&!m.mustHit)m={...m,mustHit:true,sukDomainSure:true};if(m.sukunaKind==='furnace'&&!m.sukFurnaceLocked){const d=sukFurnace(f),extra=Math.min(SUK_CFG.furnace.extraSegments,Math.max(0,d?.activeRounds||0)),count=1+extra,h=SUK_CFG.furnace.outerRatio,q=SUK_CFG.furnace.qiRatio;m={...m,hpR:h*count,qqR:q*count,segs:Array.from({length:count},()=>({hpR:h,qqR:q})),sukPen:Math.max(0,d?.marksConsumed||0)*SUK_CFG.furnace.penPerMark,sukFurnaceSegments:count};}return m;}
function sukCommon(f,t,m){return (m?.sukMarks||0)*SUK_CFG.cleave.damagePerMark+(m?.sukChanted?SUK_CFG.body.chantCommon:0);}
function sukReason(f,m){if(m?.sukunaKind==='domain'&&f.baiwuV1?.domain&&!f.baiwuV1.domain.ended)return '自身领域仍在持续';if(m?.sukunaKind==='furnace'&&!sukFurnace(f))return '灶须在无在场队友且成功展开的本次伏魔领域生效期间使用；对抗、被覆盖或结束时停用';return '';}
function sukOpenDomain(f,m){const s=bwuState(f);s.domain={id:runId+'/'+bwuId(f)+'/sukuna-domain/'+ ++s.serial,kind:'sukuna',realm:f.realm,until:round+SUK_CFG.domain.turns-1,lastTick:0,ended:false,chanted:!!m.sukChanted,activeRounds:0,marksConsumed:0,furnaceUnlocked:false};sukState(f).stats.domains++;const rows=bwuDomains(),highest=Math.max(...rows.map(x=>x.d.realm));for(const x of rows)if(x.d.realm<highest)bwuEndDomain(x.f,'被高大境界领域覆盖');s.domain.furnaceUnlocked=sukSolo(f)&&!!sukDomain(f);log(f.name+'展开伏魔御厨子 · 特殊地形，持续'+SUK_CFG.domain.turns+'回合'+(s.domain.furnaceUnlocked?'，解锁【灶】':'')+(bwuDomains().some(x=>x.state==='对抗')?'，同境领域对抗，效果无效':''),'sig');}
function sukDomainTick(f,d){d.activeRounds=(d.activeRounds||0)+1;const ratio=SUK_CFG.domain.segmentRatio,m={id:'domainSlash',art:SUK_IDS.domain,name:'伏魔御厨子·解',type:'hybrid',hpR:ratio*SUK_CFG.dismantle.segments,qqR:0,cost:0,nai:0,segs:Array.from({length:SUK_CFG.dismantle.segments},()=>({hpR:ratio,qqR:0})),sukunaKind:'domainSlash',sukChanted:!!d.chanted,mustHit:true,range:true,fx:[]};for(const t of groupActors())if(t.side!==f.side&&groupActive(t)){groupExecute(f,t,m,true,[t]);sukState(f).stats.domainCasts++;checkEnd(t);if(over)break;}}
function sukRecover(f,layers){if(!layers||!sukHas(f,'inner'))return;const s=sukState(f);if(s.lastManaRound===round)return;s.lastManaRound=round;const gain=Math.min(f.neiliMax-f.neili,f.neiliMax*SUK_CFG.inner.manaPerMark*layers);if(gain>0){dariWrite(f,'neili',f.neili+gain);s.stats.manaRecovered+=gain;log(f.name+'噬痕归流 · 消耗'+layers+'层斩痕，内力+'+DLH_DISPLAY.number(gain),'sig');}}
function sukFollow(f,t){if(!sukBody(f)||!groupActive(f)||!groupActive(t)||SUK_FOLLOW_DEPTH)return;const s=sukState(f),stamp=round+'/'+cursor+'/'+bwuId(f);if(s.lastFollow===stamp)return;s.lastFollow=stamp;s.stats.follows++;const m={id:'fourArms',art:'talent:天赋·两面四臂',name:'四臂·徒手追击',type:'hybrid',hpR:SUK_CFG.body.followRatio,qqR:0,cost:0,nai:0,fist:true,secondaryDirect:true,sukFollow:true,fx:[]};const parent=SUK_CAST;SUK_CAST=null;SUK_FOLLOW_DEPTH++;try{groupExecute(f,t,m,true,[t]);}finally{SUK_FOLLOW_DEPTH--;SUK_CAST=parent;}}
function sukChoice(f,t){if(f.name!=='宿傩'||!sukActor(f))return null;const moves=pool(f).filter(m=>!m.free&&!m.reaction&&!unavailable(f,m,t)&&f.neili>=costOf(f,m)&&f.nai>=moveNai(f,m));if(f.hp<f.hpMax*.55){const heal=moves.find(m=>m.baiwuKind==='heal');if(heal)return heal;}const domain=moves.find(m=>m.sukunaKind==='domain');if(domain&&(round>=4||f.hp<f.hpMax*.75||groupActors().filter(x=>x.side!==f.side&&groupActive(x)).length>1))return domain;const furnace=moves.find(m=>m.sukunaKind==='furnace'),field=sukFurnace(f);if(furnace&&((field.activeRounds>=2&&field.marksConsumed>0)||field.until-round<=1))return furnace;const cleave=moves.find(m=>m.sukunaKind==='cleave');if(cleave&&(sukMark(f,t)>=2||sukDomain(f)&&sukMark(f,t)>0))return cleave;return moves.find(m=>m.sukunaKind==='dismantle')||cleave||moves.find(m=>m.id==='pg')||null;}
function sukInstallCore(){const b={pool,unavailable,perform,groupExecute,strike,soulHit,executeMove,comboEndAction,statusDict,utilityShadow,enemyChoice,checkEnd,getSt,newRound,penV};
 pool=f=>b.pool(f).map(m=>sukMove(f,m));unavailable=(f,m,t)=>sukReason(f,m)||b.unavailable(f,m,t);
 perform=function(f,t,m){const why=sukReason(f,m);if(why){log(why,'sys');return;}const out=b.perform(f,t,sukMove(f,m));if(sukBody(f)&&f.charging?.mv){f.charging.mv.sukChanted=true;f.charging.mv.chargeProtection||='强韧';f.statuses=f.statuses.filter(x=>!x.sukCharge);f.statuses.push({name:'强韧',src:'两面四臂·双口',sukCharge:true,buff:true,stacks:1,turns:f.charging.left+1,expires:round+f.charging.left});}return out;};
 penV=function(f,channel,t,m){return b.penV(f,channel,t,m)+(m?.sukunaKind==='furnace'&&['w','q'].includes(channel)?m.sukPen||0:0);};
 getSt=function(f,name){const out=b.getSt(f,name);return name==='强韧'&&out?.sukCharge&&!f.charging?.mv?.sukChanted?f.statuses.find(s=>s.name===name&&!s.sukCharge):out;};
 newRound=function(...a){for(const f of groupActors())if(f.statuses.some(s=>s.sukCharge)&&!f.charging?.mv?.sukChanted)f.statuses=f.statuses.filter(s=>!s.sukCharge);return b.newRound(...a);};
 executeMove=function(f,t,m,full){if(m.sukunaKind==='domain'){if(!GROUP_CAST_INDEX)sukOpenDomain(f,m);return {dealt:0,hpLost:0,effectHit:true};}return b.executeMove(f,t,sukMove(f,m),full);};
 groupExecute=function(f,t,m,full,...a){if(!sukActor(f)&&!m.sukunaKind)return b.groupExecute(f,t,m,full,...a);const why=sukReason(f,m);if(why){log(why,'sys');return;}m=sukMove(f,m);if(m.sukunaKind==='furnace')m={...m,sukFurnaceLocked:true};if(m.sukunaKind==='cleave'){const n=sukMark(f,t);m={...m,sukMarks:n,defPen:(m.defPen||0)+n*SUK_CFG.cleave.defensePerMark};if(n){delete sukState(f).marks[bwuId(t)];sukState(f).stats.marksSpent+=n;const d=f.baiwuV1?.domain;if(d?.kind==='sukuna'&&!d.ended&&d.until>=round)d.marksConsumed=(d.marksConsumed||0)+n;sukRecover(f,n);}}const parent=SUK_CAST,frame={f,m,hit:new Set()};SUK_CAST=frame;try{return b.groupExecute(f,t,m,full,...a);}finally{SUK_CAST=parent;if(m.sukChanted)f.statuses=f.statuses.filter(x=>!x.sukCharge);if(!over&&['dismantle','domainSlash'].includes(m.sukunaKind))for(const target of frame.hit)sukGainMark(f,target);const target=[...frame.hit].find(groupActive);if(!over&&target&&!SUK_FOLLOW_DEPTH&&!m.sukFollow&&!m.secondaryDirect&&!m.innateIndependent&&!m.bwPeriodic&&!m.reaction&&m.sukunaKind!=='domainSlash'&&(m.sukunaKind==='dismantle'||m.sukunaKind==='cleave'||m.id==='pg'||m.art&&m.art!=='none')&&intentOwnTurn(f))sukFollow(f,target);}};
 strike=function(f,t,m,...a){const hp=t.hp,qi=t.qi,out=b.strike(f,t,sukMove(f,m),...a);if(SUK_CAST?.f===f&&SUK_CAST.m.id===m.id&&!m.sukFollow&&(t.hp<hp||t.qi<qi))SUK_CAST.hit.add(t);return out;};
 soulHit=function(f,t,n,label,opts={}){const hp=t.hp,qi=t.qi,out=b.soulHit(f,t,n,label,opts);if(SUK_CAST?.f===f&&!opts.dot&&!opts.bwPeriodic&&(t.hp<hp||t.qi<qi))SUK_CAST.hit.add(t);return out;};
 comboEndAction=function(f){const out=b.comboEndAction(f);if(!f.charging)f.statuses=f.statuses.filter(x=>!x.sukCharge);return out;};
 enemyChoice=(f=E,t=P)=>sukChoice(f,t)||b.enemyChoice(f,t);
 statusDict=function(f){const out=b.statusDict(f);if(f.statuses.some(s=>s.sukCharge)&&!f.charging?.mv?.sukChanted&&!f.statuses.some(s=>s.name==='强韧'&&!s.sukCharge))delete out.强韧;if(over)return out;let total=0,turns=0;for(const source of groupActors()){const mark=source.sukunaV1?.marks?.[bwuId(f)];if(mark?.until>=round){total+=mark.layers;turns=Math.max(turns,mark.until-round+1);}}if(total)out.斩痕={层数:total,剩余回合:turns,来源:'御厨子',说明:'按施术者分别记录，捌仅消耗自身施加的斩痕，每来源上限3层。'};return out;};
 utilityShadow=function(...a){const out=b.utilityShadow(...a);for(const f of [out.f,...out.targets,...(out.allies||[])])if(f.sukunaV1)f.sukunaV1=copy(f.sukunaV1);return out;};
 checkEnd=function(...a){const out=b.checkEnd(...a);if(over)for(const f of groupActors())if(f.sukunaV1){f.sukunaV1.marks={};f.statuses=f.statuses.filter(x=>!x.sukCharge);}return out;};
}
