function sukInstallPublic(api){api.sukunaView=()=>copy(groupActors().filter(sukActor).map(f=>({id:bwuId(f),name:f.name,...(f.sukunaV1||{version:1,marks:{}})})));}
/* A normal dodge result belongs to one committed cast and one target.
 * Existing layers, per-round limit, grade restrictions and soul rolls remain.
 * This is separate from Baiwu's proposed independent per-packet defense. */
let DG_CAST=null;
function dgKey(m){return (m?.art||'none')+'/'+(m?.id||m?.key||m?.name||'');}
function dgFrame(f,m){return DG_CAST?.f===f&&dgKey(DG_CAST.m)===dgKey(m)&&!m?.secondaryDirect&&!m?.secondary&&!m?.innateIndependent&&!m?.nineBurst&&!m?.jxAuto?DG_CAST:null;}
function dgRecall(f,t,m){return dgFrame(f,m)?.targets.get(t)||null;}
function dgRemember(f,t,m,kind,layer){const c=dgFrame(f,m);if(c)c.targets.set(t,{kind,layer});}
function dgReplay(t,row,tag){offenseNoteDodge(t);lightNoteDodge(t,row.layer);log('【'+tag+'】整招闪避延续 · 本段落空','hit');return {dealt:0};}
function dgRun(f,m,run){if(dgFrame(f,m))return run();const parent=DG_CAST;DG_CAST={f,m,targets:new Map()};try{return run();}finally{DG_CAST=parent;}}
function dgInstall(){const previousGroup=groupExecute,previousExec=execMove;
 groupExecute=function(f,t,m,...a){return dgRun(f,m,()=>previousGroup(f,t,m,...a));};
 execMove=function(f,t,m,...a){return dgRun(f,m,()=>previousExec(f,t,m,...a));};
}
