 statusDict=function(f){const result=base.statusDict(f);if(!over)for(const x of icActive(f))result['内功组合·'+x.term.id]={层数:1,剩余回合:f.innerV3.terms[x.key].until-round+1,来源:x.a.name,显示名称:x.term.name,说明:DLH_INNER_COMPOSITION.describe(x.term)};return result;};
 api.innerComposition=()=>copy(groupActors().filter(f=>icRows(f).length).map(f=>({id:utilityId(f),name:f.name,state:f.innerV3,terms:icRows(f).map(x=>({key:x.key,name:x.term.name,trigger:x.r.trigger,effect:x.r.effect,description:DLH_INNER_COMPOSITION.describe(x.term)}))})));
