function qyRows(f,kind){return qxRows(f).filter(x=>DLH_QIMEN_ADVANCED.owns(x.term.qimen)&&(!kind||x.r.kind===kind));}
function qyState(f){return f.qimenY||(f.qimenY={version:1,serial:0,weapon:null,applied:null,lastPayment:null,rewrites:[]});}
function qyGear(h){const g=DLH_EQUIPMENT.get(h?.装备栏,'主武器');if(!g||!g.通用加成?.length||!g.名称||['空手','无','未装备'].includes(g.名称)||!DLH_WEAPONS.validKind(DLH_WEAPONS.kind(g)))return null;try{const terms=DLH_GEAR_GROWTH.terms(h,g),fx=DLH_EQUIPMENT.compile({版本:g.词条版本||3,种类:g.种类,通用加成:terms},g,'主武器').面板加成;const values={...(fx.数值加成||{})},five=DLH_FIVE.bonus(fx.五维);for(const [k,v]of Object.entries(five))values[k]=(values[k]||0)+v;return {id:String(g.库存标识||g.标识||g.名称)+'/'+DLH_EQUIPMENT.panelSignature({kind:g.种类,terms:g.通用加成}),kind:DLH_WEAPONS.kind(g),values,weaponDamage:fx.兵器增伤?.[DLH_WEAPONS.kind(g)]||0};}catch(_){return null;}}
