function qyWeaponDelta(f,s){if(s?.benefit!=='affixes')return null;const values={};for(const[k,v]of Object.entries(f.qyWeapon.values))values[k]=v*s.ratio;return values;}
function qyDelta(f,values,sign){if(!values)return;const fields={最小外功攻击:'wMin',最大外功攻击:'wMax',最小真气攻击:'qiMin',最大真气攻击:'qiAtk',外功防御:'wDef',真气防御:'qDef'};for(const[k,field]of Object.entries(fields))f.base[field]+=sign*(values[k]||0);f.base.wMid+=sign*(values.最大外功攻击||0)*.75;for(const[k,field]of Object.entries({精准率:'prec',会心率:'crit',会意率:'ins'}))f[field]+=sign*(values[k]||0)/100;f.spd+=sign*(values.速度||0);const hp=sign*(values.最大气血||0);f.hpMax+=hp;f.hpMaxBase+=hp;f.base.hp+=hp;if(sign<0)f.hp=Math.min(f.hp,f.hpMax);}
function qyReconcile(f,at=round){const state=f.qimenY;if(!state)return;const live=qyWeaponLive(f,at),next=qyWeaponDelta(f,live);if(JSON.stringify(state.applied)===JSON.stringify(next))return;qyDelta(f,state.applied,-1);state.applied=next;qyDelta(f,next,1);if(!live)state.weapon=null;}
function qyWeaponStart(f,x,at,quiet=false){const r=x.r,s=qyState(f);if(qyWeaponLive(f,at)||!qimenReady(f,x,at)||f.weaponKind!==r.weapon||f.qyWeapon?.kind!==r.weapon)return;s.weapon={key:x.key,weaponId:f.qyWeapon.id,kind:r.weapon,benefit:r.benefit,ratio:r.ratio,until:at+r.turns-1};qimenState(f).fired[x.key]=at;qyReconcile(f,at);if(!quiet)log(f.name+'【'+x.term.name+'】强化手中'+r.weapon+' '+r.turns+'回合','sig');}
function qyWeaponAttack(f,m){if(!m||m.type==='self'||m.soul||m.customChannel==='soul'||m.secondaryDirect||m.free||m.reaction||m.innateIndependent||m.nineBurst||m.jxActor||f.jxActor)return false;if(m.art==='none'&&(m.id==='pg'||m.name==='普攻'))return true;const fit=m.zwMimic?zwRows(f).find(r=>r.id===m.zwRow)?.move.fit:f.arts[m.art]?.suitable;return Array.isArray(fit)&&fit.some(k=>k===f.weaponKind||DLH_WEAPONS.unarmed(k)&&DLH_WEAPONS.unarmed(f.weaponKind));}
function qyWeaponDamage(f,m){const s=qyWeaponLive(f,f.lightForecastRound??round);if(!s||!qyWeaponAttack(f,m))return 0;return s.benefit==='damage'?s.ratio:(f.qyWeapon.weaponDamage||0)*s.ratio;}
function qySwap(f,m){if(!m||!qimenMain(m)||m.generic||m.art==='none'||m.innerUpkeep)return null;return qyRows(f,'costSwap').find(x=>qxBound(x,m))||null;}
