      const starContribution=ordinaryMaximum-withoutStar,starDelta=starContribution-n(p.命星容量贡献?.[max]);p.命星容量贡献=p.命星容量贡献||{};p.命星容量贡献[max]=starContribution;
      const artContribution=ordinaryMaximum-Math.max(minimum,ordinaryMaximum-n(artResources[max])),priorArt=p.功法固定资源贡献?.[max]??(seen?artContribution:0),artDelta=artContribution-priorArt;p.功法固定资源贡献=p.功法固定资源贡献||{};p.功法固定资源贡献[max]=artContribution;
