    if(context==='daily'&&item.使用限制==='仅战斗')throw Error('此药仅可在战斗中使用');
    if(context==='battle'&&item.使用限制==='仅日常')throw Error('此药仅可在日常使用');
    if(!['hp','qi','neili'].includes(item.回复资源)||!(n(item.回复量)>0))throw Error('此物尚无可直接使用的回复词条');
