  for(const row of rows){row.share=row.weight/groups[row.group];row.minimum=budget(row.term,row.definition);row.floor=Object.fromEntries(owned.filter(k=>row.term.inner[k]!==undefined).map(k=>[k,row.term.inner[k]]));row.goal=goal(row,info.评级);}
