 function managed(t){return t?.trigger==='body'&&(!!fields[t.body?.kind]||t.body?.kind==='resistance'&&t.body.mode==='dot'||t.body?.kind==='defenseProc'&&Array.isArray(t.effects)&&t.effects.some(f=>['heal','restoreQi','restoreNeili','dodge','block'].includes(f.kind)));}
