   // another participant in the same encounter with the exact same source.
   for(const group of job.groups.values()){
    if(group.rows.every(row=>valid(row.info.战斗定义,row))){group.phase='ready';reused++;continue;}
    const row=group.row,sd=rt.snapshot().stat_data||{};assertCurrent(job,sd);
    const shared=DLH_SHARED_ARTS.find(sd,row.name,row.info,registry)||cached(sd,row)||group.rows.map(r=>r.info.战斗定义).find(s=>valid(s,row));
    if(shared){await install(job,group.rows,shared);group.phase='ready';reused++;continue;}
    if(rt.wumuArtCandidate){try{const saved=await rt.wumuArtCandidate(row.name,row.info);assertCurrent(job,rt.snapshot().stat_data||{});if(saved){await install(job,group.rows,saved);group.phase='ready';reused++;continue;}}catch(e){assertCurrent(job,rt.snapshot().stat_data||{});group.phase='failed';group.reason='武墓定义未能载入：'+redact(e,config);continue;}}
    if(!job.selected||!job.selected.has(row.fp)){group.phase='waiting';continue;}
    if(DLH_ART_IDENTITY.intrinsic(row.info)){group.phase='failed';group.reason='本命能力须登记在此人的天赋体质并完善能力定义';continue;}
    if(config.npcAuto===false||config.available===false){group.phase='failed';group.reason='连接尚不可用';continue;}
    const history=sd.世界?.NPC生成记录?.[key(row.fp)];if(!force&&history?.原文指纹===row.fp){group.phase='failed';group.reason='上次准备未完成：'+(history.原因||'未记录原因');}
   }
