function renderMedicalHall(){
 const box=$('#industry-content'),v=MEDICAL_VIEW;if(!box||!v.open)return;const scroll=$('#p15').scrollTop,people=DLH_PARTY_MEDICAL.participants(V),usable=people.filter(x=>!x.reason);
 if(!usable.some(x=>x.id===v.patient)){v.patient='主角';v.key='';}if(!usable.some(x=>x.id===v.healer))v.healer=v.patient;if(!usable.some(x=>x.id===v.owner))v.owner='主角';
 const patient=DLH_PARTY_MEDICAL.actor(V,v.patient),doctor=DLH_PARTY_MEDICAL.actor(V,v.healer),supplier=DLH_PARTY_MEDICAL.actor(V,v.owner),rows=DLH_INJURY.view(patient.h,WORLD.游戏累计时辰||0).rows;if(v.key&&!rows.some(r=>r.template===v.key))v.key='';
 const selected=rows.find(r=>r.template===v.key),selection={patient:v.patient,healer:v.healer,key:v.key,hours:v.hours},p=DLH_PARTY_MEDICAL.preview(V,selection),r=patient.h.战斗面板.资源||{},s=DLH_SELF_HEAL.coefficients(doctor.h),changed=v.scope!==RT.generationScope()||v.message!==RT.messageToken(),blocked=changed?'聊天或消息分支已变化，请返回产业后重新进入医馆。':p.blocked;
 const options=[{key:'',name:'调息养血',hint:'恢复患者气血'},...rows.map(w=>({key:w.template,name:w.name,hint:w.degree+(w.cultivation?' · 特殊伤势':w.treated?' · 调养中':' · 待处置')}))],percent=Math.max(0,Math.min(100,100*(r.气血||0)/Math.max(1,r.最大气血||1))),medicines=DLH_PARTY_MEDICAL.medicines(V,{patient:v.patient,owner:v.owner,key:v.key});
 const forecast=blocked?'<p>'+esc(blocked)+'</p>':'<dl><div><dt>耗时</dt><dd>'+p.hours+'时辰</dd></div><div><dt>预计恢复气血</dt><dd>+'+Math.round(p.hp)+'</dd></div>'+(p.key?'<div><dt>伤势康复</dt><dd>'+(p.healed?'本次可痊愈':'+'+DLH_DISPLAY.number(p.points)+'点')+'</dd></div>':'')+'</dl>'+(p.healer==='主角'&&s.medicine?'<p>预计医术经验 +'+DLH_DISPLAY.number(p.practice||0)+'</p>':'')+(p.treated?'<p>施治者医术足够，将先处置重伤，再推进调养。</p>':'');
 const personOptions=id=>people.map(x=>'<option value="'+esc(x.id)+'"'+(x.id===id?' selected':'')+(x.reason?' disabled':'')+'>'+esc(x.name+(x.reason?' · '+x.reason:''))+'</option>').join('');
 box.innerHTML='<section class="medical-hall" aria-label="医馆"><header class="medical-header"><button type="button" id="medical-back">‹ 返回产业</button><h2>医馆</h2><span>'+esc(WORLD.当前时间||'')+'</span></header><div class="medical-layout"><div class="medical-people"><label>患者<select id="medical-patient"'+(v.busy?' disabled':'')+'>'+personOptions(v.patient)+'</select></label><label>施治者<select id="medical-healer"'+(v.busy?' disabled':'')+'>'+personOptions(v.healer)+'</select></label><p>患者与施治者相同为自行疗伤；替他人疗伤须有医术。队友使用已登记的当前资源与伤势。</p></div><div class="medical-case"><header class="medical-patient"><div><h3>'+esc(patient.name)+'</h3><p>'+esc(DLH_DISPLAY.realm(patient.h.基础信息.武道境界))+'　施治：'+esc(doctor.name)+' · 医术 '+esc(s.medicineName)+'</p></div><span>'+rows.length+'处伤势</span></header><div class="medical-vital"><span>气血</span><strong>'+Math.round(r.气血||0)+' <small>/ '+Math.round(r.最大气血||0)+'</small></strong><div class="medical-health-track"><i style="width:'+percent+'%"></i></div></div><div class="medical-treatment"><section class="medical-targets" aria-label="疗伤目标"><h4>诊案</h4>'+options.map(o=>'<button type="button" data-healing-target="'+esc(o.key)+'" aria-pressed="'+(v.key===o.key)+'"'+(v.busy?' disabled':'')+'><span>'+esc(o.name)+'</span><small>'+esc(o.hint)+'</small></button>').join('')+'</section><section class="medical-prescription" aria-label="疗伤安排"><h4>'+esc(selected?.name||'调息养血')+'</h4><p>'+esc(selected?.description||'恢复患者当前不足的气血；伤势康复另按处置与调养计算。')+'</p><label for="self-heal-hours">疗伤时长</label><select id="self-heal-hours"'+(v.busy?' disabled':'')+'>'+DLH_SELF_HEAL.rules.hours.map(h=>'<option value="'+h+'"'+(h===v.hours?' selected':'')+'>'+h+'时辰</option>').join('')+'</select><div class="medical-forecast" role="status" aria-live="polite">'+forecast+'</div><button type="button" id="self-heal-confirm"'+(v.busy||blocked?' disabled':'')+'>'+(v.busy?'疗伤结算中…':v.patient===v.healer?'开始自行疗伤':'开始为患者疗伤')+'</button><p class="medical-cost">共同经过所选游戏时间，不自动用药或扣钱。未处置重伤须先对症治疗，特殊伤势沿用原修复条件。</p><p id="self-heal-status" role="status">'+esc(v.error||v.result)+'</p></section></div><section class="medical-medicines"><h4>药房 · 恢复与对症用药</h4><label>药品来源<select id="medical-owner"'+(v.busy?' disabled':'')+'>'+personOptions(v.owner)+'</select></label><p>从所选持有者的真实行囊取用一份，作用于当前患者；用药本身不额外推进时间。</p>'+(medicines.length?medicines.map((m,i)=>'<div><span><b>'+esc(m.name)+'</b><small>'+esc((m.item.品级||m.item.评级)+'　持有 '+(m.item.数量??1))+'</small></span><button type="button" data-medical-use="'+i+'"'+(v.busy||changed||m.quote.blocked?' disabled':'')+'>给'+esc(patient.name)+'使用一份</button>'+(m.quote.blocked?'<p>'+esc(m.quote.blocked)+'</p>':'')+'</div>').join(''):'<p>所选行囊暂无已登记效用的恢复、净化或伤势处置药食。可在炼丹入口制作，或先在行囊补全效用。</p>')+'<button type="button" id="medical-recipes">前往炼丹</button></section></div></div></section>';
 $('#p15').scrollTop=scroll;
 $('#medical-back').onclick=()=>{v.open=false;$('#p15').onkeydown=null;ESTATE_VIEW.tab='property';renderIndustry();$('#estate-tab-medical')?.focus({preventScroll:true});};$('#p15').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();$('#medical-back').click();}};
 for(const[field,id]of [['patient','medical-patient'],['healer','medical-healer'],['owner','medical-owner']])$('#'+id).onchange=e=>{if(v.busy)return;v[field]=e.target.value;if(field==='patient'){v.key='';v.healer=v.patient;}v.error='';v.result='';renderMedicalHall();$('#'+id).focus({preventScroll:true});};
 for(const b of box.querySelectorAll('[data-healing-target]'))b.onclick=()=>{if(v.busy)return;v.key=b.dataset.healingTarget;v.error='';v.result='';renderMedicalHall();};
 $('#self-heal-hours').onchange=e=>{v.hours=Number(e.target.value);v.error='';v.result='';renderMedicalHall();$('#self-heal-hours').focus({preventScroll:true});};$('#medical-recipes').onclick=()=>openCrafting('炼丹');
 const guard=()=>{if(v.scope!==RT.generationScope()||v.message!==RT.messageToken())throw Error('聊天或消息分支已变化，请重新进入医馆');};
 function finish(){v.busy=false;snap();if(MEDICAL_VIEW===v&&v.open){renderMedicalHall();$('#self-heal-status').tabIndex=-1;$('#self-heal-status').focus({preventScroll:true});}}
 $('#self-heal-confirm').onclick=async()=>{if(v.busy||blocked)return;v.busy=true;const request='medical/'+Date.now()+'/'+Math.random().toString(36).slice(2);renderMedicalHall();try{let result;await RT.mutate(all=>{guard();result=DLH_PARTY_MEDICAL.act(all.stat_data,selection,p.stamp,request);CHARACTER.recompute(all.stat_data.主角);});v.error='';v.result=result.duplicate?'此治疗请求已完成，未重复结算':'疗伤完成，经过'+result.hours+'时辰，患者气血恢复'+Math.round(result.hp)+(result.healed?'，此伤已痊愈':'')+'。'+(result.practice>0?' 医术经验 +'+DLH_DISPLAY.number(result.practice):'');}catch(e){v.error=e.message;}finally{finish();}};
 for(const b of box.querySelectorAll('[data-medical-use]'))b.onclick=async()=>{if(v.busy)return;const m=medicines[Number(b.dataset.medicalUse)],request='medicine/'+Date.now()+'/'+Math.random().toString(36).slice(2);v.busy=true;renderMedicalHall();try{await RT.mutate(all=>{guard();DLH_PARTY_MEDICAL.useMedicine(all.stat_data,m.selection,m.quote.stamp,request);CHARACTER.recompute(all.stat_data.主角);});v.error='';v.result='已从'+supplier.name+'的行囊取用一份'+m.name+'，用于'+patient.name+'。';}catch(e){v.error=e.message;}finally{finish();}};
}
