function entry(name,sub,key,selected){return '<button class="entry" data-key="'+esc(key)+'" aria-pressed="'+selected+'"><strong>'+esc(name)+'</strong><small>'+esc(sub)+'</small></button>';}
function bindList(callback){$('.list').querySelectorAll('.entry').forEach(button=>button.onclick=()=>{const key=button.dataset.key;const repeated=button.getAttribute('aria-pressed')==='true';callback(key);const next=$('.list [data-key="'+RT.host.CSS.escape(key)+'"]');next?.scrollIntoView({block:"nearest",inline:"nearest"});next?.focus({preventScroll:true});if(!repeated)selectedFeedback(next);});$('.list').onkeydown=e=>{if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const buttons=[...$('.list').querySelectorAll('button')],at=buttons.indexOf(e.target);if(at<0)return;e.preventDefault();const i=e.key==='Home'?0:e.key==='End'?buttons.length-1:(at+(['ArrowDown','ArrowRight'].includes(e.key)?1:-1)+buttons.length)%buttons.length;buttons[i].click();};}
