document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.section=state.page==='arts'?'功法':'感悟录';state.query='';render();});
document.addEventListener('keydown',e=>{const tabs=e.target.closest?.('[role="tablist"]');if(!tabs||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const buttons=[...tabs.querySelectorAll('[role="tab"]')],at=buttons.indexOf(e.target);if(at<0)return;e.preventDefault();const index=e.key==='Home'?0:e.key==='End'?buttons.length-1:(at+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length,name=buttons[index].textContent,selector=tabs.id?'#'+tabs.id:'.detail-tabs';buttons[index].click();[...document.querySelectorAll(selector+' [role="tab"]')].find(b=>b.textContent===name)?.focus();});
