function recoverNarrativeBattleStart(force){
  if(force)BATTLE_START_CHECKED='';
  if(!RT.isReady()||typeof RT.narrative!=='function')return;
  if(BATTLE_START_RECOVERING){if(force)BATTLE_START_RECHECK=true;return;}
  const scope=RT.generationScope(),message=RT.messageToken(),branch=RT.narrativeBranch?RT.narrativeBranch():'',key=scope+':'+message+':'+branch;
  const current=()=>scope===RT.generationScope()&&message===RT.messageToken()&&branch===(RT.narrativeBranch?RT.narrativeBranch():'');
  if(BATTLE_START_CHECKED===key)return;
  BATTLE_START_CHECKED=key;BATTLE_START_RECOVERING=key;
  (async function(){try{
    const n=await RT.narrative();if(!n||!current())return;
    const proposal=narrativeBattleStart(n.text);if(!proposal){if(n.previousBattle?.stage==='已结束'&&n.previousBattle.over===true&&DLH_BATTLE_BRANCH.explicitStart(n.text)&&currentBattle(V).阶段==='进行中'&&!currentBattle(V).引擎存档)battlePreparationFailed(Error('本条开战资料不完整，尚未建立新战斗；请补齐敌方名称、境界、模板档及战斗类型'));return;}if(!canRecoverNarrativeBattleStart(V,n,branch,proposal))return;
    // A new root replaces the ended battle as a whole; never carry its checkpoint.
    proposal.引擎存档='';proposal.事件流=[];proposal.结果='';
    let committed=false;
    await RT.mutate(function(all){
      if(!current())throw Error('聊天或消息分支已变化，未补写开战');
      const sd=all.stat_data;if(!canRecoverNarrativeBattleStart(sd,n,branch,proposal))return;
      sd.战斗状态=proposal;committed=true;
    });
    if(committed)toast('已补写本条消息的明确开战记录');
  }catch(e){if(scope===RT.generationScope()&&message===RT.messageToken()){battlePreparationFailed(e);toast('开战记录未能写入：'+e.message);}}
  finally{if(BATTLE_START_RECOVERING===key)BATTLE_START_RECOVERING=false;if(BATTLE_START_RECHECK){BATTLE_START_RECHECK=false;recoverNarrativeBattleStart(true);}if(RT.isReady())RT.timeout(ensureLocalBattle,0);}
  })();
}
function battleContext(){return {scope:RT.generationScope(),message:RT.messageToken(),trial:TRIAL_WAR_ACTIVE};}
function battleContextReason(context){return context&&(context.scope!==RT.generationScope()||context.message!==RT.messageToken()||context.trial!==TRIAL_WAR_ACTIVE)?'聊天或消息已变化，请重新选择':'';}
function captureBattleSelection(){return {checkpoint:warState().引擎存档,context:battleContext()};}
function battleSelectionReason(selection){return battleContextReason(selection.context)||(selection.checkpoint!==warState().引擎存档?'战况已变化，请重新选择':'');}
function currentBattle(sd){return sd.战斗状态||G(sd,['主角','战斗状态'],{});}
function battleInitSignature(){return RT.generationScope()+':'+RT.messageToken()+':'+(warState().引擎存档||JSON.stringify(warState()));}
var BATTLE_PREPARATION_NOTE=null;
function currentBattlePreparationNote(){return BATTLE_PREPARATION_NOTE?.signature===battleInitSignature()?BATTLE_PREPARATION_NOTE:null;}
function battlePreparationStep(message){BATTLE_PREPARATION_NOTE={signature:battleInitSignature(),message,error:''};}
function battlePreparationFailed(error){
 let message=String(error?.message||error||'布阵未完成');const key=artApiConfig()?.key;if(key)message=message.split(key).join('[密钥已隐藏]');
 BATTLE_ERROR=battleInitSignature();BATTLE_PREPARATION_NOTE={signature:BATTLE_ERROR,message:'',error:message.slice(0,500)};
}
async function readBattleOpening(){
 // Narrative provenance is optional; a failed reader must not block a valid handoff.
 let timer;try{return await Promise.race([Promise.resolve().then(()=>RT.narrative()).catch(()=>null),new Promise(resolve=>{timer=RT.timeout(()=>resolve(null),5000);})]);}finally{if(timer)RT.clearTimeout(timer);}
}

function ensureLocalBattle(){
  if(trialWarCurrent(V))return;
  if(!RT.isReady()||BATTLE_INIT)return;
  recoverNarrativeBattleStart();if(BATTLE_START_RECOVERING)return;
  if(!inBattle()){recoverNarrativeBattleStart();return;}
  var signature=battleInitSignature();if(BATTLE_ERROR===signature)return;
  if(warState().引擎存档){
    try{const old=JSON.parse(warState().引擎存档);if(old.manualEnd===true&&old.panelVersion===3&&old.dreamRevision===1&&(old.cycleRevision===1||![old.P,old.E,...(old.groupRoster||[])].some(f=>f.arts?.sixiang||f.arts?.dameng))&&(old.innateRevision===2||![old.P,old.E,...(old.groupRoster||[])].some(f=>f.arts?.jiuxiao||f.arts?.yunlong))&&old.P.weaponKind&&old.E.weaponKind&&Object.values(old.P.arts||{}).every(a=>a.suitable!==undefined)&&!createDlhBattleEngine(old,ARTS,V).needsAutoResume())return;}
    catch(e){battlePreparationFailed(e);toast(e.message);return;}
  }
  if(ART_GENERATOR.busy()||CAL_GENERATOR.busy()||GEAR_GENERATOR.busy()||ITEM_GENERATOR.busy()){
    battlePreparationStep(ART_GENERATOR.busy()?'等待当前武学生成结束':GEAR_GENERATOR.busy()?'等待本地装备生成结束':ITEM_GENERATOR.busy()?'等待当前物品处理结束':'等待当前日历任务结束');
    if(!NPC_WAIT_QUEUED){NPC_WAIT_QUEUED=true;RT.timeout(function(){NPC_WAIT_QUEUED=false;ensureLocalBattle();},100);}return;
  }
  var token=RT.generationScope()+':'+RT.messageToken()+':'+Date.now(),scope=RT.generationScope(),message=RT.messageToken();BATTLE_INIT=token;
  RT.timeout(async function(){
    try{
      battlePreparationStep('正在核对本场同行配置');
      if(!warState().引擎存档&&WORLD.同行)await RT.mutate(function(all){const sd=all.stat_data,bs=currentBattle(sd);if(bs.阶段==='进行中'&&!bs.引擎存档)DLH_COMPANIONS.prepareBattle(sd,ARTS);});
      battlePreparationStep('正在核对对手武学');
      if(!warState().引擎存档){var config=artApiConfig();config.npcSelectFirst=true;config.available=config.provider==='tavern'?RT.canGenerate():!!config.endpoint&&!!config.model&&RT.canProxyModels();await NPC_GENERATOR.prepare(config);}
      if(scope!==RT.generationScope()||message!==RT.messageToken())return;
      battlePreparationStep('正在读取开场记录');
      var openingNarrative=await readBattleOpening();if(scope!==RT.generationScope()||message!==RT.messageToken())return;
      battlePreparationStep('正在建立本地战斗');
      await RT.mutate(function(all){
      var sd=all.stat_data,bs=currentBattle(sd);if(bs.阶段!=='进行中')return;
      if(bs.引擎存档){var engine=createDlhBattleEngine(JSON.parse(bs.引擎存档),ARTS,sd);engine.enableManualEnd();engine.resumeIfNoReaction();engine.sync(sd);}
      else {NPC_GENERATOR.requireReady(sd);DLH_CULTIVATION.process(sd,true);CHARACTER.recompute(sd.主角);var engine=createDlhBattleEngine(sd,ARTS);engine.recordOpening(openingNarrative?.id||message,RT.narrativeBranch?RT.narrativeBranch():'');engine.enableManualEnd();engine.sync(sd);}
    });BATTLE_ERROR='';BATTLE_PREPARATION_NOTE=null;}
    catch(e){if(scope===RT.generationScope()&&message===RT.messageToken()){if(e.message==='战前准备已取消'&&!artApiConfig().npcAuto){BATTLE_ERROR='';BATTLE_PREPARATION_NOTE=null;}else battlePreparationFailed(e);if(e.code!=='NPC_PREPARATION_PENDING')toast(e.message);}}
    finally{if(BATTLE_INIT===token){BATTLE_INIT=false;renderWarViews();if(RT.isReady()&&inBattle()&&!warState().引擎存档&&BATTLE_ERROR!==battleInitSignature())RT.timeout(ensureLocalBattle,0);}}
  },0);
}
var BATTLE_RELEASE_DISPLAY=null;
async function localBattleAction(action,expectedCheckpoint,expectedContext,expectedAuto){
  if(trialWarCurrent(V))return trialWarAction(action,expectedCheckpoint||warState().引擎存档,expectedContext||battleContext(),expectedAuto);
  if(BATTLE_BUSY){toast('本地结算中');return;}
  BATTLE_BUSY=true;var expected=expectedCheckpoint||warState().引擎存档,releaseCues=[],stageHpCues=[],releaseContext=expectedContext||battleContext();
  try{
    await RT.mutate(function(all){
      if(expectedAuto&&BATTLE_AUTO!==expectedAuto)throw Error('自动战斗已暂停');
      var contextError=battleContextReason(expectedContext);if(contextError)throw Error(contextError);
      var sd=all.stat_data,bs=currentBattle(sd);
      if(bs.阶段!=='进行中'||!bs.引擎存档)throw Error('当前没有可继续的战斗');
      if(bs.引擎存档!==expected)throw Error('战况已变化，请重新选择');
      var engine=createDlhBattleEngine(JSON.parse(bs.引擎存档),ARTS,sd);
      engine.enableManualEnd();
      var why=engine.reason(action);if(why)throw Error(why);
      if(action.name==='切换武器'){
        engine.sync(sd);CHARACTER.swapWeapons(sd.主角);
        const g=sd.主角.装备栏.主武器;if(DLH_WEAPONS.kind(g)==='种类未登记')throw Error('请先补全该武器种类');
        CHARACTER.recompute(sd.主角);engine.rebase(sd.主角);
      }
      if(action.item){
        const name=action.item.name,itemLabel=DLH_ITEMS.label(DLH_INVENTORY.get(sd.主角,name),DLH_INVENTORY.locate(sd.主角,name).key);
        if(DLH_INVENTORY.get(sd.主角,name)?.效用){
          engine.sync(sd);const result=DLH_ITEMS.apply(sd.主角,name,'battle',action.item.replace,G(sd,['世界','游戏累计时辰'],0));CHARACTER.recompute(sd.主角);engine.rebase(sd.主角);action.item={name:itemLabel,contract:true,...result};
        }else{action.item=CHARACTER.medicine(sd.主角,name,'battle');CHARACTER.consume(sd.主角,name);}
      }
      var releaseBefore=engine.snapshot();engine.advance(action);var releaseAfter=engine.snapshot();try{stageHpCues=DLH_STAGE_EVENTS.between(releaseBefore,releaseAfter);}catch(_){}
      try{releaseCues=typeof DLH_ULTIMATE_EVENTS==='object'?DLH_ULTIMATE_EVENTS.between(releaseBefore,releaseAfter):[];if(releaseCues.length)BATTLE_RELEASE_DISPLAY=releaseContext;}catch(_){releaseCues=[];}
      engine.sync(sd);if(currentBattle(sd).阶段==='已结束')CHARACTER.recompute(sd.主角);
    });
    try{if(!battleContextReason(releaseContext)&&typeof DLH_ULTIMATE_UI==='object')await DLH_ULTIMATE_UI.playRelease(releaseCues,releaseContext);}catch(_){/* A cosmetic failure cannot undo or block the committed action. */}
    try{if(!battleContextReason(releaseContext))DLH_STAGE_UI.enqueue(stageHpCues,releaseContext);}catch(_){}
    return true;
  }catch(e){toast(e.message||'本地结算失败');return false;}
  finally{BATTLE_RELEASE_DISPLAY=null;BATTLE_BUSY=false;renderWarViews();}
}
function chooseWeapon(){
  snap();const selection=captureBattleSelection();return localBattleAction({name:'切换武器'},selection.checkpoint,selection.context);
}
function chooseMedicine(){
  if(trialWarCurrent(V)){toast("侠境暂未配置境内药品");return;}
  snap();var bs=warState(),selection=captureBattleSelection();if(bs.输入阶段==='应变'){toast('应变窗口无法服药，请先应变');return;}
  try{
    if(bs.阶段!=='进行中'||!bs.引擎存档){toast('当前没有可操作的战斗');return;}
    var why=createDlhBattleEngine(JSON.parse(bs.引擎存档),ARTS,V).reason({name:'服药',item:{}});if(why){toast(why);return;}
  }catch(e){toast(e.message);return;}
  var views=DLH_INVENTORY.view(HERO),items={...views.物品,...views.天材地宝},names=Object.keys(items).filter(function(n){try{if(items[n].效用)DLH_ITEMS.canUse(HERO,n,'battle');else CHARACTER.medicine(HERO,DLH_INVENTORY.locate(HERO,n).key,'battle');return true;}catch(e){return e.message.startsWith('生效位已满');}});
  if(!names.length){toast('物品栏没有登记回复词条的药物');return;}
  openPop('<h3>服药 · 本场最多三次</h3>'+names.map(function(n,i){return '<button class="med-choice" data-i="'+i+'">'+esc(DLH_ITEMS.label(items[n],n))+' ×'+items[n].数量+'</button>';}).join(''));
  qa('.med-choice').forEach(function(b){b.onclick=function(){$('#poplay').classList.remove('open');const name=names[Number(b.dataset.i)];if(items[name].效用)chooseConsumable(name,true,selection);else localBattleAction({name:'服药',item:{name:DLH_INVENTORY.locate(HERO,name).key}},selection.checkpoint,selection.context);};});
}
function chooseConsumable(name,battle,selection){
  snap();const i=DLH_INVENTORY.get(HERO,name);if(!i){toast('物品已用尽');return;}
  if(battle){selection=selection||captureBattleSelection();const why=battleSelectionReason(selection);if(why){toast(why);return;}}
  function use(replace){$('#poplay').classList.remove('open');if(battle)localBattleAction({name:'服药',item:{name,replace}},selection.checkpoint,selection.context);else mutateVars(function(all){const sd=all.stat_data,h=sd.主角;DLH_INVENTORY.use(sd,name,replace);CHARACTER.recompute(h);},function(){toast('消耗品效用已结算');});}
  try{DLH_ITEMS.canUse(HERO,name,battle?'battle':'daily');use();}catch(e){if(!e.message.startsWith('生效位已满')){toast(e.message);return;}const list=DLH_ITEMS.state(HERO)[i.类型];openPop('<h3>选择替换的'+esc(i.类型)+'增益</h3>'+list.map((x,index)=>'<button class="consumable-replace" data-i="'+index+'">'+esc(x.名称)+' · 剩余 '+x.剩余+' '+x.单位+'</button>').join(''));qa('.consumable-replace').forEach(b=>b.onclick=()=>use(list[Number(b.dataset.i)].标识||list[Number(b.dataset.i)].名称));}
}
function ensureBattleReviewStyle(){if(ROOT.querySelector('#battle-review-style'))return;const reviewStyle=document.createElement('style');reviewStyle.textContent='#battle-review article,.battle-mastery-row{padding:12px 0;border-bottom:1px solid rgba(185,175,140,.25)}#battle-review summary{cursor:pointer;padding:8px 0;overflow-wrap:anywhere}#battle-review select{max-width:100%}.battle-mastery-row>div:first-child{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.battle-mastery-row strong{color:#d7bc78}.battle-xp-track{position:relative;height:8px;background:rgba(255,255,255,.09);overflow:hidden;border-radius:3px}.battle-xp-track i,.battle-xp-track em{position:absolute;height:100%;background:#7b9695}.battle-xp-track em{background:#dfbc70}.battle-mastery-row p{margin:6px 0;font-variant-numeric:tabular-nums}#battle-dossiers-open,#battle-preparation-dossiers{margin:8px 0}';reviewStyle.id='battle-review-style';ROOT.append(reviewStyle); }
function battleReviewHTML(rows,selected){
 ensureBattleReviewStyle();
 const record=rows.find(r=>r.id===selected)||rows[0];return '<section id="battle-review"><h3>对手功法与装备</h3>'+(rows.length>1?'<label>交锋记录<select id="battle-review-select">'+rows.map(r=>'<option value="'+esc(r.id)+'" '+(r===record?'selected':'')+'>'+esc(r.title+' · '+r.people.map(p=>p.name).join('、'))+'</option>').join('')+'</select></label>':'')+(record?.people||[]).map(p=>'<article class="battle-dossier"><h4>'+esc(p.name)+'</h4><p>'+esc(p.realm)+'</p><h5>功法</h5>'+(p.arts.length?p.arts.map(a=>'<details><summary>'+esc(a.name)+' · '+esc([a.grade,a.type,a.tier,a.equipped?'装配中':'已掌握'].filter(Boolean).join(' · '))+'</summary><p>'+esc(a.description||'没有登记更多介绍')+'</p></details>').join(''):'<p>尚未登记功法资料。</p>')+'<h5>穿戴装备</h5>'+(p.equipment.length?p.equipment.map(g=>'<details><summary>'+esc(g.slot+' · '+g.name)+' · '+esc([g.grade,g.kind].filter(Boolean).join(' · '))+'</summary><p>'+esc(g.description)+'</p><p>'+g.traits.map(esc).join(' · ')+'</p>'+(g.signature?'<p>'+esc(g.signature)+'</p>':'')+'</details>').join(''):'<p>尚未登记装备资料。</p>')+'</article>').join('')+(!record?'<p>暂无可查看的对手记录。</p>':'')+'<p class="empty-note">查看交锋中实际登记的资料；准备前仅显示已知资料。获取功法与战利品仍由后续剧情确认。</p></section>';
}
function showBattleDossiers(selected){snap();const rows=DLH_BATTLE_REVIEW.dossiers(battleData());openPop(battleReviewHTML(rows,selected));const select=$('#battle-review-select');if(select)select.onchange=()=>showBattleDossiers(select.value);}
function battleMasteryProgressHTML(h,id,summary){
 ensureBattleReviewStyle();
 const rows=DLH_BATTLE_REVIEW.progress(h,id,summary);return '<div class="battle-mastery-progress"><h4>熟练度增长</h4>'+rows.map(x=>{
  if(!x.after)return '<p>'+esc(x.name)+' · 本场熟练值 +'+esc(x.gain)+'</p>'+(x.why?'<p class="empty-note">'+esc(x.why)+'</p>':'')+(x.xp!==undefined?'<p class="empty-note">当前 '+esc(x.tier)+' · 熟练值 '+esc(x.xp)+(x.next===null?' · 已圆满':' / '+esc(x.next)+'，距下一档 '+esc(Math.round(Math.max(0,x.next-x.xp)*10)/10))+'</p>':'')+'<p class="empty-note">历史记录未保存结算前后快照。</p>';
  const a=x.after,b=x.before,max=Math.max(1,a.next??a.xp,b.xp,a.xp),old=Math.max(0,Math.min(100,b.xp/max*100)),now=Math.max(old,Math.min(100,a.xp/max*100));return '<article class="battle-mastery-row"><div><b>'+esc(x.name)+'</b><strong>熟练值 +'+esc(x.totalGain)+'</strong></div><p>'+esc(b.tier===a.tier?a.tier:b.tier+' → '+a.tier)+' · '+esc(b.xp)+' → '+esc(a.xp)+(a.next===null?' · 已圆满':' / '+esc(a.next))+'</p><div class="battle-xp-track" role="progressbar" aria-label="'+esc(x.name+'本场增加'+x.totalGain+'熟练值')+'" aria-valuemin="0" aria-valuemax="'+esc(max)+'" aria-valuenow="'+esc(a.xp)+'"><i style="width:'+old+'%"></i><em style="left:'+old+'%;width:'+(now-old)+'%"></em></div>'+(x.why?'<p class="empty-note">'+esc(x.why)+'</p>':'')+'</article>';
 }).join('')+(!rows.length?'<p>本场未形成有效武学实践。</p>':'')+'</div>';
}

function battleGrowthResultHTML(h,id){
  if(typeof DLH_BATTLE_GROWTH==='undefined')return '';
  const row=DLH_BATTLE_GROWTH.summary(h,id);if(!row)return '<p class="empty-note">本场未保存可追溯的成长记录。</p>';
  return battleMasteryProgressHTML(h,id,row)+'<div class="battle-growth-results"><h4>本场所得</h4>'+row.insights.map(x=>'<p><b>'+esc(x.title)+'</b> · '+Object.entries(x.gain||{}).map(([n,v])=>esc(n)+' 额外熟练值 +'+esc(v)).join('，')+'</p><p class="empty-note">'+esc(x.facts)+'</p>').join('')+'<p>修为积累 +'+esc(row.cultivation)+(row.requestedCultivation>row.cultivation?' <small>（部分受当日额度、阶段上限或修行状态限制）</small>':'')+'</p></div>';
}
function showBattleReceipt(record){
  const checkpoint=DLH_BATTLE_REVIEW.checkpoint(V),closed=!!warState().结束记录,id=warState().结束记录?.战斗标识||checkpoint?.runId,growth=id?battleGrowthResultHTML(HERO,id):'';
  openPop((closed?'<h3>交锋已归档</h3><p>本场已结算并完成正文承接。战报与成长记录保留，可继续江湖行程。</p>':'<h3>战报已加入统一承接</h3><p>最终资源已保存。可继续其他操作，下次正常正文会承接本场战报；战斗前的旧待办保留在承接列表，可手动选择补叙。</p>')+growth+'<button id="battle-receipt-dossiers">查看对手功法与装备</button><pre class="battle-record">'+esc(record)+'</pre><button id="battle-return">返回江湖</button><button id="battle-deliver">将本次记录写入聊天输入框</button>');
  $('#battle-receipt-dossiers').onclick=()=>showBattleDossiers();
  $('#battle-return').onclick=function(){collapseBattleView();$('#poplay').classList.remove('open');showMenu();};
  $('#battle-deliver').hidden=closed;$('#battle-deliver').onclick=function(){try{RT.stageNarrative();this.textContent='统一记录已写入';toast('统一记录已写入，正常发送即可');}catch(e){toast(e.message);}};
}
function showBattleResult(force){
  if(trialWarCurrent(V)){showTrialWarResult(force);return;}
  var bs=warState();if(bs.结束记录){DLH_BATTLE_TERMINAL.validate(V,bs);if(force)showBattleReceipt(bs.战报);return;}
  var save;try{save=JSON.parse(bs.引擎存档);}catch(_){return;}
  if(!save.over||bs.阶段!=='已结束')return;if(!force&&RESULT_SHOWN===save.runId)return;if(bs.战报已发送||bs.尾声&&bs.战报){RESULT_SHOWN=save.runId;if(force)showBattleReceipt(bs.战报);return;}RESULT_SHOWN=save.runId;const resultContext=battleContext(),resultId=save.runId;
  var won=bs.结果==='胜',type=bs.类型;
  var tails=bs.结果==='敌逃'?['敌方逃逸']:bs.结果==='逃'?['主动脱身']:won&&type!=='切磋'?['击杀','重创放行','手下留情','擒获']:type==='切磋'?['点到为止']:['败退'];
  var events=(save.logs||[]).slice(-12).map(function(l){return '<div>'+esc(l.text)+'</div>';}).join('');
  var consequences=(save.groupRoster||[save.P,save.E]).filter(Boolean).flatMap(f=>f.battleConsequences||[]);
  if(consequences.length)events+='<div class="battle-consequences"><b>后续影响</b>'+consequences.map(e=>'<p>'+esc(e.人物)+' · '+esc(e.招式||e.类型||'特殊行动')+(e.消耗造化?' · 消耗造化 '+esc(e.消耗造化):'')+(e.真实自伤?' · 实付血价 '+esc(e.真实自伤):'')+(e.长期后果?'。'+esc(e.长期后果):'')+(e.永久获得武学?'。'+(e.类型==='战斗悟学'?'悟得':'摄得')+esc(e.永久获得武学)+'，从'+esc(e.起始熟练度)+'起修':'')+'</p>').join('')+'</div>';
  var vitality=[save.P,save.E].filter(Boolean).map(function(f){return '<p>'+esc(f.name)+' · 气血 '+Math.max(0,Math.round(f.hp))+'／'+Math.round(f.hpMax)+'</p>';}).join('');
  openPop('<h3>战局已定 · '+esc(bs.结果)+'</h3><p>双方资源已由本地引擎保存。选择尾声后，本场战报会交给下一次正文承接；旧待办不会一并展开。</p><div class="battle-vitality">'+vitality+'</div>'+battleGrowthResultHTML(HERO,save.runId)+'<div class="battle-summary">'+events+'</div><div class="battle-tails">'+tails.map(function(t){return '<button data-tail="'+t+'">'+t+'</button>';}).join('')+'</div>');
  qa('[data-tail]').forEach(function(b){b.onclick=async function(){
    if(BATTLE_BUSY)return;BATTLE_BUSY=true;
    b.disabled=true;b.textContent='正在保存战后记录…';
    await new Promise(resolve=>{let done=false;const finish=()=>{if(!done){done=true;resolve();}};RT.timeout(finish,80);RT.host.requestAnimationFrame(()=>RT.timeout(finish,0));});
    try{
      var record='';await RT.mutate(function(all){
        var contextError=battleContextReason(resultContext);if(contextError)throw Error(contextError);var sd=all.stat_data,latest=currentBattle(sd);if(latest.阶段!=='已结束'||JSON.parse(latest.引擎存档).runId!==resultId)throw Error('战局已经变化');
        record=DLH_BATTLE_REVIEW.record(JSON.parse(latest.引擎存档),b.dataset.tail,latest.战后环境);latest.尾声=b.dataset.tail;latest.战报=record;DLH_BATTLE_LIFECYCLE.capture(sd,latest);
      });
      if(!battleContextReason(resultContext)){collapseBattleView();showBattleReceipt(record);}
    }catch(e){b.disabled=false;b.textContent=b.dataset.tail;toast(e.message);}finally{BATTLE_BUSY=false;}
  };});
}

function installDlhRemoteUpdates(){
 const api=window.__DLH_REMOTE_UPDATER_V1__;if(!api||$('#dlh-release-settings'))return;
 const blocked=()=>{
  if(inBattle())return '交战中不能切换脚本版本';
  if(!RT.updateIdle())return '正在接收或保存变量，请稍后更新';
  if(ART_REQUESTS.size||[ART_GENERATOR,COMPANION_ART_GENERATOR,INTENT_GENERATOR,NPC_GENERATOR,GEAR_GENERATOR,ITEM_GENERATOR,TALENT_GENERATOR,CAL_GENERATOR].some(g=>g?.busy?.()))return '正在生成内容，请稍后更新';
  return '';
 };
 api.setBusyProvider(blocked);
 // A manifest check never downloads or activates scripts. Keep it infrequent and quiet.
 const cadence=6*60*60*1000,retryDelay=30*60*1000;let disposed=false,timer=null,lastAttempt=0;
 function schedule(delay){if(timer!==null)clearTimeout(timer);if(!disposed)timer=setTimeout(autoCheck,delay);}
 async function autoCheck(){
  timer=null;if(disposed)return;const s=api.view();if(!s.configured)return;
  if(document.hidden||s.working||blocked()){schedule(30000);return;}
  const remaining=lastAttempt+cadence-Date.now();if(lastAttempt&&remaining>0){schedule(remaining);return;}
  if(s.reloadNeeded){schedule(cadence);return;}
  lastAttempt=Date.now();let delay=cadence;
  try{await api.check();}catch(_){lastAttempt=0;delay=retryDelay;}finally{schedule(delay);}
 }
 const settings=$('#menu .mt[data-p="p12"]'),orb=$('#orb'),badge=document.createElement('span'),dot=document.createElement('span'),style=document.createElement('style');
 badge.className='dlh-release-badge';badge.hidden=true;badge.setAttribute('aria-hidden','true');
 dot.className='dlh-release-dot';dot.hidden=true;dot.setAttribute('aria-hidden','true');
 style.textContent='#dlhud-root #menu .mt[data-p="p12"]{position:relative;overflow:visible}#dlhud-root .dlh-release-badge{position:absolute;right:-10px;top:-7px;font:600 11px/1.3 "Microsoft YaHei",sans-serif;letter-spacing:0;color:#ffb0a6;background:#352320;border:1px solid #b96155;border-radius:3px;padding:1px 3px;white-space:nowrap;pointer-events:none}#dlhud-root .dlh-release-dot{position:absolute;right:3px;top:3px;width:8px;height:8px;border:1px solid #211a17;border-radius:50%;background:#e58071;pointer-events:none}#dlhud-root .dlh-release-badge[hidden],#dlhud-root .dlh-release-dot[hidden]{display:none!important}#dlhud-root #menu .mt.dlh-release-attention .menu-icon{background:#edb1a0!important}';
 ROOT.append(style);settings?.append(badge);orb?.append(dot);
 function notice(s){
  const label=s.reloadNeeded?'待启用':s.available?'新':s.candidate&&!s.compatible?'需换卡':'';
  const title=s.reloadNeeded?'脚本包已下载，重新加载后启用':s.available?'有新脚本版本 '+s.candidate+'，打开设置查看':label?'此发布版本需要更新配套角色卡':'';
  badge.textContent=label;badge.hidden=!label;badge.title=title;dot.hidden=!label;dot.title=title;
  settings?.classList.toggle('dlh-release-attention',!!label);settings?.setAttribute('aria-label',label?'设置 · '+title:'设置');
 }
 const box=document.createElement('section');box.id='dlh-release-settings';box.className='fate-panel';box.style.cssText='margin-top:24px;padding-top:20px;border-top:1px solid rgba(189,166,111,.3);overflow-wrap:anywhere';
 box.innerHTML='<h3>脚本更新</h3><p data-release-versions></p><p data-release-message role="status" aria-live="polite"></p><p data-release-notes></p><div data-release-actions style="display:flex;flex-wrap:wrap;gap:10px"></div><p style="opacity:.65;font-size:13px">世界书、开局或预设有变更时，仍需更新对应文件。更新不会在当前页面中途替换战斗引擎。</p>';
 const actions=box.querySelector('[data-release-actions]'),buttons={};for(const [key,label]of [['check','检查更新'],['download','下载更新'],['reload','重新加载启用'],['rollback','回退上一版']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.style.cssText='min-height:44px;padding:8px 16px;white-space:normal';b.onclick=async()=>{try{if(key==='check')lastAttempt=Date.now();await api[key]();}catch(e){box.querySelector('[data-release-message]').textContent=e.message;}finally{if(key==='check')schedule(cadence);}};buttons[key]=b;actions.append(b);}
 $('#p12').append(box);
 const stop=api.subscribe(s=>{notice(s);box.querySelector('[data-release-versions]').textContent='运行版本 '+s.running+' · 配套卡 '+s.card+(s.reloadNeeded?' · 待启用 '+s.installed:'');box.querySelector('[data-release-message]').textContent=s.note||(!s.configured?'尚未配置发布源，当前使用随卡版本':'启动后会自动检查更新；也可手动检查');box.querySelector('[data-release-notes]').textContent=s.notes;buttons.check.disabled=s.working||!s.configured;buttons.download.disabled=s.working||!s.available||!s.cacheOK;buttons.reload.disabled=s.working||!s.reloadNeeded;buttons.rollback.disabled=s.working||!s.canRollback||!s.cacheOK;});
 schedule(3000);
 RT.onDispose(()=>{disposed=true;if(timer!==null)clearTimeout(timer);stop();badge.remove();dot.remove();style.remove();settings?.classList.remove('dlh-release-attention');settings?.setAttribute('aria-label','设置');});
}

/* Provider settings stay on this device; credentials never enter card/MVU data. */
var ART_REQUESTS=new Map(),AUTO_ART_QUEUED=false;
var ART_MODEL_REQUEST=null;
function artApiConfig(){return {provider:$('#art-api-provider').value,endpoint:$('#art-api-url').value.trim(),model:$('#art-api-model').value.trim(),key:$('#art-api-key').value,auto:$('#art-api-auto').checked,npcAuto:$('#npc-api-auto').checked,thinking:$('#art-api-thinking').checked,maxTokens:Math.max(1,Math.min(1000000,Math.round(Number($('#art-api-tokens').value)||30000))),timeout:Math.max(120,Math.min(1800,Number($('#art-api-timeout').value)||120))*1000};}
function artCertificateError(error){return /SELF_SIGNED_CERT|self.signed certificate|UNABLE_TO_VERIFY|UNABLE_TO_GET_ISSUER|CERT_HAS_EXPIRED/i.test(typeof error==='string'?error:JSON.stringify(error&&error.message||error));}
function artCertificateMessage(){return '酒馆后端无法验证 API 证书链，请检查酒馆服务器的代理与证书信任配置。';}
async function artReadResponse(response){try{return await response.json();}catch(_){throw Error(response.ok?'酒馆后端返回的内容不是有效 JSON':'酒馆后端请求失败（HTTP '+response.status+'）');}}
function artBackendError(response,reply,key){
  var error=reply&&reply.error,hasError=!!error&&(typeof error!=='object'||Object.keys(error).length>0);
  if(response.ok&&!hasError)return '';
  function reason(value,depth){
    if(depth>4||value==null)return '';
    if(typeof value==='string'){
      var clean=value.trim();if(!clean)return '';
      if(/^[{\[]/.test(clean)){try{return reason(JSON.parse(clean),depth+1);}catch(_){}}
      return clean;
    }
    if(typeof value!=='object')return '';
    for(var field of ['message','error','detail','details','response','body','statusText']){var text=reason(value[field],depth+1);if(text)return text;}
    return '';
  }
  var detail=reason(error,0)||reason(reply,0),status='（酒馆HTTP '+response.status+'）';
  if(!detail)return (hasError?'生成服务报告失败，但未返回具体原因':'酒馆后端拒绝请求')+status+'；请查看酒馆运行终端。';
  if(key)detail=detail.split(key).join('[密钥已隐藏]');
  detail=detail.replace(/Bearer\s+[^\s"'<>]+/gi,'Bearer [密钥已隐藏]').replace(/\bsk-[A-Za-z0-9_-]{8,}/g,'[密钥已隐藏]').replace(/[\r\n\t]+/g,' ');
  return '生成服务返回错误'+status+'：'+detail.slice(0,260);
}
function artTransientFailure(response,reply,message){
  var details=typeof reply==='string'?reply:JSON.stringify(reply||{}),status=Number(reply&&reply.status||reply&&reply.error&&reply.error.status||response.status);
  if([400,401,403,404,422].includes(status)||/invalid.{0,20}(key|token|parameter|argument|model)|unauthori[sz]ed|forbidden|insufficient|balance|quota|context|maximum.{0,25}token|unsupported|not.found|certificate|SELF_SIGNED|SSL|TLS|余额|密钥|参数|上下文/i.test(details))return false;
  return [429,500,502,503,504].includes(status)||/rate[_ -]?limit|too many requests|overload|temporar|timeout|timed out|service unavailable|bad gateway|internal server error|频率|繁忙|暂时|超时/i.test(details)||response.status===200&&/未返回具体原因/.test(message);
}
function artRetryPause(signal){return new Promise(function(resolve,reject){
  var timer;function abort(){RT.clearTimeout(timer);signal.removeEventListener('abort',abort);var e=Error('请求已取消');e.name='AbortError';reject(e);}
  if(signal.aborted){abort();return;}signal.addEventListener('abort',abort,{once:true});
  timer=RT.timeout(function(){signal.removeEventListener('abort',abort);resolve();},1000);
});}
function artEndpoint(value){
  var url;try{url=new URL(value);}catch(_){throw Error('请填写完整的 API 地址');}
  if(!['http:','https:'].includes(url.protocol)||url.username||url.password||url.search||url.hash)throw Error('API地址须为HTTP或HTTPS，密钥请填在密钥栏');
  var base=url.href.replace(/\/$/,'').replace(/\/(?:chat\/completions|models)$/,'')+(url.pathname==='/'?'/v1':'');
  return {base:base};
}
function resetArtModels(){
  if(ART_MODEL_REQUEST){ART_MODEL_REQUEST.controller.abort();ART_MODEL_REQUEST=null;}
  if(!ROOT||!$('#art-api-model-list'))return;
  $('#art-api-model-list').replaceChildren();$('#art-api-model-list').hidden=true;
  $('#art-api-model-status').textContent='';$('#art-api-model-fetch').disabled=false;$('#art-api-model-fetch').textContent='获取可用模型';
}
async function fetchArtModels(){
  resetArtModels();var config=artApiConfig(),endpoint;
  try{endpoint=artEndpoint(config.endpoint);}catch(e){$('#art-api-model-status').textContent=e.message;return;}
  var job={controller:new AbortController(),scope:RT.generationScope(),endpoint:config.endpoint,key:config.key,timedOut:false};ART_MODEL_REQUEST=job;
  var timer=RT.timeout(function(){job.timedOut=true;job.controller.abort();},20000);
  $('#art-api-model-fetch').disabled=true;$('#art-api-model-fetch').textContent='正在获取…';$('#art-api-model-status').textContent='正在读取模型列表';
  function current(){var c=artApiConfig();return ART_MODEL_REQUEST===job&&job.scope===RT.generationScope()&&c.provider==='independent'&&c.endpoint===job.endpoint&&c.key===job.key;}
  try{
    if(!RT.canProxyModels())throw Error('酒馆后端转发不可用，请在酒馆中使用并检查酒馆版本');
    var response=await RT.proxyModels(endpoint.base,config.key,job.controller.signal),data=await artReadResponse(response);
    if(artCertificateError(data))throw Error(artCertificateMessage());
    var backendError=artBackendError(response,data,config.key);if(backendError)throw Error(backendError);
    var rows=Array.isArray(data)?data:data&&(data.data||data.models);if(!Array.isArray(rows))throw Error('接口未返回兼容的模型列表；可手动填写模型');
    var ids=[...new Set(rows.map(function(x){return typeof x==='string'?x:x&&x.id;}).filter(function(x){return typeof x==='string'&&x.trim()&&x.length<=512;}))].sort(function(a,b){return a.localeCompare(b);});
    if(!ids.length)throw Error('此接口没有返回可用模型；可手动填写模型');
    if(!current())return;
    var list=$('#art-api-model-list'),placeholder=document.createElement('option');placeholder.value='';placeholder.textContent='请选择模型（'+ids.length+' 个）';list.appendChild(placeholder);
    ids.forEach(function(id){var option=document.createElement('option');option.value=id;option.textContent=id;list.appendChild(option);});
    list.value=ids.includes($('#art-api-model').value)?$('#art-api-model').value:'';list.hidden=false;
    $('#art-api-model-status').textContent='已获取 '+ids.length+' 个模型，选择后保存设置';
  }catch(e){if(current())$('#art-api-model-status').textContent=job.timedOut?'获取超时，可重试或手动填写模型':e.name==='AbortError'?'获取已取消':e instanceof TypeError?'无法连接酒馆后端，请检查酒馆服务；可手动填写模型':'获取失败：'+(String(e.message).split(config.key||'\u0000').join('[密钥已隐藏]').slice(0,200));}
  finally{RT.clearTimeout(timer);if(ART_MODEL_REQUEST===job){ART_MODEL_REQUEST=null;$('#art-api-model-fetch').disabled=false;$('#art-api-model-fetch').textContent='获取可用模型';}}
}
var AI_TRANSPORT={
  request:async function(config,messages,id){
    var call={generation_id:id,should_stream:false,should_silence:true,max_chat_history:0,ordered_prompts:messages};
    if(config.provider==='tavern'&&!RT.canReuseConnection()){try{return await RT.generateRaw(call);}catch(e){if(artCertificateError(e))throw Error(artCertificateMessage());throw e;}}
    if(config.provider==='independent'&&!config.model)throw Error('请填写独立API的模型名称');
    var endpoint=config.provider==='independent'?artEndpoint(config.endpoint):null;
    var controller=new AbortController();ART_REQUESTS.set(id,controller);
    try{
      if(!RT.canProxyModels())throw Error('酒馆后端转发不可用，请在酒馆中使用并检查酒馆版本');
      var backendRetried=false;
      for(var attempt=0;attempt<2;attempt++){
      var options={...config,maxTokens:(config.maxTokens||30000)*(attempt?2:1)};
      var proxy,reply;
      for(;;){
        proxy=await (endpoint?RT.proxyArt(endpoint.base,config.key,config.model,messages,controller.signal,options):RT.proxyCurrentArt(messages,controller.signal,options));reply=await artReadResponse(proxy);
        if(artCertificateError(reply))throw Error(artCertificateMessage());
        var backendError=artBackendError(proxy,reply,config.key);
        if(backendError&&!backendRetried&&!controller.signal.aborted&&artTransientFailure(proxy,reply,backendError)){backendRetried=true;await artRetryPause(controller.signal);continue;}
        if(backendError)throw Error(backendError);break;
      }
      var text=G(reply,['choices',0,'message','content'],null),reasoning=G(reply,['choices',0,'message','reasoning_content'],''),limited=G(reply,['choices',0,'finish_reason'],'')==='length';
      if(limited||typeof text!=='string'||!text.trim()){
        if((reasoning||limited)&&attempt===0&&!controller.signal.aborted)continue;
        throw Error(reasoning||limited?'模型的输出预算已耗尽，未返回完整正文；已扩大预算重试一次，请提高令牌上限或关闭思考。':'酒馆转发未返回有效文本结果');
      }
      return text;
      }
    }catch(e){if(e.name==='AbortError')throw Error('请求已取消');if(e instanceof TypeError)throw Error('无法连接酒馆后端，请检查酒馆服务');throw e;}
    finally{ART_REQUESTS.delete(id);}
  },
  cancel:function(id){var controller=ART_REQUESTS.get(id);if(controller)controller.abort();try{RT.stopGeneration(id);}catch(_){}}
};
var ART_GENERATOR=createDlhArtGenerator(RT,ART_REGISTRY,AI_TRANSPORT,function(){renderArtGenerationStatus();scheduleArtGeneration();},{set:RT.timeout,clear:function(id){clearTimeout(id);}});
var INTENT_GENERATOR=createDlhIntentGenerator(RT,AI_TRANSPORT,function(){renderIntentGenerationStatus();if(ROOT){snap();renderCompanions();refreshCompanionIntentDetail();}},ARTS);
RT.onDispose(()=>INTENT_GENERATOR.reset());
RT.onDispose(function(){ART_GENERATOR.cancelAll();resetArtModels();});
function loadArtSettings(){
  try{var s=JSON.parse(localStorage.getItem('dlhud_art_api')||'{}');$('#art-api-provider').value=s.provider||'tavern';$('#art-api-url').value=s.endpoint||'';$('#art-api-model').value=s.model||'';$('#art-api-key').value=s.key||'';if('transport' in s){delete s.transport;localStorage.setItem('dlhud_art_api',JSON.stringify(s));}}catch(_){}
  try{var s=JSON.parse(localStorage.getItem('dlhud_art_api')||'{}');$('#npc-api-auto').checked=s.npcAuto!==false;$('#art-api-thinking').checked=s.thinking===true;$('#art-api-tokens').value=s.maxTokens||30000;$('#art-api-timeout').value=Math.max(120,(s.timeout||120000)/1000);}catch(_){}$('#art-api-auto').checked=false;updateArtSettings();
}
function updateArtSettings(){
  var independent=$('#art-api-provider').value==='independent';$('#art-api-fields').hidden=!independent;
  $('#art-api-retry-save').hidden=!RT.state.savePending;
  $('#art-api-availability').textContent=independent?(RT.canProxyModels()?'由酒馆后端统一查询模型并生成':'酒馆后端转发不可用，请在酒馆中使用'):(RT.canReuseConnection()?'复用酒馆当前连接，由酒馆后端生成':RT.canGenerate()?'通过酒馆助手复用当前连接；令牌与思考按助手设置':'等待酒馆当前连接或助手生成接口');
  $('#art-api-thinking-note').textContent=$('#art-api-thinking').checked?'允许思考：本次请求令牌上限自动翻倍；思考内容不作为生成正文。':'默认关闭思考；部分兼容接口是否执行关闭取决于服务支持。';
  const cache=RT.storageInfo?.();if(cache?.volatile)$('#art-api-availability').textContent+='。界面缓存空间受限，部分历史保护仅在本次页面有效；请先导出聊天备份，再检查酒馆存储。';
  renderArtGenerationStatus();
}
function saveArtSettings(){
  var s=artApiConfig();if(s.provider==='independent'){try{artEndpoint(s.endpoint);}catch(e){toast(e.message);return;}}
  try{const previous=JSON.parse(localStorage.getItem('dlhud_art_api')||'{}');localStorage.setItem('dlhud_art_api',JSON.stringify({provider:s.provider,endpoint:s.endpoint,model:s.model,key:s.key,npcAuto:s.npcAuto,thinking:s.thinking,maxTokens:s.maxTokens,timeout:s.timeout}));if(['provider','endpoint','model','key'].some(k=>previous[k]!==s[k])&&RT.isReady())RT.mutate(all=>{if(all.stat_data.世界)delete all.stat_data.世界.NPC生成记录;}).catch(()=>{});toast('生成设置已保存到当前浏览器，刷新后仍保留');}catch(_){toast('此浏览器不允许本机存储，设置未保存');}
  updateArtSettings();scheduleArtGeneration();
}
function clearArtKey(){
  $('#art-api-key').value='';resetArtModels();
  try{var s=JSON.parse(localStorage.getItem('dlhud_art_api')||'{}');delete s.key;localStorage.setItem('dlhud_art_api',JSON.stringify(s));toast('已清除当前页面及本机保存的密钥');}catch(_){toast('当前页面密钥已清空，未能修改本机存储');}
}
function artDefinition(name){return ART_REGISTRY.resolve(name,known()[name]||{}).metadata;}
function renderArtGenerationStatus(){
  if(ROOT)$('#pop-box .scenic-generation')?.syncGeneration?.();
  if(!ROOT||!$('#art-ai-status'))return;
  var completed=Object.keys(known()).filter(function(n){return ART_REGISTRY.resolve(n,known()[n]).state==='已生成';}).length;
  $('#art-api-progress').textContent=ART_GENERATOR.busy()?'正在生成：'+ART_GENERATOR.current():'当前已有 '+completed+' 门新武学保存了战斗定义';
  var name=$('#ad-name').textContent,info=known()[name];if(!info)return;
  var resolved=ART_REGISTRY.resolve(name,info),job=ART_GENERATOR.status(name),button=$('#art-ai-generate'),cancel=$('#art-ai-cancel');
  $('#art-ai-status').textContent=resolved.native?'内置战斗定义':(job?job.status+(job.error?' · '+job.error:''):resolved.state);
  // Old saves can contain historical unsupported notes; these are not playable effects.
  $('#art-ai-warning').textContent='';
  const diagnostic=$('#art-ai-diagnostics'),history=job?.validationErrors||[];
  diagnostic.hidden=!history.length;$('#art-ai-errors').replaceChildren();
  for(const [index,error] of history.entries()){const row=document.createElement('p');row.textContent='第'+(index+1)+'次：'+error;$('#art-ai-errors').appendChild(row);}
  const report='武学：'+name+'\n类型：'+(info.类型||'')+'；品级：'+(info.评级||'')+'\n'+history.map((error,i)=>'第'+(i+1)+'次：'+error).join('\n');
  $('#art-ai-copy').onclick=async function(){try{if(RT.host.navigator.clipboard?.writeText){await RT.host.navigator.clipboard.writeText(report);toast('检查记录已复制');return;}}catch(_){}const field=$('#art-ai-copy-text');field.hidden=false;field.value=report;field.focus();field.select();const copied=document.execCommand('copy');field.hidden=!!copied;toast(copied?'检查记录已复制':'请选中检查记录手动复制');};
  button.textContent=job&&job.status.startsWith('待保存')?'保存生成结果':resolved.state==='已生成'?'重新完善武学效果':'完善武学效果';
  button.disabled=resolved.native||inBattle()||ART_GENERATOR.busy()||!!OPENING_GENERATOR?.busy()||!!COMPLETION_BATCH?.busy()||!!COMPANION_ART_GENERATOR?.busy();cancel.hidden=!(job&&job.status==='正在生成')||!!OPENING_GENERATOR?.busy()||!!COMPLETION_BATCH?.busy();
  button.onclick=async function(){try{if(job&&job.status.startsWith('待保存'))await ART_GENERATOR.save(name);else await ART_GENERATOR.generate(name,artApiConfig());toast('「'+name+'」战斗定义已处理');}catch(e){toast(e.message);}};
  cancel.onclick=function(){ART_GENERATOR.cancel(name);toast('已取消，迟到结果不会写入');};
}
function scheduleArtGeneration(){
  if(!ROOT||AUTO_ART_QUEUED||CAL_PENDING||CAL_GENERATOR.busy()||INTENT_GENERATOR.busy()||OPENING_GENERATOR?.busy()||COMPANION_ART_GENERATOR?.busy()||COMPLETION_BATCH?.busy())return;
  const opening=OPENING_GENERATOR?.state();if(opening?.failures.length&&opening.scope===RT.generationScope()&&opening.token===RT.messageToken?.())return;
  var config=artApiConfig();if(config.provider==='independent'&&(!config.endpoint||!config.model))return;
  if(config.provider==='tavern'&&!RT.canGenerate())return;
  var name=ART_GENERATOR.next(config);if(!name)return;
  AUTO_ART_QUEUED=true;
  RT.timeout(function(){AUTO_ART_QUEUED=false;if(OPENING_GENERATOR?.busy()||COMPANION_ART_GENERATOR?.busy()||COMPLETION_BATCH?.busy()||inBattle())return;ART_GENERATOR.generate(name,artApiConfig()).catch(function(e){toast(e.message);scheduleArtGeneration();});},0);
}

