 qa('[data-craft-mode]').forEach(b=>b.onclick=()=>openCrafting(b.dataset.craftMode));qa('[data-recipe]').forEach(b=>b.onclick=()=>{v.recipe=b.dataset.recipe;v.name=null;v.description=null;v.recycle=false;v.materials={};v.request=null;renderCraftingPopup();});if($('#craft-recycle'))$('#craft-recycle').onclick=()=>{v.recycle=true;v.waste=null;v.recycleCount=null;renderCraftingPopup();};
