 if($('#craft-design'))$('#craft-design').onclick=()=>{v.design=true;renderCraftingPopup();};
 if($('#craft-name'))$('#craft-name').oninput=e=>{v.name=e.target.value;$('#pop-box .craft-object-title h3').textContent=v.name;};if($('#craft-description'))$('#craft-description').oninput=e=>{v.description=e.target.value;};
 if($('#craft-facility'))$('#craft-facility').onchange=e=>{v.facility=e.target.value;renderCraftingPopup();};qa('[data-material]').forEach(b=>b.onchange=e=>{v.materials[b.dataset.material]=e.target.value;renderCraftingPopup();});if($('#craft-recycle-spec'))$('#craft-recycle-spec').onchange=e=>{v.spec=e.target.value;v.waste=null;v.recycleCount=null;renderCraftingPopup();};qa('[data-waste]').forEach(b=>b.onchange=()=>{v.waste=[...qa('[data-waste]:checked')].map(x=>x.dataset.waste);v.recycleCount=null;renderCraftingPopup();});if($('#craft-fuel'))$('#craft-fuel').onchange=e=>{v.fuel=e.target.value;renderCraftingPopup();};
 if($('#craft-recycle-count'))$('#craft-recycle-count').oninput=e=>{v.recycleCount=Number(e.target.value);renderCraftingPopup();};if($('#craft-advance-hours'))$('#craft-advance-hours').oninput=e=>{v.advanceHours=Number(e.target.value);};
 if($('#craft-start'))$('#craft-start').onclick=()=>{if(!plan||v.busy)return;let current;try{current=craftPreview();}catch(e){toast(e.message);return;}const sel=v.recycle?{recipeId:'R01',facilityId:v.facility,spec:v.spec,wasteKeys:cpCraft(v.waste),fuelKey:v.fuel,count:v.recycleCount,fingerprint:current.fingerprint}:{recipeId:v.recipe,facilityId:v.facility,materials:cpCraft(v.materials),name:v.name,description:v.description,fingerprint:current.fingerprint};v.request=v.request||('craft-request-'+Date.now()+'-'+Math.random().toString(36).slice(2));const request=v.request;craftRun(sd=>v.segmented?DLH_CRAFTING.start(sd,sel,request):DLH_CRAFTING.make(sd,sel,request));};
 if($('#craft-advance'))$('#craft-advance').onclick=()=>{const left=j.状态==='操作'?j.计划.work-j.操作进度:Math.max(0,j.等待至-(WORLD.游戏累计时辰||0)),hours=left>0?(v.advanceHours??left):0,expected=WORLD.游戏累计时辰||0;if(left>0&&(!Number.isFinite(hours)||hours<=0||hours>left)){toast('推进时辰须为正数且不超过当前工序剩余时辰');return;}craftRun(sd=>hours>0?DLH_CRAFTING.advance(sd,j.标识,hours,expected):DLH_CRAFTING.complete(sd,j.标识));};
