function bindCompanionTabs(box){
 const sections=[['arts','武学','.companion-arts'],['equipment','装备','.companion-equipment'],['bag','行囊','.companion-bag']];
 const nav=document.createElement('div');nav.className='companion-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','同行者详情');
 nav.innerHTML=sections.map(([key,label])=>'<button type="button" role="tab" data-comp-tab="'+key+'" id="companion-tab-'+key+'" aria-controls="companion-panel-'+key+'">'+label+'</button>').join('');
 box.querySelector('.companion-arts').before(nav);
 const select=key=>{COMPANION_TAB=key;for(const [k,,selector] of sections){const panel=box.querySelector(selector),button=nav.querySelector('[data-comp-tab="'+k+'"]');panel.id='companion-panel-'+k;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','companion-tab-'+k);panel.hidden=k!==key;button.setAttribute('aria-selected',String(k===key));button.tabIndex=k===key?0:-1;}};
 for(const b of nav.querySelectorAll('button'))b.onclick=()=>select(b.dataset.compTab);
 nav.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=sections.findIndex(x=>x[0]===COMPANION_TAB),n=e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowRight'?1:2))%3;select(sections[n][0]);nav.querySelector('[data-comp-tab="'+COMPANION_TAB+'"]').focus();};select(COMPANION_TAB);
}

function completionWorkersBusy(){return TALENT_GENERATOR?.busy()||OPENING_GENERATOR?.busy()||ART_GENERATOR.busy()||GEAR_GENERATOR.busy()||ITEM_GENERATOR.busy()||CAL_GENERATOR.busy()||NPC_GENERATOR.busy()||COMPANION_ART_GENERATOR?.busy();}
var COMPLETION_BATCH=createDlhCompletionBatch(RT,{
  art:{generate:(task,config)=>ART_GENERATOR.generate(task.name,config),cancel:()=>ART_GENERATOR.cancelAll(),busy:()=>ART_GENERATOR.busy()},
  gear:{generate:(task,config)=>GEAR_GENERATOR.generate(task.selection,config),cancel:()=>GEAR_GENERATOR.cancel(),busy:()=>GEAR_GENERATOR.busy()},
  item:{generate:(task,config)=>ITEM_GENERATOR.generate(task.name,config),cancel:()=>ITEM_GENERATOR.cancel(),busy:()=>ITEM_GENERATOR.busy()},
},(sd,kind)=>dlhCompletionTasks(sd,kind,ART_REGISTRY,CHARACTER),function(){if(ROOT){renderCompletionBatch();renderArtGenerationStatus();const page=$('.page.on');if(page?.id==='p5')renderEq();if(page?.id==='p6')renderGoods();if(!COMPLETION_BATCH.busy()){scheduleArtGeneration();scheduleCalendarSync();}}},()=>OPENING_GENERATOR?.busy()||CAL_GENERATOR.busy()||NPC_GENERATOR.busy()||COMPANION_ART_GENERATOR?.busy());
RT.onDispose(()=>COMPLETION_BATCH.reset());
function renderCompletionBatch(){
  if(!ROOT||!COMPLETION_BATCH)return;
  const sd=RT.snapshot().stat_data||{};
  for(const [kind,id] of [['opening','opening'],['equipment','eq'],['consumables','goods']]){
    const button=$('#'+id+'-batch'),cancel=$('#'+id+'-batch-cancel'),status=$('#'+id+'-batch-status'),errors=$('#'+id+'-batch-errors');if(!button)continue;if(kind==='equipment'){button.closest('.completion-tools').hidden=true;continue;}
    const state=kind==='opening'?OPENING_GENERATOR.state():COMPLETION_BATCH.state(),busy=kind==='opening'?OPENING_GENERATOR.busy():COMPLETION_BATCH.busy();
    const count=dlhCompletionTasks(sd,kind,ART_REGISTRY,CHARACTER).length,relevant=state&&state.kind===kind;
    button.disabled=!RT.isReady()||RT.state.savePending||inBattle()||COMPLETION_BATCH.busy()||completionWorkersBusy()||(!count&&kind!=='opening');
    button.textContent=({opening:'同步武学定义',equipment:'补全全部装备',consumables:'补全全部食物／丹药'})[kind]+(count?' · '+count+'项':'');
    cancel.hidden=!(busy&&relevant);cancel.onclick=()=>{$('#art-api-auto').checked=false;kind==='opening'?OPENING_GENERATOR.cancel():COMPLETION_BATCH.cancel();};
    status.textContent=relevant?state.status+' · '+state.done+'/'+state.total+' · 已保存'+state.saved+(state.skipped?' · 跳过'+state.skipped:'')+(state.failures.length?' · 失败'+state.failures.length:'')+(state.current?' · '+state.current:''):count?'待补全 '+count+' 项；已登记内容会跳过。':'当前无待补全内容。';
    errors.replaceChildren();errors.hidden=!(relevant&&state.failures.length);
    if(!errors.hidden){const summary=document.createElement('summary');summary.textContent='查看失败项（'+state.failures.length+'）';errors.appendChild(summary);for(const f of state.failures){const row=document.createElement('p');row.textContent=f.name+'：'+f.error;errors.appendChild(row);}}
  }
}
function bindCompletionBatch(){
  for(const [kind,id] of [['opening','opening'],['equipment','eq'],['consumables','goods']])$('#'+id+'-batch').onclick=async function(){try{if(kind==='opening')await OPENING_GENERATOR.start(artApiConfig());else await COMPLETION_BATCH.start(kind,artApiConfig());renderCompletionBatch();}catch(e){toast(e.message);}};
}

