var TRAVEL_VIEW=null;
function openTravel(){
 if(!RT.isReady()){toast('等待当前聊天的变量加载');return;}
 const here=DLH_TRAVEL.location(V),list=DLH_TRAVEL.nodes(V),t=DLH_TRAVEL.trip(V),ongoing=t&&t.状态!=='抵达'&&t.当前位置===WORLD.当前地点;TRAVEL_VIEW={from:ongoing?t.from:here.pointId||'',to:ongoing?t.to:list.find(n=>n.id!==here.pointId)?.id||'',mode:ongoing?t.交通:'徒步',distanceLi:ongoing&&t.里程依据==='已登记里程'?t.里程:'',transportConfirmed:!!ongoing,busy:false};paintTravel();
}
function refreshTravel(){if(TRAVEL_VIEW&&$('#travel-panel')&&$('#poplay').classList.contains('open')){const signature=JSON.stringify([WORLD.当前地点,WORLD.游戏累计时辰,V.系统接入?.地理,HERO.基础信息?.武道境界,inBattle()]);if(signature!==TRAVEL_VIEW.signature)paintTravel();}}
function paintTravel(){
 const v=TRAVEL_VIEW,t=DLH_TRAVEL.trip(V),here=DLH_TRAVEL.location(V),list=DLH_TRAVEL.nodes(V),active=t?.状态==='进行中',busy=v.busy||inBattle(),locked=busy||active,fmt=n=>Math.round(n*10)/10;
 if(!ROOT.querySelector('#travel-style')){const s=document.createElement('style');s.id='travel-style';s.textContent='#travel-panel{max-width:760px}#travel-panel p{line-height:1.8}#travel-panel h2{font-family:KaiTi,STKaiti,serif;font-weight:400;color:#d8be80}#travel-panel .travel-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}#travel-panel label{display:flex;flex-direction:column;gap:8px;min-width:0}#travel-panel select,#travel-panel input{max-width:100%;width:100%;box-sizing:border-box;padding:10px;background:#172021;color:inherit;border:1px solid #716d55}#travel-panel .travel-check{display:block;margin:18px 0}#travel-panel .travel-check input{width:auto;display:inline-block;margin-right:8px}#travel-panel .travel-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px}#travel-panel button{padding:10px 18px}#travel-panel progress{width:100%;accent-color:#d4b36e}#travel-preview,#travel-current{padding:16px 0;border-bottom:1px solid #55584b;font-variant-numeric:tabular-nums}@media(max-width:540px){#travel-panel .travel-fields{grid-template-columns:1fr}}';ROOT.append(s);}
 const options=selected=>list.map(n=>'<option value="'+esc(n.id)+'" '+(n.id===selected?'selected':'')+'>'+esc(n.region+'·'+n.city)+'</option>').join('');
 openPop('<section id="travel-panel" aria-label="山河行程"><h2>山河行程</h2><p>当前所在：'+esc(WORLD.当前地点||'未定')+' · '+esc(here.precision)+'</p>'+(t?'<div id="travel-current"><strong>'+esc(t.状态)+' · '+esc(DLH_TRAVEL.data.nodes.find(n=>n.id===t.to)?.city)+'</strong><p>'+esc(t.交通)+' · 已行 '+fmt(t.已走里程)+' / '+fmt(t.里程)+' 里 · '+esc(t.里程依据)+'</p><progress max="'+t.里程+'" value="'+t.已走里程+'" aria-label="行程进度"></progress>'+(active?'<p>预计抵达：'+esc(DLH_CALENDAR.display(DLH_CALENDAR.date(JSON.parse(JSON.stringify(WORLD)),t.抵达时辰)))+'</p>':'')+'</div>':'')+'<details '+(active?'':'open')+'><summary>行程设置</summary><div class="travel-fields"><label>出发地<select id="travel-from" disabled><option value="">当前位置尚未定点</option>'+options(v.from)+'</select></label><label>目的地<select id="travel-to" '+(locked?'disabled':'')+'>'+options(v.to)+'</select></label><label>交通方式<select id="travel-mode" '+(locked?'disabled':'')+'>'+['徒步',...Object.keys(DLH_TRAVEL.data.speeds)].map(m=>'<option '+(v.mode===m?'selected':'')+'>'+m+'</option>').join('')+'</select></label><label>已知实际里程（里，可留空）<input id="travel-li" type="number" min="0.01" step="any" value="'+esc(v.distanceLi)+'" '+(locked?'disabled':'')+'></label></div><label class="travel-check"><input type="checkbox" id="travel-transport" '+(v.transportConfirmed?'checked ':'')+(locked?'disabled':'')+'>已确认具有相应坐骑、车船或搭乘条件</label></details><div id="travel-preview" role="status"></div><p class="empty-note">准备行程不推进日期。留空里程按总图直线估算，不能据此认定道路或航路可用；城外、山林须先明确当前位置。停驻修炼、休息或制作会中断赶路，可在原地续行。</p><div class="travel-actions"><button id="travel-start" '+(locked?'disabled':'')+'>开始赶路</button><button id="travel-cancel" '+(!active||busy?'disabled':'')+'>中断行程</button><button id="travel-resume" '+(t?.状态!=='中断'||busy?'disabled':'')+'>原地续行</button><button id="travel-time" '+(!active||busy?'disabled':'')+'>推进赶路时间</button><button id="travel-map">查看舆图</button></div></section>');
 $('#travel-from').value=v.from;const preview=()=>{if(active){$('#travel-preview').textContent='按本段已确认脚程继续赶路；停驻可中断，回来后可原地续行。';$('#travel-start').disabled=true;return;}try{const p=DLH_TRAVEL.preview(V,v);$('#travel-preview').textContent='每日 '+p.日脚程+' 里 · '+fmt(p.里程)+' 里（'+p.里程依据+'） · 预计 '+p.hours+' 时辰 · '+p.预计抵达;$('#travel-start').disabled=locked||v.mode!=='徒步'&&!v.transportConfirmed;}catch(e){$('#travel-preview').textContent=e.message;$('#travel-start').disabled=true;}};
 $('#travel-to').onchange=e=>{v.to=e.target.value;preview();};$('#travel-mode').onchange=e=>{v.mode=e.target.value;preview();};$('#travel-li').oninput=e=>{v.distanceLi=e.target.value;preview();};$('#travel-transport').onchange=e=>{v.transportConfirmed=e.target.checked;preview();};
 const write=action=>{if(v.busy)return;const r={...v,action,expected:WORLD.游戏累计时辰||0,revision:DLH_TRAVEL.read(V)?.序号||0};v.busy=true;paintTravel();RT.mutate(all=>{DLH_TRAVEL.act(all.stat_data,r);}).then(()=>{snap();toast(action==='start'?'行程已建立；日期尚未推进':action==='cancel'?'已中断行程':'已原地续行');},e=>toast(e.message)).finally(()=>{v.busy=false;if($('#travel-panel'))paintTravel();});};
 $('#travel-start').onclick=()=>write('start');$('#travel-cancel').onclick=()=>write('cancel');$('#travel-resume').onclick=()=>write('resume');$('#travel-map').onclick=openInkMap;
 $('#travel-time').onclick=()=>{openCalendar();CAL_VIEW.type='赶路';CAL_VIEW.hours=1;paintCalendar();};preview();v.signature=JSON.stringify([WORLD.当前地点,WORLD.游戏累计时辰,V.系统接入?.地理,HERO.基础信息?.武道境界,inBattle()]);
}
function mapLocation(){const p=DLH_TRAVEL.location(V);return {place:p.label,region:p.region,precision:p.precision,point:Number.isFinite(p.x)&&Number.isFinite(p.y)?[p.x/6,p.y/4]:null};}
function mapPlane(){const loc=mapLocation();return '<div class="map-plane"><img class="ink-map-image" src="'+MAP_IMAGE+'" alt="大凉十三州与周边山川舆图" draggable="false">'+(loc.point?'<span class="map-marker" style="left:'+loc.point[0]+'%;top:'+loc.point[1]+'%" title="'+esc(loc.place)+'" aria-label="当前所在：'+esc(loc.place)+'"></span>':'')+'</div>';}
function renderInkMap(){const box=$('#map-art');if(!box)return;box.innerHTML=mapPlane();const loc=mapLocation();$('#map-place').textContent='当前所在：'+(loc.place||'待定')+(loc.point?'':' · 暂无对应定位');}
function openInkMap(){
  const trigger=ROOT.activeElement||$('#map-x');
  openPop('<section class="map-viewer" aria-label="大凉舆图"><h2>大凉舆图</h2><button type="button" id="map-travel">山河行程 · 赶路</button><p>'+esc(mapLocation().place||'当前地点待定')+'</p><div class="map-toolbar"><button type="button" id="map-minus" aria-label="缩小舆图">−</button><output id="map-scale">100%</output><button type="button" id="map-plus" aria-label="放大舆图">＋</button><button type="button" id="map-reset">全图</button><button type="button" id="map-locate">当前位置</button></div><div class="map-viewport" id="map-viewport" tabindex="0" aria-label="舆图，放大后可滚动查看">'+mapPlane()+'</div></section>');
  $('#map-travel').onclick=openTravel;
  const dialog=$('#pop-box'),viewport=$('#map-viewport'),plane=viewport.querySelector('.map-plane');dialog.classList.add('map-dialog');dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');
  let scale=1;const update=v=>{scale=Math.max(1,Math.min(4,v));plane.style.width=scale*100+'%';$('#map-scale').textContent=Math.round(scale*100)+'%';$('#map-minus').disabled=scale<=1;$('#map-plus').disabled=scale>=4;};
  $('#map-plus').onclick=()=>update(scale+.5);$('#map-minus').onclick=()=>update(scale-.5);$('#map-reset').onclick=()=>{update(1);viewport.scrollTo(0,0);};$('#map-locate').disabled=!mapLocation().point;
  $('#map-locate').onclick=()=>{const point=mapLocation().point;update(3);viewport.scrollTo({left:plane.offsetWidth*point[0]/100-viewport.clientWidth/2,top:plane.offsetHeight*point[1]/100-viewport.clientHeight/2});};
  let drag=null;viewport.onpointerdown=e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,l:viewport.scrollLeft,t:viewport.scrollTop};viewport.setPointerCapture(e.pointerId);};viewport.onpointermove=e=>{if(drag){viewport.scrollLeft=drag.l+drag.x-e.clientX;viewport.scrollTop=drag.t+drag.y-e.clientY;}};viewport.onpointerup=viewport.onpointercancel=()=>{drag=null;};
  dialog.onkeydown=e=>{if(e.key==='Tab'){const items=[...dialog.querySelectorAll('button:not(:disabled),[tabindex="0"]')];const i=items.indexOf(ROOT.activeElement),n=(i+(e.shiftKey?-1:1)+items.length)%items.length;e.preventDefault();items[n].focus();}if(e.key==='Escape'){e.preventDefault();e.stopPropagation();$('#pop-x').click();}};
  $('#pop-x').onclick=()=>{$('#poplay').classList.remove('open');dialog.classList.remove('map-dialog');dialog.onkeydown=null;dialog.removeAttribute('role');dialog.removeAttribute('aria-modal');if(trigger?.isConnected)trigger.focus();};update(1);$('#map-plus').focus();
}
function renderArtOverview(){const box=$('#art-overview');if(!box)return;const query=$('#art-search').value.trim(),type=$('#art-filter').value;box.innerHTML='';const names=Object.keys(known()).filter(n=>(!query||(n+' '+(known()[n].特殊效果||'')).includes(query))&&(!type||slotOf(known()[n].类型)===type));$('#art-owned-count').textContent='已学 '+Object.keys(known()).length+' 门';for(const n of names){const inf=artInfoOf(n),button=document.createElement('button');button.type='button';button.className='art-overview-row';button.innerHTML='<span>'+esc(n)+'</span><small>'+esc(inf.type)+' · '+esc(inf.lv)+(isEquipped(n)?' · 已装配':' · 在库')+'</small>';button.dataset.artName=n;const available=unlockedMoves(n,inf.prof),line=document.createElement('small');line.className='art-available';line.textContent=available?(artDefinition(n).moves.length?'已习得 '+available.length+' / '+artDefinition(n).moves.length+' 式':'常驻效果 · 装配后生效'):'效果未录';button.appendChild(line);button.onclick=()=>openArt(n);box.appendChild(button);}if(!names.length)box.innerHTML='<p class="empty-note">'+(Object.keys(known()).length?'没有符合条件的武学。':'尚未学得武学。')+'</p>';}


