var DlhRecordedInk={create:async function(canvas,options){
 const frame=document.createElement('iframe');frame.title='山水散墨与领悟题字';frame.className='insight-recording-frame';frame.setAttribute('aria-label','领悟演出');frame.style.cssText='display:block;visibility:hidden;width:100%;aspect-ratio:1020/530;border:0;background:#b6b3bf';canvas.style.display='none';canvas.after(frame);
 let state='loading',destroyed=false;const emit=s=>{state=s;options.onState?.({state:s});};
 const loaded=new Promise((resolve,reject)=>{frame.onload=async()=>{try{await frame.contentWindow.inkPlayer.ready;resolve()}catch(e){reject(e)}};frame.onerror=()=>reject(Error('领悟素材未能载入'));});frame.srcdoc=DLH_RECORDED_INK_HTML;
 try{await loaded}catch(e){frame.remove();canvas.style.display='';throw e}if(destroyed)throw Error('演出已关闭');const player=()=>frame.contentWindow.inkPlayer;player().setPresentationKey(options.presentationKey||'preview');
 const ended=event=>{if(event.source!==frame.contentWindow)return;if(event.data?.type==='ink-title:ended')emit('hold');if(event.data?.type==='ink-title:state'&&['hold','error'].includes(event.data.state))emit(event.data.state);};window.addEventListener('message',ended);
 return {setText:async text=>player().setTitle(text),play:()=>{frame.style.visibility='visible';emit('playing');player().play().catch(()=>emit('error'));},skip:()=>{frame.style.visibility='visible';return player().hold().then(()=>emit('hold')).catch(()=>emit('error'))},exit:()=>{player().pause();emit('exiting');setTimeout(()=>{if(!destroyed)emit('idle')},160)},destroy:()=>{destroyed=true;try{player().pause()}catch(_){}window.removeEventListener('message',ended);frame.remove();canvas.style.display='';},snapshot:()=>({implementation:'recording-v3',state,textMode:player().title!=='剑意初成',fontFallback:[],scheduled:state==='playing'&&!frame.contentDocument.querySelector('video').paused,title:player().title}),get state(){return state}};
}};

/* Cosmetic presentations observe settled insight records. Never award or write MVU. */
function insightMotionEvent(key,record){
  const changes=record.阶段变化||[],subjects=(record.事件.真意||[]).filter(t=>changes.some(s=>s.startsWith(t.名称+'：')));
  const domain=record.事件.类型==='顿悟'&&(Object.values(record.百艺收益||{}).some(v=>v>0)||(record.知识成果||[]).length||(record.心性成果||[]).length);
  if(!subjects.length&&!domain)return null;
  const sword=subjects.some(t=>['剑意','剑之意'].includes(t.名称)&&changes.some(s=>s.startsWith(t.名称+'：未悟 → 初境_意')));
  const title=sword?'剑意初成':changes.some(s=>s.endsWith('极境_真意'))?'真意大成':changes.some(s=>s.endsWith('中境_明意'))?'明意渐成':'初悟其意';
  return {key,title:record.事件.题字||(domain?'融会贯通':title),domain,original:sword&&!record.事件.题字,record,signature:JSON.stringify(record),subjects:subjects.length?subjects.map(t=>t.名称):Object.keys(record.百艺收益||{}).concat(record.知识成果||[],record.心性成果||[])};
}
var INSIGHT_MOTION_STATE={scope:'',ready:false,seen:new Set(),queue:[],current:null,motion:null,token:0,disposed:false,observer:null};
function insightMotionScope(){return RT.contextKey();}
function rememberInsightMotion(){try{localStorage?.setItem('dlhud_insight_motion_v1:'+insightMotionScope(),JSON.stringify(Array.from(INSIGHT_MOTION_STATE.seen).slice(-512)));}catch(_){}}
function resetInsightMotion(){
  const s=INSIGHT_MOTION_STATE;s.token++;s.motion?.destroy();s.motion=null;s.current=null;s.readyToPlay=false;s.skipRequested=false;s.queue=[];s.ready=false;s.seen=new Set();s.scope='';$('#insight-motion')?.classList.remove('open');
}
function syncInsightMotion(){
  const s=INSIGHT_MOTION_STATE;if(s.disposed||!ROOT||!RT.isReady()||CHARACTER_BUSY)return;
  const scope=insightMotionScope(),records=HERO.感悟成长?.账本||{};
  if(s.scope!==scope){resetInsightMotion();s.scope=scope;try{const seen=JSON.parse(localStorage?.getItem('dlhud_insight_motion_v1:'+scope)||'[]');if(Array.isArray(seen))s.seen=new Set(seen.filter(x=>typeof x==='string'));}catch(_){}}
  if(!s.ready){Object.keys(records).forEach(k=>s.seen.add(k));s.ready=true;rememberInsightMotion();return;}
  for(const [key,record] of Object.entries(records)){
    if(s.seen.has(key))continue;s.seen.add(key);const event=insightMotionEvent(key,record);
    if(event){
      if(!event.domain)event.subjects=event.subjects.filter(name=>(record.阶段变化||[]).some(line=>line.startsWith(name+'：')&&line.endsWith('→ '+(yis()[name]?.境界||'invalid'))));
      if(event.subjects.length&&s.queue.length<8)s.queue.push(event);
    }
  }
  rememberInsightMotion();
  // Retraction clears a presentation; it does not retain a revoked reward display.
  s.queue=s.queue.map(e=>records[e.key]&&insightMotionEvent(e.key,records[e.key])).filter(Boolean);
  if(s.current&&(!records[s.current.key]||JSON.stringify(records[s.current.key])!==s.current.signature||!insightMotionEvent(s.current.key,records[s.current.key]))){closeInsightMotion();return;}
  if(inBattle()&&s.current){s.queue.unshift(s.current);closeInsightMotion(false);return;}
  startNextInsightMotion();
}
function startNextInsightMotion(){
  const s=INSIGHT_MOTION_STATE;if(s.disposed||s.current||!s.queue.length||inBattle()||document.hidden||$('#poplay').classList.contains('open'))return;
  const event=s.queue.shift();if(!HERO.感悟成长?.账本?.[event.key])return startNextInsightMotion();showInsightMotion(event);
}
async function showInsightMotion(event){
  const s=INSIGHT_MOTION_STATE,token=++s.token;s.current=event;s.readyToPlay=false;s.skipRequested=false;const box=$('#insight-motion');box.classList.add('open');box.dataset.phase='loading';$('#insight-motion-canvas').style.visibility='hidden';
  $('#insight-motion-subject').textContent=event.subjects.join('、');$('#insight-motion-source').textContent=event.record.事件.标题;
  $('#insight-motion-results').innerHTML='<strong>'+esc(event.subjects.join('、'))+'</strong>'+insightResults(event.record).map(t=>'<div>'+esc(t)+'</div>').join('');
  $('#insight-motion-results').hidden=true;$('#insight-motion-status').textContent='墨迹凝形';
  const manifest=JSON.parse(JSON.stringify(DLH_INK_MANIFEST));manifest.layouts.vertical.glyphs.forEach(g=>g.x-=72);
  try{
    const motion=await DlhRecordedInk.create($('#insight-motion-canvas'),{manifest,assets:DLH_INK_ASSETS,theme:'dark',textCenter:320,presentationKey:RT.contextKey()+'|'+event.key,onState:status=>{
      if(s.token!==token||s.disposed||!s.readyToPlay)return;
      if(box.dataset.phase!==status.state){box.dataset.phase=status.state;$('#insight-motion-results').hidden=!['hold','idle','error'].includes(status.state);$('#insight-motion-status').textContent=status.state==='hold'?'已领悟 · 结果已保存':status.state==='error'?'已领悟 · 结果已保存':status.state==='exiting'?'收势':'墨迹凝形';}
      if(status.state==='idle')closeInsightMotion();
    }});
    if(s.token!==token||s.disposed){motion.destroy();return;}s.motion=motion;
    await motion.setText(event.title);if(s.token!==token||s.disposed)return;
    $('#insight-motion-canvas').style.visibility='visible';
    if(s.skipRequested||RT.host.matchMedia('(prefers-reduced-motion: reduce)').matches){await motion.skip();if(s.token!==token||s.disposed)return;s.readyToPlay=true;box.dataset.phase='hold';$('#insight-motion-results').hidden=false;$('#insight-motion-status').textContent='已领悟 · 结果已保存';}
    else{s.readyToPlay=true;motion.play();}
  }catch(_){if(s.token===token){$('#insight-motion-results').hidden=false;$('#insight-motion-status').textContent='已领悟 · 结果已保存';}}
}
function closeInsightMotion(next=true){
  const s=INSIGHT_MOTION_STATE,box=$('#insight-motion'),focused=box?.contains(ROOT.getRootNode().activeElement);s.token++;s.current=null;s.readyToPlay=false;s.skipRequested=false;const m=s.motion;s.motion=null;m?.destroy();box?.classList.remove('open');
  if(focused)$('#orb').focus({preventScroll:true});if(next)startNextInsightMotion();
}
function replayInsightMotion(key){
  const r=HERO.感悟成长?.账本?.[key],event=r&&insightMotionEvent(key,r);if(!event)return;
  if(inBattle()){toast('交战中暂不播放领悟演出');return;}
  closeInsightMotion(false);safelyQueueInsightMotion(event);startNextInsightMotion();
}
function safelyQueueInsightMotion(event){INSIGHT_MOTION_STATE.queue.unshift(event);}
function bindInsightMotion(){
  $('#insight-motion-skip').onclick=()=>{INSIGHT_MOTION_STATE.skipRequested=true;if(INSIGHT_MOTION_STATE.readyToPlay)INSIGHT_MOTION_STATE.motion?.skip();$('#insight-motion-results').hidden=false;};
  $('#insight-motion-close').onclick=()=>{const m=INSIGHT_MOTION_STATE.motion;if(INSIGHT_MOTION_STATE.readyToPlay&&m&&m.state!=='error')m.exit();else closeInsightMotion();};
  INSIGHT_MOTION_STATE.observer=new MutationObserver(startNextInsightMotion);INSIGHT_MOTION_STATE.observer.observe($('#poplay'),{attributes:true,attributeFilter:['class']});
  RT.listen(document,'visibilitychange',startNextInsightMotion);
}
RT.onDispose(()=>{INSIGHT_MOTION_STATE.disposed=true;INSIGHT_MOTION_STATE.token++;INSIGHT_MOTION_STATE.motion?.destroy();INSIGHT_MOTION_STATE.observer?.disconnect();});

function mount(){
  ROOT=RT.mount(CSS,HTML);
  if(!$('#toast')){ var t=document.createElement('div'); t.id='toast'; t.setAttribute('role','status'); ROOT.appendChild(t); }
}
function $(s){ return ROOT.querySelector(s); }
function qa(s){ return ROOT.querySelectorAll(s); }
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function toast(t){ var el=$('#toast'); if(!el) return; el.textContent=t; el.classList.add('show'); clearTimeout(el._t); el._t=setTimeout(function(){el.classList.remove('show')},2400); }
function pct(c,m){ c=num(c); m=num(m); return m>0?Math.max(0,Math.min(100,c/m*100)):0; }
var CND=['零','一','二','三','四','五','六','七','八','九','十'];
function cn(n){ return CND[n]!=null?CND[n]:n; }
var CNC=['壹','贰','叁','肆','伍','陆','柒','捌','玖','拾'];

/* ═══ 快照 ═══ */
var V={}, HERO={}, WORLD={}, PLOT={}, NPCS={};
function snap(){
  var all=readVars(); V=G(all,['stat_data'],{});
  HERO=G(V,['主角'],{}); WORLD=G(V,['世界'],{}); PLOT=G(V,['剧情线'],{}); NPCS=G(V,['登场人物'],{});
}
function baseInfo(){ return G(HERO,['基础信息'],{}); }
function panel(){ return G(HERO,['战斗面板'],{}); }
function res(){ return G(panel(),['资源'],{}); }
function attrs(){ return G(panel(),['生效属性'],{}); }
function slots(){ return G(panel(),['槽位'],{}); }
function warState(){const d=battleData();return G(d,['战斗状态'],G(d.主角,['战斗状态'],{})); }
function inBattle(){ return warState()['阶段']==='进行中'; }
