/* ═══ 武学槽位工具 ═══ */
var SLOT_TYPES={'内功':['内功'],'横练':['横练','锻体','硬功'],'外功':['刀','剑','掌','拳','指','腿','枪','棍','锤','鞭','弓','爪','擒拿','手法','外功'],'轻功':['轻功','身法'],'奇门':['奇门','奇术','蛊','幻术','机关','驯兽','音','暗器']};
function slotOf(type){ type=String(DLH_ART_IDENTITY.type(type)||''); if(DLH_ART_IDENTITY.intrinsic({类型:type}))return ''; for(var s in SLOT_TYPES){ for(var i=0;i<SLOT_TYPES[s].length;i++) if(type.indexOf(SLOT_TYPES[s][i])!==-1) return s; } return '外功'; }
function slotFits(type,slot){return slotOf(type)===(slot==='副外功'?'外功':slot);}
var SLOT_EN={'内功':'nei','横练':'heng','轻功':'qing','外功':'wai','副外功':'wai2','奇门':'qi'};
var SLOT_CN={'nei':'内功','heng':'横练','qing':'轻功','wai':'外功','wai2':'副外功','qi':'奇门'};
function unlockedMoves(artName,prof){
  var a=artDefinition(artName); if(!a) return null;
  var tiers=ARTS.tiers, upto=tiers.indexOf(prof); if(upto<0) upto=0;
  var names={};
  for(var i=0;i<=upto;i++){ var u=a.unlock[tiers[i]]; var ns=u?(u.moves||u):[]; for(var j=0;j<ns.length;j++) names[ns[j]]=1; }
  var out=[];
  for(var k=0;k<a.moves.length;k++) if(names[a.moves[k].name]) out.push(a.moves[k]);
  return out;
}
function unlockedSigs(artName,prof){
  var a=artDefinition(artName); if(!a) return [];
  var tiers=ARTS.tiers, upto=tiers.indexOf(prof); if(upto<0) upto=0;
  var names={};
  for(var i=0;i<=upto;i++){ var u=a.unlock[tiers[i]]; var ns=u?(u.sigs||[]):[]; for(var j=0;j<ns.length;j++) names[ns[j]]=1; }
  return a.sigs.map(function(s){ return {name:s[0],desc:s[1],open:!!names[s[0]]}; });
}
function moveMeta(artName,moveName){
  var a=artDefinition(artName); if(!a) return null;
  for(var i=0;i<a.moves.length;i++) if(a.moves[i].name===moveName) return a.moves[i];
  return null;
}

