function attributeGroups(hero){
  const p=hero.战斗面板||{},a=p.生效属性||{},b=p.基础属性||{},r=p.资源||{},num=k=>a[k]||0,pct=k=>(/^(?:直接)?(?:精准率|会心率|会意率)$/.test(k)?Number(num(k)).toFixed(1):num(k))+'%',rows=[];
  const whole=v=>String(Math.round(Number(v)||0));
  function attack(label,min,max){return [label,whole(num(min))+'–'+whole(num(max)),'影响攻击造成'+label.replace('攻击','')+'伤害的能力。\n基础'+label+'：'+whole(b[min])+'–'+whole(b[max])+'\n生效'+label+'：'+whole(num(min))+'–'+whole(num(max))+'\n可通过使用增益食物和丹药、装备与词条提升。\n生效最小值大于最大值时，按生效最小值造成固定伤害。',num(min)>num(max)?whole(num(min)):whole(num(min))+'–'+whole(num(max))];}
  const judgment=[['精准率',pct('精准率'),'攻击时精准命中目标的几率。\n会意先独立判定，不受精准概率影响。未触发会意时判定精准；精准命中后才可触发会心，未精准命中则擦伤，基于自身攻击最小值结算。'],['会心率',pct('会心率'),'攻击时触发会心的概率。\n触发时伤害提高 '+num('会心伤害')+'%。受精准概率影响，只有精准命中后才能触发。'],['会意率',pct('会意率'),'攻击时触发会意的概率，先于精准与会心判定。\n触发时伤害提高 '+num('会意伤害')+'%，并基于自身攻击最大值结算；攻击区间反超时按生效最小值。\n会意不受精准概率影响，与会心不能同时触发。']];
  for(const row of judgment)row[2]+='\n判定抗性：面对高一境的对手，普通加成部分降低一成。天赋与奇物的基础加成、直接会心／会意不受影响。\n普通上限'+({精准率:100,会心率:80,会意率:40})[row[0]]+'%。';
  for(const k of ['直接会心率','直接会意率'])judgment.push([k,pct(k),'额外提升攻击时触发'+k.slice(2,4)+'的几率，不受普通率上限限制，也不受目标判定抗性影响。']);
  for(const [key,label] of [['会心伤害','会心伤害加成'],['会意伤害','会意伤害加成']])judgment.push([label,pct(key),'触发'+label.slice(0,2)+'时的伤害提升效果。\n基础 '+(b[key]||0)+'%，生效 '+num(key)+'%。']);
  const basic=[['气血',whole(r.气血)+' / '+whole(r.最大气血),'当前生命值，归零即败。\n基础气血上限：'+whole(p.基础上限?.最大气血)+'\n生效气血上限：'+whole(r.最大气血)+'\n上限可通过增益食物、丹药、装备、词条和奇物提升。'],['真气',whole(r.真气条)+' / '+whole(r.最大真气条),'承伤护盾，归零则气竭。'],['内力',whole(r.内力值)+' / '+whole(r.最大内力值),'施展招式所需的内力，由功法或药物回复。\n基础内力上限：'+whole(p.基础上限?.最大内力值)+'\n生效内力上限：'+whole(r.最大内力值)+'\n上限可通过增益食物、丹药、装备、词条和奇物提升。'],['耐力',whole(r.耐力)+' / '+whole(r.最大耐力),'格挡、闪避和脱身的行动资源。'],attack('外功攻击','最小外功攻击','最大外功攻击'),attack('真气攻击','最小真气攻击','最大真气攻击'),['速度',whole(num('速度')),'决定出手顺序。']];
  const lightName=p.槽位?.轻功,light=(hero.武学与意境面板?.掌握武学||{})[lightName],nativeLight=(typeof ARTS!=='undefined'?ARTS.arts?.[lightName]:null),grade=nativeLight?.lv||light?.评级,bonus=DLH_DODGE.grades[grade]||0,wx=hero.武学与意境面板||{},yi=(wx.领悟之意||{})[wx.真意位],perception=Math.min(.15,DLH_TALENTS.dodge(hero)+(yi?DLH_INTENT.dodge(wx.真意位,yi):0));
  basic[basic.length-1][2]+='\n闪避率：'+Math.round(DLH_DODGE.ordinary(bonus+perception)*10000)/100+'%（基础20%'+(light?'＋'+(grade||'未评级')+'轻功'+Math.round(bonus*100)+'%':'，未装配轻功')+'）。\n体质与所装真意额外提供 '+DLH_DISPLAY.percent(perception)+'，两类额外加成合计最多15个百分点；临时效果以战斗实际判定为准。\n普通闪避上限60%；速度不影响闪避概率。\n闪避抗性：面对高一境的对手，普通闪避率降低一成。某些状态和武学也会改变实际概率。\n主动闪避只提供机会，不额外加率。';
  const defense=[];for(const channel of ['外功','真气']){defense.push([channel+'防御',num(channel+'防御'),'与'+channel+'攻击做加减法，再进入其他乘区。'],[channel+'穿透',num(channel+'穿透'),'提升'+channel+'攻击造成的伤害，与'+channel+'抗性对抗。\n以整数点数与抗性对冲，1点对应此乘区1个百分点。\n净穿透溢出折半，净抗性减伤封顶80%。'],[channel+'抗性',num(channel+'抗性'),'与'+channel+'穿透对抗，减少受到的'+channel+'伤害。以整数点数登记，与穿透对冲。'],[channel+'伤害加成',pct(channel+'伤害加成'),'提升造成的'+channel+'伤害效果。'],[channel+'伤害减免',pct(channel+'伤害减免'),'减免受到的'+channel+'伤害效果。']);}defense.push(['神魂穿透',num('神魂穿透'),'提升神魂伤害的穿透能力，以整数点数登记。'],['神魂伤害加成',pct('神魂伤害加成'),'提升造成的神魂伤害效果。'],['神魂伤害减免',pct('神魂伤害减免'),'减免受到的神魂伤害效果。']);
  const five=DLH_FIVE.view(hero),fiveRows=DLH_FIVE.keys.map(k=>[k,whole(five.合计[k]),k+DLH_FIVE.describe(k)+'。\n境界 '+whole(five.基础[k])+'；体质 '+whole(five.天赋体质?.[k]||0)+'；永久成长 '+whole(five.成长[k])+'；装备 '+whole(five.装备[k])+'；奇物 '+whole(five.奇物[k])+'；临时丹药 '+whole(five.丹药[k])+'。']);
  const format=value=>typeof value==='number'?DLH_DISPLAY.number(value):typeof value==='string'?value.replace(/-?\d+\.\d{3,}(?:[eE][+-]?\d+)?/g,raw=>DLH_DISPLAY.number(raw)):value;
  return [['五维',fiveRows],['基础属性',basic],['判定属性',judgment],['防御属性',defense]].map(([title,items])=>[title,items.map(row=>row.map((value,i)=>i?format(value):value))]);
}
function attributeDetail(row){return '<div class="attribute-heading"><span class="attribute-value">'+esc(row[3]??row[1])+'</span><span class="attribute-name">'+esc(row[0])+'</span></div>'+String(row[2]).split('\n').map(t=>'<p class="attribute-description">'+esc(t)+'</p>').join('');}

/* Permanent buff presentation only: retain every native source and tooltip. */
function permanentBuffRows(hero,permanent){
  const artNames=Object.keys(hero?.武学与意境面板?.掌握武学||{}).sort((a,b)=>b.length-a.length);
  const artKinds=new Set(['内功','横练','轻功','外功','副外功','奇门','内功兼修','横练兼修','功法']);
  const equipmentKinds=new Set([...(typeof DLH_EQUIPMENT==='undefined'?[]:DLH_EQUIPMENT.slots),'主武器','副武器','冠冕','胸甲','腿甲','腕甲','防具','环','佩','本命剑']);
  const groups=new Map();
  for(const [key,text]of Object.entries(permanent||{})){
    const parts=key.split(/\s*·\s*/),rawSource=parts.length>1?parts.shift():'',derived=rawSource.startsWith('五维/');
    let source=derived?rawSource.slice(3):rawSource,name=parts.join(' · '),detail=name;
    if(derived)name=name.replace(/\s*·\s*五维$/,'');
    if(derived&&source==='装备'){
      const split=name.split(/\s*·\s*/),slot=split.at(-1);
      if(equipmentKinds.has(slot)){source=slot;split.pop();name=split.join(' · ');}
    }
    let family=source;
    if(artKinds.has(source)){
      const art=artNames.find(a=>name===a||name.startsWith(a+' · '));
      if(art){family='功法';name=art;}
    }
    if(source==='天赋体质')family='体质';
    if(derived&&source==='成长'&&name==='天材地宝等永久成长')name='五维成长';
    const id=JSON.stringify([family,name]),row=groups.get(id)||{id,name,family,keys:[],details:[]};
    row.keys.push(key);
    const label=derived?'五维换算':detail||name;
    const description=String(text??'').trim();
    if(description){const line=label+'：'+description;if(!row.details.includes(line))row.details.push(line);}
    groups.set(id,row);
  }
  const rows=[...groups.values()],names=new Map();
  for(const row of rows)names.set(row.name,(names.get(row.name)||0)+1);
  return rows.map(row=>({...row,label:row.name+(names.get(row.name)>1&&row.family?' · '+row.family:''),tip:['来源：'+(row.family?row.family+' · ':'')+row.name,...row.details].join('\n')}));
}
/* End permanent buff presentation. */
