  g1.querySelector('.character-realm').textContent=DLH_DISPLAY.realm(b['武道境界']||'无修为');
  g1.querySelector('.gl').textContent=[b['年龄']!=null?'年'+b['年龄']:'',(b['所属势力']||'无门无派')+(b['势力地位']?' · '+b['势力地位']:''),b['江湖绰号']||''].filter(Boolean).join(' · ');
  /* 属性 */
  var r=res(), at=attrs();
