/* Equipment and item views use stable record keys, including newly acquired entries. */
var EQ_GRADE_CLS={'先天':'qz','后天':'qz','一品':'qj','二品':'ql','三品':'ql','不入流':'ql'};
var eqSelected=null,goodsCat='物品',goodsSelected='';
function matching(name,item,search){return !search||(name+' '+(item.名称||'')+' '+(item.描述||'')+' '+(item.特殊效果||'')+' '+(item.效果||'')).toLowerCase().includes(search.toLowerCase());}
function modifierText(fx){
  var out=[];fx=fx||{};for(const k of ['全武学增伤','强敌增伤'])if(fx[k])out.push(k+' +'+DLH_EQUIPMENT.percent(fx[k]));
  Object.entries(fx.五维||{}).forEach(([k,v])=>{if(v)out.push(k+' +'+DLH_DISPLAY.number(v));});
  Object.keys(fx.数值加成||{}).forEach(function(k){var v=fx.数值加成[k];if(v)out.push(k+' '+(v>0?'+':'')+(['精准率','会心率','会意率'].includes(k)?DLH_EQUIPMENT.points(v):DLH_DISPLAY.number(v)));});
  Object.keys(fx.比例加成||{}).forEach(function(k){var v=fx.比例加成[k];if(v)out.push(k+' '+(v>0?'+':'')+DLH_EQUIPMENT.percent(v));});
  if(fx.减伤率)out.push('减伤 '+DLH_EQUIPMENT.percent(fx.减伤率));
  Object.keys(fx.属性增伤||{}).forEach(function(k){out.push(k+'系招式直伤 +'+DLH_EQUIPMENT.percent(fx.属性增伤[k]));});
  Object.keys(fx.兵器增伤||{}).forEach(function(k){out.push(DLH_EQUIPMENT.weaponText(k,fx.兵器增伤[k]));});
  (fx.武学增伤||[]).forEach(t=>out.push('《'+t.武学+'》'+(t.招式?'·'+t.招式:'')+'伤害 +'+DLH_EQUIPMENT.percent(t.倍率)));
  return out.join(' ｜ ')||'无数值加成';
}
/* Inventory removal is a checked transaction; worn gear is first returned to the bag. */
var DLH_GEAR_DISCARD=(function(){
 function check(sd,selection,fingerprint){
  if((sd.战斗状态||sd.主角?.战斗状态)?.阶段==='进行中')throw Error('交战中不能丢弃装备');
  if(selection?.from!=='bag'||typeof selection.key!=='string')throw Error('请先卸下装备，再从行囊丢弃');
  const item=sd.主角?.装备栏?.装备库?.[selection.key];
  if(!item||JSON.stringify(item)!==fingerprint)throw Error('装备已变化，请重新选择');
  const bound=sd.主角?.装备栏?.本命剑;
  if(item.绑定===true||item.本命绑定===true||(bound&&item.同行标识&&bound.同行标识===item.同行标识))throw Error('请先解除绑定，再丢弃此装备');
  return item;
 }
 function discard(sd,selection,fingerprint){check(sd,selection,fingerprint);delete sd.主角.装备栏.装备库[selection.key];}
 return {check,discard};
})();
