/* Inventory owns the transfer entry point; the domain operation commits both bags atomically. */
function inventoryGiftButton(detail,selection,item){
 const b=document.createElement('button');b.type='button';b.className='inventory-action';b.dataset.inventoryGift=selection.kind;b.textContent='转赠同行者';
 b.disabled=inBattle()||COMPANION_BUSY||item.状态==='已服用';b.onclick=()=>openInventoryGift(selection);detail.appendChild(b);
}
function inventoryGiftItem(sd,s){return s.kind==='gear'?(s.from==='on'?sd.主角?.装备栏?.[s.key]:sd.主角?.装备栏?.装备库?.[s.key]):sd.主角?.[s.kind]?.[s.key];}
function openInventoryGift(selection){
 selection={...selection};const item=inventoryGiftItem(V,selection);if(!item)return;
 const members=Object.values(DLH_COMPANIONS.read(V).成员).filter(m=>m.状态==='同行'&&!DLH_COMPANIONS.dead(V,m.标识));
 const max=selection.kind==='gear'?1:Number(item.数量??1),scope=RT.generationScope(),message=RT.messageToken(),source=JSON.stringify(item);
 const roster=JSON.stringify(DLH_COMPANIONS.read(V).成员);
 openPop('<div class="inventory-gift"><h3>转赠 · '+esc(item.名称||selection.key)+'</h3><p>交给同行者保管。离队后仍由对方持有。</p>'+(members.length?'<label>交给谁<select id="inventory-gift-target">'+members.map(m=>'<option value="'+esc(m.标识)+'">'+esc(companionName(m.标识))+'</option>').join('')+'</select></label><label>数量<input id="inventory-gift-quantity" type="number" min="1" max="'+max+'" step="1" value="1"'+(max===1?' readonly':'')+'></label><p>当前持有 '+max+' 份</p><button type="button" id="inventory-gift-confirm">确认转赠</button><p id="inventory-gift-status" role="status"></p>':'<p>当前没有可接收的同行者。</p>')+'</div>');
 const button=$('#inventory-gift-confirm');if(!button)return;
 button.onclick=async()=>{
  if(COMPANION_BUSY)return;const target=$('#inventory-gift-target').value,quantity=Number($('#inventory-gift-quantity').value),status=$('#inventory-gift-status');
  if(!Number.isSafeInteger(quantity)||quantity<1||quantity>max){status.textContent='请输入 1 至 '+max+' 的整数。';return;}
  COMPANION_BUSY=true;button.disabled=true;
  try{await RT.mutate(all=>{
   if(scope!==RT.generationScope()||message!==RT.messageToken())throw Error('聊天或消息已变化，请重新选择物品');
   const sd=all.stat_data;if(JSON.stringify(inventoryGiftItem(sd,selection))!==source||JSON.stringify(DLH_COMPANIONS.read(sd).成员)!==roster)throw Error('物品或同行名单已变化，请重新选择');
   if(selection.kind==='gear'){CHARACTER.initialise(sd.主角);DLH_COMPANIONS.move(sd,'主角',target,selection.from==='on'?selection.key:'bag',selection.key,ARTS);CHARACTER.recompute(sd.主角);}
   else DLH_COMPANIONS.giftItem(sd,target,selection.kind,selection.key,quantity);
  });snap();renderEq();renderGoods();renderCompanions();$('#pop-x').click();const grid=selection.kind==='gear'?$('#eq-bag'):$('#shop-grid');INVENTORY_FLOAT.suppressFocus=true;(grid?.querySelector('button')||$(selection.kind==='gear'?'#eq-search':'#goods-search'))?.focus({preventScroll:true});INVENTORY_FLOAT.suppressFocus=false;toast('已转赠给 '+companionName(target));}
  catch(e){status.textContent=e.message||'转赠未保存';}
  finally{COMPANION_BUSY=false;button.disabled=false;}
 };
}
function renderEq(){
  var eq=G(HERO,['装备栏'],{}),bag=eq.装备库||{},on=$('#eq-on'),grid=$('#eq-bag');on.innerHTML='';grid.innerHTML='';
  DLH_EQUIPMENT.migrate(eq);var equipped=DLH_EQUIPMENT.slots.filter(function(k){return !CHARACTER.empty(eq[k]);});
  const eqFilter=$('#eq-filter'),oldFilter=DLH_EQUIPMENT.slot(eqFilter.value);eqFilter.innerHTML='<option value="">全部部位</option>'+DLH_EQUIPMENT.slots.map(s=>'<option value="'+s+'">'+s+'</option>').join('');eqFilter.value=oldFilter||'';
  var search=$('#eq-search').value,filter=eqFilter.value,names=Object.keys(bag).filter(function(k){return (!filter||bag[k].部位===filter)&&matching(k,bag[k],search);});
  if(eqSelected&&((eqSelected.from==='on'&&CHARACTER.empty(eq[eqSelected.key]))||(eqSelected.from==='bag'&&!names.includes(eqSelected.key))))eqSelected=null;
  if(!eqSelected)eqSelected=equipped.length?{from:'on',key:equipped[0]}:names.length?{from:'bag',key:names[0]}:null;
  function card(target,key,e,from){
    var d=document.createElement('button');d.type='button';d.className='eq '+(EQ_GRADE_CLS[e.评级]||'ql')+(eqSelected&&eqSelected.from===from&&eqSelected.key===key?' on':'');d.dataset.gearKey=key;d.dataset.gearFrom=from;d.setAttribute('aria-pressed',String(!!(eqSelected&&eqSelected.from===from&&eqSelected.key===key)));
    d.innerHTML=inventoryArt(e,e.名称||key,from==='on'?key:e.部位)+'<div class="es"><span>'+esc(from==='on'?key:e.部位||'部位待补')+'</span><span>'+esc(e.评级||'不入流')+'</span></div><div class="en2">'+esc(e.名称||key)+'</div><div class="ee">'+esc(e.通用加成?.length?DLH_GEAR_GROWTH.terms(HERO,e).map(t=>DLH_EQUIPMENT.termText(t,e.种类,DLH_JIANXIANG.active(HERO)&&DLH_JIANXIANG.sword(e)?1.3:1)).join(' ｜ '):DLH_EQUIPMENT.registered(e.面板加成)?modifierText(e.面板加成):DLH_DISPLAY.text(e.特殊效果||e.描述||'无特殊效果'))+'</div>';
    bindInventoryInspect(d,'gear',{from:from,key:key});d.onclick=function(){const view=inventoryMutationView();inspectInventory('gear',{from:from,key:key},d,true);$('#p5').scrollTop=view.page;grid.scrollTop=view.bag;};target.appendChild(d);
  }
  DLH_EQUIPMENT.slots.forEach(function(k){
    if(!CHARACTER.empty(eq[k]))card(on,k,eq[k],'on');
    else {var d=document.createElement('div');d.className='eq eq-empty';d.innerHTML=inventoryArt({},'',k)+'<div class="es">'+k+'</div><div class="en2">'+(k==='主武器'?'空手':'未穿戴')+'</div>';on.appendChild(d);}
  });
  names.forEach(function(k){card(grid,k,bag[k],'bag');});
  if(!names.length)grid.innerHTML='<div class="empty-note">'+(Object.keys(bag).length?'没有符合筛选的装备。':'行囊暂无备用装备。')+'</div>';
  $('#p5 .eqsplit').textContent='行囊备用 · '+Object.keys(bag).length+' 件'+(filter||search?' · 筛选 '+names.length+' 件':'');
  var sk=DLH_CURIOS.entries(HERO);curioLoadoutUI();
  renderJianxiangEntry();
  $('#gl-eq').textContent='穿戴 '+equipped.length+' 件 ｜ 备用 '+Object.keys(bag).length+' 件 ｜ 奇物 '+sk.length+' 件';
  inventoryGridKeys(on);inventoryGridKeys(grid);gearDetail(eq,bag);inventoryFloatAfterRender('gear');
}
function renderGoods(){
  var w=G(HERO,['财富资源'],{}),coin=w.银钱||{},ind=w.产业||{};
  $('#wealth-line').innerHTML='<span>银钱 <b>'+esc(coin.两||0)+' 两 '+esc(coin.文||0)+' 文</b></span><span>产业：'+esc(Object.keys(ind).join('、')||'无')+'</span>';
  var cats=DLH_INVENTORY.view(HERO),catBox=$('#shop-cat');catBox.innerHTML='';
  Object.keys(cats).forEach(function(k){var b=document.createElement('button');b.type='button';b.textContent=k+' · '+Object.keys(cats[k]).length;b.className=k===goodsCat?'on':'';b.onclick=function(){goodsCat=k;goodsSelected='';$('#goods-filter').value='';renderGoods();};catBox.appendChild(b);});
  var dict=cats[goodsCat]||{},filter=$('#goods-filter'),selectedType=filter.value,category=it=>it.类型||it.类别||(goodsCat==='天材地宝'?'天材地宝':'其他'),types=Array.from(new Set(Object.keys(dict).map(function(k){return category(dict[k]);}))).sort();
  filter.innerHTML='<option value="">所有类别</option>';
  types.forEach(function(t){var o=document.createElement('option');o.value=t;o.textContent=t;filter.appendChild(o);});filter.value=types.includes(selectedType)?selectedType:'';
  var names=Object.keys(dict).filter(function(k){return (!filter.value||category(dict[k])===filter.value)&&matching(k,dict[k],$('#goods-search').value);});
  if(!names.includes(goodsSelected))goodsSelected=names[0]||'';
  var grid=$('#shop-grid');grid.innerHTML='';
  names.forEach(function(nm){var it=dict[nm],d=document.createElement('button'),grade=it.品级||it.评级;d.type='button';d.dataset.itemKey=nm;
    d.className='gi '+(['先天','后天'].includes(grade)?'q-tian':grade==='一品'?'q-shu':grade==='二品'?'q-dan':'q-an')+(nm===goodsSelected?' on':'');
    d.setAttribute('aria-pressed',String(nm===goodsSelected));d.innerHTML=inventoryArt(it,DLH_ITEMS.label(it,nm),'')+'<div class="gn3">'+esc(DLH_ITEMS.label(it,nm))+'</div><div class="gc">'+(it.状态==='已服用'?'已服用':'×'+esc(it.数量!=null?it.数量:1))+'</div>';bindInventoryInspect(d,'goods',nm);d.onclick=function(){const scroll=grid.scrollTop,pageScroll=$('#p6').scrollTop;inspectInventory('goods',nm,d,true);grid.scrollTop=scroll;$('#p6').scrollTop=pageScroll;};grid.appendChild(d);});
  inventoryGridKeys(grid);renderGoodsDetail(dict,names,category);inventoryFloatAfterRender('goods');
}
function itemUseReason(name,item){
 if(item.状态==='已服用')return '此物已服用，无剩余库存';
 if(DLH_ITEMS.restriction(item))return '使用条件尚需确认：'+DLH_ITEMS.restriction(item);
 if(item.效用){try{DLH_ITEMS.canUse(HERO,name,inBattle()?'battle':'daily');if(inBattle())return warState().引擎存档?createDlhBattleEngine(JSON.parse(warState().引擎存档),ARTS).reason({name:'服药',item:{}}):'战斗正在初始化';return '';}catch(e){return e.message;}}
 const r=DLH_INVENTORY.locate(HERO,name);if(item.五维增益&&r.bag==='天材地宝栏'){if(inBattle())return '天材地宝须在场外炼化';try{DLH_FIVE.treasure(JSON.parse(JSON.stringify(HERO)),r.key);return '';}catch(e){return e.message;}}
 if(item.回复资源&&item.回复量){try{CHARACTER.medicine(HERO,r.key,inBattle()?'battle':'daily');return '';}catch(e){return e.message;}}
 if(!DLH_INVENTORY.registrationReason(HERO,name))return '尚未登记服食效果，请先登记并补全药效。';
 return '此物没有直接服用效果，可保留、转赠、丢弃或补全用途。';
}
function renderGoodsDetail(dict,names,category){
 const grid=$('#shop-grid'),detail=$('#shop-detail');if(!names.length){grid.innerHTML='<div class="empty-note">'+(Object.keys(dict).length?'没有符合筛选的物品。':'行囊空空如也。')+'</div>';detail.textContent='选择一件物品查看详情。';return;}
 const id=goodsSelected,it=dict[id],r=DLH_INVENTORY.locate(HERO,id),why=itemUseReason(id,it),name=it.名称||r.key,e=it.效用;
 detail.innerHTML=inventoryArtHero(it,name,'')+'<div class="gn4">'+esc(name)+'</div><div class="gk">'+esc(category(it))+' ｜ '+esc(it.品级||it.评级||'')+' ｜ '+(it.状态==='已服用'?'已服用':'持有 ×'+esc(it.数量??1))+'</div><div class="gd4">'+esc(it.描述||it.效果||'')+'</div>';
 if(DLH_INVENTORY.isSpent(it)){detail.innerHTML+='<p class="inventory-effects">服用记录 · 无可用库存</p><p class="empty-note">此物已服用，记录已与可用物品分开，不再占用物品或天材地宝列表。此处仅供查阅，原有成长与感悟进度保留，不会再次结算；感悟仍在感悟页查看和处理。</p>';return;}
 if(it.使用条件)detail.innerHTML+='<p class="inventory-effects">使用条件：'+esc(it.使用条件)+'</p>';
 if(it.用途说明)detail.innerHTML+='<p class="inventory-effects">用途：'+esc(it.用途说明)+'</p>';
 if(e){const lines=[(DLH_INVENTORY.type(it)==='食物'?DLH_INVENTORY.foodGroup(it):DLH_INVENTORY.type(it))+' · '+e.类别];
  if(e.恢复)for(const [key,v]of Object.entries(e.恢复)){const d=DLH_ITEMS.dose(v);lines.push('回复'+key+' '+(d.比例!=null?DLH_DISPLAY.number(d.比例*100)+'% 上限':d.数值));}
  if(e.伤势处置)lines.push(DLH_INJURY.medicineText(e.伤势处置));if(e.净化?.length)lines.push('净化：'+e.净化.map(x=>typeof x==='string'?x:x.状态+' '+x.层数+'层').join('、'));
  if(e.面板加成)lines.push(modifierText(e.面板加成));if(e.持续)lines.push('持续 '+Object.entries(e.持续).map(([k,v])=>v+' '+k).join('、'));
  if(e.悟性加成!=null){lines.push('悟性永久 +'+DLH_DISPLAY.number(e.悟性加成*100)+'% · 参与武学与感悟结算，不随境界放大');try{const q=DLH_INVENTORY.permanentInfo(HERO);lines.push('本大境界永久药力已获 '+q.used+'/3 次；'+(q.left?'还可获得 '+q.left+' 次':'再次服用转为境界积累'));}catch(error){lines.push(error.message);}}
  if(e.装备折算){lines.push('药力相当于同品级、同境界 '+DLH_DISPLAY.number(e.装备折算.条数)+' 条满值装备词条');try{lines.push('本次服用：'+modifierText(DLH_INVENTORY.scaled(HERO,it)));}catch(error){lines.push(error.message);}if(e.类别==='永久类'){try{const q=DLH_INVENTORY.permanentInfo(HERO);lines.push('本大境界永久药力已获 '+q.used+'/3 次；'+(q.left?'还可获得 '+q.left+' 次':'再次服用转为境界积累'));}catch(error){lines.push(error.message);}}}
  if(e.类别==='持续类'){const old=[...(panel().消耗品?.食物||[]),...(panel().消耗品?.丹药||[])].filter(x=>x.剩余>0);lines.push(old.length?'将覆盖：'+old.map(x=>x.名称).join('、'):'临时属性只生效一个来源');}
  if(e.基础属性)for(const [k,v]of Object.entries(e.基础属性))lines.push(k+'永久增长 '+DLH_DISPLAY.number(DLH_ITEMS.dose(v).比例*100)+'%（服用时定格）');
  if(e.成长?.修为比例)lines.push('获得当前阶段门槛 '+DLH_DISPLAY.number(e.成长.修为比例*100)+'% 的修为积累，至多填满当前阶段');if(e.成长?.感悟)lines.push('获得一次普通感悟，使用时选择一门已学武学');
  if(e.限服)lines.push('同名限服 '+e.限服+' 次，已服 '+(panel().消耗品?.服用计数?.[DLH_ITEMS.identity(it,r.key)]||0)+' 次');
  detail.innerHTML+='<div class="inventory-effects">'+lines.map(esc).join('<br>')+'</div>';
 }
 if(it.效用来源)detail.innerHTML+='<p class="empty-note">'+esc(it.效用来源==='本地模板'?'本地模板效果，可按需重新补全。':!e&&it.效用来源==='API补全'?'用途说明已补全，尚无服食药效':it.效用来源)+(it.效用修订?.length?' · 已保留最近 '+it.效用修订.length+' 版记录':'')+'</p>';
 if(r.bag==='物品栏')DLH_XIANLU_UI.item(detail,r.key);
 if(it.灵木增益){const bonus=DLH_LINGMU.consumableBonus(HERO,r.key);if(bonus)detail.innerHTML+='<p class="inventory-effects">灵木培养：气血恢复额外增强 '+DLH_DISPLAY.number(bonus*100)+'%。</p>';}
 if(it.五维增益&&!e)detail.innerHTML+='<p class="inventory-effects">'+Object.entries(it.五维增益).filter(([,v])=>v).map(([k,v])=>esc(k+' 永久 +'+v)).join(' ｜ ')+'</p>';
 if(e||it.五维增益||it.回复量){const b=document.createElement('button');b.id='goods-use';b.className='inventory-action';b.textContent=inBattle()?'服药 · 占一次主动作':'使用一份';b.disabled=!!why&&!why.startsWith('生效位已满');detail.appendChild(b);b.onclick=()=>{
  if(e?.类别==='成长类'){openGrowthItem(id,it);return;}
  if(e){chooseConsumable(id,inBattle());return;}
  if(it.五维增益){mutateVars(all=>{if((all.stat_data.战斗状态||{}).阶段==='进行中')throw Error('交战中不能炼化');DLH_FIVE.treasure(all.stat_data.主角,r.key);CHARACTER.recompute(all.stat_data.主角);},()=>toast('五维成长已结算'));return;}
  if(inBattle())localBattleAction({name:'服药',item:{name:r.key}});else mutateVars(all=>CHARACTER.useDaily(all.stat_data.主角,r.key),()=>toast('已使用「'+name+'」'));
 };}
 inventoryGiftButton(detail,{kind:r.bag,key:r.key},it);
 const discard=document.createElement('button');discard.id='item-discard';discard.className='inventory-action';discard.textContent='丢弃';discard.disabled=inBattle()||it.状态==='已服用'||Number(it.数量??1)<1;discard.onclick=()=>openItemDiscard(id);detail.appendChild(discard);
 if(why){const p=document.createElement('p');p.className='empty-note';p.textContent=why;detail.appendChild(p);}
 const register=document.createElement('button');register.id='item-register';register.className='inventory-action';register.textContent=ITEM_GENERATOR.busy()?'正在补全…':(!DLH_INVENTORY.registrationReason(HERO,id)?'登记服食效果':DLH_INVENTORY.type(it)?'补全药效':'补全用途')+' · 调用酒馆API';register.disabled=inBattle()||ITEM_GENERATOR.busy()||OPENING_GENERATOR.busy()||COMPLETION_BATCH.busy()||!RT.isReady();detail.appendChild(register);register.onclick=()=>{if(!DLH_INVENTORY.registrationReason(HERO,id))openItemCompletionChoice(id);else ITEM_GENERATOR.generate(id,artApiConfig()).then(()=>toast(ITEM_GENERATOR.status())).catch(e=>toast(e.message));};
 if(!DLH_INVENTORY.type(it)&&DLH_INVENTORY.registrationReason(HERO,id).includes('修行机缘')){const p=document.createElement('p');p.className='empty-note';p.textContent=DLH_INVENTORY.registrationReason(HERO,id);detail.appendChild(p);}
 if(ITEM_GENERATOR.busy()&&!COMPLETION_BATCH.busy()){const cancel=document.createElement('button');cancel.className='inventory-action';cancel.textContent='取消补全';cancel.onclick=()=>ITEM_GENERATOR.cancel();detail.appendChild(cancel);}
 if(ITEM_GENERATOR.status()){const p=document.createElement('p');p.className='empty-note';p.textContent=ITEM_GENERATOR.status();detail.appendChild(p);}
}
function openItemCompletionChoice(id){
 const i=DLH_INVENTORY.get(HERO,id);if(!i)return;const source=JSON.stringify(i),scope=RT.generationScope(),message=RT.messageToken();
 openPop('<div class="inventory-gift"><h3>补全 · '+esc(i.名称||DLH_INVENTORY.locate(HERO,id).key)+'</h3><p>此宝物尚未明确登记是否可服食。选择登记后补全可执行药效，仍按原品级校验；本次不会服用、扣库存或发放收益。材料和任务物品请保留原用途。</p><button type="button" id="item-complete-food">登记为可服食并补全药效</button><button type="button" id="item-complete-purpose">仅补用途</button><p id="item-complete-status" role="status"></p></div>');
 const run=async registerConsumption=>{const status=$('#item-complete-status');try{await RT.refresh();if(scope!==RT.generationScope()||message!==RT.messageToken()||source!==JSON.stringify(DLH_INVENTORY.get(RT.snapshot().stat_data.主角,id)))throw Error('物品或消息已变化，请重新选择');if(inBattle()||OPENING_GENERATOR.busy()||COMPLETION_BATCH.busy())throw Error('当前正在战斗或补全，请稍后重试');$('#pop-x').click();await ITEM_GENERATOR.generate(id,artApiConfig(),{registerConsumption});snap();renderGoods();toast(registerConsumption?'药效已登记，可从物品详情使用；本次未服用':'用途说明已保存；未登记服食药效');}catch(e){if(status?.isConnected)status.textContent=e.message;toast(e.message);}};
 $('#item-complete-food').onclick=()=>run(true);$('#item-complete-purpose').onclick=()=>run(false);
}
function openItemDiscard(id){
 const r=DLH_INVENTORY.locate(HERO,id),i=r.item;if(!i)return;const source=JSON.stringify(i),scope=RT.generationScope(),message=RT.messageToken(),max=Number(i.数量??1);
 openPop('<div class="inventory-gift"><h3>丢弃 · '+esc(i.名称||r.key)+'</h3><p>丢弃后从当前库存扣除，不返还材料或已结算的成长。</p><label>数量<input id="item-discard-count" type="number" min="1" max="'+max+'" step="1" value="1"></label><p>当前持有 '+max+' 份</p><button type="button" id="item-discard-confirm">确认丢弃</button><p id="item-discard-status" role="status"></p></div>');
 $('#item-discard-confirm').onclick=async function(){this.disabled=true;const count=Number($('#item-discard-count').value);try{await RT.mutate(all=>{if(scope!==RT.generationScope()||message!==RT.messageToken())throw Error('消息已切换，请重新选择');DLH_INVENTORY.discard(all.stat_data,id,count,source);});$('#pop-x').click();snap();renderGoods();toast('已丢弃 '+count+' 份');}catch(e){$('#item-discard-status').textContent=e.message;this.disabled=false;}};
}
function openGrowthItem(id,item){
 const names=Object.keys(HERO.武学与意境面板?.掌握武学||{}),source=JSON.stringify(DLH_INVENTORY.get(HERO,id)),scope=RT.generationScope(),message=RT.messageToken();
 openPop('<div class="inventory-gift"><h3>炼化 · '+esc(item.名称)+'</h3>'+(item.效用.成长.感悟?'<label>感悟承接武学<select id="item-growth-art"><option value="">请选择已学武学</option>'+names.map(n=>'<option value="'+esc(n)+'">'+esc(n)+'</option>').join('')+'</select></label>':'')+'<p>使用一份，收益在当前阶段结算，不自动冲关。</p><button type="button" id="item-growth-confirm">确认使用</button><p id="item-growth-status" role="status"></p></div>');
 $('#item-growth-confirm').onclick=async function(){this.disabled=true;const art=$('#item-growth-art')?.value;try{await RT.mutate(all=>{if(scope!==RT.generationScope()||message!==RT.messageToken()||source!==JSON.stringify(DLH_INVENTORY.get(all.stat_data.主角,id)))throw Error('物品或消息已变化，请重新选择');DLH_INVENTORY.use(all.stat_data,id,null,art);CHARACTER.recompute(all.stat_data.主角);});$('#pop-x').click();snap();renderGoods();toast('修行所得已结算');}catch(e){$('#item-growth-status').textContent=e.message;this.disabled=false;}};
}

/* Reuses the equipment/workshop shell and its existing keyboard and scroll stack. */
function renderJianxiangEntry(){
 let root=$('#jianxiang-entry');if(!DLH_JIANXIANG.known(HERO)){root?.remove();return;}
 if(!root){root=document.createElement('section');root.id='jianxiang-entry';root.className='gear-effects';$('#eq-on').parentElement.insertBefore(root,$('#eq-on'));}
 const g=DLH_JIANXIANG.bound(HERO);root.innerHTML='<h3>本命剑 · 剑相经</h3><p>'+esc(g?g.名称+' · '+g.评级+' · 附载 '+(HERO.剑相经?.附载剑法||'未选剑法'):'尚未绑定本命剑')+'</p><button type="button" class="inventory-action" id="jianxiang-open">绑定与温养</button>';root.querySelector('button').onclick=openJianxiang;
}
function openJianxiang(){
 const g=DLH_JIANXIANG.bound(HERO),s=g?.剑相养成,active=DLH_JIANXIANG.active(HERO),a=HERO.剑相经?.附载剑法||'',learned=HERO.武学与意境面板?.掌握武学||{};
 const choices=Object.keys(learned).filter(n=>n!=='剑相经'&&(DLH_WEAPONS.suitable(n,learned[n],ARTS)||[]).includes('剑')&&['外功','剑法','剑法外功'].includes(learned[n].类型||ARTS.arts[n]?.type));
 const swords=DLH_JIANXIANG.entries(HERO).filter(([slot,item])=>slot!=='本命剑'&&DLH_JIANXIANG.sword(item)).map(([slot,item])=>({from:'on',key:slot,item})).concat(Object.entries(HERO.装备栏?.装备库||{}).filter(([,item])=>DLH_JIANXIANG.sword(item)).map(([key,item])=>({from:'bag',key,item})));
 const disabled=inBattle()||!RT.isReady(),options=(rows,value)=>rows.map(n=>'<option value="'+esc(n)+'"'+(n===value?' selected':'')+'>'+esc(n)+'</option>').join('');
 openPop('<div class="crafting-workshop"><header class="craft-title"><div><h2>剑相经 · 本命剑</h2><p>以气养相，以剑伴身。</p></div><button type="button" id="jx-close">返回装备</button></header><p>'+esc(active?'已装配 · 剑器收益提高30%':'尚未装配剑相经，战斗能力与剑器加成暂不生效')+'</p>'+(g?'<section class="gear-effects"><h3>'+esc(g.名称)+' · '+esc(g.评级)+'</h3><p>'+esc(modifierText(DLH_JIANXIANG.fx(HERO,g)))+'</p><p>养剑积累 '+(s?.积累||0)+' · 累计 '+(s?.累计||0)+'；本命剑不占装备槽。</p><label>御使剑法<select id="jx-art"><option value="">暂不附载</option>'+options(choices,a)+'</select></label><button type="button" id="jx-attach">保存剑法</button><p>本命剑借用主人实时属性与增减益，独立调息、蓄势及剑法资源。内力和耐力由主人支付。主人每回合首次主动攻击有效命中积一层剑鸣，三层令下次御剑以完整威力释放。</p><button type="button" id="jx-warm">温养 · 2时辰 / 积累+10</button><button type="button" id="jx-promote">培养升品</button><button type="button" id="jx-reforge">精锻 · 本命剑同普通装备120%～150%</button><button type="button" id="jx-unbind">解除绑定，收入行囊</button></section><section class="gear-effects"><h3>养性 · 改定音</h3><p>'+esc(g.定音?DLH_EQUIPMENT.dingyinText(g.定音):'尚无定音')+'</p><p>每次消耗50养剑积累及2时辰，替换为一条现行定音；材料原文保留。</p><label>定音方向<select id="jx-term">'+options(DLH_EQUIPMENT.dingyinKeys,'特定武学技增伤')+'</select></label><label>数值<input type="number" id="jx-value" min="1" max="20" value="10"></label><label>属性<select id="jx-element">'+options(['雷','火','寒','毒','神魂'],'雷')+'</select></label><label>绑定武学<select id="jx-target-art">'+options(choices,a||choices[0])+'</select></label><button type="button" id="jx-retune">重养定音</button></section>':'<section class="gear-effects"><h3>选定一把真实拥有的剑</h3><p>绑定后从原位置取出，独立伴身；请先补全装备定义。</p>'+swords.map((x,i)=>'<button type="button" data-jx-bind="'+i+'">'+esc(x.item.名称+' · '+x.item.评级+' · '+(x.from==='bag'?'行囊':x.key))+'</button>').join('')+(!swords.length?'<p>暂无可绑定的剑。</p>':'')+'</section>')+'<p id="jx-status" role="status" tabindex="-1"></p></div>');
 $('#jx-close').onclick=()=>{$('#pop-x').click();renderEq();};
 const commit=fn=>{const scope=RT.generationScope(),message=RT.messageToken(),old=JSON.stringify(HERO.装备栏?.本命剑||null),request='剑相/'+Date.now()+'/'+Math.random().toString(36).slice(2);$('#pop-box').querySelectorAll('button').forEach(b=>b.disabled=true);
  RT.mutate(all=>{if(scope!==RT.generationScope()||message!==RT.messageToken()||old!==JSON.stringify(all.stat_data.主角.装备栏?.本命剑||null))throw Error('消息或本命剑已变化，请重新选择');fn(all.stat_data,request);CHARACTER.recompute(all.stat_data.主角);}).then(()=>{snap();renderEq();openJianxiang();$('#jx-status').textContent='已保存';},e=>{snap();openJianxiang();$('#jx-status').textContent=e.message;}).finally(()=>$('#jx-status')?.focus({preventScroll:true}));};
 $('#pop-box').querySelectorAll('[data-jx-bind]').forEach(b=>b.onclick=()=>{const x=swords[+b.dataset.jxBind],expected=JSON.stringify(x.item);commit((sd,id)=>{const item=x.from==='on'?sd.主角.装备栏[x.key]:sd.主角.装备栏.装备库[x.key];if(expected!==JSON.stringify(item))throw Error('剑器已变化，请重新选择');DLH_JIANXIANG.bind(sd,{from:x.from,key:x.key},id);});});
 if(g){$('#jx-attach').onclick=()=>{const n=$('#jx-art').value;commit((sd,id)=>DLH_JIANXIANG.attach(sd,n,id,ARTS));};$('#jx-warm').onclick=()=>commit((sd,id)=>DLH_JIANXIANG.warm(sd,null,id));$('#jx-promote').onclick=()=>commit((sd,id)=>DLH_JIANXIANG.promote(sd,null,id));$('#jx-unbind').onclick=()=>commit((sd,id)=>DLH_JIANXIANG.unbind(sd,null,id));$('#jx-reforge').onclick=()=>{openReforge();};$('#jx-retune').textContent='前往精锻定音';$('#jx-retune').onclick=()=>{openReforge();return;const t={词条:$('#jx-term').value,数值:Number($('#jx-value').value)};if(t.词条==='指定属性攻击增幅')t.属性=$('#jx-element').value;if(t.词条==='特定武学技增伤')t.武学=$('#jx-target-art').value;commit((sd,id)=>DLH_JIANXIANG.retune(sd,t,id));};}
 if(disabled)$('#pop-box').querySelectorAll('[data-jx-bind],#jx-attach,#jx-warm,#jx-promote,#jx-unbind,#jx-retune,#jx-reforge').forEach(b=>b.disabled=true);
}




/* ═══ 卷四·武学（装配 + 详情） ═══ */
var SLOT_LABEL={'nei':'内功位','heng':'横练位','qing':'轻功位','wai':'外功位一','wai2':'外功位二','qi':'奇门位'};
function loadout(){
  var s=slots(), L={nei:[],heng:[],qing:[],wai:[],wai2:[],qi:[]};
  Object.keys(SLOT_EN).forEach(function(k){ if(s[k]) L[SLOT_EN[k]]=[s[k]]; });
  return L;
}
function isEquipped(name){ var L=loadout(); return Object.keys(L).some(function(k){ return L[k].indexOf(name)>=0; }); }
function artInfoOf(name){
  var kn=known()[name]||{};
  var a=artDefinition(name);
  var lv=(kn['评级']||(a?a.lv:''))+' · '+(kn['熟练度']||'');
  var typ=kn['类型']||(a?a.type:'');
  return {lv:lv,type:typ,prof:kn['熟练度']||'皮毛',grade:kn['评级']||(a?a.lv:'三品'),fx:kn['特殊效果']||''};
}
function renderSlots2(){
  var L=loadout(), locked=inBattle();
  ['nei','heng','qing','wai','wai2','qi'].forEach(function(sk){
    var box=$('#eq-'+sk); if(!box) return; box.innerHTML='';
    if(!L[sk].length){
      var d=document.createElement('button');d.type='button'; d.className='al';d.disabled=locked;
      d.innerHTML='<span style="color:var(--dim2)">（空位）</span><span class="alv" style="color:var(--gold-d)">点击选配 →</span>';
      d.onclick=function(){ if(locked){toast('交战中 · 装配已锁定');return;} openPicker2(sk); };
      box.appendChild(d); return;
    }
    L[sk].forEach(function(nm){
      var inf=artInfoOf(nm);
      var d=document.createElement('div'); d.className='al';
      d.innerHTML='<button type="button" class="art-slot-open">'+esc(nm)+'</button><span class="alv">'+esc(inf.lv)+' · '+esc(inf.type)+'</span><button type="button" class="unEq" aria-label="卸下'+esc(nm)+'" data-tip="卸下 · 武学回库">卸</button>';
      const fit=DLH_WEAPONS.suitable(nm,known()[nm],ARTS),why=DLH_WEAPONS.reason(DLH_WEAPONS.kind(G(HERO,['装备栏','主武器'],{})),fit);if(fit){d.querySelector('.alv').textContent+=' · 适器：'+fit.join('／');if(why){d.classList.add('unavailable');d.title=why;}}
      d.onclick=function(){ openArt(nm); };
      d.querySelector('.unEq').disabled=locked;
      d.querySelector('.unEq').onclick=function(e){ e.stopPropagation(); if(inBattle()){toast('交战中 · 装配已锁定');return;} setSlotApi(SLOT_CN[sk],''); };
      box.appendChild(d);
    });
  });
  renderPlans2();
  renderArtOverview();
  $('#art-insight-open').textContent='当前真意：'+(zhenyiOn()||'未装配')+' · 查看感悟';
  var gl=$('#p2-main .goose .gl');
  if(gl) gl.textContent='当前装配 · 内功一 · 横练一 · 轻功一 · 外功二 · 奇门一';
}
function setSlotApi(slot,art){
  mutateVars(function(all){
    var hero=G(all,['stat_data','主角'],{}), zd=hero['战斗面板'];
    var learned=G(hero,['武学与意境面板','掌握武学'],{});
    if(!zd) throw new Error('尚无战斗面板');
    if(art&&(!learned[art]||!slotFits(learned[art]['类型'],slot))) throw new Error('武学不符合此槽位');
    if(!zd['槽位']) zd['槽位']={};
    if(art&&Object.keys(zd['槽位']).some(function(k){return k!==slot&&zd['槽位'][k]===art;}))throw new Error('同一武学不能重复装配');
    zd['槽位'][slot]=art;
  },function(){ toast(art?('已装配「'+art+'」'):'已卸下'); });
}
function openPicker2(sk){
  var kn=known(), cand=Object.keys(kn).filter(function(n){ return slotFits(kn[n]['类型'],SLOT_CN[sk])&&!isEquipped(n); });
  if(!cand.length){ toast('没有可归入'+SLOT_LABEL[sk]+'的武学'); return; }
  openArt(cand[0],SLOT_CN[sk]);
}
function moveRelations(m,tier,locked,fitReason,artName){
  const lines=[];
  if(locked)lines.push('熟练度达「'+tier+'」后可使用。');
  if(fitReason)lines.push(fitReason);
  if(m.followUp){const from=m.followUp.from||[];const src=from.map(x=>(x.art?x.art+'·':'')+x.move).join('、');
    lines.push('「'+src+'」'+(m.followUp.requireHit?'成功命中敌人后，':'施展后，')+(m.followUp.free?'本次行动内':m.followUp.windowRounds+'回合内')+'可使用'+(m.followUp.free?'，不占行动':'')+'。');}
  if(m.replaces)lines.push('满足条件时替代「'+m.replaces+'」。');
  const arts=m.requirements?.arts||[],sts=m.requirements?.statuses||[],rs=m.requirements?.resources||[];
  if(arts.length)lines.push('同场装配'+arts.map(r=>'「'+r.name+'」'+r.tier+'以上').join('、')+'后可使用。');
  if(sts.length)lines.push(sts.map(r=>(r.target==='self'?'自身':'敌方')+'「'+r.status+'」'+(r.stacks?r.stacks+'层以上':'')+'时').join('、')+'可使用。');
  if(rs.length){const resources=ART_REGISTRY.resolve(artName,known()[artName]).definition?.resources||[];
    lines.push(rs.map(r=>((resources.find(x=>x.id===r.id)?.name)||'本门资源')+' '+r.minimum+' 以上时').join('、')+'可使用。');}
  return lines.length?'<div class="move-relations">'+lines.map(t=>'<p>'+esc(t)+'</p>').join('')+'</div>':'';
}
var ART_DETAIL_FILTER=null,ART_DETAIL_NAME='',ART_DETAIL_MOVE='',ART_RETURN=null;
function openArt(name,filter){
  const enteringDetail=$('#p2-main').style.display!=='none';
  if(enteringDetail)ART_RETURN={scroll:$('#p2').scrollTop,trigger:ROOT.getRootNode().activeElement};
  const sameArt=ART_DETAIL_NAME===name;if(!sameArt)ART_DETAIL_MOVE='';ART_DETAIL_NAME=name;
  ART_DETAIL_FILTER=filter||null;
  $('#p2-main').style.display='none';
  $('#p2-detail').style.display='block';if(enteringDetail)$('#p2-back').focus({preventScroll:true});
  var kn=known();
  var al=$('#art-list'),listScroll=sameArt?al.scrollTop:0; al.innerHTML='';
  Object.keys(kn).filter(function(k){ return !filter||slotFits(kn[k]['类型'],filter); }).forEach(function(k){
    var d=document.createElement('button');d.type='button';
    d.className='al'+(k===name?' on':'');d.setAttribute('aria-pressed',String(k===name));
    d.innerHTML='<span>'+esc(k)+'</span><span class="alv">'+esc(kn[k]['熟练度']||'')+(isEquipped(k)?'':' · 在库')+'</span>';
    d.onclick=function(){ openArt(k,filter); };
    al.appendChild(d);
  });
  var inf=artInfoOf(name), a=artDefinition(name);
  const fit=DLH_WEAPONS.suitable(name,kn[name],ARTS),fitReason=DLH_WEAPONS.reason(DLH_WEAPONS.kind(G(HERO,['装备栏','主武器'],{})),fit);
  $('#ad-name').textContent=name;
  renderXingmingEntry(name);
  renderMastery(name);
  $('#ad-meta').textContent=inf.lv+' · '+inf.type+(isEquipped(name)?' · 已装配':' · 在库');
  if(fit)$('#ad-meta').textContent+=' · 适器 '+fit.join('／')+(fitReason?' · '+fitReason:'');
  var eb=$('#ad-equip');
  eb.disabled=inBattle();
  eb.textContent=isEquipped(name)?'卸下此功':'装配此功';
  eb.onclick=function(){
    if(inBattle()){toast('交战中 · 装配已锁定');return;}
    if(isEquipped(name)){ Object.keys(SLOT_EN).forEach(function(k){ if(slots()[k]===name) setSlotApi(k,''); }); }
    else {var target=filter||slotOf(inf.type);if(!filter&&target==='外功'&&slots().外功&&!slots().副外功)target='副外功';setSlotApi(target,name);}
  };
  /* 招式 */
  var mg=$('#ad-moves'); mg.innerHTML='';
  var mv=a?a.moves:[], prof=inf.prof, tiers=ARTS.tiers, upto=tiers.indexOf(prof); if(upto<0) upto=0;
  if(mv.length){
    mv.forEach(function(m,i){
      /* 习得判定：找该招所在档位 */
      var mt=tiers.length-1;
      for(var t=0;t<tiers.length;t++){ var u=a.unlock[tiers[t]]; var ns=u?(u.moves||u):[]; if(ns.indexOf(m.name)>=0){ mt=t; break; } }
      var locked=mt>upto||!!fitReason;
      var d=document.createElement('button');d.type='button';
      d.className='mdia'+(locked?' lock':'');d.setAttribute('aria-pressed','false');d.dataset.moveName=m.name;
      d.innerHTML='<div class="dc"><div class="mn3">'+esc(m.name)+'</div><div class="mk">'+esc([mt>upto?'未习得':'已习得',fitReason,m.followUp?(m.followUp.free?'派生 · 不占行动':'派生'):'',m.replaces?'变招':''].filter(Boolean).join(' · '))+'</div></div>';
      d.onclick=function(){
        ART_DETAIL_MOVE=m.name;
        mg.querySelectorAll('.mdia').forEach(function(x){x.classList.remove('on');x.setAttribute('aria-pressed','false');}); d.classList.add('on');d.setAttribute('aria-pressed','true');
        $('#ad-info').innerHTML='<div class="an">'+esc(m.name)+'<small>内力 '+(m.cost||0)+(m.cd?' · 调息 '+m.cd+' 回合':'')+(m.charge?' · 蓄势 '+m.charge+' 回合':'')+'</small></div><div class="ad">'+esc(m.desc||'')+'</div>'+moveRelations(m,tiers[mt],mt>upto,fitReason,name);
      };
      mg.appendChild(d);
    });
  }else{
    mg.innerHTML='<div style="font-size:11px;color:var(--dim);padding:10px 4px">'+(a?'本门无主动招式；装配后已习得的条目按各自条件生效。':'本门招式尚未录入，暂留原文说明。')+'</div>';
  }
  var nativeArt=ART_REGISTRY.resolve(name,kn[name]).native;
  var artSummary=nativeArt?(a.pos+' '+(inf.fx||'')):(a.pos||'')+' 本门可用招式 '+mv.length+' 式。'+modifierText(ART_REGISTRY.passivesFor(name,kn[name],HERO));
  $('#ad-info').innerHTML='<div class="an">'+esc(name)+'</div><div class="ad">'+esc(artSummary)+'</div>'+(a&&a.yuan?'<div class="ag2">渊源：'+esc(a.yuan)+'</div>':'');
  /* 签名 */
  var sg=$('#ad-sigs'); sg.innerHTML='';
  var sigs=unlockedSigs(name,prof);
  if(!sigs.length&&a&&a.sigs) sigs=a.sigs.map(function(s){return {name:s[0],desc:s[1],open:true};});
  var resolved=ART_REGISTRY.resolve(name,kn[name]);
  if(DLH_ART_PACKAGE.enabled(resolved.definition)||resolved.native&&resolved.metadata.bonuses)for(const b of (resolved.definition?.bonuses||resolved.metadata.bonuses))sigs.push({name:b.name,desc:DLH_ART_PACKAGE.bonusText(b,HERO)+' · '+(b.slot===1?'粗通':'入室')+'可习 · 装配后生效',open:tiers.indexOf(prof)>=(b.slot===1?1:3)});
  else if(!resolved.native)sigs.push({name:'常驻数值',desc:modifierText(ART_REGISTRY.passivesFor(name,kn[name],HERO)),open:true});
  sigs.forEach(function(s){
    var d=document.createElement('div'); d.className='al'; d.style.cursor='default';
    if(!s.open) d.classList.add('art-term-locked');
    d.innerHTML='<span style="color:var(--gold);white-space:nowrap">'+esc(s.name)+(s.open?'':' ·未醒')+'</span><span class="alv" style="margin-left:10px;text-align:left;flex:1;line-height:1.6">'+esc(DLH_PLAYER_COPY.signature(resolved.definition,s.name,s.desc).brief)+(DLH_PLAYER_COPY.signature(resolved.definition,s.name,s.desc).rules?'<details class="move-rules"><summary>详细规则</summary><p>'+esc(s.desc)+'</p></details>':'')+'</span>';
    sg.appendChild(d);
  });
  if(DLH_ART_PACKAGE.enabled(resolved.definition))for(const r of resolved.definition.resources){var row=document.createElement('div');row.className='al';row.textContent=r.name+'：上限'+r.maximum+'层，持续至战斗结束，'+({hit:'本门招式命中',cast:'本门招式释放',roundEnd:'每回合结束'})[r.gain.event]+'可获得'+r.gain.amount+'层。';sg.appendChild(row);}
  renderArtGenerationStatus();
  DLH_BLOOD_WHALE_UI.art(name);
  DLH_XIANLU_UI.art(name);
  if(DLH_GUANGHAN.names.includes(name)){const gh=inBattle()?battleEngine().guanghanView():HERO.战斗面板?.广寒派生;const node=document.createElement('p');node.className='ad';node.dataset.guanghan='';if(gh){const p=gh.projection||gh;node.textContent='额外内力 '+DLH_DISPLAY.number(p.extraMana||0)+(name==='开晦启明'?' · 明 '+(HERO.广寒真功?.明||0)+' · 已炼化 '+(p.ming||0)+' / '+(p.mingLimit||0):name==='炽心无改'?' · 心焰 '+(p.heart||0)+' / 10':' · 付费招式增伤 '+DLH_DISPLAY.percent(p.damageBonus||0));}else node.textContent='装配后生效';sg.appendChild(node);}
  al.scrollTop=listScroll;
  const chosen=Array.from(mg.querySelectorAll('button')).find(b=>b.dataset.moveName===ART_DETAIL_MOVE);if(chosen)chosen.click();
}
function renderZyi2(){
  var box=$('#eq-zy'); if(!box) return; box.innerHTML='';
  var ys=yis(), kn=Object.keys(ys), on=zhenyiOn();
  if(!kn.length){
    var d=document.createElement('div'); d.className='al'; d.style.cssText='cursor:default;opacity:.45';
    d.innerHTML='<span>（尚未悟意）</span><span class="alv">历练 · 观天地而悟</span>'; box.appendChild(d);
  }
  kn.forEach(function(nm){
    var isOn=on===nm, y=ys[nm]||{};
    var fx=DLH_DISPLAY.intent(y['境界']);
    var d=document.createElement('div'); d.className='al'+(isOn?' on':'');
    d.innerHTML='<button type="button" class="art-slot-open">'+esc(nm)+'</button><span class="alv">'+esc(fx)+'</span><button type="button" class="unEq" aria-label="'+(isOn?'卸下':'装配')+esc(nm)+'">'+(isOn?'撤':'装')+'</button>';
    d.querySelector('.unEq').disabled=inBattle();
    d.dataset.tip='参悟详情 · '+(isOn?'生效中，再点卸下':'点此装配')+(y['来源']?' · 出自'+y['来源']:'');
    d.onclick=function(){INSIGHT_YI=nm;renderInsightYi();};
    d.querySelector('.unEq').onclick=function(e){e.stopPropagation();
      if(inBattle()){toast('交战中 · 装配已锁定');return;}
      mutateVars(function(all){
        var wx=G(all,['stat_data','主角','武学与意境面板'],null);
        if(!wx||!G(wx,['领悟之意',nm],null)) throw new Error('此意已不在库中');
        if(wx.真意位!==nm&&!DLH_INTENT.resolve(nm,wx.领悟之意[nm])&&!DLH_INTENT.hasLegacy(wx.领悟之意[nm]))throw new Error('此意尚无战斗效果，请先完善三阶真意');
        wx['真意位']=wx['真意位']===nm?'':nm;
      },function(){ toast('真意位已更新'); });
    };
    box.appendChild(d);
  });
  const pending=Object.keys(HERO.感悟成长?.派生||{}).filter(n=>!ys[n]);
  pending.forEach(nm=>{const d=document.createElement('div');d.className='al';d.innerHTML='<span>'+esc(nm)+'</span><span class="alv">未悟 · 参悟记录</span>';d.onclick=function(){INSIGHT_YI=nm;renderInsightYi();};box.appendChild(d);});
}
function renderPlans2(){
  var box=$('#plans'); if(!box) return;
  box.querySelectorAll('.planchip').forEach(function(x){x.remove()});
  var plans=G(panel(),['方案库'],{});
  Object.keys(plans).forEach(function(nm){
    var c=document.createElement('span'); c.className='planchip';
    c.innerHTML=esc(nm)+'<i data-tip="删除此方案">×</i>';
    c.onclick=function(){
      if(inBattle()){toast('交战中 · 装配已锁定');return;}
      mutateVars(function(all){
      var zd=G(all,['stat_data','主角','战斗面板'],null); if(!zd||!zd['方案库']||!zd['方案库'][nm]) return;
      try{
        var snapD=JSON.parse(zd['方案库'][nm]);
        var learned=G(all,['stat_data','主角','武学与意境面板','掌握武学'],{}), next={};
        Object.keys(SLOT_EN).forEach(function(slot){
          var art=(snapD.slots||{})[slot]||'';
          if(art&&(!learned[art]||!slotFits(learned[art]['类型'],slot))) throw new Error('方案中的武学已不可装配：'+art);
          if(art&&Object.values(next).includes(art))throw new Error('方案重复装配同一武学：'+art);
          next[slot]=art;
        });
        zd['槽位']=next;
        var wx=G(all,['stat_data','主角','武学与意境面板'],null); if(wx) wx['真意位']=snapD.zhenyi||'';
        if(wx&&wx['真意位']&&!G(wx,['领悟之意',wx['真意位']],null)) throw new Error('方案中的真意已不在库中');
      }catch(e){ throw new Error(e.message||'方案数据坏了'); }
      },function(){ toast('已换上「'+nm+'」'); });
    };
    c.querySelector('i').onclick=function(e){
      e.stopPropagation();
      mutateVars(function(all){
      var zd=G(all,['stat_data','主角','战斗面板'],null); if(!zd||!zd['方案库']) return;
      delete zd['方案库'][nm];
      },function(){ toast('方案「'+nm+'」已删'); });
    };
    box.insertBefore(c,$('#plan-save'));
  });
}
function savePlan2(){
  if(inBattle()){toast('交战中 · 装配已锁定');return;}
  openPop('<div style="font-family:var(--serif);font-size:18px;color:var(--gold);letter-spacing:2px;font-weight:600;margin-bottom:8px">存为方案</div>'+
    '<input id="plan-name" placeholder="方案名 · 如：切磋案" maxlength="8" style="width:100%;background:rgba(0,0,0,.3);border:1px solid var(--line);color:var(--moon);padding:5px 9px;font-size:12.5px;border-radius:2px;margin-bottom:10px">'+
    '<div style="display:flex;gap:8px;justify-content:center"><button id="plan-ok">定</button></div>');
  $('#pop-box #plan-ok').onclick=function(){
    var nm=($('#pop-box #plan-name').value||'').trim()||('方案'+Object.keys(G(panel(),['方案库'],{})).length);
    mutateVars(function(all){
    var zd=G(all,['stat_data','主角','战斗面板'],null); if(!zd) return;
    if(!zd['方案库']) zd['方案库']={};
    zd['方案库'][nm]=JSON.stringify({slots:zd['槽位']||{},zhenyi:G(all,['stat_data','主角','武学与意境面板','真意位'],'')});
    },function(){ toast('方案「'+nm+'」已存'); $('#poplay').classList.remove('open'); });
  };
}

/* ═══ 卷五·战阵（实时战斗页） ═══ */
function chipHtml(nm,s,bad){
  return '<span class="tag '+(bad?'debuff':'buff')+'" data-tip="'+esc(nm)+(s['层数']>1?' '+s['层数']+'层':'')+(s.持续说明?' · '+s.持续说明:s['剩余回合']!=null?' · 剩余'+s['剩余回合']+'回合':'')+(s['来源']?' · 来源：'+esc(s['来源']):'')+'">'+esc(nm)+(s['层数']>1?' '+cn(s['层数'])+'层':'')+'</span>';
}
/* ═══ 卷六·归档 ═══ */
function renderArchive(){
  var bs=warState();
  var box=$('#p4');
  var old=box.querySelectorAll('.slot,.arc-detail,.arc-empty'); for(var i=0;i<old.length;i++) old[i].remove();
  if(bs['阶段']==='已结束'&&bs['结果']){
    var d=document.createElement('div'); d.className='slot';
    d.innerHTML='<span class="nm">上一战 <span class="arc">· 第 '+(bs['回合数']||'?')+' 回合终</span></span><span class="stamp w">结</span>';
    box.appendChild(d);
    var d2=document.createElement('div'); d2.className='arc-detail'; d2.textContent=bs['结果'];
    box.appendChild(d2);
  }else{
    var e2=document.createElement('div'); e2.className='arc-empty';
    e2.innerHTML='<div style="color:var(--dim2);font-size:12px;padding:14px 4px">尚无归档战报。往后的胜败，都记在这里。</div>';
    box.appendChild(e2);
  }
}

/* ═══ 卷七·天下 ═══ */
function renderWorld2(){
  renderInkMap();
  $('#p7-time').innerHTML='<div>'+esc(WORLD['当前时间']||'时辰未记')+' · '+esc(WORLD['当前地点']||'地界未记')+'</div>';
  var rm=G(WORLD,['江湖传闻'],{}), rk=Object.keys(rm);
  $('#p7-rumor').innerHTML=rk.map(function(k){
    return '<div data-tip="'+esc(rm[k])+'" style="cursor:default">'+esc(k)+'</div>';
  }).join('')||'<div style="color:var(--dim2)">风平浪静，尚无传闻。</div>';
}

/* ═══ 卷八·因果 ═══ */
/* Titles are display-only; stable record keys and original content stay intact. */
function dlhQuestDisplayTitle(key,value,kind,index){
 const han=/\p{Script=Han}/u,name=String(key||'').trim();
 if(han.test(name)&&!/^(?:clue|quest|task|lead|thread|rumor)[_-]/i.test(name))return name;
 const text=typeof value==='string'?value.trim().replace(/\s+/g,' '):'',start=text.search(han);
 if(start>=0){const first=text.slice(start>0&&/[【《「“]/u.test(text[start-1])?start-1:start).split(/[：:。！？；]/,1)[0].trim(),chars=Array.from(first);if(chars.length)return chars.slice(0,18).join('')+(chars.length>18?'…':'');}
 return (kind==='c'?'线索':'委托')+' '+index;
}
var qNow='w';
function renderQ2(){
  qa('#qtabs span').forEach(function(t){ t.classList.toggle('on',t.dataset.q===qNow); });
  var src={'w':G(HERO,['奇遇与目标','当前任务'],{}),'c':G(HERO,['奇遇与目标','奇遇线索'],{}),'s':null};
  var box=$('#qlist'); box.innerHTML='';
  if(qNow==='s'){
    var cur=PLOT['当前']||'';
    var done=G(PLOT,['已完成'],{});
    var h='<div class="qgrp">当前剧情</div>';
    if(cur) h+='<div class="qrow"><span class="qn2">'+esc(cur)+'</span></div>'+(typeof PLOT.进度?.[cur]==='string'?'<div style="color:var(--dim);font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere;padding:4px 8px">'+esc(PLOT.进度[cur])+'</div>':'');
    var dk=Array.isArray(done)?done:Object.keys(done);
    if(dk.length) h+='<div class="qgrp">已了结 '+dk.length+' 桩</div>'+dk.map(function(k){ return '<div class="qrow" style="opacity:.6;flex-wrap:wrap"><span class="qn2">'+esc(k)+'</span><span style="font-size:10px;color:var(--dim);flex-basis:100%;white-space:pre-wrap;overflow-wrap:anywhere">'+esc(PLOT.进度?.[k]||(Array.isArray(done)?'':String(done[k]).slice(0,40)))+'</span></div>'; }).join('');
    if(!cur&&!dk.length) h+='<div style="color:var(--dim2);font-size:12px;padding:8px 4px">尚无剧情线。</div>';
    box.innerHTML=h; return;
  }
  var dict=src[qNow]||{}, names=Object.keys(dict);
  var g=document.createElement('div'); g.className='qgrp';
  g.textContent=(qNow==='w'?'手上有 '+names.length+' 桩委托':'记下 '+names.length+' 条线索'); box.appendChild(g);
  if(!names.length){ var e=document.createElement('div'); e.style.cssText='color:var(--dim2);font-size:12px;padding:8px 4px'; e.textContent='眼下没有。'; box.appendChild(e); return; }
  names.forEach(function(nm,index){
    var title=dlhQuestDisplayTitle(nm,dict[nm],qNow,index+1);
    var d=document.createElement('div'); d.className='qrow';
    d.innerHTML='<span class="qn2">'+esc(title)+'</span><span style="font-size:10px;color:var(--dim)">'+esc(String(dict[nm]).slice(0,30))+'</span>';
    d.onclick=function(){ openPop('<div style="font-family:var(--serif);font-size:20px;color:var(--gold);letter-spacing:2px;font-weight:600">'+esc(title)+'</div><div style="font-size:12px;color:var(--moon);line-height:2;margin-top:8px">'+esc(String(dict[nm]))+'</div>'); };
    box.appendChild(d);
  });
  $('#gl-q').textContent='委托 '+cn(Object.keys(src.w||{}).length)+' · 线索 '+cn(Object.keys(src.c||{}).length);
}

