  q('.qf-name-grid').innerHTML=visible.map(r=>'<button type="button" class="qf-person" data-qf-name="'+esc(r.name)+'" data-met="'+r.met+'" '+(!r.canView?'disabled':'')+'><strong>'+esc(r.name)+'</strong><small>'+esc(r.region)+' · '+(r.met?'已结识':r.canView&&!r.viewed?'初始立绘可看':'尚未结识')+(r.met&&!r.hasImage?' · 暂无立绘':'')+'</small></button>').join('')||'<p class="qf-empty">没有符合条件的人物，请调整地区或筛选。</p>';
