   defenseProc:()=>`${on}后，${(t.effects||[]).map(fx=>({heal:'回复气血',restoreQi:'回复护体真气',restoreNeili:'回复内力',dodge:'获得闪避判定',block:'获得格挡判定',cleanse:'净化普通负面状态'})[fx.kind]+(['heal','restoreQi','restoreNeili'].includes(fx.kind)?(fx.ratio?pct(fx.ratio)+'上限':n(fx.amount)):['dodge','block'].includes(fx.kind)?fx.stacks+'层':'')).join('、')}；每回合最多${r.perRound}次。`,
   negation:()=>`${context.charges!=null?'':opening+'开启'+r.turns+'回合防护；'}${r.channels.map(k=>channel[k]||'持续').join('／')}伤害无效，${context.charges!=null?'剩余':'可抵御'}${context.charges??r.charges}次。`,
   rescueWindow:()=>`${context.charges!=null?'':opening+'开启'+r.turns+'回合守护；'}${r.mode==='rollback'?'回退窗口内损失的气血与新增负面状态':'致命伤害时保留生机'}，${context.charges!=null?'剩余':'可触发'}${context.charges??r.charges}次。`,
   dotDefense:()=>`减轻${r.statuses.length?r.statuses.map(s=>'【'+s+'】').join('／'):'持续'}伤害${pct(r.ratio)}。`,
   conditionalGuard:()=>`${resource[r.resource]}在${pct(r.minRatio)}～${pct(r.maxRatio)}时，减轻${channel[r.channel]}伤害${pct(r.ratio)}。`,
   comboAdapt:()=>`连续承受同一攻击者的整招后，逐招加强${channel[r.channel]}防护，最多减轻${pct(r.capRatio)}伤害；一招内各段共用同一减伤快照。`,
   aftershockGuard:()=>`单招损血达到最大气血的${pct(r.minimumLoss)}后，减轻下一次${channel[r.channel]}伤害${pct(r.ratio)}。`,
   healingReceived:()=>`${r.gate==='medicine'?'医术达到'+r.minimumMedicine:'处于【润物】状态'}时，所受武学治疗提高${pct(r.ratio)}。`,
   capacity:()=>`已学至${r.minimumTier}的横练可提高气血上限，最多${pct(r.capRatio)}。`,
   resistance:()=>r.mode==='dot'?`减轻【${r.status}】持续伤害${pct(r.ratio)}。`:`新受到的【${r.status}】缩短1回合，至少保留1回合。`,
   pressureReserve:()=>`单招损血达到最大气血的${pct(r.minimumLoss)}后，获得1点本门资源；每回合最多${r.perRound}次。`,
   defenseShift:()=>`主动格挡期间，额外获得相当于自身${channel[r.from]}防御${pct(r.ratio)}的${channel[r.from==='external'?'qi':'external']}防御，保留原防御。`,
