 function window(a,t,w){const d={moves:a.customMoves||[],mechanisms:a.packageTerms||[],resources:a.packageResourceDefs||[]};return d.mechanisms.filter(x=>x.trigger==='light'&&x.light?.stateId===t.id&&a.tier>=['皮毛','粗通','登堂','入室','圆满'].indexOf(x.tier)).map(x=>term(x,d,{active:true,spent:w.spent,targetName:w.targetName})).filter(Boolean).join('\n');}
