 function signature(d,name,original){const t=d?.mechanisms?.find(t=>t.name===name);if(t?.trigger==='inner'&&typeof DLH_INNER_RULES!=='undefined'&&DLH_INNER_RULES.details)return {brief:DLH_INNER_RULES.describe(t,d),rules:DLH_INNER_RULES.details(t,d)};if(t?.trigger==='qimen'&&typeof DLH_QIMEN_RULES!=='undefined'&&DLH_QIMEN_RULES.details)return {brief:DLH_QIMEN_RULES.describe(t,d),rules:DLH_QIMEN_RULES.details(t,d)};const brief=term(t,d);return brief?{brief,rules:original}:{brief:original,rules:''};}
