    var statuses=(f.statuses||[]).map(function(s){return {name:playerText(s.label||s.name),template:s.name,label:s.label||'',stacks:s.stacks||1,turns:s.cycleKind==='dream'||s.jiemaiSilk?null:s.jiemaiSeal?Math.max(0,s.expires-currentRound+1):s.turns,source:s.src||'',buff:typeof s.buff==='boolean'?s.buff:undefined,description:s.description||s.desc||'',lifetime:s.lifetime||'',neipanCost:!!s.neipanCost};});
