    if(f.guanghanV1){const s=f.guanghanV1,p=s.applied;if(s.tiers[1]>=0&&s.heart)statuses.push({name:'心焰 · '+s.heart+'/10',template:'心焰',stacks:s.heart,turns:null,source:'炽心无改',buff:true,lifetime:'combat'});if(s.tiers[2]>=0){if(s.hui)statuses.push({name:'晦 · 待发',template:'晦',stacks:1,turns:null,source:'开晦启明',buff:true,lifetime:'combat'});if(p.ming)statuses.push({name:'明 · 已炼化 '+p.ming+'/'+p.mingLimit,template:'明',stacks:p.ming,turns:null,source:'开晦启明',buff:true,lifetime:'combat'});}}
    const specialRows=[];for(const[art,a]of Object.entries(f.arts||{}))for(const t of a.packageTerms||[])if(t.trigger==='special'&&a.tier>=['皮毛','粗通','登堂','入室','圆满'].indexOf(t.tier))specialRows.push({t,key:art+'::'+t.id,source:a.name});if(f.intentV1)for(const t of f.intentV1.definition.terms)if(t.special&&t.tier<=f.intentV1.tier)specialRows.push({t,key:'intent:'+f.intentV1.name+'::'+t.id,source:f.intentV1.name});
    for(const {t,key,source}of specialRows){const s=f.specialAbilitiesV1?.terms[key],r=t.special;let suffix='',turns=null;if(r.kind==='revival')suffix=f.specialAbilitiesV1?.revived?'本场已用':'本场可用';else if(r.kind==='ward'&&s?.until>=currentRound&&s.pool>0){suffix='余量 '+DLH_DISPLAY.number(s.pool);turns=s.until-currentRound+1;}else if(r.kind==='form'&&s?.until>=currentRound){suffix='生效中';turns=s.until-currentRound+1;}else if(r.kind==='observation'&&Object.keys(s?.observed||{}).length)suffix='已观察 '+Object.keys(s.observed).length+' 项';if(suffix)statuses.push({name:t.name+' · '+suffix,stacks:1,turns,source,buff:true,description:DLH_SPECIAL_ABILITIES.describe(t)});}
