    if(f.arts?.jian&&f.jian){const s=f.jian;statuses.push({name:'剑气 '+s.qi+'/100',stacks:1,turns:null,source:'剑髓经'},{name:'化剑 '+s.form+'/8',stacks:1,turns:null,source:'剑髓经'});if(s.flower&&s.flowerUntil>=currentRound)statuses.push({name:'剑花',stacks:s.flower,turns:s.flowerUntil-currentRound+1,source:'剑髓经'});if(s.qiUntil>=currentRound)statuses.push({name:'神真见独',stacks:1,turns:s.qiUntil-currentRound+1,source:'剑髓经'});if(s.formUntil>=currentRound)statuses.push({name:'无我无剑状态',stacks:1,turns:s.formUntil-currentRound+1,source:'剑髓经'});if(s.seal)statuses.push({name:'用晦而明',stacks:1,turns:null,source:'剑髓经'});if(f.as?.wj)statuses.push({name:'万剑化一',stacks:f.as.wj,turns:null,source:'剑髓经'});}
    if(f.innate){const s=f.innate;if(f.arts?.jiuxiao){statuses.push({name:'荡魔 '+s.storm.dm+'/3',stacks:1,turns:null,source:'九霄雷诀'});if(s.storm.field&&s.storm.domainUntil>=currentRound)statuses.push({name:s.storm.field.gathered?'聚雷域·感应天雷':'雷域·感应天雷',stacks:1,turns:s.storm.domainUntil-currentRound+1,source:'九霄雷诀'});}if(f.arts?.yunlong){statuses.push({name:'虚影 '+s.cloud.xy+'/6',stacks:1,turns:null,source:'云龙九现'},{name:'照现 '+s.cloud.zx+'/9',stacks:1,turns:null,source:'云龙九现'});if(s.cloud.shadow)statuses.push({name:'待发影招 · '+s.cloud.shadow.move.name,stacks:1,turns:null,source:'云龙九现'});if(s.cloud.body)statuses.push({name:'龙隐虚身',stacks:1,turns:null,source:'云龙九现'});}}
