   return [{id:after.runId+':hp:'+a.length+':'+b.length+':'+f.groupId,personId:f.groupId,name:f.name,before:from,after:to,beforeMax:Math.max(1,Math.round(prev.hpMax)),afterMax:Math.max(1,Math.round(f.hpMax)),delta,kind:delta>0?'heal':'damage'}];
