  const env=view.environment,dream=env?.梦境;var environmentText=env?'天气 '+env.天气+' · '+env.地貌+(env.地形.length?' · '+env.地形.map(s=>s.种类).join('、'):'')+(dream?' · '+dream.种类+' · '+dream.景象+' · 余 '+Math.max(0,dream.持续至-view.round+1)+' 回合':''):'';
  $('#battle-threat').textContent=[view.dream?.text|| (view.pendingAction?(view.participantsById[view.pendingAction.sourceId]?.name||'敌方')+'将施展「'+view.pendingAction.name+'」→ '+view.pendingAction.targetIds.map(function(id){return view.participantsById[id]?.name||'未知目标';}).join('、'):''),].filter(Boolean).join('；');
