  $('#battle-threat').hidden=!$('#battle-threat').textContent;renderBattleParticipants(view);renderWarDomain(view);DLH_BATTLE_SYSTEMS.environment(view);renderBattleMoves(view);renderBattleLogs();restoreBattleFocus(token);if(enteringDream)$('#wb-mvs .dream-response:not([aria-disabled="true"])')?.focus();
  $('#wbpv-ok').disabled=BATTLE_BUSY||!!ARMED&&!!DLH_BATTLE_VIEW.validate(view,ARMED);renderOrb();
