function actionReason(art,move){
  if(!RT.isReady())return '变量尚未连接';
  var view=DLH_BATTLE_VIEW.from(battleData(),ARTS),m=view.moves.concat(view.generic).find(function(x){return x.name===move.name&&x.art===art;})||view.generic.find(function(x){return x.name===move.name;});
  return m?m.reason:view.error||'当前没有可执行的动作';
}
function disarmMove(){
  var key=ARMED?.key;ARMED=null;$('.battle-controls').classList.remove('has-preview');$('#wb-pv').classList.remove('open');
  qa('.wb-mv.armed').forEach(function(b){b.classList.remove('armed');b.setAttribute('aria-pressed','false');});
  if(BATTLE_VIEW?.teams)renderBattleParticipants(BATTLE_VIEW);
  if(key)restoreBattleFocus({kind:'move',value:key});
}
function armMove(button,art,move){
  stopBattleAuto();
  snap();var view=DLH_BATTLE_VIEW.from(battleData(),ARTS),actual=view.moves.concat(view.generic).find(function(m){return m.key===move.key;});
  if(!actual||actual.reason){toast(actual?.reason||'战况已变化，请重新选择');return;}
  disarmMove();ARMED={battleId:view.battleId,checkpoint:view.checkpoint,context:battleContext(),key:actual.key,targetIds:DLH_BATTLE_TARGETS.initial(view,actual),art:actual.art,name:actual.name,moveKey:actual.generic?undefined:actual.key};button.classList.add('armed');button.setAttribute('aria-pressed','true');
  renderBattleParticipants(view);renderArmedBattlePreview(view);
  $('.battle-controls').classList.add('has-preview');$('#wb-pv').classList.add('open');$('#wbpv-ok').textContent=view.phase==='dreamReaction'?'确认应对':view.phase==='reaction'?'确认应变':'确认出招';
}
function renderArmedBattlePreview(view){
 if(!ARMED)return;const actual=view.moves.concat(view.generic).find(m=>m.key===ARMED.key);if(!actual)return;
 const p=DLH_BATTLE_SYSTEMS.preview(view,actual,ARMED),names=ARMED.targetIds.map(id=>view.participantsById[id]?.name||'未知目标');$('#wbpv-n').textContent=(actual.variantText?(actual.displayName||actual.name):actual.name)+(names.length?' · '+names.join('、'):'');
 const cost='内力 '+(p.cost||0)+(p.nai?' · 耐力 '+p.nai:'')+(p.cd?' · 调息 '+p.cd+' 回合':'')+(p.charge?' · 蓄势 '+p.charge+' 回合':'');
 const targetHint=actual.targetPolicy?.team==='ally'?DLH_BATTLE_TARGETS.label(actual)+'\n':'',selectionError=DLH_BATTLE_VIEW.validate(view,ARMED);
 const hint=targetHint+DLH_BATTLE_SYSTEMS.hint(actual,p)+(selectionError?'\n'+selectionError:''),resource=p.resourceText&&!p.contextHint?p.resourceText+'\n':'';
 $('#wbpv-d').textContent=(actual.variantText?actual.variantText+'\n':'')+cost+'\n'+resource+hint+(p.fallback?'\n内力不足，此次只施展外功部分。':'');$('#wbpv-ok').disabled=BATTLE_BUSY||!!DLH_BATTLE_VIEW.validate(view,ARMED);
}

async function strikeMove(){
  if(!ARMED||BATTLE_BUSY)return;var picked=ARMED;
  await RT.refresh();snap();var why=battleContextReason(picked.context)||DLH_BATTLE_VIEW.validate(DLH_BATTLE_VIEW.from(battleData(),ARTS),picked);disarmMove();if(why){toast(why);return;}
  await localBattleAction({art:picked.art,name:picked.name,moveKey:picked.moveKey,targetIds:picked.targetIds.slice()},picked.checkpoint,picked.context);
}
async function doGeneric(name){
  stopBattleAuto();
  if(BATTLE_BUSY)return;
  snap();var view=DLH_BATTLE_VIEW.from(battleData(),ARTS),move=view.generic.find(function(m){return m.name===name;});
  if(!move||move.reason){toast(move?.reason||view.error||'当前没有可执行的动作');return;}
  if(view.group&&name==='普攻'){armMove(Array.from(qa('[data-action]')).find(b=>b.dataset.action===name),'',move);return;}
  disarmMove();if(name==='服药'){chooseMedicine();return;}if(name==='切换武器'){chooseWeapon();return;}
  await localBattleAction({name:name},view.checkpoint,battleContext());
}
function bindBattleView(){DLH_BATTLE_SYSTEMS.init();
  $('#battle-auto').onclick=toggleBattleAuto;RT.onDispose(stopBattleAuto);
  RT.onDispose(()=>BATTLE_VOID_FX?.dispose());
  const exit=document.createElement('button');exit.id='trial-war-exit';exit.textContent='退出侠境';exit.hidden=true;exit.onclick=requestLeaveTrialWar;$('#wb-menu').before(exit);
 DLH_STAGE_UI.init();
  DLH_ULTIMATE_UI.init();
  $('#wb-menu').onclick=function(event){event.stopPropagation();collapseBattleView();$('#menu').classList.add('open');RT.positionMenu($('#menu'),$('#orb'));$('#menu [data-p="p1"]').focus();};
  $('#wb-x').onclick=collapseBattleView;$('#wbpv-ok').onclick=strikeMove;$('#wbpv-no').onclick=disarmMove;
  $('#battle-log-more').onclick=function(){BATTLE_LOG_LIMIT+=60;renderBattleLogs();BATTLE_RENDER_SIGNATURE=battleRenderSignature(BATTLE_VIEW);};
  // A confirming double click must not hit a newly revealed end-action button.
  qa('.gn2,.weapon-switch').forEach(function(b){b.onclick=function(event){if(event?.detail>1)return;doGeneric(b.dataset.action);};});
  /* Full-screen battle stage has fixed safe margins. */
}

/* One scheduled input at a time. Autoplay is session-local and stops on any
 * context change; it cannot silently resume after reload or closing the stage. */
var BATTLE_AUTO=null,BATTLE_AUTO_TIMER=null,BATTLE_AUTO_STEP=false;
function stopBattleAuto(){BATTLE_AUTO=null;if(BATTLE_AUTO_TIMER!==null){RT.clearTimeout(BATTLE_AUTO_TIMER);BATTLE_AUTO_TIMER=null;}const b=$('#battle-auto');if(b){b.textContent='自动战斗';b.setAttribute('aria-pressed','false');}}
function toggleBattleAuto(){
 if(BATTLE_AUTO){stopBattleAuto();return;}
 const v=DLH_BATTLE_VIEW.from(battleData(),ARTS);if(BATTLE_BUSY||!RT.isReady()||!['player','finish','reaction','dreamReaction'].includes(v.phase)){toast('请等待战斗准备完成');return;}
 disarmMove();BATTLE_AUTO={context:battleContext(),id:v.battleId,steps:0};renderBattleAuto(v);
}
function renderBattleAuto(view){
 const b=$('#battle-auto');if(!b)return;
 if(BATTLE_AUTO&&(battleContextReason(BATTLE_AUTO.context)||!anyWarViewOpen()||view.battleId!==BATTLE_AUTO.id||!['player','finish','reaction','dreamReaction'].includes(view.phase)))stopBattleAuto();
 b.disabled=!BATTLE_AUTO&&(BATTLE_BUSY||!['player','finish','reaction','dreamReaction'].includes(view.phase));b.textContent=BATTLE_AUTO?'暂停自动':'自动战斗';b.setAttribute('aria-pressed',String(!!BATTLE_AUTO));
 if(!BATTLE_AUTO||BATTLE_BUSY||BATTLE_AUTO_STEP||BATTLE_AUTO_TIMER!==null)return;
 const session=BATTLE_AUTO,checkpoint=view.checkpoint;
 BATTLE_AUTO_TIMER=RT.timeout(async function(){
  BATTLE_AUTO_TIMER=null;if(BATTLE_AUTO!==session)return;BATTLE_AUTO_STEP=true;
  try{
   await RT.refresh();snap();if(BATTLE_AUTO!==session)return;
   if(battleContextReason(session.context)||warState().引擎存档!==checkpoint||!anyWarViewOpen()){stopBattleAuto();return;}
   if(++session.steps>1200){stopBattleAuto();toast('交锋持续较久，自动战斗已暂停，请检查战况');return;}
   const engine=battleReadEngine(JSON.parse(checkpoint),ARTS,battleData()),a=engine.autoAction();
   if(!a){stopBattleAuto();toast('没有可执行的自动行动，请手动选择');return;}
   if(BATTLE_AUTO!==session)return;
   if(!await localBattleAction(a,checkpoint,session.context,session))stopBattleAuto();
  }catch(e){stopBattleAuto();toast('自动战斗已暂停：'+(e.message||'请检查战况'));}
  finally{BATTLE_AUTO_STEP=false;if(BATTLE_AUTO===session)renderWarViews();}
 },700);
}


/* ═══ 弹层 ═══ */
/* Shared popup controls; visual effects must never prevent dismissal. */
var POPUP_VIEWPORT_FIT=null;
function installPopupSafety(){
 const style=RT.host.document.createElement('style');
 style.textContent=`
 #dlhud-root #poplay .pop-x{min-width:44px;min-height:44px;touch-action:manipulation}
 #dlhud-root #poplay:not(.courtyard-care):not(.courtyard-information) .pop-box:not(.map-dialog):not(:has(.rc-page,.crafting-workshop))>.pop-x{
   position:sticky;float:right;top:0;right:0;width:44px;height:44px;margin:-8px -6px 0 6px;padding:0;z-index:100;
   background:var(--bg,#191a17);color:var(--moon,#e3e1d5);border:1px solid var(--gold-d,#766847);border-radius:2px;
 }
 #dlhud-root #poplay .pop-x:focus-visible{outline:2px solid var(--gold,#bca26c);outline-offset:2px}
 `;
 ROOT.getRootNode().appendChild(style);RT.onDispose(()=>style.remove());
 const layer=$('#poplay'),box=$('#pop-box'),host=RT.host;let backdropPress=false,frame=0;
 function fit(){
  if(!layer.classList.contains('open'))return;
  const v=host.visualViewport,left=v&&Number.isFinite(v.offsetLeft)?v.offsetLeft:0,top=v&&Number.isFinite(v.offsetTop)?v.offsetTop:0,width=v?.width>0?v.width:host.innerWidth,height=v?.height>0?v.height:host.innerHeight;
  Object.assign(layer.style,{position:'fixed',inset:'auto',left:left+'px',top:top+'px',width:width+'px',height:height+'px',boxSizing:'border-box',padding:'8px',overflow:'hidden',contain:'layout'});
  /* Account for a translated/scrolled fixed containing block in host themes. */
  const bounds=layer.getBoundingClientRect();layer.style.left=(left+(left-bounds.left))+'px';layer.style.top=(top+(top-bounds.top))+'px';
  layer.style.setProperty('--dlh-popup-height',height+'px');
  box.style.maxWidth=Math.max(44,width-16)+'px';box.style.maxHeight=Math.max(44,height-16)+'px';
 }
 function schedule(){if(frame)return;frame=host.requestAnimationFrame(()=>{frame=0;fit();});}
 POPUP_VIEWPORT_FIT=fit;
 RT.listen(host,'resize',schedule);RT.listen(host,'scroll',schedule,{passive:true});
 if(host.visualViewport){RT.listen(host.visualViewport,'resize',schedule);RT.listen(host.visualViewport,'scroll',schedule);}
 RT.onDispose(()=>{if(frame)host.cancelAnimationFrame(frame);POPUP_VIEWPORT_FIT=null;});
 RT.listen(layer,'pointerdown',e=>{backdropPress=e.target===layer;});
 RT.listen(layer,'pointercancel',()=>{backdropPress=false;});
 RT.listen(layer,'click',e=>{const dismiss=backdropPress&&e.target===layer;backdropPress=false;if(dismiss&&layer.classList.contains('open'))$('#pop-x')?.click();});
}

var UI_POP_TRIGGER=null;
function openPop(html){$('#poplay').classList.remove('courtyard-care','courtyard-information');
  closeInventoryFloat(false);
  const wasOpen=$('#poplay').classList.contains('open');let previousFocus=ROOT.getRootNode().activeElement;while(previousFocus?.shadowRoot?.activeElement)previousFocus=previousFocus.shadowRoot.activeElement;const focusId=previousFocus&&previousFocus.id;
  if(!wasOpen)UI_POP_TRIGGER=previousFocus;const popTrigger=UI_POP_TRIGGER;
  $('#pop-box').classList.remove('map-dialog');$('#pop-box').onkeydown=null;
  var tip=ROOT.querySelector('.tip');if(tip)tip.style.opacity=0;
  $('#pop-box').innerHTML='<button type="button" class="pop-x" id="pop-x" aria-label="关闭详情">✕</button>'+html;
  $('#poplay').classList.add('open');POPUP_VIEWPORT_FIT?.();
  $('#pop-box').setAttribute('role','dialog');$('#pop-box').setAttribute('aria-modal','true');$('#pop-box').setAttribute('aria-label','详情');
  $('#pop-x').onclick=function(){ departSurface($('#pop-box'));$('#poplay').classList.remove('open');if(!$('#hud').classList.contains('open')&&!anyWarViewOpen()&&!COURTYARD_UI?.active)showMenu();else restoreScenicPopupFocus(popTrigger); };
  if(!wasOpen)$('#pop-x').focus();else if(focusId&&$('#'+focusId))$('#'+focusId).focus({preventScroll:true});
  $('#pop-box').onkeydown=function(e){if(e.key!=='Tab')return;const nodes=Array.from(this.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),summary,[tabindex="0"]')).filter(x=>x.getClientRects().length);const current=ROOT.getRootNode().activeElement;if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&current===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&current===last){e.preventDefault();first.focus();}};
  if($('#pop-box .character-attribute-popup')){
    const trigger=popTrigger;
    $('#pop-box').setAttribute('role','dialog');$('#pop-box').setAttribute('aria-modal','true');$('#pop-box').setAttribute('aria-label','属性详情');
    $('#pop-x').onclick=function(){ $('#poplay').classList.remove('open');const back=trigger&&trigger.isConnected?trigger:$('#attr-list .al.on');if(back)back.focus(); };
    $('#pop-x').onkeydown=function(e){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();this.click();}if(e.key==='Tab'){e.preventDefault();this.focus();}};
    $('#pop-x').focus();
  }
}

/* ═══ 总刷新 ═══ */
function renderFromCache(){
  snap();WUMU?.observe(V);refreshTravel();refreshCompanionIntentDetail();refreshSocialNpc();COMPANION_ART_GENERATOR.check(); ensureCharacter();syncXingmingObservatory();
  recoverNarrativeBattleStart();
  if(COMPLETION_BATCH.busy()&&inBattle())COMPLETION_BATCH.cancel('已进入战斗，批量补全已停止');
  var p=panel(),base=p.基础属性||{};
  var missingBase=RT.isReady()&&num(G(p,['基础上限','最大气血'],0))>0&&
    !(num(base.最大外功攻击)>0||num(base.最大真气攻击)>0||num(base.真气攻击)>0)&&num(G(p,['生效属性','最大外功攻击'],0))<=0;
  if(missingBase&&!BASE_WARNED){BASE_WARNED=true;toast('面板尚未建立：请先确认当前武道境界。');}
  if(!missingBase)BASE_WARNED=false;
  renderOrb();
  renderNarrativeHandoff();
  syncMenuState();
  renderTitle();
  if($('#hud').classList.contains('open')){
    var cur=qa('.page.on')[0];
    var pid=cur?cur.id:null;
    if(pid==='p1') renderP1();
    else if(pid==='p5') renderEq();
    else if(pid==='p6') renderGoods();
    else if(pid==='p2'){ renderSlots2(); if($('#p2-detail').style.display==='block'){ var nm=$('#ad-name').textContent; if(nm&&known()[nm]) openArt(nm,ART_DETAIL_FILTER);else {$('#p2-detail').style.display='none';$('#p2-main').style.display='block';} } }
    else if(pid==='p13') renderInsightPage();
    else if(pid==='p4') renderArchive();
    else if(pid==='p7') renderWorld2();
    else if(pid==='p8') renderQ2();
    else if(pid==='p9') renderWho2();
    else if(pid==='p16') renderQunfangNative();
    else if(pid==='p15') renderIndustry();
    else if(pid==='p14') renderCompanions();
    else if(pid==='p10') renderPets2();
    else if(pid==='p11') renderCrafts2();
  }
  if(!CRAFT_VIEW.busy&&$('#poplay').classList.contains('open')&&$('#pop-box .crafting-workshop'))renderCraftingPopup();
  if(LINGMU_VIEW.open&&$('#poplay').classList.contains('open')&&$('#pop-box .lm-workshop'))renderLingmu();
  if(SCENIC_UI){if($('#hud').classList.contains('open')&&['p2','p13'].includes(UI_PAGE))SCENIC_UI.open(UI_PAGE);else SCENIC_UI.close();COURTYARD_UI.refresh();}
  renderWarViews();
  refreshCalendar();
  renderCultivation();refreshCultivation();
  updateArtSettings();renderCompletionBatch();scheduleCalendarSync();scheduleArtGeneration();syncInsightMotion();
  if(SCENIC_UI){scenicNumbers($('#p1 .character-identity'));scenicNumbers($('#titlebar'));}
}
function refresh(){ renderFromCache(); return RT.refresh(); }

