 const style=doc.createElement('style');style.textContent=`
 .dlh-void-stage{position:relative;isolation:isolate;overflow:hidden;min-height:260px}
 .dlh-void-fx{position:absolute;inset:0;z-index:3;overflow:hidden;pointer-events:none!important;contain:paint;background:#020409;opacity:0;transition:opacity .45s ease}
 .dlh-void-fx[data-visible="true"]{opacity:1}
 .dlh-void-fx[hidden]{display:none}
 .dlh-void-fx *{pointer-events:none!important}
 .dlh-void-plate{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;opacity:.82;filter:brightness(.72);transform:scale(1)}
 .dlh-void-fx[data-phase="opening"] .dlh-void-plate{animation:dlhVoidOpen 2.8s cubic-bezier(.16,.7,.25,1) both}
 .dlh-void-fx:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,#02040975,transparent 32%);pointer-events:none}
 .dlh-void-caption{position:absolute;z-index:1;bottom:14px;left:24px;right:24px;text-align:right;text-shadow:0 2px 9px #000;color:#e4e7e8;letter-spacing:.2em;font:400 clamp(18px,3vw,30px)/1.4 var(--dlh-font-title,KaiTi,serif)}
 .dlh-void-caption small{display:block;margin-top:5px;letter-spacing:.12em;font:400 12px/1.6 var(--dlh-font-body,SimSun,serif);color:#bbc2c8}
 .dlh-void-fx[data-phase="opening"] .dlh-void-caption{animation:dlhVoidTitle 2.8s ease both}
 @keyframes dlhVoidOpen{0%{transform:scale(.64);clip-path:circle(0% at 50% 48%);opacity:0;filter:brightness(.3)}28%{clip-path:circle(28% at 50% 48%);opacity:1;filter:brightness(1)}64%{transform:scale(1.045);clip-path:circle(85% at 50% 48%);opacity:1;filter:brightness(.92)}100%{transform:scale(1);clip-path:circle(85% at 50% 48%);opacity:.82;filter:brightness(.72)}}
 @keyframes dlhVoidTitle{0%,35%{opacity:0}70%,100%{opacity:1}}
 @media(prefers-reduced-motion:reduce){.dlh-void-fx{transition:none}.dlh-void-plate,.dlh-void-caption{animation:none!important}}
 `;host.append(style);
 const layer=doc.createElement('div');layer.className='dlh-void-fx';layer.hidden=true;layer.setAttribute('aria-hidden','true');
