 const source=media?.still||'';
 const caption=doc.createElement('div');caption.className='dlh-void-caption';const title=doc.createElement('span');title.textContent='无量空处';const detail=doc.createElement('small');caption.append(title,detail);layer.append(plate,caption);
 const win=doc.defaultView||globalThis,motion=win.matchMedia?.('(prefers-reduced-motion: reduce)');
