 BATTLE_VOID_FX.update(stage,domains.some(row=>row.名称==='无量空处')||!opening?domains:[opening,...domains],RT.generationScope()+'|'+(TRIAL_WAR_ACTIVE||RT.messageToken())+'|'+view.battleId);
