  const native=Object.values(catalog||{}).find(x=>x.name===name),moves=native?.moves||a.moves||[],sections=[];
  if(a.yuan)sections.push({name:'传承',text:a.yuan});
  for(const s of a.sigs||[])sections.push({name:String(s[0]),text:String(s[1]||'')});
  for(const b of a.bonuses||[])sections.push({name:b.name||'通用加成',text:b.key+' +'+num(b.mode==='ratio'?b.value*100:b.value)+(b.mode==='ratio'||/率|增伤|减伤|伤害加成|会心伤害|会意伤害/.test(b.key)?'%':'')+' · '+(b.tier||['粗通','入室'][b.slot-1]||'随熟练度开放')});
  for(const m of moves){const tier=typeof m.tier==='number'?tiers[m.tier]:m.tier;sections.push({name:m.name||m.id,text:[m.desc||m.description,tier?`${tier}可习`:'',m.type==='hybrid'||m.type==='attack'||m.hpR||m.qqR?`整招外功倍率 ${num(m.hpR)} · 真气倍率 ${num(m.qqR)}`:'',`内力 ${num(m.cost)} · 调息 ${num(m.cd)} 回合`,m.nai!==undefined?`耐力 ${num(m.nai)}`:'',m.charge?`蓄势 ${num(m.charge)} 回合`:'',m.count>1?`${num(m.count)}段`:''].filter(Boolean).join(' · ')});}
